def _image_metadata_group_for_field(field: str) -> str:
    normalized = str(field or '').strip()
    for label, members in _IMAGE_METADATA_FIELD_GROUPS:
        if normalized in members:
            return label
    return _format_image_metadata_field_label(normalized)


def _image_metadata_payload(image_row: dict | None) -> dict:
    row = dict(image_row or {})
    hidden_fields = {
        'upload_mode',
        'source_width',
        'source_height',
        'stored_width',
        'stored_height',
        'stored_bytes',
    }
    return {
        field: row.get(field)
        for field in _SNAPSHOT_IMG_FIELDS
        if field not in {'id', 'desktop_id', 'sort_order', 'storage_path', 'original_filename'}
        and field not in hidden_fields
    }


def _format_image_metadata_field_label(field: str) -> str:
    labels = {
        'captured_at': 'capture time',
        'measure_color': 'measurement color',
        'crop_mode': 'crop mode',
        'ai_crop_x1': 'AI crop left',
        'ai_crop_y1': 'AI crop top',
        'ai_crop_x2': 'AI crop right',
        'ai_crop_y2': 'AI crop bottom',
        'ai_crop_source_w': 'AI crop source width',
        'ai_crop_source_h': 'AI crop source height',
        'ai_crop_is_custom': 'custom crop',
    }
    return labels.get(field, field.replace('_', ' '))


def _summarize_image_changes(
    current_images: list[dict],
    baseline_images: list[dict],
    *,
    ignored_keys: set[str] | None = None,
) -> list[str]:
    """Return short, user-facing lines describing what changed to images.

    We group by "kind of change" (crop, notes, calibration) and by
    "kind of image" (microscope photo, field photo) rather than listing
    raw filenames — the user sees results in the app UI, they don't
    remember `img_1.webp`.
    """
    current = [dict(row or {}) for row in (current_images or [])]
    baseline = [dict(row or {}) for row in (baseline_images or [])]
    ignored = {str(key or '').strip() for key in (ignored_keys or set()) if str(key or '').strip()}
    current_keys = [_image_compare_key(row) for row in current]
    baseline_keys = [_image_compare_key(row) for row in baseline]
    current_map = {_image_compare_key(row): row for row in current}
    baseline_map = {_image_compare_key(row): row for row in baseline}

    added = [current_map[key] for key in current_keys if key not in baseline_map and key not in ignored]
    removed = [baseline_map[key] for key in baseline_keys if key not in current_map and key not in ignored]
    shared_keys = [key for key in current_keys if key in baseline_map and key not in ignored]

    lines: list[str] = []

    # {group_label: [image_row, ...]} — each image row is only recorded
    # once per group even when several fields inside the group changed.
    change_buckets: dict[str, list[dict]] = {}
    change_order: list[str] = []
    for key in shared_keys:
        c_meta = _image_metadata_payload(current_map[key])
        b_meta = _image_metadata_payload(baseline_map[key])
        if c_meta == b_meta:
            continue
        seen_groups: set[str] = set()
        for field, value in c_meta.items():
            if value == b_meta.get(field):
                continue
            group = _image_metadata_group_for_field(field)
            if group in seen_groups:
                continue
            seen_groups.add(group)
            if group not in change_buckets:
                change_buckets[group] = []
                change_order.append(group)
            change_buckets[group].append(current_map[key])

    if added:
        # This is a comparison with the stored sync snapshot, not evidence
        # that a particular app or device originally added the photo. Older
        # observation-only snapshots may contain no photo history at all.
        lines.append(
            f'Present now but not recorded in the previous sync: '
            f'{_pluralize_image_count(added)}.'
        )
    if removed:
        lines.append(f'Removed {_pluralize_image_count(removed)}.')
    for group in change_order:
        rows = change_buckets[group]
        lines.append(f'Changed {group} on {_pluralize_image_count(rows)}.')
    if not lines and len(current) != len(baseline) and not ignored:
        lines.append(f'Photo count went from {len(baseline)} to {len(current)}.')
    return lines


def _normalize_observation_sync_field(field: str) -> str:
    normalized = str(field or '').strip()
    if normalized in {'visibility', 'sharing_scope'}:
        return 'sharing_scope'
    return normalized


def _format_observation_metadata_field_label(field: str) -> str:
    labels = {
        'date': 'date',
        'genus': 'genus',
        'species': 'species',
        'common_name': 'common name',
        'species_guess': 'species guess',
        'uncertain': 'uncertain',
        'unspontaneous': 'unspontaneous',
        'determination_method': 'determination method',
        'location': 'location',
        'gps_latitude': 'latitude',
        'gps_longitude': 'longitude',
        'location_public': 'location public',
        'is_draft': 'draft flag',
        'location_precision': 'location precision',
        'ai_selected_service': 'AI service',
        'ai_selected_taxon_id': 'AI taxon id',
        'ai_selected_scientific_name': 'AI scientific name',
        'ai_selected_probability': 'AI probability',
        'ai_selected_at': 'AI selected at',
        'habitat': 'habitat',
        'habitat_nin2_path': 'NIN2 path',
        'habitat_substrate_path': 'substrate path',
        'habitat_host_genus': 'host genus',
        'habitat_host_species': 'host species',
        'habitat_host_common_name': 'host common name',
        'habitat_nin2_note': 'NIN2 note',
        'habitat_substrate_note': 'substrate note',
        'habitat_grows_on_note': 'grows-on note',
        'notes': 'notes',
        'open_comment': 'open comment',
        'interesting_comment': 'interesting comment',
        'publish_target': 'publish target',
        'artsdata_id': 'Artsobs id',
        'artportalen_id': 'Artportalen id',
        'inaturalist_id': 'iNaturalist id',
        'mushroomobserver_id': 'Mushroom Observer id',
        'spore_data_visibility': 'spore visibility',
        'visibility': 'visibility',
        'sharing_scope': 'sharing scope',
    }
    normalized = str(field or '').strip()
    return labels.get(normalized, normalized.replace('_', ' '))


def _analyze_observation_field_changes(local_obs: dict | None, remote_obs: dict | None, baseline_obs: dict | None) -> dict:
    local_payload = _observation_compare_payload(local_obs, local=True)
    remote_payload = _observation_compare_payload(remote_obs, local=False)
    baseline_payload = _baseline_observation_compare_payload(baseline_obs)
    remote_only_fields: list[str] = []
    local_only_fields: list[str] = []
    conflict_fields: list[str] = []
    shared_same_fields: list[str] = []

    for field in _SNAPSHOT_OBS_FIELDS:
        if field in {'id', 'desktop_id'}:
            continue
        baseline_value = baseline_payload.get(field)
        local_value = local_payload.get(field)
        remote_value = remote_payload.get(field)
        local_changed = not _observation_field_values_match(field, local_value, baseline_value)
        remote_changed = not _observation_field_values_match(field, remote_value, baseline_value)
        if local_changed and remote_changed:
            if _observation_field_values_match(field, local_value, remote_value):
                shared_same_fields.append(field)
            else:
                conflict_fields.append(field)
        elif local_changed:
            local_only_fields.append(field)
        elif remote_changed:
            remote_only_fields.append(field)

    return {
        'local_payload': local_payload,
        'remote_payload': remote_payload,
        'baseline_payload': baseline_payload,
        'local_only_fields': local_only_fields,
        'remote_only_fields': remote_only_fields,
        'conflict_fields': conflict_fields,
        'shared_same_fields': shared_same_fields,
    }


def _analyze_image_changes(
    current_images: list[dict],
    baseline_images: list[dict],
    *,
    ignored_keys: set[str] | None = None,
) -> dict:
    current = [dict(row or {}) for row in (current_images or [])]
    baseline = [dict(row or {}) for row in (baseline_images or [])]
    ignored = {str(key or '').strip() for key in (ignored_keys or set()) if str(key or '').strip()}
    current_keys = [_image_compare_key(row) for row in current]
    baseline_keys = [_image_compare_key(row) for row in baseline]
    current_map = {_image_compare_key(row): row for row in current}
    baseline_map = {_image_compare_key(row): row for row in baseline}

    added_keys = [key for key in current_keys if key not in baseline_map and key not in ignored]
    removed_keys = [key for key in baseline_keys if key not in current_map and key not in ignored]
    shared_keys = [key for key in current_keys if key in baseline_map and key not in ignored]
    metadata_changed_keys = [
        key
        for key in shared_keys
        if _image_metadata_payload(current_map[key]) != _image_metadata_payload(baseline_map[key])
    ]

    return {
        'added_keys': added_keys,
        'removed_keys': removed_keys,
        'metadata_changed_keys': metadata_changed_keys,
        'order_changed': False,
        'added': [current_map[key] for key in added_keys],
        'removed': [baseline_map[key] for key in removed_keys],
        'changed': bool(added_keys or removed_keys or metadata_changed_keys),
    }


def _non_blocking_local_only_fields(field_changes: dict) -> frozenset[str]:
    if 'local_payload' not in field_changes:
        return _PULL_NON_BLOCKING_LOCAL_ONLY_FIELDS
    local_payload = dict(field_changes.get('local_payload') or {})
    identification_is_empty = not any(
        str(local_payload.get(field) or '').strip()
        for field in ('genus', 'species', 'common_name', 'species_guess')
    )
    if identification_is_empty:
        return frozenset()
    return _PULL_NON_BLOCKING_LOCAL_ONLY_FIELDS


def _remaining_local_changes_after_remote_merge(
    field_changes: dict,
    *,
    local_media_changed: bool,
) -> bool:
    non_blocking_fields = _non_blocking_local_only_fields(field_changes)
    blocking_local_only_fields = {
        str(field or '').strip()
        for field in (field_changes.get('local_only_fields') or [])
        if str(field or '').strip() not in non_blocking_fields
    }
    return bool(blocking_local_only_fields or field_changes.get('conflict_fields') or local_media_changed)


def _format_review_needed_error(local_id: int, cloud_id: str, reasons: list[str] | None = None) -> str:
    reason_text = ', '.join(str(reason or '').strip() for reason in (reasons or []) if str(reason or '').strip())
    base = (
        f"cloud {str(cloud_id or '').strip() or '?'}: needs review before applying remaining "
        f"cloud changes to local observation {int(local_id)}"
    )
    return f'{base} ({reason_text})' if reason_text else base


# Marker persisted on `observations.sync_blocked_reason` when push_all's
# preflight detects an unresolved three-way conflict. The observation stays
# dirty; a subsequent sync re-evaluates and clears the marker automatically
# once the divergence is gone (either the user resolved it or an incoming pull
# reconciled the state).
CONFLICT_REVIEW_PENDING_MARKER = 'conflict_review_pending'


@dataclass(frozen=True)
class ObservationPushConflictReport:
    """Structured result from :func:`_analyze_observation_push_conflicts`.

    Mirrors the categories pull_all already reports as review-needed so push
    never silently overwrites a remote divergence.
    """

    has_conflict: bool
    categories: list[str]
    field_labels: list[str]
    measurement_conflict_ids: list[int]
    image_conflict_keys: list[str]
    remote_removed_image_keys: list[str]


def _analyze_observation_push_conflicts(
    *,
    local_obs: dict | None,
    local_images: list[dict] | None,
    local_measurements_by_cloud_id: dict[str, dict] | None,
    remote_obs: dict | None,
    remote_images: list[dict] | None,
    remote_measurements: list[dict] | None,
    baseline_snapshot: dict | None,
) -> ObservationPushConflictReport:
    """Detect per-observation conflicts before push_all mutates cloud state.

    The three input sides — local rows, fetched remote rows, and the stored
    sync baseline (``_load_cloud_observation_snapshot`` / parsed) — are the
    same primitives pull_all uses. Returned categories align with the review
    reasons pull_all emits so a single review dialog covers both directions:

    * ``observation`` — obs metadata field conflict
      (via :func:`_analyze_observation_field_changes` ``conflict_fields``).
    * ``images`` — a shared image was edited on both sides.
    * ``measurements`` — a shared spore measurement differs local vs remote
      (mirrors :func:`_import_remote_measurements_for_observation` ``conflict``).
    * ``remote_removed_media`` — cloud removed an image still present locally
      (mirrors pull_all's ``removed_keys`` review-needed guard).
    """
    baseline_snapshot = dict(baseline_snapshot or {})
    baseline_obs = _baseline_observation_compare_payload(
        baseline_snapshot.get('observation') or {}
    )
    baseline_images = [dict(row or {}) for row in (baseline_snapshot.get('images') or [])]

    # ---- Observation metadata: three-way conflict fields ----
    field_changes = _analyze_observation_field_changes(local_obs, remote_obs, baseline_obs)
    conflict_fields = list(field_changes.get('conflict_fields') or [])
    if local_measurements_by_cloud_id or remote_measurements:
        # Derived statistics follow the selected scientific measurement set;
        # they are never an independent winner-takes-all field conflict.
        conflict_fields = [field for field in conflict_fields if field != 'spore_statistics']
    field_labels = [
        _format_observation_metadata_field_label(field)
        for field in sorted(set(conflict_fields))
    ]

    # ---- Image removals: mirror pull_all "cloud removed local image files" ----
    remote_images = list(remote_images or [])
    remote_image_payloads = [_remote_image_payload(img) for img in remote_images]
    tombstoned_remote_image_keys = (
        _deleted_remote_image_identity_keys(remote_images)
        | _locally_tombstoned_snapshot_image_identity_keys(baseline_images)
    )
    remote_image_changes = _analyze_image_changes(
        remote_image_payloads,
        baseline_images,
        ignored_keys=tombstoned_remote_image_keys,
    )
    remote_removed_image_keys = list(remote_image_changes.get('removed_keys') or [])

    # ---- Image metadata: three-way conflict on shared cloud image rows ----
    # Normalize each side to a canonical snapshot payload before comparing so
    # that representation differences (e.g. cloud lowercase sample_source vs
    # desktop Title_Case, calibration_id vs calibration_uuid, naive local
    # captured_at vs UTC timestamptz) do not produce false conflicts.
    baseline_by_cloud_id = {
        str(row.get('id') or '').strip(): _remote_image_payload(row)
        for row in baseline_images
        if str(row.get('id') or '').strip()
    }
    remote_by_cloud_id = {
        str(row.get('id') or '').strip(): row
        for row in remote_image_payloads
        if str(row.get('id') or '').strip()
    }
    local_by_cloud_id = {
        str((img or {}).get('cloud_id') or '').strip(): _local_image_snapshot_payload(dict(img or {}))
        for img in (local_images or [])
        if str((img or {}).get('cloud_id') or '').strip()
    }
    image_conflict_keys: list[str] = []
    shared_cloud_ids = sorted(
        set(baseline_by_cloud_id) & set(remote_by_cloud_id) & set(local_by_cloud_id)
    )
    for cloud_image_id in shared_cloud_ids:
        baseline_meta = _image_metadata_payload(baseline_by_cloud_id[cloud_image_id])
        remote_meta = _image_metadata_payload(remote_by_cloud_id[cloud_image_id])
        local_meta = _image_metadata_payload(local_by_cloud_id[cloud_image_id])
        local_changed = local_meta != baseline_meta
        remote_changed = remote_meta != baseline_meta
        if local_changed and remote_changed and local_meta != remote_meta:
            image_conflict_keys.append(f'cloud:{cloud_image_id}')

    # ---- Measurements: mirror pull-side conflict detection (no apply) ----
    remote_measurements = list(remote_measurements or [])
    remote_image_lookup = {
        str(row.get('id') or '').strip(): row
        for row in remote_images
        if str(row.get('id') or '').strip()
    }
    tombstoned_remote_image_ids = _local_tombstoned_cloud_image_ids(list(remote_image_lookup.keys()))
    local_measurements_by_cloud_id = dict(local_measurements_by_cloud_id or {})

    measurement_conflict_ids: list[int] = []
    seen_local_ids: set[int] = set()
    for remote_row in remote_measurements:
        remote_measurement_id = str(remote_row.get('id') or '').strip()
        if not remote_measurement_id:
            continue
        remote_image_id = str(remote_row.get('image_id') or '').strip()
        remote_image = remote_image_lookup.get(remote_image_id)
        if not remote_image:
            continue
        if not _is_spore_measurement_source_image(remote_image):
            continue
        if remote_image_id in tombstoned_remote_image_ids:
            continue
        local_measurement = local_measurements_by_cloud_id.get(remote_measurement_id)
        if local_measurement is None:
            continue
        if not _measurement_payloads_match(
            local_measurement,
            remote_row,
            cloud_image_id=remote_image_id,
        ):
            local_measurement_id = _safe_int(local_measurement.get('id'))
            if local_measurement_id > 0 and local_measurement_id not in seen_local_ids:
                seen_local_ids.add(local_measurement_id)
                measurement_conflict_ids.append(local_measurement_id)

    categories: list[str] = []
    if conflict_fields:
        categories.append('observation')
    if image_conflict_keys:
        categories.append('images')
    if measurement_conflict_ids:
        categories.append('measurements')
    if remote_removed_image_keys:
        categories.append('remote_removed_media')

    return ObservationPushConflictReport(
        has_conflict=bool(categories),
        categories=categories,
        field_labels=field_labels,
        measurement_conflict_ids=measurement_conflict_ids,
        image_conflict_keys=image_conflict_keys,
        remote_removed_image_keys=remote_removed_image_keys,
    )


def _format_push_conflict_review_reasons(report: ObservationPushConflictReport) -> list[str]:
    """Human-readable review reasons corresponding to conflict categories."""
    reasons: list[str] = []
    if report.field_labels:
        reasons.append(', '.join(report.field_labels))
    if report.image_conflict_keys:
        reasons.append(
            f'images changed on both sides ({len(report.image_conflict_keys)})'
        )
    if report.measurement_conflict_ids:
        reasons.append(
            f'measurements changed on both sides ({len(report.measurement_conflict_ids)})'
        )
    if report.remote_removed_image_keys:
        reasons.append('cloud removed local image files')
    return reasons


def _set_observation_conflict_review_pending(local_id: int) -> None:
    """Mark an observation blocked on user review while keeping it dirty."""
    conn = get_connection()
    try:
        cursor = conn.cursor()
        update_observation_sync_state(
            cursor,
            int(local_id),
            sync_status='dirty',
            sync_blocked_reason=CONFLICT_REVIEW_PENDING_MARKER,
            sync_blocked_at=datetime.now(timezone.utc).isoformat(),
        )
        conn.commit()
    finally:
        conn.close()


def _clear_observation_conflict_review_pending(local_id: int) -> None:
    """Clear the conflict-review marker without disturbing other sync error state."""
    conn = get_connection()
    try:
        cursor = conn.cursor()
        columns = _table_columns_for_conflict_marker(cursor)
        if 'sync_blocked_reason' not in columns:
            return
        # Only clear when the current marker is our review flag so we do not
        # step on privacy/plan blocked reasons written by other paths.
        cursor.execute(
            "UPDATE observations SET sync_blocked_reason = NULL, sync_blocked_at = NULL "
            "WHERE id = ? AND sync_blocked_reason = ?",
            (int(local_id), CONFLICT_REVIEW_PENDING_MARKER),
        )
        conn.commit()
    finally:
        conn.close()


def _table_columns_for_conflict_marker(cursor) -> set[str]:
    try:
        cursor.execute("PRAGMA table_info(observations)")
        return {str(row[1] or '') for row in cursor.fetchall()}
    except sqlite3.OperationalError:
        return set()


def _local_has_real_changes_since_snapshot(local_obs: dict, cloud_id: str | None = None) -> bool:
    cloud_value = str(cloud_id or local_obs.get('cloud_id') or '').strip()
    if not cloud_value:
        return True
    snapshot = _parse_cloud_observation_snapshot(_load_cloud_observation_snapshot(cloud_value))
    baseline_obs = _baseline_observation_compare_payload(snapshot.get('observation') or {})
    if not baseline_obs:
        return True
    local_payload = _observation_compare_payload(local_obs, local=True)
    for field in _SNAPSHOT_OBS_FIELDS:
        if field in {'id', 'desktop_id'}:
            continue
        if not _observation_field_values_match(field, local_payload.get(field), baseline_obs.get(field)):
            return True

    local_id = _safe_int(local_obs.get('id'))
    if local_id <= 0:
        return False
    stored_media_sig = _load_local_cloud_media_signature(local_id)
    if not stored_media_sig:
        return True
    current_media_sig = _local_cloud_media_signature(local_id)
    if not current_media_sig:
        return False
    if not _local_media_signatures_match(stored_media_sig, current_media_sig):
        return True
    _store_local_media_signature_if_equivalent(local_id, stored_media_sig, current_media_sig)

    try:
        _, local_measurements_by_id = _load_local_measurement_lookup(local_id)
    except Exception:
        return True
    local_measurement_payloads = [
        _local_measurement_snapshot_payload(row)
        for row in (local_measurements_by_id.values() if local_measurements_by_id else [])
    ]
    baseline_measurements = [dict(row or {}) for row in (snapshot.get('measurements') or [])]
    if _analyze_measurement_changes(local_measurement_payloads, baseline_measurements).get('changed'):
        return True
    return False


def _clear_observation_dirty_if_no_real_changes(local_id: int, cloud_id: str) -> bool:
    local_obs = ObservationDB.get_observation(int(local_id))
    if not local_obs:
        return False
    if _local_has_real_changes_since_snapshot(local_obs, cloud_id):
        return False
    conn = get_connection()
    try:
        cursor = conn.cursor()
        update_observation_sync_state(
            cursor,
            int(local_id),
            sync_status='synced',
            clear_sync_error_state=True,
        )
        conn.commit()
    finally:
        conn.close()
    return True


def _progress_done(progress_state: dict | None) -> int:
    try:
        return max(0, int((progress_state or {}).get('done', 0) or 0))
    except Exception:
        return 0


def _progress_total(progress_state: dict | None) -> int:
    try:
        return max(0, int((progress_state or {}).get('total', 0) or 0))
    except Exception:
        return 0


def _trace_progress_gap(message: str) -> None:
    """Log when a long backend step elapsed between two UI progress updates.

    The UI only shows the *last* emitted message. If a slow step runs while that
    message stays on screen (e.g. the bar appears frozen on "Checking
    calibration 4/8"), the gap is logged here naming both messages so the pause
    can be traced to the actual backend work, even when that work emits no
    progress text of its own.
    """
    trace = _cloud_sync_progress_trace()
    if not isinstance(trace, dict):
        return
    now = _cloud_sync_perf_counter()
    last_t = trace.get('last_t')
    last_msg = trace.get('last_msg')
    start = trace.get('start', now)
    if last_t is not None:
        gap = now - last_t
        if gap >= _CLOUD_SYNC_SLOW_STEP_SECONDS:
            print(
                f"[cloud_sync] progress gap: {gap * 1000:.0f}ms with no UI update "
                f"(stuck showing \"{last_msg}\") before \"{message}\" "
                f"at +{(now - start):.1f}s into sync",
                flush=True,
            )
    trace['last_t'] = now
    trace['last_msg'] = message


# Weighted global progress model for cloud sync.
#
# The UI shows a single progress bar; each sync phase maps onto a fixed
# percentage range. Per-phase (done, total) counters are turned into a global
# 0–100 value by _sync_progress_percent so the bar advances monotonically at
# roughly the pace of real work — never jumping to 99% while phases like
# "Loading cloud measurements" or "Checking cloud observation N/M" are still
# running.
#
# Ordered by execution — the tuple is (name, start_percent, end_percent).
_SYNC_PROGRESS_PHASES: tuple[tuple[str, int, int], ...] = (
    ('auth', 0, 5),
    ('calibration_push', 5, 12),
    ('observation_preflight', 12, 18),
    ('push_observations', 18, 45),
    ('refresh_remote', 45, 50),
    ('pull_preflight', 50, 65),
    ('pull_measurements', 65, 75),
    ('pull_observations', 75, 92),
    ('calibration_pull', 92, 97),
    ('finalize', 97, 100),
)
_SYNC_PROGRESS_PHASE_RANGES: dict[str, tuple[int, int]] = {
    name: (start, end) for name, start, end in _SYNC_PROGRESS_PHASES
}
_SYNC_PROGRESS_TOTAL_UNITS = 100


def _sync_progress_percent(phase: str | None, done: int, total: int) -> int:
    """Map per-phase (done, total) onto the global 0–100 progress scale.

    Unknown or missing phases resolve to 0 so a bug in phase wiring can never
    silently pin the bar to 99%.
    """
    start, end = _SYNC_PROGRESS_PHASE_RANGES.get(str(phase or ''), (0, 0))
    try:
        done_int = max(0, int(done))
        total_int = max(0, int(total))
    except Exception:
        done_int, total_int = 0, 0
    if total_int <= 0:
        return int(start)
    frac = min(1.0, done_int / total_int)
    return int(round(start + frac * (end - start)))


def _set_progress_phase(
    progress_state: dict | None,
    phase_name: str,
    phase_total: int = 0,
) -> None:
    """Enter a named sync phase and reset the per-phase (done, total) counter.

    Progress is tracked *per phase*, not globally: each phase gets a fresh
    ``done``/``total`` pair which the ``_emit_progress`` mapper then squeezes
    into that phase's slice of the global 0–100 range. The finalize phase is
    the only one allowed to reach 100%; other phases cap at their configured
    end percentage even if more work than expected turns out to be needed.
    """
    if not isinstance(progress_state, dict):
        return
    if phase_name not in _SYNC_PROGRESS_PHASE_RANGES:
        # Silently ignore unknown phases so tests that seed a raw
        # {done, total} dict without wiring phases keep working.
        return
    progress_state['phase'] = phase_name
    progress_state['done'] = 0
    try:
        progress_state['total'] = max(0, int(phase_total or 0))
    except Exception:
        progress_state['total'] = 0


def _current_progress_phase(progress_state: dict | None) -> str | None:
    if not isinstance(progress_state, dict):
        return None
    phase = progress_state.get('phase')
    if isinstance(phase, str) and phase in _SYNC_PROGRESS_PHASE_RANGES:
        return phase
    return None


def _emit_progress(
    progress_cb: ProgressCallback | None,
    message: str,
    progress_state: dict | None,
) -> None:
    _trace_progress_gap(message)
    if not callable(progress_cb):
        return
    phase = _current_progress_phase(progress_state)
    if phase is not None:
        phase_done = _progress_done(progress_state)
        phase_total = _progress_total(progress_state)
        percent = _sync_progress_percent(phase, phase_done, phase_total)
        progress_cb(message, percent, _SYNC_PROGRESS_TOTAL_UNITS)
    else:
        progress_cb(message, _progress_done(progress_state), max(1, _progress_total(progress_state)))


def _advance_progress(
    progress_state: dict | None,
    amount: int = 1,
) -> tuple[int, int]:
    state = progress_state or {}
    try:
        increment = max(0, int(amount))
    except Exception:
        increment = 0
    state['done'] = _progress_done(state) + increment
    state['total'] = _progress_total(state)
    return _progress_done(state), _progress_total(state)


def _extend_progress_total(
    progress_state: dict | None,
    amount: int,
) -> tuple[int, int]:
    state = progress_state or {}
    try:
        increment = max(0, int(amount))
    except Exception:
        increment = 0
    state['done'] = _progress_done(state)
    state['total'] = _progress_total(state) + increment
    return _progress_done(state), _progress_total(state)


_SYNC_SUMMARY_KEYS = (
    'observations_checked',
    'observations_redirtied_pending_local_images',
    'observations_patched',
    'observations_skipped_noop',
    'observations_deleted_remote',
    'images_checked',
    'images_prepared_local',
    'images_uploaded',
    'images_skipped_already_synced',
    'images_cloud_id_repaired',
    'images_deleted_remote',
    'measurements_checked',
    'measurements_patched',
    'measurements_skipped_noop',
    'calibrations_pushed',
    'calibrations_pulled',
    'calibrations_skipped_noop',
    'calibrations_conflicts',
    'calibration_reference_images_uploaded',
    'calibration_remote_lookups',
    'storage_quota_delta_rpc_calls',
    'remote_media_downloads',
    'remote_media_materializations',
)


def _new_sync_summary() -> dict[str, int]:
    return {key: 0 for key in _SYNC_SUMMARY_KEYS}


def _sync_summary_value(sync_summary: dict | None, key: str) -> int:
    try:
        return max(0, int((sync_summary or {}).get(key, 0) or 0))
    except Exception:
        return 0


def _increment_sync_summary(sync_summary: dict | None, key: str, amount: int = 1) -> None:
    if not isinstance(sync_summary, dict):
        return
    try:
        increment = max(0, int(amount))
    except Exception:
        increment = 0
    if increment <= 0:
        return
    sync_summary[key] = _sync_summary_value(sync_summary, key) + increment


def format_sync_summary(sync_summary: dict | None) -> str | None:
    summary = dict(sync_summary or {})
    if not summary:
        return None

    lines: list[str] = []

    observation_bits = []
    observations_checked = _sync_summary_value(summary, 'observations_checked')
    if observations_checked:
        observation_bits.append(f'{observations_checked} checked')
    observations_redirtied = _sync_summary_value(summary, 'observations_redirtied_pending_local_images')
    if observations_redirtied:
        observation_bits.append(f'{observations_redirtied} re-dirtied due to pending local images')
    observations_patched = _sync_summary_value(summary, 'observations_patched')
    if observations_patched:
        observation_bits.append(f'{observations_patched} patched')
    observations_noop = _sync_summary_value(summary, 'observations_skipped_noop')
    if observations_noop:
        observation_bits.append(f'{observations_noop} skipped as no-op')
    observations_deleted = _sync_summary_value(summary, 'observations_deleted_remote')
    if observations_deleted:
        observation_bits.append(f'{observations_deleted} deleted remotely')
    if observation_bits:
        lines.append(f"Observations: {'; '.join(observation_bits)}.")

    image_bits = []
    images_checked = _sync_summary_value(summary, 'images_checked')
    if images_checked:
        image_bits.append(f'{images_checked} checked')
    images_prepared = _sync_summary_value(summary, 'images_prepared_local')
    if images_prepared:
        image_bits.append(f'{images_prepared} prepared for upload')
    images_uploaded = _sync_summary_value(summary, 'images_uploaded')
    if images_uploaded:
        image_bits.append(f'{images_uploaded} uploaded')
    images_skipped = _sync_summary_value(summary, 'images_skipped_already_synced')
    if images_skipped:
        image_bits.append(f'{images_skipped} skipped as already synced')
    images_repaired = _sync_summary_value(summary, 'images_cloud_id_repaired')
    if images_repaired:
        image_bits.append(f'{images_repaired} cloud_id associations repaired')
    images_deleted = _sync_summary_value(summary, 'images_deleted_remote')
    if images_deleted:
        image_bits.append(f'{images_deleted} deleted remotely')
    if image_bits:
        lines.append(f"Images: {'; '.join(image_bits)}.")

    measurement_bits = []
    measurements_checked = _sync_summary_value(summary, 'measurements_checked')
    if measurements_checked:
        measurement_bits.append(f'{measurements_checked} checked')
    measurements_patched = _sync_summary_value(summary, 'measurements_patched')
    if measurements_patched:
        measurement_bits.append(f'{measurements_patched} patched')
    measurements_noop = _sync_summary_value(summary, 'measurements_skipped_noop')
    if measurements_noop:
        measurement_bits.append(f'{measurements_noop} skipped as no-op')
    if measurement_bits:
        lines.append(f"Measurements: {'; '.join(measurement_bits)}.")

    calibration_bits = []
    calibrations_pushed = _sync_summary_value(summary, 'calibrations_pushed')
    if calibrations_pushed:
        calibration_bits.append(f'{calibrations_pushed} pushed')
    calibrations_pulled = _sync_summary_value(summary, 'calibrations_pulled')
    if calibrations_pulled:
        calibration_bits.append(f'{calibrations_pulled} pulled')
    calibrations_noop = _sync_summary_value(summary, 'calibrations_skipped_noop')
    if calibrations_noop:
        calibration_bits.append(f'{calibrations_noop} skipped as no-op')
    calibrations_conflicts = _sync_summary_value(summary, 'calibrations_conflicts')
    if calibrations_conflicts:
        calibration_bits.append(f'{calibrations_conflicts} conflicts')
    calibration_reference_uploads = _sync_summary_value(summary, 'calibration_reference_images_uploaded')
    if calibration_reference_uploads:
        calibration_bits.append(f'{calibration_reference_uploads} reference image(s) uploaded')
    if calibration_bits:
        lines.append(f"Calibrations: {'; '.join(calibration_bits)}.")

    storage_quota_delta_calls = _sync_summary_value(summary, 'storage_quota_delta_rpc_calls')
    if storage_quota_delta_calls:
        lines.append(f'Storage quota delta RPC calls: {storage_quota_delta_calls}.')

    remote_downloads = _sync_summary_value(summary, 'remote_media_downloads')
    remote_materializations = _sync_summary_value(summary, 'remote_media_materializations')
    if remote_downloads or remote_materializations:
        lines.append(
            'Remote media downloads/materializations: '
            f'{remote_downloads} downloads; {remote_materializations} materializations.'
        )

    return '\n'.join(lines) if lines else None


def summarize_sync_change_activity(result: dict | None) -> dict:
    """Classify a sync result into real changes vs. checked/no-op/local-only work.

    The push phase walks every observation whose row is dirty or has no cloud_id
    and counts each as "pushed" even when the upsert was a no-op (e.g. an
    observation re-dirtied only because a local image row was re-associated to an
    existing cloud image). The user-facing notification must reflect *real*
    remote-facing or local changes, not the raw dirty-scan count, otherwise a
    no-change sync wrongly reports that an observation was synced.

    Returns a dict with explicit counters plus ``any_real_change``:
      - real remote change: observation/measurement metadata written, image bytes
        uploaded or deleted remotely, calibration pushed / reference image uploaded.
      - real local change: observation/calibration pulled, remote media downloaded
        or materialized locally.
    Local-only cloud_id repairs (``images_cloud_id_repaired``) and pure no-op /
    checked counts are reported but excluded from ``any_real_change``.
    """
    data = dict(result or {})
    summary = data.get('sync_summary') or {}

    def _value(key: str) -> int:
        return _sync_summary_value(summary, key)

    def _result_int(key: str) -> int:
        try:
            return max(0, int(data.get(key, 0) or 0))
        except Exception:
            return 0

    observations_metadata_patched = _value('observations_patched')
    observations_checked = _value('observations_checked')
    observations_checked_noop = _value('observations_skipped_noop')
    observations_deleted_remote = _value('observations_deleted_remote')
    images_uploaded = _value('images_uploaded')
    images_deleted_remote = _value('images_deleted_remote')
    images_repaired_local_only = _value('images_cloud_id_repaired')
    measurements_patched = _value('measurements_patched')
    calibrations_pushed = _value('calibrations_pushed')
    calibration_reference_images_uploaded = _value('calibration_reference_images_uploaded')
    calibrations_pulled = _value('calibrations_pulled')
    remote_media_downloads = _value('remote_media_downloads')
    remote_media_materializations = _value('remote_media_materializations')
    # ``pulled`` is the count of observations pulled into the local DB; fall back
    # to the summary count is not tracked separately, so use the result value.
    observations_pulled = _result_int('pulled')
    deleted_remote_rows = len(data.get('deleted_remote') or [])
    reference_sync = data.get('reference_sync')
    if not isinstance(reference_sync, dict):
        reference_sync = {}

    def _reference_int(key: str) -> int:
        try:
            return max(0, int(reference_sync.get(key, 0) or 0))
        except Exception:
            return 0

    reference_pushed = _reference_int('pushed')
    reference_pulled = _reference_int('pulled')

    real_remote_change = (
        observations_metadata_patched
        + images_uploaded
        + images_deleted_remote
        + measurements_patched
        + calibrations_pushed
        + calibration_reference_images_uploaded
        + observations_deleted_remote
        + reference_pushed
    )
    real_local_change = (
        observations_pulled
        + calibrations_pulled
        + remote_media_downloads
        + remote_media_materializations
        + reference_pulled
    )
    # ``deleted_remote_rows`` (cloud observations deleted elsewhere, awaiting local
    # review) is surfaced by its own notification branch, so it is reported here
    # but not folded into ``any_real_change``.
    any_real_change = bool(real_remote_change or real_local_change)

    return {
        'observations_metadata_patched': observations_metadata_patched,
        'observations_checked': observations_checked,
        'observations_checked_noop': observations_checked_noop,
        'observations_images_repaired_local_only': images_repaired_local_only,
        'observations_pulled': observations_pulled,
        'images_uploaded': images_uploaded,
        'images_deleted_remote': images_deleted_remote,
        'measurements_patched': measurements_patched,
        'calibrations_pushed': calibrations_pushed,
        'calibrations_pulled': calibrations_pulled,
        'calibration_reference_images_uploaded': calibration_reference_images_uploaded,
        'remote_media_downloads': remote_media_downloads,
        'remote_media_materializations': remote_media_materializations,
        'deleted_remote_rows': deleted_remote_rows,
        'reference_pushed': reference_pushed,
        'reference_pulled': reference_pulled,
        'real_remote_change': real_remote_change,
        'real_local_change': real_local_change,
        'any_real_change': any_real_change,
    }


_SYNC_SUMMARY_OBSERVATION_REFRESH_KEYS = (
    'observations_redirtied_pending_local_images',
    'observations_patched',
    'observations_deleted_remote',
    'images_uploaded',
    'images_cloud_id_repaired',
    'images_deleted_remote',
    'measurements_patched',
    'calibrations_pushed',
    'calibrations_pulled',
    'calibrations_conflicts',
    'calibration_reference_images_uploaded',
    'remote_media_downloads',
    'remote_media_materializations',
)


def sync_result_requires_observation_refresh(result: dict | None) -> bool:
    """Return False only when a complete sync result proves a UI no-op."""
    data = dict(result or {})
    summary = data.get('sync_summary')
    if not isinstance(summary, dict):
        return True
    if data.get('cancelled') or data.get('skipped'):
        return True
    if data.get('errors') or data.get('deleted_remote'):
        return True

    reference_sync = data.get('reference_sync')
    if isinstance(reference_sync, dict):
        if any(
            reference_sync.get(key)
            for key in (
                'pushed',
                'pulled',
                'errors',
                'retryable_errors',
                'terminal_errors',
                'conflicts',
                'blocked',
            )
        ):
            return True

    for key in ('pushed', 'pulled'):
        try:
            if int(data.get(key, 0) or 0) != 0:
                return True
        except Exception:
            return True

    return any(
        _sync_summary_value(summary, key) > 0
        for key in _SYNC_SUMMARY_OBSERVATION_REFRESH_KEYS
    )


def _observation_display_name(obs: dict | None) -> str:
    record = obs or {}
    parts = [
        str(record.get('genus') or '').strip(),
        str(record.get('species') or '').strip(),
    ]
    name = " ".join(part for part in parts if part).strip()
    if name:
        return name
    species_guess = str(record.get('species_guess') or '').strip()
    if species_guess:
        return species_guess
    location = str(record.get('location') or '').strip()
    if location:
        return location
    obs_id = str(record.get('id') or '').strip()
    return f'observation {obs_id}' if obs_id else 'observation'


def _cloud_media_signature() -> str:
    """Return clean cloud converter identity, excluding external publish state."""
    snapshot = {
        'converter_version': _CLEAN_CLOUD_IMAGE_CONVERTER_VERSION,
        'format': 'webp',
        'upload_mode': 'full',
    }
    return json.dumps(snapshot, ensure_ascii=True, sort_keys=True, separators=(',', ':'))


def _cloud_observation_snapshot_key(cloud_id: str) -> str:
    return f"{_SETTING_CLOUD_OBS_SNAPSHOT_PREFIX}{str(cloud_id or '').strip()}"


def _cloud_image_file_signature_key(observation_id: int | str, image_id: int | str) -> str:
    return (
        f"{_SETTING_CLOUD_IMAGE_FILE_SIG_PREFIX}"
        f"{str(observation_id or '').strip()}_{str(image_id or '').strip()}"
    )


def _cloud_metadata_only_image_ids_key(observation_id: int | str) -> str:
    return f"sporely_cloud_metadata_only_image_ids_{str(observation_id or '').strip()}"


def _cloud_image_promotion_pending_key(observation_id: int | str, image_id: int | str) -> str:
    return (
        f"{_SETTING_CLOUD_IMAGE_PROMOTION_PENDING_PREFIX}"
        f"{str(observation_id or '').strip()}_{str(image_id or '').strip()}"
    )


# Stage 1: cloud image-storage desired state lives under its own setting so it
# is fully independent of the Artsobs/iNaturalist publication exclusion set.
# The old ``artsobs_publish_excluded_image_ids_<obs>`` key remains a
# publication-only concern and must not be read to infer cloud deletion intent.
CLOUD_IMAGE_STORAGE_EXCLUDED_SETTING_PREFIX = "sporely_cloud_image_storage_excluded_ids_"
# RETIRED (2026-08-19 mass microscope upload): the observation-level
# initialization sentinel. Once set, images imported later never received a
# default and — being absent from the excluded set — looked explicitly
# checked. No code reads or writes this key anymore; existing rows in user
# databases are inert. Storage intent initialization is now recorded per
# image in the ledger key below.
_CLOUD_IMAGE_STORAGE_LEGACY_SENTINEL_PREFIX = "sporely_cloud_image_storage_initialized_"
# Per-image storage-intent ledger: JSON list of local image ids for which a
# default (or explicit) cloud byte-storage decision has been recorded. An
# image id absent from this ledger has NO storage intent yet — its absence
# from the excluded set proves nothing.
_CLOUD_IMAGE_STORAGE_INTENT_LEDGER_PREFIX = "sporely_cloud_image_storage_intent_ids_"


def _cloud_image_storage_excluded_ids_key(observation_id: int | str) -> str:
    return f"{CLOUD_IMAGE_STORAGE_EXCLUDED_SETTING_PREFIX}{str(observation_id or '').strip()}"


def _cloud_image_storage_intent_ledger_key(observation_id: int | str) -> str:
    return f"{_CLOUD_IMAGE_STORAGE_INTENT_LEDGER_PREFIX}{str(observation_id or '').strip()}"


def _cloud_local_media_signature_key(observation_id: int | str) -> str:
    return f"{_SETTING_CLOUD_LOCAL_MEDIA_SIG_PREFIX}{str(observation_id or '').strip()}"


def _normalize_snapshot_value(value):
    if isinstance(value, bool):
        return bool(value)
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, dict):
        return {str(k): _normalize_snapshot_value(v) for k, v in sorted(value.items(), key=lambda item: str(item[0]))}
    if isinstance(value, (list, tuple)):
        return [_normalize_snapshot_value(v) for v in value]
    return str(value)


def _normalize_image_captured_at_for_cloud(value, *, local: bool) -> str | None:
    """Return one image capture timestamp as a canonical UTC ISO value.

    SQLite stores capture timestamps as local wall-clock text. Postgres
    ``timestamptz`` values are absolute instants. Naive local values therefore
    use the host timezone (including historical DST), while a defensive naive
    cloud value is interpreted as UTC. A missing/invalid value stays missing;
    ``created_at`` is never used as a substitute.
    """
    if value is None:
        return None
    if isinstance(value, datetime):
        parsed = value
    else:
        text = str(value or '').strip()
        if not text:
            return None
        try:
            parsed = datetime.fromisoformat(text.replace('Z', '+00:00'))
        except Exception:
            return None
    if parsed.tzinfo is None:
        parsed = parsed.astimezone() if local else parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc).isoformat()


def _cloud_image_captured_at_to_local(value) -> str | None:
    """Convert a cloud capture instant to SQLite's local wall-clock format."""
    canonical = _normalize_image_captured_at_for_cloud(value, local=False)
    if canonical is None:
        return None
    parsed = datetime.fromisoformat(canonical)
    return parsed.astimezone().replace(tzinfo=None).strftime('%Y-%m-%d %H:%M:%S')


def _is_generated_cloud_image(image_row: dict | None) -> bool:
    row = dict(image_row or {})
    notes = str(row.get('notes') or '').strip().lower()
    filename = str(row.get('original_filename') or '').strip().lower()
    desktop_id = _safe_int(row.get('desktop_id'))
    if notes.startswith('generated media'):
        return True
    if filename.startswith('cloud_extra_'):
        return True
    if desktop_id < 0:
        return True
    return False


def should_push_local_image_to_cloud(image_row: dict | None) -> bool:
    row = dict(image_row or {})
    if _is_generated_cloud_image(row):
        return False
    source_role = str(row.get('source_role') or '').strip().lower()
    file_purpose = str(row.get('file_purpose') or '').strip().lower()
    if source_role == 'cloud_recovery_cache' or file_purpose == 'cache':
        # Cloud-imported rows are cached locally, but they are still the
        # canonical syncable image rows and must remain publishable so the
        # cloud copy can be preserved or restored.
        return True
    return True


def should_pull_cloud_image_to_desktop(image_row: dict | None) -> bool:
    row = dict(image_row or {})
    if _is_generated_cloud_image(row):
        return False
    if str(row.get('deleted_at') or '').strip():
        return False
    if str(row.get('purged_at') or '').strip():
        return False
    return True


def _is_metadata_only_microscope_cloud_image(image_row: dict | None) -> bool:
    row = dict(image_row or {})
    if not should_pull_cloud_image_to_desktop(row):
        return False
    if str(row.get('image_type') or '').strip().lower() != 'microscope':
        return False
    return not _normalize_cloud_media_key(row.get('storage_path'))


def _is_spore_measurement_source_image(image_row: dict | None) -> bool:
    row = dict(image_row or {})
    if not should_pull_cloud_image_to_desktop(row):
        return False
    if str(row.get('image_type') or '').strip().lower() == 'microscope':
        return True
    if _normalize_cloud_media_key(row.get('storage_path')):
        return True
    return _resolve_existing_local_image_asset_path(str(row.get('filepath') or '')) is not None


def _is_local_metadata_only_microscope_anchor(image_row: dict | None) -> bool:
    row = dict(image_row or {})
    if not should_pull_cloud_image_to_desktop(row):
        return False
    if str(row.get('image_type') or '').strip().lower() != 'microscope':
        return False
    return bool(str(row.get('cloud_id') or '').strip())


def _update_image_columns_without_touching_observation(
    image_id: int,
    updates: dict[str, object | None],
) -> None:
    if image_id <= 0 or not updates:
        return
    conn = get_connection()
    try:
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        cursor.execute("PRAGMA table_info(images)")
        image_columns = {
            str(row[1] or '').strip()
            for row in cursor.fetchall()
            if str(row[1] or '').strip()
        }
        assignments: list[str] = []
        values: list[object | None] = []
        for column_name, column_value in updates.items():
            if column_name not in image_columns:
                continue
            assignments.append(f"{column_name} = ?")
            values.append(column_value)
        if not assignments:
            return
        values.append(int(image_id))
        cursor.execute(
            f"UPDATE images SET {', '.join(assignments)} WHERE id = ?",
            values,
        )
        conn.commit()
    finally:
        conn.close()


def _cloud_pulled_image_order_key(image_row: dict) -> tuple[int, int, str, int]:
    image_type = str(image_row.get('image_type') or '').strip().lower()
    if image_type == 'field':
        type_rank = 0
    elif image_type == 'microscope':
        type_rank = 1
    else:
        type_rank = 2
    sort_order = _safe_int(image_row.get('sort_order'))
    sort_rank = sort_order if sort_order is not None else 10**9
    created_at = str(image_row.get('created_at') or '').strip()
    image_id = _safe_int(image_row.get('id')) or 0
    return (type_rank, sort_rank, created_at, image_id)


def _normalize_cloud_pulled_image_order(local_id: int) -> None:
    try:
        obs_id = int(local_id)
    except (TypeError, ValueError):
        return
    if obs_id <= 0:
        return

    image_rows = [dict(row or {}) for row in ImageDB.get_images_for_observation(obs_id) or []]
    if len(image_rows) < 2:
        return

    # Only normalize the mixed cloud-pulled cases. Local manual galleries keep
    # their existing order unless we have imported cloud recovery cache rows.
    has_cloud_cache_row = any(
        str(row.get('source_role') or '').strip().lower() == 'cloud_recovery_cache'
        for row in image_rows
    )
    if not has_cloud_cache_row:
        return

    image_types = {str(row.get('image_type') or '').strip().lower() for row in image_rows}
    if 'field' not in image_types or 'microscope' not in image_types:
        return

    ordered_rows = sorted(image_rows, key=_cloud_pulled_image_order_key)
    ordered_ids = [_safe_int(row.get('id')) for row in ordered_rows]
    ordered_ids = [image_id for image_id in ordered_ids if image_id is not None]
    current_ids = [_safe_int(row.get('id')) for row in image_rows]
    current_ids = [image_id for image_id in current_ids if image_id is not None]
    if ordered_ids == current_ids:
        return

    for index, image_id in enumerate(ordered_ids):
        _update_image_columns_without_touching_observation(int(image_id), {'sort_order': index})


_CLOUD_OBSERVATION_SNAPSHOT_SCHEMA_VERSION = 2


def _cloud_observation_snapshot(
    remote: dict,
    remote_images: list[dict] | None,
    remote_measurements: list[dict] | None = None,
    *,
    include_images: bool = True,
    include_measurements: bool = True,
    accepted_asymmetry: dict | None = None,
) -> str:
    """Deterministic snapshot payload.

    Turn-B B3: adds an optional ``accepted_asymmetry`` section that records
    intentionally one-sided items the user chose to keep.  Older callers that
    do not pass it still produce a schema-2 payload with an empty asymmetry
    section (kept backward-compatible on the read side by
    ``_parse_cloud_observation_snapshot``).
    """
    obs_part = {
        field: _normalize_snapshot_value((remote or {}).get(field))
        for field in _SNAPSHOT_OBS_FIELDS
    }
    payload: dict = {
        'schema_version': _CLOUD_OBSERVATION_SNAPSHOT_SCHEMA_VERSION,
        'observation': obs_part,
    }
    if include_images:
        images_part = []
        filtered_images = [
            dict(row or {})
            for row in (remote_images or [])
            if should_pull_cloud_image_to_desktop(row)
        ]
        for image in sorted(filtered_images, key=lambda row: (int(row.get('sort_order') or 0), str(row.get('id') or ''))):
            image_payload = {
                field: _normalize_snapshot_value(image.get(field))
                for field in _SNAPSHOT_IMG_FIELDS
            }
            image_payload['captured_at'] = _normalize_image_captured_at_for_cloud(
                image.get('captured_at'), local=False
            )
            for field in _SNAPSHOT_IMG_PASSIVE_FIELDS:
                passive_value = _normalize_cloud_media_key(image.get(field))
                if passive_value:
                    image_payload[field] = _normalize_snapshot_value(passive_value)
            images_part.append(image_payload)
        payload['images'] = images_part
    if include_measurements:
        measurements_part = []
        filtered_measurements = [dict(row or {}) for row in (remote_measurements or [])]
        for measurement in sorted(
            filtered_measurements,
            key=lambda row: (
                str(row.get('image_id') or ''),
                _safe_int(row.get('desktop_id')),
                str(row.get('id') or ''),
            ),
        ):
            measurements_part.append(
                {
                    field: _normalize_snapshot_value(measurement.get(field))
                    for field in _SNAPSHOT_MEAS_FIELDS
                }
            )
        payload['measurements'] = measurements_part
    # ── Accepted-asymmetry section ────────────────────────────────────────
    # Only include the section when meaningful; older readers ignore it.
    if accepted_asymmetry:
        payload['accepted_asymmetry'] = _normalize_accepted_asymmetry_for_snapshot(
            accepted_asymmetry
        )
    return json.dumps(payload, ensure_ascii=True, sort_keys=True, separators=(',', ':'))


def _normalize_accepted_asymmetry_for_snapshot(raw: dict | None) -> dict:
    """Canonicalize the accepted-asymmetry section for stable serialization.

    Each collection is a list of entries; each entry always carries:

    * ``side``: ``"local_only"`` or ``"cloud_only"``;
    * ``kind``: ``"image"`` or ``"measurement"``;
    * ``local_id`` and ``cloud_id`` (one of them will be null);
    * ``owning_local_image_id`` / ``owning_cloud_image_id`` for measurements;
    * ``fingerprint``: normalized content fingerprint at acceptance time;
    * ``accepted_at``: ISO timestamp (diagnostic only; never a privacy path);
    * ``choice``: ``"keep_local"`` or ``"keep_cloud"``.

    No secrets, tokens, or filesystem paths are stored.
    """
    if not isinstance(raw, dict):
        return {
            'local_only_images': [],
            'cloud_only_images': [],
            'local_only_measurements': [],
            'cloud_only_measurements': [],
        }
    result = {
        'local_only_images': [],
        'cloud_only_images': [],
        'local_only_measurements': [],
        'cloud_only_measurements': [],
    }
    for key in result.keys():
        for entry in raw.get(key) or []:
            if not isinstance(entry, dict):
                continue
            result[key].append(_normalize_accepted_asymmetry_entry(entry))
        # Stable sort so snapshots round-trip byte-for-byte.
        result[key].sort(key=lambda e: (
            str(e.get('local_id') or ''),
            str(e.get('cloud_id') or ''),
        ))
    return result


def _normalize_accepted_asymmetry_entry(entry: dict) -> dict:
    return {
        'side': str(entry.get('side') or ''),
        'kind': str(entry.get('kind') or ''),
        'local_id': _safe_int(entry.get('local_id')) or None,
        'cloud_id': str(entry.get('cloud_id') or '').strip() or None,
        'owning_local_image_id': _safe_int(entry.get('owning_local_image_id')) or None,
        'owning_cloud_image_id': str(entry.get('owning_cloud_image_id') or '').strip() or None,
        'fingerprint': entry.get('fingerprint') if isinstance(entry.get('fingerprint'), dict) else {},
        'accepted_at': str(entry.get('accepted_at') or '').strip() or None,
        'choice': str(entry.get('choice') or '').strip() or None,
    }


def _load_cloud_observation_snapshot(cloud_id: str) -> str:
    raw = str(SettingsDB.get_setting(_cloud_observation_snapshot_key(cloud_id), '') or '').strip()
    if not raw:
        return ''
    parsed = _parse_cloud_observation_snapshot(raw)
    if not parsed:
        return raw
    return json.dumps(parsed, ensure_ascii=True, sort_keys=True, separators=(',', ':'))


def _store_cloud_observation_snapshot(cloud_id: str, snapshot: str) -> None:
    if not str(cloud_id or '').strip():
        return
    normalized = str(snapshot or '').strip()
    if normalized:
        parsed = _parse_cloud_observation_snapshot(normalized)
        if parsed:
            normalized = json.dumps(parsed, ensure_ascii=True, sort_keys=True, separators=(',', ':'))
    SettingsDB.set_setting(_cloud_observation_snapshot_key(cloud_id), normalized)


def _load_cloud_image_file_signature(observation_id: int | str, image_id: int | str) -> str:
    return str(
        SettingsDB.get_setting(_cloud_image_file_signature_key(observation_id, image_id), '') or ''
    ).strip()


def _store_cloud_image_file_signature(
    observation_id: int | str,
    image_id: int | str,
    signature: str,
) -> None:
    SettingsDB.set_setting(
        _cloud_image_file_signature_key(observation_id, image_id),
        str(signature or '').strip(),
    )


def _clear_cloud_image_file_signature(observation_id: int | str, image_id: int | str) -> None:
    SettingsDB.set_setting(_cloud_image_file_signature_key(observation_id, image_id), '')


def _load_pending_image_promotion_key(observation_id: int | str, image_id: int | str) -> str:
    return _normalize_cloud_media_key(
        SettingsDB.get_setting(
            _cloud_image_promotion_pending_key(observation_id, image_id), ''
        ) or ''
    )


def _store_pending_image_promotion_key(
    observation_id: int | str,
    image_id: int | str,
    storage_path: str,
) -> None:
    SettingsDB.set_setting(
        _cloud_image_promotion_pending_key(observation_id, image_id),
        _normalize_cloud_media_key(storage_path),
    )


def _clear_pending_image_promotion_key(observation_id: int | str, image_id: int | str) -> None:
    SettingsDB.set_setting(_cloud_image_promotion_pending_key(observation_id, image_id), '')


def _cloud_metadata_only_image_ids(observation_id: int | str) -> set[int]:
    raw = SettingsDB.get_setting(_cloud_metadata_only_image_ids_key(observation_id), '[]')
    try:
        values = json.loads(raw or '[]')
    except (TypeError, ValueError, json.JSONDecodeError):
        return set()
    if not isinstance(values, list):
        return set()
    return {_safe_int(value) for value in values if _safe_int(value) > 0}


def _set_cloud_image_metadata_only_state(
    observation_id: int | str,
    image_id: int | str,
    metadata_only: bool,
) -> None:
    obs_id = _safe_int(observation_id)
    local_image_id = _safe_int(image_id)
    if obs_id <= 0 or local_image_id <= 0:
        return
    image_ids = _cloud_metadata_only_image_ids(obs_id)
    if metadata_only:
        image_ids.add(local_image_id)
    else:
        image_ids.discard(local_image_id)
    SettingsDB.set_setting(
        _cloud_metadata_only_image_ids_key(obs_id),
        json.dumps(sorted(image_ids)),
    )


def _cloud_image_storage_excluded_image_ids(observation_id: int | str) -> set[int]:
    """Return the local image ids the user has excluded from cloud image storage.

    Stage 1 canonical persistence for the gallery "Keep image in Sporely Cloud"
    checkbox. Separate from the Artsobs/iNat publication-exclusion set.
    """
    raw = SettingsDB.get_setting(
        _cloud_image_storage_excluded_ids_key(observation_id), '[]'
    )
    try:
        values = json.loads(raw or '[]')
    except (TypeError, ValueError, json.JSONDecodeError):
        return set()
    if not isinstance(values, list):
        return set()
    return {_safe_int(value) for value in values if _safe_int(value) > 0}


def _set_cloud_image_storage_excluded_image_ids(
    observation_id: int | str,
    excluded_ids: set[int] | list[int] | tuple[int, ...] | None,
) -> None:
    """Persist the full cloud image-storage excluded id set for one observation."""
    obs_id = _safe_int(observation_id)
    if obs_id <= 0:
        return
    normalized = sorted({
        _safe_int(value) for value in (excluded_ids or set()) if _safe_int(value) > 0
    })
    SettingsDB.set_setting(
        _cloud_image_storage_excluded_ids_key(obs_id),
        json.dumps(normalized),
    )


def _add_cloud_image_storage_excluded_image_id(
    observation_id: int | str,
    image_id: int | str,
) -> None:
    obs_id = _safe_int(observation_id)
    local_image_id = _safe_int(image_id)
    if obs_id <= 0 or local_image_id <= 0:
        return
    excluded = _cloud_image_storage_excluded_image_ids(obs_id)
    if local_image_id in excluded:
        return
    excluded.add(local_image_id)
    _set_cloud_image_storage_excluded_image_ids(obs_id, excluded)


def _remove_cloud_image_storage_excluded_image_id(
    observation_id: int | str,
    image_id: int | str,
) -> None:
    obs_id = _safe_int(observation_id)
    local_image_id = _safe_int(image_id)
    if obs_id <= 0 or local_image_id <= 0:
        return
    excluded = _cloud_image_storage_excluded_image_ids(obs_id)
    if local_image_id not in excluded:
        return
    excluded.discard(local_image_id)
    _set_cloud_image_storage_excluded_image_ids(obs_id, excluded)


def _cloud_image_storage_intent_initialized_ids(observation_id: int | str) -> set[int]:
    """Local image ids whose cloud byte-storage intent has been recorded.

    Canonical answer to "has default cloud-storage intent already been
    assigned to this local image?". Membership here — never mere absence
    from the excluded set — is what proves a decision exists.
    """
    raw = SettingsDB.get_setting(
        _cloud_image_storage_intent_ledger_key(observation_id), '[]'
    )
    try:
        values = json.loads(raw or '[]')
    except (TypeError, ValueError, json.JSONDecodeError):
        return set()
    if not isinstance(values, list):
        return set()
    return {_safe_int(value) for value in values if _safe_int(value) > 0}


def _set_cloud_image_storage_intent_initialized_ids(
    observation_id: int | str,
    image_ids: set[int] | list[int] | tuple[int, ...] | None,
) -> None:
    obs_id = _safe_int(observation_id)
    if obs_id <= 0:
        return
    normalized = sorted({
        _safe_int(value) for value in (image_ids or set()) if _safe_int(value) > 0
    })
    SettingsDB.set_setting(
        _cloud_image_storage_intent_ledger_key(obs_id),
        json.dumps(normalized),
    )


def _mark_cloud_image_storage_intent_initialized(
    observation_id: int | str,
    image_ids: set[int] | list[int] | tuple[int, ...],
) -> None:
    """Record that storage intent now exists for these images.

    Called for explicit checkbox interactions and by the initializer itself.
    Once an image is in the ledger, default seeding never touches it again.
    """
    obs_id = _safe_int(observation_id)
    normalized = {_safe_int(value) for value in (image_ids or ()) if _safe_int(value) > 0}
    if obs_id <= 0 or not normalized:
        return
    ledger = _cloud_image_storage_intent_initialized_ids(obs_id)
    if normalized <= ledger:
        return
    _set_cloud_image_storage_intent_initialized_ids(obs_id, ledger | normalized)


def cloud_image_storage_intent_initialized(
    observation_id: int | str,
    image_id: int | str,
) -> bool:
    """Pure read: has a storage-intent decision been recorded for this image?"""
    obs_id = _safe_int(observation_id)
    local_image_id = _safe_int(image_id)
    if obs_id <= 0 or local_image_id <= 0:
        return False
    return local_image_id in _cloud_image_storage_intent_initialized_ids(obs_id)


def cloud_image_bytes_desired(
    observation_id: int | str,
    image_id: int | str,
    image_row: dict | None = None,
) -> bool:
    """Return whether cloud image *bytes* are desired for this local image.

    Byte-storage intent only. Anchors are separate — metadata-only microscope
    anchor lifecycle is managed by
    ``_ensure_metadata_only_microscope_image_for_public_spores`` and is not
    affected by this predicate.
    """
    obs_id = _safe_int(observation_id)
    local_image_id = _safe_int(image_id)
    if obs_id <= 0 or local_image_id <= 0:
        return False
    excluded = _cloud_image_storage_excluded_image_ids(obs_id)
    return local_image_id not in excluded


class CloudImageBytesNotDesiredError(CloudSyncError):
    """Raised when a byte upload is attempted for an image the user unchecked.

    The cloud-storage-desired predicate rejects the upload at the client
    boundary. Recovery flows may opt in explicitly by passing
    ``recovery_authorized=True`` to the upload method.
    """


def _cloud_image_storage_initialized(observation_id: int | str) -> bool:
    """Derived: every current image row of this observation is in the ledger.

    Kept as a convenience predicate for tests and diagnostics. The legacy
    observation-level sentinel setting is retired and no longer consulted —
    an observation only counts as initialized when each of its images has a
    per-image intent record.
    """
    obs_id = _safe_int(observation_id)
    if obs_id <= 0:
        return False
    conn = get_connection()
    try:
        image_ids = {
            _safe_int(row[0])
            for row in conn.execute(
                "SELECT id FROM images WHERE observation_id = ?", (obs_id,)
            ).fetchall()
        }
    finally:
        conn.close()
    image_ids = {image_id for image_id in image_ids if image_id > 0}
    if not image_ids:
        return True
    return image_ids <= _cloud_image_storage_intent_initialized_ids(obs_id)


def _microscope_group_key_from_row(row: dict) -> str:
    """Coarse magnification-group key used by the storage-desired initializer.

    Kept local so ``utils.cloud_sync`` does not import Qt UI code. The heuristic
    mirrors :func:`ui.observations_tab._image_microscope_publish_group_key` for
    the fields available on ImageDB rows: use ``objective_name`` and fall back
    to a magnification number scraped from it. This is only used for the
    initializer's sparse-default rule; UI still uses its own resolver.
    """
    if not isinstance(row, dict):
        return "__unknown__"
    objective_name = str(row.get('objective_name') or '').strip()
    if not objective_name:
        lab_metadata = row.get('lab_metadata')
        if isinstance(lab_metadata, dict):
            objective_name = str(lab_metadata.get('objective_name') or '').strip()
            if not objective_name:
                microscope_metadata = lab_metadata.get('microscope')
                if isinstance(microscope_metadata, dict):
                    objective_name = str(
                        microscope_metadata.get('objective_name') or ''
                    ).strip()
    if not objective_name:
        return "__unknown__"
    import re as _re
    match = _re.search(r"(\d+(?:\.\d+)?)\s*[xX]", objective_name)
    if match:
        return f"{match.group(1)}x".casefold()
    match = _re.search(r"(\d+(?:\.\d+)?)", objective_name)
    if match:
        return f"{match.group(1)}x".casefold()
    return objective_name.casefold() or "__unknown__"


def _ensure_cloud_image_storage_intent_initialized(
    observation_id: int | str,
) -> dict:
    """Canonical per-image cloud-storage intent initializer (incremental).

    Records, in the persistent per-image ledger
    (``sporely_cloud_image_storage_intent_ids_<obs>``), that a default (or
    explicit) byte-storage decision exists for each local image. Only ledger
    membership proves a decision — absence from the excluded set proves
    nothing. This replaces the retired observation-level sentinel, which let
    images imported after first initialization masquerade as explicitly
    checked (2026-08-19 mass microscope upload incident).

    Rules applied to images NOT yet in the ledger (images already in the
    ledger are never rewritten):

    * Active tombstone (DELETE_PENDING / DELETED) → excluded + initialized.
      Tombstone lifecycle itself is untouched.
    * Field (and any non-microscope) image → desired by default (left out of
      the excluded set) + initialized. A pre-existing explicit exclusion is
      preserved.
    * Microscope image whose magnification group already contains ANY
      initialized member → excluded + initialized. No replacement keeper is
      chosen: the user may have deliberately unchecked every member of that
      group, and a silent re-enable is exactly the failure being fixed.
    * Microscope image in a group with NO initialized member (a genuinely
      new group, or legacy pre-ledger rows):
        - Legacy inference (explicit "checked" history was never stored
          before the ledger existed): a member that is cloud-identified,
          NOT a registered metadata-only anchor, and NOT tombstoned is
          treated as byte-backed / previously selected — it stays desired.
        - If no such member exists, one deterministic keeper is chosen: the
          first member by (sort_order NULLS LAST, id) that is neither
          explicitly excluded nor tombstoned.
        - Every other uninitialized member is excluded.
      Registered metadata-only anchors are never inferred as byte-backed;
      unless chosen as the deterministic keeper they default local-only,
      and their anchor identity/measurements are untouched either way.
    * In every branch, a cloud-identified non-anchor member without a
      tombstone is never defaulted into the excluded set — its bytes (or
      its explicit selection) already exist; only an explicit user action
      may exclude it.

    Idempotent, mutates local settings only (never cloud I/O, never image
    rows, never tombstones). Returns a small summary dict for diagnostics:
    ``{"seeded_desired": int, "seeded_excluded": int}``.
    """
    summary = {"seeded_desired": 0, "seeded_excluded": 0}
    obs_id = _safe_int(observation_id)
    if obs_id <= 0:
        return summary

    conn = get_connection()
    try:
        conn.row_factory = sqlite3.Row
        existing_cols = {
            str(info["name"])
            for info in conn.execute("PRAGMA table_info(images)").fetchall()
        }
        if "id" not in existing_cols:
            return summary
        wanted = [
            col
            for col in (
                "id", "image_type", "cloud_id", "synced_at",
                "objective_name",
                "sort_order",
            )
            if col in existing_cols
        ]
        order_bits: list[str] = []
        if "sort_order" in existing_cols:
            order_bits.append("CASE WHEN sort_order IS NULL THEN 1 ELSE 0 END")
            order_bits.append("sort_order")
        order_bits.append("id")
        rows = [
            dict(row)
            for row in conn.execute(
                f"SELECT {', '.join(wanted)} FROM images WHERE observation_id = ? "
                f"ORDER BY {', '.join(order_bits)}",
                (obs_id,),
            ).fetchall()
        ]
    finally:
        conn.close()

    if not rows:
        return summary

    ledger = _cloud_image_storage_intent_initialized_ids(obs_id)
    uninitialized_ids = {
        _safe_int(row.get("id"))
        for row in rows
        if _safe_int(row.get("id")) > 0 and _safe_int(row.get("id")) not in ledger
    }
    if not uninitialized_ids:
        return summary

    excluded = _cloud_image_storage_excluded_image_ids(obs_id)
    anchor_ids = _cloud_metadata_only_image_ids(obs_id)
    new_excluded: set[int] = set(excluded)
    new_ledger: set[int] = set(ledger)

    tombstone_cache: dict[str, bool] = {}

    def _has_active_tombstone(row: dict) -> bool:
        cloud_id = str(row.get("cloud_id") or '').strip()
        if not cloud_id:
            return False
        if cloud_id not in tombstone_cache:
            tombstone_cache[cloud_id] = bool(
                ImageDB.get_image_tombstone_by_deleted_cloud_id(cloud_id)
            )
        return tombstone_cache[cloud_id]

    def _inferred_byte_backed(row: dict) -> bool:
        # Legacy inference documented in the docstring: before the ledger,
        # cloud identity (minus registered anchors and tombstones) is the
        # only durable evidence of a prior byte upload / explicit selection.
        image_id = _safe_int(row.get("id"))
        return (
            bool(str(row.get("cloud_id") or '').strip())
            and image_id not in anchor_ids
            and not _has_active_tombstone(row)
        )

    microscope_groups: dict[str, list[dict]] = {}
    for row in rows:
        image_id = _safe_int(row.get("id"))
        if image_id <= 0:
            continue
        image_type = str(row.get("image_type") or '').strip().lower()
        if image_type == "microscope":
            microscope_groups.setdefault(
                _microscope_group_key_from_row(row), []
            ).append(row)
            continue
        if image_id not in uninitialized_ids:
            continue
        if _has_active_tombstone(row):
            new_excluded.add(image_id)
        new_ledger.add(image_id)

    for group_rows in microscope_groups.values():
        pending_members = [
            row for row in group_rows
            if _safe_int(row.get("id")) in uninitialized_ids
        ]
        if not pending_members:
            continue
        group_has_initialized_member = any(
            _safe_int(row.get("id")) in ledger for row in group_rows
        )
        keeper_ids: set[int] = set()
        if not group_has_initialized_member:
            keeper_ids = {
                _safe_int(row.get("id"))
                for row in group_rows
                if _inferred_byte_backed(row)
                and _safe_int(row.get("id")) not in excluded
            }
            if not keeper_ids:
                for row in group_rows:
                    image_id = _safe_int(row.get("id"))
                    if image_id <= 0 or image_id in excluded:
                        continue
                    if _has_active_tombstone(row):
                        continue
                    keeper_ids = {image_id}
                    break
        for row in pending_members:
            image_id = _safe_int(row.get("id"))
            if image_id <= 0:
                continue
            new_ledger.add(image_id)
            if image_id in keeper_ids:
                continue
            if _has_active_tombstone(row):
                new_excluded.add(image_id)
                continue
            if _inferred_byte_backed(row):
                # Bytes/selection already exist on cloud — never default an
                # uploaded image into the excluded set.
                continue
            new_excluded.add(image_id)

    if new_excluded != excluded:
        _set_cloud_image_storage_excluded_image_ids(obs_id, new_excluded)
    if new_ledger != ledger:
        _set_cloud_image_storage_intent_initialized_ids(obs_id, new_ledger)

    seeded = new_ledger - ledger
    summary["seeded_excluded"] = len([i for i in seeded if i in new_excluded])
    summary["seeded_desired"] = len(seeded) - summary["seeded_excluded"]
    return summary


def _initialize_cloud_image_storage_desired_state_for_observation(
    observation_id: int | str,
) -> None:
    """Back-compat alias for the canonical per-image intent initializer.

    Existing call sites (gallery load, measure gallery load, sync-time
    prerequisite) keep this name; all semantics live in
    :func:`_ensure_cloud_image_storage_intent_initialized`.
    """
    _ensure_cloud_image_storage_intent_initialized(observation_id)


def _reconcile_local_image_cloud_id(
    local_image_id: int | str,
    cloud_image_id: str,
    *,
    mark_synced: bool = False,
) -> bool:
    """Persist ``cloud_image_id`` onto the local images row.

    Returns ``True`` when the row was updated because its ``cloud_id`` was
    missing or stale. This makes metadata-only associations of an existing
    remote cloud image persistent: previously-synced local rows whose
    ``cloud_id`` was lost get re-linked instead of being re-dirtied on every
    sync. No image bytes are uploaded here — only the local link is restored.
    """
    try:
        image_id = int(local_image_id)
    except Exception:
        image_id = 0
    cloud_image_id = str(cloud_image_id or '').strip()
    if image_id <= 0 or not cloud_image_id:
        return False
    conn = get_connection()
    try:
        row = conn.execute('SELECT cloud_id FROM images WHERE id = ?', (image_id,)).fetchone()
        if row is None:
            return False
        existing = str((row['cloud_id'] if isinstance(row, sqlite3.Row) else row[0]) or '').strip()
        if existing == cloud_image_id:
            return False
        if mark_synced:
            conn.execute(
                'UPDATE images SET cloud_id = ?, synced_at = ? WHERE id = ?',
                (cloud_image_id, datetime.now(timezone.utc).isoformat(), image_id),
            )
        else:
            conn.execute(
                'UPDATE images SET cloud_id = ? WHERE id = ?',
                (cloud_image_id, image_id),
            )
        conn.commit()
        return True
    finally:
        conn.close()


def _local_tombstoned_cloud_image_ids(cloud_image_ids: list[str] | tuple[str, ...] | set[str] | None = None) -> set[str]:
    tombstones = get_image_tombstones_by_deleted_cloud_id(cloud_image_ids)
    return set(tombstones.keys())


def _local_tombstoned_local_image_ids(local_image_ids: list[int] | tuple[int, ...] | set[int] | None = None) -> set[int]:
    tombstones = get_image_tombstones_by_local_image_id(local_image_ids)
    return set(tombstones.keys())


def _pull_remote_images_for_sync(client: "SporelyCloudClient", cloud_id: str) -> list[dict]:
    """Fetch cloud image rows including deleted ones so tombstones can be recorded."""
    cloud_value = str(cloud_id or '').strip()
    if not cloud_value:
        return []
    return [
        dict(row or {})
        for row in (client.pull_image_metadata(cloud_value, include_deleted_for_sync=True) or [])
    ]


def _record_remote_image_tombstones(
    remote_images,
    *,
    local_observation_id: int | None = None,
    cloud_observation_id: str | None = None,
) -> set[str]:
    # Option A: keep the local active image row visible for now.
    # Recording the tombstone is enough to block reupload/recreation; local
    # hiding/deletion and any explicit confirmation flow stay deferred.
    rows = [dict(row or {}) for row in (remote_images or [])]
    tombstone_rows = [
        row
        for row in rows
        if str(row.get("id") or "").strip() and str(row.get("deleted_at") or "").strip()
    ]
    if not tombstone_rows:
        return set()

    tombstone_cloud_ids = [
        str(row.get("id") or "").strip()
        for row in tombstone_rows
        if str(row.get("id") or "").strip()
    ]
    existing_tombstones = get_image_tombstones_by_deleted_cloud_id(tombstone_cloud_ids)
    new_tombstone_cloud_ids = [
        cloud_id
        for cloud_id in dict.fromkeys(tombstone_cloud_ids)
        if cloud_id not in existing_tombstones
    ]
    _increment_sync_summary(_cloud_sync_current_summary(), 'images_deleted_remote', len(new_tombstone_cloud_ids))
    deleted_cloud_ids: set[str] = set()
    conn = get_connection()
    try:
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        try:
            cursor.execute("PRAGMA table_info(images)")
            image_columns = {str(row[1] or "") for row in cursor.fetchall()}
        except Exception:
            image_columns = set()

        has_cloud_id = "cloud_id" in image_columns
        select_columns = ["id"]
        for column in ("observation_id", "image_type", "filepath", "original_filepath"):
            if column in image_columns:
                select_columns.append(column)

        local_image_sql = (
            f"SELECT {', '.join(select_columns)} FROM images WHERE cloud_id = ? LIMIT 1"
            if has_cloud_id
            else None
        )
        local_desktop_image_sql = (
            f"SELECT {', '.join(select_columns)} FROM images WHERE id = ? LIMIT 1"
        )

        for remote_image in tombstone_rows:
            cloud_image_id = str(remote_image.get("id") or "").strip()
            deleted_at = str(remote_image.get("deleted_at") or "").strip()
            resolved_local_observation_id = None
            if local_observation_id is not None:
                local_observation_id_value = _safe_int(local_observation_id)
                if local_observation_id_value > 0:
                    resolved_local_observation_id = local_observation_id_value
            local_image_row = None
            if local_image_sql:
                local_image_row = cursor.execute(local_image_sql, (cloud_image_id,)).fetchone()
            if local_image_row is None:
                desktop_image_id = _safe_int(remote_image.get("desktop_id"))
                if desktop_image_id > 0:
                    local_image_row = cursor.execute(
                        local_desktop_image_sql,
                        (desktop_image_id,),
                    ).fetchone()

            image_type = None
            filepath = None
            original_filepath = None
            if local_image_row:
                local_image_data = dict(local_image_row)
                if resolved_local_observation_id is None and "observation_id" in local_image_data:
                    local_observation_id_value = _safe_int(local_image_data.get("observation_id"))
                    if local_observation_id_value > 0:
                        resolved_local_observation_id = local_observation_id_value
                image_type = str(local_image_data.get("image_type") or "").strip() or None
                filepath = str(local_image_data.get("filepath") or "").strip() or None
                original_filepath = str(local_image_data.get("original_filepath") or "").strip() or None

            _upsert_image_tombstone(
                cursor,
                deleted_cloud_id=cloud_image_id,
                deleted_at=deleted_at,
                deleted_storage_path=_normalize_cloud_media_key(remote_image.get("storage_path")) or None,
                deleted_observation_cloud_id=(
                    str(cloud_observation_id or remote_image.get("observation_id") or "").strip() or None
                ),
                local_observation_id=resolved_local_observation_id,
                # A remote deletion must not classify a matching active image
                # as locally deleted.  The upsert keeps any pre-existing ID
                # from a genuine local deletion via COALESCE.
                local_image_id=None,
                image_type=image_type,
                filepath=filepath,
                original_filepath=original_filepath,
            )
            deleted_cloud_ids.add(cloud_image_id)

        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()

    return deleted_cloud_ids


def _tombstoned_cloud_image_warning(local_id: int | None, cloud_image_id: str) -> str:
    return f"obs {int(local_id or 0)}: skipped cloud image {cloud_image_id} because it has a local tombstone"


def _remote_images_missing_locally(local_id: int, remote_images: list[dict] | None) -> list[dict]:
    """Return cloud images that should exist locally but are missing or unreadable."""
    pullable_remote_images = [
        dict(row or {})
        for row in (remote_images or [])
        if should_pull_cloud_image_to_desktop(row)
        and not str(row.get('deleted_at') or '').strip()
        and str(row.get('id') or '').strip()
    ]
    if not pullable_remote_images:
        return []

    local_images = ImageDB.get_images_for_observation(int(local_id))
    local_cloud_map = {
        str(img.get('cloud_id') or '').strip(): img
        for img in local_images
        if should_pull_cloud_image_to_desktop(img)
        if str(img.get('cloud_id') or '').strip()
    }
    tombstoned_cloud_ids = _local_tombstoned_cloud_image_ids(
        [str(row.get('id') or '').strip() for row in pullable_remote_images]
    )

    missing_remote_images: list[dict] = []
    for remote_image in pullable_remote_images:
        cloud_image_id = str(remote_image.get('id') or '').strip()
        if not cloud_image_id or cloud_image_id in tombstoned_cloud_ids:
            continue
        local_image = local_cloud_map.get(cloud_image_id)
        if local_image is None:
            missing_remote_images.append(remote_image)
            continue
        if (
            _is_metadata_only_microscope_cloud_image(remote_image)
            and _is_local_metadata_only_microscope_anchor(local_image)
        ):
            continue
        if _resolve_existing_local_image_asset_path(local_image.get('filepath')) is None:
            missing_remote_images.append(remote_image)
    return missing_remote_images


def _push_pending_image_tombstones(client: "SporelyCloudClient") -> list[str]:
    warnings: list[str] = []
    # Compatibility repair: older versions may have queued a cloud deletion
    # merely because an external-publish checkbox was unchecked.
    repaired = reconcile_legacy_publish_exclusion_tombstones()
    repaired_pending = int(repaired.get("pending") or 0)
    repaired_synced = int(repaired.get("synced") or 0)
    if repaired_pending or repaired_synced:
        print(
            "[cloud_sync] Reconciled legacy external-publish tombstones: "
            f"{repaired_pending} pending, {repaired_synced} previously synced"
        )
    pending = list_pending_image_tombstones()
    if pending:
        print(f"[cloud_sync] Image tombstones pending push: {len(pending)}", flush=True)
    protected_count = 0
    soft_deleted: list[str] = []
    for tombstone in pending:
        cloud_image_id = str(tombstone.get('deleted_cloud_id') or '').strip()
        if not cloud_image_id:
            continue
        local_image_id = _safe_int(tombstone.get('local_image_id'))
        if (
            local_image_id > 0
            and microscope_image_requires_public_spore_anchor(local_image_id)
        ):
            try:
                ImageDB.clear_image_tombstone_by_deleted_cloud_id(cloud_image_id)
            except Exception as exc:
                warning = (
                    f"obs {int(tombstone.get('local_observation_id') or 0)}: "
                    f"could not cancel protected microscope anchor tombstone "
                    f"{cloud_image_id}: {exc}"
                )
                warnings.append(warning)
                print(f'[cloud_sync] Warning: {warning}')
            else:
                protected_count += 1
                print(
                    f'[cloud_sync] Cancelled tombstone for microscope image '
                    f'{local_image_id}: public spore metadata anchor required',
                    flush=True,
                )
            continue
        deleted_at = str(tombstone.get('deleted_at') or '').strip() or datetime.now(timezone.utc).isoformat()
        try:
            client.soft_delete_image(cloud_image_id, deleted_at)
        except Exception as exc:
            warning = (
                f"obs {int(tombstone.get('local_observation_id') or 0)}: "
                f"could not sync cloud image tombstone {cloud_image_id}: {exc}"
            )
            warnings.append(warning)
            print(f'[cloud_sync] Warning: {warning}')
            continue
        try:
            mark_image_tombstone_synced(cloud_image_id)
        except Exception as exc:
            warning = (
                f"obs {int(tombstone.get('local_observation_id') or 0)}: "
                f"synced cloud image tombstone {cloud_image_id} but could not mark it locally: {exc}"
            )
            warnings.append(warning)
            print(f'[cloud_sync] Warning: {warning}')
            continue
        soft_deleted.append(cloud_image_id)
    if pending:
        # One summary line makes the delete flow diagnosable from logs
        # without dumping cloud IDs into normal-path noise.
        print(
            "[cloud_sync] Image tombstone push complete: "
            f"soft_deleted={len(soft_deleted)}, "
            f"protected_microscope={protected_count}, "
            f"failed={len(warnings)}",
            flush=True,
        )
        if soft_deleted:
            print(
                "[cloud_sync] Soft-deleted cloud image ids: "
                + ", ".join(soft_deleted),
                flush=True,
            )
    return warnings


def _load_local_cloud_media_signature(observation_id: int | str) -> str:
    return str(SettingsDB.get_setting(_cloud_local_media_signature_key(observation_id), '') or '').strip()


def _store_local_cloud_media_signature(observation_id: int | str, signature: str) -> None:
    SettingsDB.set_setting(
        _cloud_local_media_signature_key(observation_id),
        str(signature or '').strip(),
    )


def _pull_remote_measurements_for_images(
    client: "SporelyCloudClient",
    image_cloud_ids: list[str],
) -> list[dict]:
    fetcher = getattr(client, 'pull_measurements_for_images', None)
    if not callable(fetcher):
        return []
    rows = fetcher(image_cloud_ids)
    return [dict(row or {}) for row in (rows or [])]


def _group_remote_measurements_by_observation(
    remote_images: list[dict] | None,
    remote_measurements: list[dict] | None,
) -> dict[str, list[dict]]:
    image_to_obs: dict[str, str] = {}
    for image_row in (remote_images or []):
        cloud_image_id = str(image_row.get('id') or '').strip()
        cloud_obs_id = str(image_row.get('observation_id') or '').strip()
        if cloud_image_id and cloud_obs_id:
            image_to_obs[cloud_image_id] = cloud_obs_id
    grouped: dict[str, list[dict]] = {}
    for measurement_row in (remote_measurements or []):
        cloud_image_id = str(measurement_row.get('image_id') or '').strip()
        cloud_obs_id = image_to_obs.get(cloud_image_id)
        if not cloud_obs_id:
            continue
        grouped.setdefault(cloud_obs_id, []).append(dict(measurement_row or {}))
    for rows in grouped.values():
        rows.sort(
            key=lambda row: (
                str(row.get('image_id') or ''),
                _safe_int(row.get('desktop_id')),
                str(row.get('id') or ''),
            )
        )
    return grouped


def _cloud_child_safety_pull_due(now: datetime | None = None) -> tuple[bool, str | None]:
    """Return whether the periodic child-reconciliation backstop is due.

    The 24h TTL safety pull is defense-in-depth: it catches anything that falls
    outside the updated_at cursor's coverage — e.g. hard-deleted rows that leave
    no updated_at trace, measurement edge-cases where image_id mapping may differ,
    or any future schema event the cursor does not track.  It is NOT the primary
    detection mechanism; the cursor probe handles the common case cheaply.
    """
    raw_last = get_app_settings().get(_CLOUD_LAST_CHILD_SAFETY_PULL_AT_SETTING)
    last_text = str(raw_last or '').strip() or None
    if last_text is None:
        return True, None

    last_at = _parse_sync_timestamp(last_text)
    if last_at is None:
        return True, last_text

    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    stale_before = current.astimezone(timezone.utc) - timedelta(
        hours=_CLOUD_CHILD_SAFETY_PULL_INTERVAL_HOURS
    )
    return last_at <= stale_before, last_text


def _load_child_change_cursor() -> dict | None:
    """Return stored child-change cursor or None if missing/old-format (bootstrap needed).

    Returns None for:
    - missing key
    - parse failures
    - cursors without a matching 'v' version marker (format/semantic change —
      treat conservatively to avoid missing metadata updates that the old
      created_at/deleted_at cursor never tracked).
    """
    raw = get_app_settings().get(_CLOUD_CHILD_CHANGE_CURSOR_SETTING)
    if not raw:
        return None
    try:
        data = json.loads(str(raw)) if isinstance(raw, str) else raw
        if (
            isinstance(data, dict)
            and data.get('v') == _CHILD_CHANGE_CURSOR_VERSION
            and isinstance(data.get('images'), dict)
            and isinstance(data.get('measurements'), dict)
            and 'ts' in data['images']
            and 'id' in data['images']
            and 'ts' in data['measurements']
            and 'id' in data['measurements']
        ):
            return data
    except Exception:
        pass
    return None


def _store_child_change_cursor(cursor: dict) -> None:
    """Persist child-change cursor to app_settings (always written with version marker)."""
    payload = dict(cursor)
    payload['v'] = _CHILD_CHANGE_CURSOR_VERSION
    update_app_settings({_CLOUD_CHILD_CHANGE_CURSOR_SETTING: json.dumps(payload)})


def _child_change_cursor_id_key(rid) -> tuple:
    """Ordering key for child-change cursor row ids.

    Cloud row ids are numeric (bigint), but the cursor stores them as strings.
    Plain string comparison misorders across digit-length boundaries
    ('10000' < '9999'), which would silently drop genuinely new rows from the
    strict tuple filter and pick the wrong maximum when advancing the cursor.
    Empty (no position yet) sorts before every id; non-numeric ids (defensive)
    sort after all numeric ids, lexicographically — matching nothing the server
    currently produces but keeping the ordering total.
    """
    s = str(rid or '').strip()
    if not s:
        return (-1, 0, '')
    if s.isdigit():
        return (0, len(s), s)
    return (1, 0, s)


def _cloud_measurement_remote_verification_due(
    *,
    full_pull: bool,
    child_safety_pull: bool,
    safety_pull_due: bool,
) -> tuple[bool, str]:
    """Select deep stamped-ID verification without weakening local repair."""
    if full_pull:
        return True, 'full_pull'

    settings = get_app_settings()
    stored_version = _safe_int(settings.get(_CLOUD_MEASUREMENT_RECONCILE_VERSION_SETTING))
    if stored_version != _CLOUD_MEASUREMENT_RECONCILE_VERSION:
        return True, f'version_{stored_version}_to_{_CLOUD_MEASUREMENT_RECONCILE_VERSION}'

    if child_safety_pull and safety_pull_due:
        return True, 'child_safety_pull'
    return False, 'fresh_watermark'


def _cloud_pending_image_repair_scan_due(
    now: datetime | None = None,
) -> tuple[bool, str]:
    """Schedule the legacy/interrupted-state scan outside ordinary no-op syncs."""
    stored_version = _safe_int(
        SettingsDB.get_setting(_CLOUD_PENDING_IMAGE_REPAIR_VERSION_SETTING, '')
    )
    if stored_version != _CLOUD_PENDING_IMAGE_REPAIR_VERSION:
        return True, f'version_{stored_version}_to_{_CLOUD_PENDING_IMAGE_REPAIR_VERSION}'

    last_text = str(
        SettingsDB.get_setting(_CLOUD_PENDING_IMAGE_REPAIR_AT_SETTING, '') or ''
    ).strip()
    last_at = _parse_sync_timestamp(last_text)
    if last_at is None:
        return True, 'missing_or_invalid_watermark'

    current = now or datetime.now(timezone.utc)
    if current.tzinfo is None:
        current = current.replace(tzinfo=timezone.utc)
    stale_before = current.astimezone(timezone.utc) - timedelta(
        hours=_CLOUD_PENDING_IMAGE_REPAIR_INTERVAL_HOURS
    )
    if last_at <= stale_before:
        return True, 'stale_watermark'
    return False, 'fresh_watermark'


def _record_cloud_pending_image_repair_scan_complete() -> bool:
    completed_at = datetime.now(timezone.utc).isoformat()
    try:
        SettingsDB.set_setting(
            _CLOUD_PENDING_IMAGE_REPAIR_VERSION_SETTING,
            str(_CLOUD_PENDING_IMAGE_REPAIR_VERSION),
        )
        SettingsDB.set_setting(_CLOUD_PENDING_IMAGE_REPAIR_AT_SETTING, completed_at)
    except Exception as exc:
        print(
            f'[cloud_sync] pending image repair watermark persist failed: {exc}',
            flush=True,
        )
        return False
    return True


_PUSH_SUMMARY_REMOTE_LIST_REUSE_SAFE_POSITIVE_KEYS = frozenset({
    'calibrations_skipped_noop',
    'calibration_remote_lookups',
})


def _push_phase_requires_remote_observation_refresh(
    calibration_push_result: dict | None,
    push_result: dict | None,
) -> bool:
    """Return False only when push results prove no cloud mutation occurred."""
    calibration_data = dict(calibration_push_result or {})
    push_data = dict(push_result or {})
    if calibration_data.get('errors') or push_data.get('errors'):
        return True

    required_zero_values = (
        calibration_data.get('pushed'),
        push_data.get('pushed'),
        push_data.get('total'),
    )
    try:
        if any(int(value) != 0 for value in required_zero_values):
            return True
    except (TypeError, ValueError):
        return True

    for key in ('spore_measurement_reconcile', 'spore_summary_reconcile'):
        reconciliation = push_data.get(key)
        if not isinstance(reconciliation, dict):
            return True
        try:
            if int(reconciliation.get('attempted')) != 0:
                return True
        except (TypeError, ValueError):
            return True

    summary = push_data.get('sync_summary')
    if not isinstance(summary, dict):
        return True
    for key, value in summary.items():
        if key in _PUSH_SUMMARY_REMOTE_LIST_REUSE_SAFE_POSITIVE_KEYS:
            continue
        if _sync_summary_value(summary, key) > 0:
            return True
    return False


def sync_all(
    client: SporelyCloudClient,
    progress_cb: ProgressCallback | None = None,
    sync_images: bool = True,
    materialize_remote_images: bool = True,
    prepare_images_cb: PreparedImagesCallback | None = None,
    full_pull: bool = True,
    child_safety_pull: bool = False,
    pull_only: bool = False,
) -> dict:
    """Run a full bidirectional sync: push local changes then pull remote ones.

    ``full_pull=False`` enables the "no-op fast path" appropriate for background
    / Refresh sync: the pull step only touches observations whose remote
    ``updated_at`` is newer than the local ``synced_at``, skipping the bulk
    image-metadata + measurement prefetches that dominate no-op sync time.
    Spore-summary reconciliation across all synced observations is also
    skipped — per-observation summaries still sync inside push for locally
    dirty rows. ``child_safety_pull=True`` periodically upgrades only the pull
    phase to a metadata-only deep reconciliation so child changes cannot stay
    hidden indefinitely when a parent timestamp was not bumped.
    """
    profiler = CloudSyncProfiler() if _cloud_sync_profile_enabled() else None
    profile_token = None
    if profiler is not None:
        profile_token = _CLOUD_SYNC_PROFILE_CONTEXT.set(profiler)
    sync_summary = _new_sync_summary()
    summary_token = _CLOUD_SYNC_SUMMARY_CONTEXT.set(sync_summary)
    progress_trace = {'start': _cloud_sync_perf_counter(), 'last_t': None, 'last_msg': None}
    progress_trace_token = _CLOUD_SYNC_PROGRESS_TRACE_CONTEXT.set(progress_trace)

    sync_error: Exception | None = None
    result: dict | None = None
    try:
        # Safety check: ensure this DB belongs to the current user
        with _cloud_sync_phase_scope(profiler, 'ensure_database_linked_to_cloud_user'):
            ensure_database_linked_to_cloud_user(client)

        if pull_only:
            # Download from Cloud: strict cloud → desktop. Skip both push
            # phases entirely and wrap the client so any accidental write
            # fails closed. This branch shares the pull implementation with
            # normal sync — no parallel engine.
            pull_only_client = (
                client
                if isinstance(client, PullOnlyCloudClient)
                else PullOnlyCloudClient(client)
            )
            progress_state: dict = {'done': 0, 'total': 0}
            _set_progress_phase(progress_state, 'auth')
            _emit_progress(progress_cb, "Connecting to Sporely Cloud...", progress_state)
            _emit_progress(progress_cb, "Loading cloud observations…", progress_state)
            remote_obs = pull_only_client.list_remote_observations()
            with _cloud_sync_phase_scope(profiler, 'pull_all'):
                pull_result = pull_all(
                    pull_only_client,
                    progress_cb=progress_cb,
                    progress_state=progress_state,
                    remote_obs=remote_obs,
                    sync_calibrations=True,
                    materialize_remote_images=materialize_remote_images,
                    sync_images=sync_images,
                    full_pull=True,
                    pull_only=True,
                )
            # Import lazily: the typed adapter depends on cloud-sync's public
            # error classes, so a module-level import would create a cycle.
            from utils.reference_cloud_sync import (
                merge_reference_sync_result,
                sync_reference_library,
            )

            with _cloud_sync_phase_scope(profiler, 'reference_sync'):
                reference_result = sync_reference_library(
                    pull_only_client, pull_only=True
                )
            _set_progress_phase(progress_state, 'finalize', phase_total=1)
            _advance_progress(progress_state, 1)
            _emit_progress(progress_cb, "Finalizing cloud sync…", progress_state)
            summary_snapshot = dict(sync_summary)
            result = {
                'pushed': 0,
                'pulled': pull_result.get('pulled', 0),
                'calibrations_pushed': 0,
                'calibrations_pulled': pull_result.get('calibrations_pulled', 0),
                'errors': list(pull_result.get('errors') or []),
                'deleted_remote': pull_result.get('deleted_remote', []),
                'sync_summary': summary_snapshot,
                'pull_only': True,
                'images_downloaded': int(summary_snapshot.get('remote_media_materializations', 0) or 0),
                'observations_updated': pull_result.get('pulled', 0),
                # Writes that actually reached the network. Under pull-only
                # this is always 0 — the wrapper fails closed on every writer
                # and source-level gates prevent even the wrapper from being
                # reached in the normal flow.
                'cloud_writes_completed': 0,
                # Writes the wrapper blocked (defence in depth). Should also
                # be empty once source-level suppression is in place; any
                # entry here indicates a new pull-side write path that needs
                # to be gated at its source.
                'blocked_write_attempts': list(pull_only_client.write_attempts),
            }
            merge_reference_sync_result(result, reference_result)
            return result

        # Progress state feeds a weighted global bar: each phase maps onto a
        # fixed percentage range so the bar never sits at 99% while real work
        # is still running. Sub-functions update the per-phase (done, total)
        # counters; _emit_progress projects that onto the 0–100 range.
        progress_state: dict = {'done': 0, 'total': 0}
        _set_progress_phase(progress_state, 'auth')
        _emit_progress(progress_cb, "Connecting to Sporely Cloud...", progress_state)

        # Pre-fetch remote metadata once to reuse in both phases
        _emit_progress(progress_cb, "Loading cloud observations…", progress_state)
        with _cloud_sync_phase_scope(profiler, 'list_remote_observations'):
            remote_obs = client.list_remote_observations()
        _emit_progress(progress_cb, "Loading cloud calibrations…", progress_state)
        with _cloud_sync_phase_scope(profiler, 'list_remote_calibrations'):
            remote_calibrations = client.list_remote_calibrations()

        _set_progress_phase(progress_state, 'calibration_push')
        with _cloud_sync_phase_scope(profiler, 'push_calibrations'):
            calibration_push_result = push_calibrations(
                client,
                progress_cb=progress_cb,
                progress_state=progress_state,
                remote_calibrations=remote_calibrations,
            )

        safety_pull_due = False
        safety_pull_last = None
        if child_safety_pull and not full_pull:
            safety_pull_due, safety_pull_last = _cloud_child_safety_pull_due()
        verify_stamped_measurements, measurement_verify_reason = (
            _cloud_measurement_remote_verification_due(
                full_pull=full_pull,
                child_safety_pull=child_safety_pull,
                safety_pull_due=safety_pull_due,
            )
        )
        print(
            f'[cloud_sync] spore measurement remote verification: '
            f'{"enabled" if verify_stamped_measurements else "skipped"} '
            f'reason={measurement_verify_reason}',
            flush=True,
        )

        # Phase 1: Push local edits to the cloud
        with _cloud_sync_phase_scope(profiler, 'push_all'):
            push_result = push_all(
                client,
                progress_cb=progress_cb,
                sync_images=sync_images,
                prepare_images_cb=prepare_images_cb,
                progress_state=progress_state,
                remote_obs=remote_obs,
                sync_calibrations=False,
                full_pull=full_pull,
                verify_stamped_measurements=verify_stamped_measurements,
            )

        # Refresh after any push-side cloud mutation so pull comparisons see
        # the resulting parent timestamps. A fully-described zero-candidate,
        # zero-reconciliation push can safely reuse the initial list.
        _set_progress_phase(progress_state, 'refresh_remote')
        if _push_phase_requires_remote_observation_refresh(
            calibration_push_result,
            push_result,
        ):
            _emit_progress(progress_cb, "Loading cloud observations…", progress_state)
            refresh_start = _cloud_sync_perf_counter()
            with _cloud_sync_phase_scope(profiler, 'refresh_remote_observations_after_push'):
                remote_obs = client.list_remote_observations()
            refresh_elapsed = _cloud_sync_perf_counter() - refresh_start
            print(
                f"[cloud_sync] observation preflight: remote observations refreshed "
                f"count={len(remote_obs or [])} duration={refresh_elapsed * 1000:.0f}ms",
                flush=True,
            )
        else:
            _emit_progress(
                progress_cb,
                "Cloud observations unchanged; reusing loaded list…",
                progress_state,
            )
            print(
                f"[cloud_sync] observation preflight: remote observations reused "
                f"count={len(remote_obs or [])} reason=push_phase_proven_no_cloud_mutation",
                flush=True,
            )

        if child_safety_pull and not full_pull:
            if safety_pull_due:
                print(
                    f"[cloud_sync] child-change safety pull: "
                    f"reason=stale_child_watermark last={safety_pull_last or 'missing'} "
                    f"interval_hours={_CLOUD_CHILD_SAFETY_PULL_INTERVAL_HOURS}",
                    flush=True,
                )
            else:
                print(
                    f"[cloud_sync] child-change safety pull skipped: "
                    f"fresh watermark last={safety_pull_last}",
                    flush=True,
                )

        forced_pull_cloud_ids: frozenset[str] = frozenset()
        child_probe_ok = False
        child_probe_rows: dict[str, list] = {'images': [], 'measurements': []}
        # Pre-scan seed captured before the authoritative bootstrap scan so that
        # nothing written between scan start and cursor seed is skipped on the
        # next probe. None means bootstrap did not run or pre-capture failed.
        _pre_scan_img_seed: dict | None = None
        _pre_scan_meas_seed: dict | None = None
        _bootstrap_needed = False

        if child_safety_pull and not full_pull:
            cursor = _load_child_change_cursor()
            if cursor is None:
                # No valid cursor (missing or old format): force the authoritative
                # child safety scan immediately, regardless of the 24h TTL.
                # Capture remote max(updated_at, id) BEFORE the scan so that rows
                # written between scan start and cursor seed are not skipped.
                _bootstrap_needed = True
                print('[cloud_sync] child-change cursor missing/old: forcing authoritative bootstrap scan', flush=True)
                try:
                    img_seed_rows = client._get(
                        f'observation_images?user_id=eq.{client.user_id}'
                        f'&select=id,updated_at'
                        f'&order=updated_at.desc,id.desc&limit=1'
                    )
                    meas_seed_rows = client._get(
                        f'spore_measurements?user_id=eq.{client.user_id}'
                        f'&select=id,measured_at'
                        f'&order=measured_at.desc&limit=1'
                    )
                    _pre_scan_img_seed = img_seed_rows[0] if img_seed_rows else {}
                    _pre_scan_meas_seed = meas_seed_rows[0] if meas_seed_rows else {}
                except Exception as e:
                    print(f'[cloud_sync] child-change pre-scan seed capture failed (non-fatal): {e}', flush=True)
            else:
                try:
                    img_rows = client.list_image_changes_since(cursor['images']['ts'], cursor['images']['id'])
                    meas_rows = client.list_measurement_changes_since(cursor['measurements']['ts'], cursor['measurements']['id'])
                    child_probe_ok = True
                    child_probe_rows['images'] = img_rows
                    child_probe_rows['measurements'] = meas_rows
                    _forced: set[str] = set()
                    for r in img_rows:
                        _forced.add(str(r['observation_id']))
                    for r in meas_rows:
                        if r.get('observation_id') is not None:
                            _forced.add(str(r['observation_id']))
                    forced_pull_cloud_ids = frozenset(_forced)
                    changed = 'yes' if forced_pull_cloud_ids else 'no'
                    print(
                        f"[cloud_sync] child-change watermark check: "
                        f"local_images=({cursor['images']['ts']}, {cursor['images']['id'] or '<none>'}) "
                        f"local_measurements=({cursor['measurements']['ts']}, {cursor['measurements']['id'] or '<none>'}) "
                        f"remote_rows={len(img_rows)+len(meas_rows)} changed={changed}",
                        flush=True,
                    )
                    if forced_pull_cloud_ids:
                        print(
                            f'[cloud_sync] child-change pull candidates: '
                            f'rows={len(img_rows)+len(meas_rows)} '
                            f'observations={len(forced_pull_cloud_ids)}',
                            flush=True,
                        )
                except Exception as e:
                    print(f'[cloud_sync] child-change probe failed (non-fatal): {e}', flush=True)

        # Phase 2: Pull cloud edits to the desktop. A due safety pass changes
        # only candidate breadth; media upload and materialization remain
        # controlled by their existing independent flags.
        with _cloud_sync_phase_scope(profiler, 'pull_all'):
            pull_result = pull_all(
                client,
                progress_cb=progress_cb,
                progress_state=progress_state,
                remote_obs=remote_obs,
                sync_calibrations=False,
                materialize_remote_images=materialize_remote_images,
                sync_images=sync_images,
                full_pull=full_pull or safety_pull_due or _bootstrap_needed,
                forced_pull_cloud_ids=forced_pull_cloud_ids,
            )
        # Row-level review issues are a completed reconciliation outcome, not a
        # failed safety pass. Exceptions from auth, transport, or bulk child
        # fetches escape pull_all and therefore never reach this write.
        completed_settings: dict[str, object] = {}
        completed_at = datetime.now(timezone.utc).isoformat()
        if safety_pull_due:
            completed_settings[_CLOUD_LAST_CHILD_SAFETY_PULL_AT_SETTING] = completed_at
        measurement_verification_completed = bool(
            verify_stamped_measurements
            and push_result.get('spore_measurement_reconcile') is not None
        )
        if measurement_verification_completed:
            completed_settings.update({
                _CLOUD_MEASUREMENT_RECONCILE_VERSION_SETTING: _CLOUD_MEASUREMENT_RECONCILE_VERSION,
                _CLOUD_MEASUREMENT_RECONCILE_AT_SETTING: completed_at,
            })
        if completed_settings:
            update_app_settings(completed_settings)

        # Advance child-change cursor after successful pull
        if child_safety_pull and not full_pull and child_probe_ok:
            # Advance images cursor (uses updated_at as authoritative timestamp).
            # Ids compare numerically via _child_change_cursor_id_key so the
            # committed position is the true MAX(updated_at, id) over every
            # inspected row, matching the strict filter's ordering exactly.
            new_img_ts = ''
            new_img_id = ''
            for r in child_probe_rows['images']:
                ts = str(r.get('updated_at') or '')
                rid = str(r.get('id', ''))
                if (ts, _child_change_cursor_id_key(rid)) > (
                    new_img_ts, _child_change_cursor_id_key(new_img_id)
                ):
                    new_img_ts, new_img_id = ts, rid
            # Advance measurements cursor
            new_meas_ts = ''
            new_meas_id = ''
            for r in child_probe_rows['measurements']:
                ts = str(r.get('measured_at') or '')
                rid = str(r.get('id', ''))
                if (ts, _child_change_cursor_id_key(rid)) > (
                    new_meas_ts, _child_change_cursor_id_key(new_meas_id)
                ):
                    new_meas_ts, new_meas_id = ts, rid
            existing_cursor = _load_child_change_cursor()
            if existing_cursor is not None:
                if not new_img_ts:
                    new_img_ts = existing_cursor['images']['ts']
                    new_img_id = existing_cursor['images']['id']
                if not new_meas_ts:
                    new_meas_ts = existing_cursor['measurements']['ts']
                    new_meas_id = existing_cursor['measurements']['id']
            # Only persist when position strictly advanced (avoids a no-op write
            # when the probe returned no rows and existing cursor is unchanged).
            if new_img_ts or new_meas_ts:
                old_img_ts = (existing_cursor or {}).get('images', {}).get('ts', '')
                old_img_id = (existing_cursor or {}).get('images', {}).get('id', '')
                old_meas_ts = (existing_cursor or {}).get('measurements', {}).get('ts', '')
                old_meas_id = (existing_cursor or {}).get('measurements', {}).get('id', '')
                position_changed = (
                    (new_img_ts, new_img_id) != (old_img_ts, old_img_id)
                    or (new_meas_ts, new_meas_id) != (old_meas_ts, old_meas_id)
                )
                if position_changed:
                    _store_child_change_cursor({
                        'images': {'ts': new_img_ts, 'id': new_img_id},
                        'measurements': {'ts': new_meas_ts, 'id': new_meas_id},
                    })

        # Bootstrap seeding: when _bootstrap_needed the full-scan ran above;
        # seed the cursor with the pre-scan max so that rows written between
        # scan start and seed are not skipped on the next probe.
        # If pull_all raised we never reach this block, so a failed scan does not
        # seed — the next explicit sync retries bootstrap (repeated full-scan cost
        # while persistently failing is correct behaviour). If only the pre-scan
        # max capture failed, seeding at EPOCH is the safe fallback: the next
        # probe re-reads everything rather than skipping anything.
        if child_safety_pull and not full_pull and _bootstrap_needed and _load_child_change_cursor() is None:
            try:
                _EPOCH = '1970-01-01T00:00:00+00:00'
                # Use the pre-scan snapshot captured before pull_all ran.
                if _pre_scan_img_seed is not None:
                    r = _pre_scan_img_seed
                    img_ts = str(r.get('updated_at') or '') or _EPOCH
                    img_id = str(r.get('id', ''))
                else:
                    img_ts, img_id = _EPOCH, ''
                if _pre_scan_meas_seed is not None:
                    r = _pre_scan_meas_seed
                    meas_ts = str(r.get('measured_at') or '') or _EPOCH
                    meas_id = str(r.get('id', ''))
                else:
                    meas_ts, meas_id = _EPOCH, ''
                _store_child_change_cursor({
                    'images': {'ts': img_ts, 'id': img_id},
                    'measurements': {'ts': meas_ts, 'id': meas_id},
                })
                print('[cloud_sync] child-change cursor bootstrapped after authoritative scan', flush=True)
            except Exception as e:
                print(
                    f'[cloud_sync] child-change cursor bootstrap seed failed — will retry on next explicit sync: {e}',
                    flush=True,
                )

        _set_progress_phase(progress_state, 'calibration_pull')
        with _cloud_sync_phase_scope(profiler, 'pull_calibrations'):
            calibration_pull_result = pull_calibrations(
                client,
                progress_cb=progress_cb,
                progress_state=progress_state,
                remote_calibrations=remote_calibrations,
            )

        # The observation pull has established any cloud identities required
        # by reference-use reconciliation. Keep this as a sibling executor and
        # import lazily to avoid a cloud-sync/adapter import cycle.
        from utils.reference_cloud_sync import (
            merge_reference_sync_result,
            sync_reference_library,
        )

        with _cloud_sync_phase_scope(profiler, 'reference_sync'):
            reference_result = sync_reference_library(client)

        # Leave the UI on a neutral phase rather than the last per-calibration
        # message while the worker finishes and the table refreshes. The
        # finalize phase is the only slot that may reach 100%.
        _set_progress_phase(progress_state, 'finalize', phase_total=1)
        _advance_progress(progress_state, 1)
        _emit_progress(progress_cb, "Finalizing cloud sync…", progress_state)
        print(
            f"[cloud_sync] sync progress complete "
            f"duration={(_cloud_sync_perf_counter() - progress_trace['start']) * 1000:.0f}ms",
            flush=True,
        )

        # Combine results for the UI summary
        result = {
            'pushed': push_result.get('pushed', 0),
            'pulled': pull_result.get('pulled', 0),
            'calibrations_pushed': calibration_push_result.get('pushed', 0),
            'calibrations_pulled': calibration_pull_result.get('pulled', 0),
            'errors': (
                calibration_push_result.get('errors', [])
                + push_result.get('errors', [])
                + pull_result.get('errors', [])
                + calibration_pull_result.get('errors', [])
            ),
            'deleted_remote': pull_result.get('deleted_remote', []),
        }
        original_sync = push_result.get('original_sync')
        if original_sync is not None:
            result['original_sync'] = original_sync
        result['sync_summary'] = dict(sync_summary)
        merge_reference_sync_result(result, reference_result)
        return result
    except Exception as exc:
        sync_error = exc
        raise
    finally:
        if profiler is not None:
            try:
                profiler.finish(result=result, error=sync_error)
            except Exception:
                pass
            if profile_token is not None:
                try:
                    _CLOUD_SYNC_PROFILE_CONTEXT.reset(profile_token)
                except Exception:
                    pass
        try:
            _CLOUD_SYNC_SUMMARY_CONTEXT.reset(summary_token)
        except Exception:
            pass
        try:
            _CLOUD_SYNC_PROGRESS_TRACE_CONTEXT.reset(progress_trace_token)
        except Exception:
            pass

def _parsed_local_media_signature(signature: str | None) -> dict:
    text = str(signature or '').strip()
    if not text:
        return {}
    try:
        payload = json.loads(text)
    except Exception:
        return {}
    return payload if isinstance(payload, dict) else {}


def _normalized_local_media_signature_payload(
    payload: dict | None,
    *,
    include_measurements: bool = True,
) -> dict:
    normalized = dict(payload or {})
    # These legacy fields affected external publishing or its selection UI,
    # never the clean cloud bytes. Drop them so old stored signatures remain
    # comparable without forcing a one-time WebP regeneration.
    normalized.pop('cloud_media_signature', None)
    normalized.pop('excluded_image_ids_raw', None)
    normalized.pop('gallery_settings_raw', None)
    images = []
    for row in list(normalized.get('images') or []):
        if not isinstance(row, dict):
            continue
        image_payload = dict(row)
        image_payload.pop('sort_order', None)
        for key in _LOCAL_MEDIA_SIGNATURE_OPTIONAL_IMAGE_KEYS:
            image_payload.setdefault(key, None)
        for path_key in ('filepath', 'original_filepath'):
            path_payload = image_payload.get(path_key)
            if isinstance(path_payload, dict):
                normalized_path = dict(path_payload)
                normalized_path.pop('mtime_ns', None)
                image_payload[path_key] = normalized_path
        images.append(image_payload)
    normalized['images'] = sorted(
        images,
        key=lambda row: (
            str(row.get('desktop_id') or ''),
            str(row.get('id') or ''),
            str(row.get('original_filename') or ''),
            str(row.get('image_type') or ''),
        ),
    )
    if not include_measurements:
        normalized.pop('measurements', None)
    return normalized


def _local_media_signatures_match(
    stored_signature: str | None,
    current_signature: str | None,
    *,
    include_measurements: bool = True,
) -> bool:
    stored_text = str(stored_signature or '').strip()
    current_text = str(current_signature or '').strip()
    if not stored_text or not current_text:
        return stored_text == current_text
    if stored_text == current_text:
        return True
    stored_payload = _parsed_local_media_signature(stored_text)
    current_payload = _parsed_local_media_signature(current_text)
    if not stored_payload or not current_payload:
        return False
    return _normalized_local_media_signature_payload(
        stored_payload,
        include_measurements=include_measurements,
    ) == _normalized_local_media_signature_payload(
        current_payload,
        include_measurements=include_measurements,
    )


def _store_local_media_signature_if_equivalent(
    observation_id: int | str,
    stored_signature: str | None,
    current_signature: str | None,
) -> None:
    current_text = str(current_signature or '').strip()
    if not current_text:
        return
    stored_text = str(stored_signature or '').strip()
    if stored_text == current_text:
        return
    if _local_media_signatures_match(stored_text, current_text):
        _store_local_cloud_media_signature(observation_id, current_text)


def _clear_cloud_observation_snapshot(cloud_id: str) -> None:
    if not str(cloud_id or '').strip():
        return
    SettingsDB.set_setting(_cloud_observation_snapshot_key(cloud_id), '')


def _clear_local_cloud_media_signature(observation_id: int | str) -> None:
    SettingsDB.set_setting(_cloud_local_media_signature_key(observation_id), '')


def _refresh_local_cloud_media_signature(observation_id: int | str) -> str:
    signature = _local_cloud_media_signature(observation_id)
    if str(signature or '').strip():
        _store_local_cloud_media_signature(observation_id, signature)
    return signature


def _resolve_existing_local_image_asset_path(path_value: str | None) -> Path | None:
    text = str(path_value or '').strip()
    if not text:
        return None
    try:
        raw_path = Path(text).expanduser()
    except Exception:
        return None

    candidates: list[Path] = []
    if raw_path.is_absolute():
        candidates.append(raw_path)
    else:
        images_dir = get_images_dir()
        if raw_path.parts and raw_path.parts[0] == images_dir.name:
            candidates.append(images_dir.parent / raw_path)
        candidates.append(images_dir / raw_path)
        candidates.append(raw_path)

    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate)
        if key in seen:
            continue
        seen.add(key)
        if _is_readable_local_file(candidate):
            return candidate
    return None


def _detect_deleted_remote_observations(remote_obs: list[dict] | None) -> list[dict]:
    remote_ids = {
        str(row.get('id') or '').strip()
        for row in (remote_obs or [])
        if str(row.get('id') or '').strip()
    }
    conn = get_connection()
    conn.row_factory = __import__('sqlite3').Row
    cursor = conn.cursor()
    try:
        cursor.execute(
            """
            SELECT *
            FROM observations
            WHERE cloud_id IS NOT NULL
              AND TRIM(COALESCE(cloud_id, '')) != ''
            ORDER BY date DESC, id DESC
            """
        )
        rows = [dict(row) for row in cursor.fetchall()]
    finally:
        conn.close()

    deleted: list[dict] = []
    for local_obs in rows:
        cloud_id = str(local_obs.get('cloud_id') or '').strip()
        if not cloud_id or cloud_id in remote_ids:
            continue
        deleted.append(
            {
                'local_id': int(local_obs.get('id') or 0),
                'cloud_id': cloud_id,
                'title': _observation_display_name(local_obs),
                'date': local_obs.get('date'),
                'location': local_obs.get('location'),
                'sync_status': str(local_obs.get('sync_status') or '').strip().lower(),
                'observation': dict(local_obs),
            }
        )
    return deleted


def _load_local_calibration_rows() -> list[dict]:
    conn = get_connection()
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(
            """
            SELECT *
            FROM calibrations
            ORDER BY objective_key ASC, calibration_date ASC, id ASC
            """
        ).fetchall()
        return [dict(row) for row in rows]
    except sqlite3.OperationalError:
        return []
    finally:
        conn.close()


def _load_local_calibration_by_uuid(calibration_uuid: str) -> dict | None:
    uuid_value = _normalize_calibration_uuid(calibration_uuid)
    if not uuid_value:
        return None
    conn = get_connection()
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute(
            "SELECT * FROM calibrations WHERE calibration_uuid = ? LIMIT 1",
            (uuid_value,),
        ).fetchone()
        return dict(row) if row else None
    except sqlite3.OperationalError:
        return None
    finally:
        conn.close()


def _local_calibration_lookup(rows: list[dict] | None = None) -> dict[str, dict]:
    lookup: dict[str, dict] = {}
    for row in (rows or _load_local_calibration_rows()):
        uuid_value = _normalize_calibration_uuid((row or {}).get('calibration_uuid'))
        if uuid_value:
            lookup[uuid_value] = dict(row or {})
    return lookup


_LEGACY_SAMPLE_SOURCE_ON_SAMPLE_TYPE = {'Spore_print', 'spore_print', 'spore print', 'Print', 'print'}

# Canonical CLOUD representation for `observation_images.sample_source`.
# The sporely-web Stage 2A migration
# (`20260715120000_add_sample_source_to_observation_images.sql`) picked
# lowercase snake_case (`spore_print`, `hymenium`, `stipe`, `pileus`,
# `context`, `other`) so public RPCs can `lower(btrim(...))`-normalize
# variants safely. Desktop keeps Title_Case locally (matches every other
# tag category) and translates at the boundary — see
# `_desktop_to_cloud_sample_source` on push and
# `_cloud_to_desktop_sample_source` on pull.
_CLOUD_SAMPLE_SOURCE_VALUES = frozenset({
    'spore_print', 'hymenium', 'stipe', 'pileus', 'context', 'other',
})


def _desktop_to_cloud_sample_source(value: object) -> str | None:
    """Translate a desktop-canonical `sample_source` to the cloud canonical form.

    Desktop stores Title_Case (`Spore_print`, `Hymenium`, ...). Cloud stores
    lowercase snake_case. Legacy / compact variants (`Print`, `spore print`,
    ...) are canonicalized via `DatabaseTerms.canonicalize_sample_source`
    first, then lowercased. Returns None for empty / unknown values so the
    push omits the field entirely rather than sending garbage.
    """
    from database.database_tags import DatabaseTerms

    text = str(value or '').strip()
    if not text:
        return None
    # The `Print` compact-pill label isn't in SAMPLE_SOURCE_DISPLAY but should
    # still round-trip to `spore_print` on the cloud.
    if text.lower() in {'print', 'spore print', 'spore_print', 'sporeprint'}:
        return 'spore_print'
    canonical = DatabaseTerms.canonicalize_sample_source(text)
    if not canonical or canonical == 'Not_set':
        return None
    lowered = canonical.lower()
    return lowered if lowered in _CLOUD_SAMPLE_SOURCE_VALUES else None


def _cloud_to_desktop_sample_source(value: object) -> str | None:
    """Translate a cloud `sample_source` value back to desktop Title_Case.

    Accepts either the canonical lowercase snake_case (`spore_print`,
    `hymenium`, ...) or the historical Title_Case some clients may still
    emit (`Spore_print`, `Hymenium`, ...). Anything else — including 'Not_set'
    and empty strings — returns None so the local column stays NULL.
    """
    from database.database_tags import DatabaseTerms

    text = str(value or '').strip()
    if not text:
        return None
    canonical = DatabaseTerms.canonicalize_sample_source(text)
    if not canonical or canonical == 'Not_set':
        return None
    return canonical


def _split_legacy_sample_type_into_source(
    sample_type: object,
    sample_source: object,
) -> tuple[str | None, str | None]:
    """Split a legacy `sample_type='Spore_print'` row into (condition, source).

    Historically, `Spore_print` lived on `images.sample_type` alongside
    Fresh/Dried. Stage 1 moved it to its own `sample_source` category. If the
    local column still carries the legacy value (e.g. because a row hasn't
    been touched since the migration), route it into `sample_source` for the
    push payload and clear the condition side. Explicit sample_source always
    wins — this only fills gaps.

    Returns ``(condition, source)`` as canonical strings or None.
    """
    from database.database_tags import DatabaseTerms

    raw_type = str(sample_type or '').strip()
    raw_source = str(sample_source or '').strip()

    normalized_type = DatabaseTerms.canonicalize_sample(raw_type) if raw_type else None
    normalized_source = (
        DatabaseTerms.canonicalize_sample_source(raw_source) if raw_source else None
    )

    if raw_type in _LEGACY_SAMPLE_SOURCE_ON_SAMPLE_TYPE and not normalized_source:
        # Legacy value stuck on the wrong column — promote it. Any of the
        # historical spore-print spellings (Spore_print, spore print, and the
        # compact-pill label "Print") map to the canonical Spore_print value.
        normalized_source = 'Spore_print'
        normalized_type = None
    elif raw_type in _LEGACY_SAMPLE_SOURCE_ON_SAMPLE_TYPE:
        # Already have a source; just clear the legacy condition value.
        normalized_type = None

    if normalized_type == 'Not_set':
        normalized_type = None
    if normalized_source == 'Not_set':
        normalized_source = None
    return normalized_type, normalized_source


def _apply_image_sample_fields_to_push_payload(
    payload: dict,
    image_row: dict,
    *,
    client: 'SporelyCloudClient | None' = None,
    obs_cloud_id: str | None = None,
) -> None:
    """Normalize sample_type / sample_source on the outgoing image payload.

    * Splits legacy `sample_type='Spore_print'` into `sample_source='Spore_print'`.
    * Null-safe merge for `sample_source`: when the local column is empty we
      OMIT `sample_source` from the payload entirely. On a PATCH, PostgREST
      leaves the existing cloud value untouched; on a POST (new row), the
      column defaults to NULL — same as sending NULL — so nothing is lost.
      This avoids a network round-trip and prevents unrelated image-metadata
      patches from wiping cloud values.
    * Drops `sample_source` from the payload entirely when the cloud
      deployment is older and doesn't have the column (schema-cache safety).
      The capability probe only runs when we actually have a value to send —
      keeps the no-op path (empty local sample_source) free of any network
      round-trip.
    """
    condition, source = _split_legacy_sample_type_into_source(
        image_row.get('sample_type'),
        image_row.get('sample_source'),
    )
    payload['sample_type'] = condition

    if not source:
        # No value to push. Omit the field so PATCH leaves cloud alone; POST
        # defaults NULL. No capability probe needed on this fast path — that
        # keeps existing tests (which don't monkeypatch every probe) working.
        payload.pop('sample_source', None)
        return

    # Boundary translation: desktop Title_Case → cloud lowercase snake_case.
    cloud_source = _desktop_to_cloud_sample_source(source)
    if not cloud_source:
        payload.pop('sample_source', None)
        return

    if client is not None:
        try:
            supported = bool(client._observation_images_support_sample_source())
        except Exception:
            supported = False
        if not supported:
            payload.pop('sample_source', None)
            return

    payload['sample_source'] = cloud_source


def _image_calibration_uuid(image_row: dict | None) -> str | None:
    row = dict(image_row or {})
    uuid_value = _normalize_calibration_uuid(row.get('calibration_uuid'))
    if uuid_value:
        return uuid_value

    calibration_id = _safe_int(row.get('calibration_id'))
    if calibration_id <= 0:
        return None

    try:
        calibration = CalibrationDB.get_calibration(calibration_id)
    except Exception:
        return None
    if not calibration:
        return None
    return _normalize_calibration_uuid(calibration.get('calibration_uuid'))


def _local_calibration_id_for_image(image_row: dict | None) -> int | None:
    calibration_uuid = _image_calibration_uuid(image_row)
    if not calibration_uuid:
        return None

    calibration = _load_local_calibration_by_uuid(calibration_uuid)
    if not calibration:
        return None

    calibration_id = _safe_int(calibration.get('id'))
    return calibration_id if calibration_id > 0 else None


def _reconcile_local_image_calibration_links() -> int:
    """Backfill local image calibration_id values from stored cloud snapshots."""
    phase_start = _cloud_sync_perf_counter()
    snapshot_count = 0
    image_count = 0
    calibration_count = 0
    thread_name = threading.current_thread().name
    execution_context = (
        'ui_thread' if threading.current_thread() is threading.main_thread() else 'worker_thread'
    )
    print(
        f"[cloud_sync] calibration image linking: start "
        f"thread={thread_name} execution_context={execution_context}",
        flush=True,
    )
    conn = get_connection()
    conn.row_factory = sqlite3.Row
    try:
        cursor = conn.cursor()
        try:
            snapshot_rows = cursor.execute(
                'SELECT key, value FROM settings WHERE key LIKE ?',
                (f'{_SETTING_CLOUD_OBS_SNAPSHOT_PREFIX}%',),
            ).fetchall()
        except sqlite3.OperationalError:
            return 0
        if not snapshot_rows:
            return 0
        snapshot_count = len(snapshot_rows)

        calibration_lookup = _local_calibration_lookup()
        calibration_count = len(calibration_lookup)
        try:
            local_image_rows = cursor.execute(
                'SELECT id, cloud_id, calibration_id FROM images WHERE cloud_id IS NOT NULL'
            ).fetchall()
        except sqlite3.OperationalError:
            return 0

        local_images_by_cloud_id = {
            str(row['cloud_id']).strip(): dict(row)
            for row in local_image_rows
            if str(row['cloud_id']).strip()
        }
        image_count = len(local_images_by_cloud_id)
        updates: list[tuple[int, int]] = []

        for snapshot_row in snapshot_rows:
            snapshot = _parse_cloud_observation_snapshot(snapshot_row['value'])
            for remote_image in snapshot.get('images') or []:
                calibration_uuid = _normalize_calibration_uuid(remote_image.get('calibration_uuid'))
                if not calibration_uuid:
                    continue
                calibration_row = calibration_lookup.get(calibration_uuid)
                if not calibration_row:
                    continue
                local_calibration_id = _safe_int(calibration_row.get('id'))
                if local_calibration_id <= 0:
                    continue

                cloud_image_id = str(remote_image.get('id') or '').strip()
                if not cloud_image_id:
                    continue
                local_image_row = local_images_by_cloud_id.get(cloud_image_id)
                if not local_image_row:
                    continue
                current_calibration_id = _safe_int(local_image_row.get('calibration_id'))
                if current_calibration_id == local_calibration_id:
                    continue
                updates.append((local_calibration_id, _safe_int(local_image_row.get('id'))))

        if not updates:
            return 0

        cursor.executemany(
            'UPDATE images SET calibration_id = ? WHERE id = ?',
            updates,
        )
        conn.commit()
        return len(updates)
    except sqlite3.OperationalError:
        return 0
    finally:
        conn.close()
        print(
            f"[cloud_sync] calibration image linking: complete "
            f"snapshots={snapshot_count} images={image_count} "
            f"calibrations={calibration_count} duration="
            f"{(_cloud_sync_perf_counter() - phase_start) * 1000:.0f}ms "
            f"thread={thread_name} execution_context={execution_context}",
            flush=True,
        )


def _calibration_sync_warning(direction: str, local_row: dict | None, remote_row: dict | None, fields: list[str]) -> str:
    calibration_uuid = _normalize_calibration_uuid((local_row or remote_row or {}).get('calibration_uuid')) or '?'
    label = _calibration_display_name(local_row or remote_row)
    field_text = ', '.join(fields[:6]) if fields else 'metadata'
    return (
        f'calibration {calibration_uuid}: skipped {direction} for {label} '
        f'because the same UUID has conflicting metadata ({field_text})'
    )


def push_calibrations(
    client: SporelyCloudClient,
    progress_cb: ProgressCallback | None = None,
    progress_state: dict | None = None,
    remote_calibrations: list[dict] | None = None,
) -> dict:
    """Push calibration metadata rows that exist only on the desktop."""
    phase_start = _cloud_sync_perf_counter()
    summary = _cloud_sync_current_summary()
    remote_rows = [dict(row or {}) for row in (remote_calibrations or client.list_remote_calibrations())]
    remote_map = {
        _normalize_calibration_uuid(row.get('calibration_uuid')): row
        for row in remote_rows
        if _normalize_calibration_uuid(row.get('calibration_uuid'))
    }
    local_rows = _load_local_calibration_rows()
    total = len(local_rows)
    pushed = 0
    matched_noop = 0
    conflicts = 0
    remote_lookups = 0
    errors: list[str] = []
    progress_state = progress_state if isinstance(progress_state, dict) else {}
    _extend_progress_total(progress_state, total)
    reference_image_uploader = getattr(client, 'push_calibration_reference_image', None)
    print(
        f"[cloud_sync] calibration push: start (local={total}, remote={len(remote_rows)})",
        flush=True,
    )
    if total:
        _emit_progress(progress_cb, "Checking local calibrations…", progress_state)

    for index, local_row in enumerate(local_rows, start=1):
        step_start = _cloud_sync_perf_counter()
        step_kind = 'metadata'
        calibration_uuid = _normalize_calibration_uuid(local_row.get('calibration_uuid'))
        label = _calibration_display_name(local_row)
        _emit_progress(
            progress_cb,
            f"Syncing calibration {index}/{max(1, total)}: {label}…",
            progress_state,
        )
        try:
            if not calibration_uuid:
                errors.append('calibration ?: skipped push because calibration_uuid is missing')
                continue

            remote_row = remote_map.get(calibration_uuid)
            if remote_row is not None:
                if not _calibration_payloads_match(local_row, remote_row):
                    conflicts += 1
                    errors.append(_calibration_sync_warning('push', local_row, remote_row, _calibration_diff_fields(local_row, remote_row)))
                    continue
                matched_noop += 1
                if callable(reference_image_uploader):
                    step_kind = 'reference_image'
                    warning = reference_image_uploader(
                        local_row,
                        cloud_row_id=str(remote_row.get('id') or '').strip() or None,
                        remote_row=remote_row,
                    )
                    if warning:
                        errors.append(warning)
                continue

            # Not in the freshly-listed remote set: double-check the server
            # before inserting so a row created since the list (e.g. another
            # device) is not duplicated. This is an extra remote call per
            # not-yet-synced calibration; tracked so an N+1 shows up in logs.
            step_kind = 'remote_lookup'
            remote_lookups += 1
            current_remote = client.find_remote_calibration(calibration_uuid)
            if current_remote is not None:
                if _calibration_payloads_match(local_row, current_remote):
                    matched_noop += 1
                    if callable(reference_image_uploader):
                        step_kind = 'reference_image'
                        warning = reference_image_uploader(
                            local_row,
                            cloud_row_id=str(current_remote.get('id') or '').strip() or None,
                            remote_row=current_remote,
                        )
                        if warning:
                            errors.append(warning)
                    continue
                conflicts += 1
                errors.append(_calibration_sync_warning('push', local_row, current_remote, _calibration_diff_fields(local_row, current_remote)))
                continue

            step_kind = 'metadata_insert'
            cloud_row_id = client.push_calibration_metadata(local_row)
            pushed += 1
            if callable(reference_image_uploader):
                step_kind = 'reference_image'
                warning = reference_image_uploader(
                    local_row,
                    cloud_row_id=cloud_row_id,
                    remote_row={'id': cloud_row_id, 'image_storage_path': None},
                )
                if warning:
                    errors.append(warning)
        except CloudSyncError as exc:
            if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
                raise
            errors.append(f'calibration {calibration_uuid or "?"}: {exc}')
        except Exception as exc:
            if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
                raise
            errors.append(f'calibration {calibration_uuid or "?"}: {exc}')
        finally:
            step_elapsed = _cloud_sync_perf_counter() - step_start
            if step_elapsed >= _CLOUD_SYNC_SLOW_STEP_SECONDS:
                print(
                    f"[cloud_sync] calibration push: slow step "
                    f"calibration {index}/{max(1, total)} ({label}) "
                    f"took {step_elapsed * 1000:.0f}ms during {step_kind}",
                    flush=True,
                )
            _advance_progress(progress_state, 1)

    _increment_sync_summary(summary, 'calibrations_pushed', pushed)
    _increment_sync_summary(summary, 'calibrations_skipped_noop', matched_noop)
    _increment_sync_summary(summary, 'calibrations_conflicts', conflicts)
    _increment_sync_summary(summary, 'calibration_remote_lookups', remote_lookups)
    print(
        f"[cloud_sync] calibration push: complete pushed={pushed} matched_noop={matched_noop} "
        f"conflicts={conflicts} remote_lookups={remote_lookups} errors={len(errors)} "
        f"duration={(_cloud_sync_perf_counter() - phase_start) * 1000:.0f}ms",
        flush=True,
    )
    return {
        'pushed': pushed,
        'total': total,
        'matched_noop': matched_noop,
        'conflicts': conflicts,
        'remote_lookups': remote_lookups,
        'errors': errors,
    }


def pull_calibrations(
    client: SporelyCloudClient,
    progress_cb: ProgressCallback | None = None,
    progress_state: dict | None = None,
    remote_calibrations: list[dict] | None = None,
) -> dict:
    """Pull cloud calibration metadata into local rows keyed by UUID."""
    phase_start = _cloud_sync_perf_counter()
    summary = _cloud_sync_current_summary()
    remote_rows = [dict(row or {}) for row in (remote_calibrations or client.list_remote_calibrations())]
    local_rows = _load_local_calibration_rows()
    local_map = _local_calibration_lookup(local_rows)
    total = len(remote_rows)
    pulled = 0
    matched_noop = 0
    conflicts = 0
    errors: list[str] = []
    progress_state = progress_state if isinstance(progress_state, dict) else {}
    _extend_progress_total(progress_state, total)
    print(
        f"[cloud_sync] calibration pull: start (remote={total}, local={len(local_rows)})",
        flush=True,
    )

    remote_rows_sorted = sorted(
        remote_rows,
        key=lambda row: (
            _normalize_calibration_bool(row.get('is_active')),
            _normalize_calibration_text(row.get('objective_key')) or '',
            _normalize_calibration_date(row.get('calibration_date')) or '',
            str(row.get('id') or ''),
        ),
    )

    for index, remote_row in enumerate(remote_rows_sorted, start=1):
        step_start = _cloud_sync_perf_counter()
        calibration_uuid = _normalize_calibration_uuid(remote_row.get('calibration_uuid'))
        label = _calibration_display_name(remote_row)
        _emit_progress(
            progress_cb,
            f"Checking calibration {index}/{max(1, total)}: {label}…",
            progress_state,
        )
        try:
            if not calibration_uuid:
                errors.append('calibration ?: skipped pull because calibration_uuid is missing')
                continue

            local_row = local_map.get(calibration_uuid)
            if local_row is not None:
                if not _calibration_payloads_match(local_row, remote_row):
                    conflicts += 1
                    errors.append(_calibration_sync_warning('pull', local_row, remote_row, _calibration_diff_fields(local_row, remote_row)))
                else:
                    matched_noop += 1
                continue

            try:
                CalibrationDB.add_calibration(**_calibration_insert_kwargs(remote_row))
                pulled += 1
                local_map[calibration_uuid] = _load_local_calibration_by_uuid(calibration_uuid) or dict(remote_row)
            except sqlite3.IntegrityError:
                current_local = _load_local_calibration_by_uuid(calibration_uuid)
                if current_local and _calibration_payloads_match(current_local, remote_row):
                    matched_noop += 1
                    local_map[calibration_uuid] = current_local
                    continue
                conflicts += 1
                errors.append(_calibration_sync_warning('pull', current_local or remote_row, remote_row, _calibration_diff_fields(current_local or {}, remote_row)))
            except Exception as exc:
                errors.append(f'calibration {calibration_uuid}: {exc}')
        except CloudSyncError as exc:
            if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
                raise
            errors.append(f'calibration {calibration_uuid or "?"}: {exc}')
        except Exception as exc:
            if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
                raise
            errors.append(f'calibration {calibration_uuid or "?"}: {exc}')
        finally:
            step_elapsed = _cloud_sync_perf_counter() - step_start
            if step_elapsed >= _CLOUD_SYNC_SLOW_STEP_SECONDS:
                print(
                    f"[cloud_sync] calibration pull: slow step "
                    f"calibration {index}/{max(1, total)} ({label}) took {step_elapsed * 1000:.0f}ms",
                    flush=True,
                )
            _advance_progress(progress_state, 1)

    reconcile_start = _cloud_sync_perf_counter()
    reconciled_links = 0
    try:
        _emit_progress(progress_cb, "Linking calibration images…", progress_state)
        reconciled_links = _reconcile_local_image_calibration_links()
        _emit_progress(progress_cb, "Calibration image linking complete.", progress_state)
    except Exception as exc:
        errors.append(f'calibration reconciliation: {exc}')
    reconcile_elapsed = _cloud_sync_perf_counter() - reconcile_start
    if reconcile_elapsed >= _CLOUD_SYNC_SLOW_STEP_SECONDS:
        print(
            f"[cloud_sync] calibration pull: image link reconciliation took "
            f"{reconcile_elapsed * 1000:.0f}ms ({reconciled_links} link(s) updated)",
            flush=True,
        )

    _increment_sync_summary(summary, 'calibrations_pulled', pulled)
    _increment_sync_summary(summary, 'calibrations_skipped_noop', matched_noop)
    _increment_sync_summary(summary, 'calibrations_conflicts', conflicts)
    print(
        f"[cloud_sync] calibration pull: complete pulled={pulled} matched_noop={matched_noop} "
        f"conflicts={conflicts} links_updated={reconciled_links} errors={len(errors)} "
        f"duration={(_cloud_sync_perf_counter() - phase_start) * 1000:.0f}ms",
        flush=True,
    )
    return {
        'pulled': pulled,
        'total': total,
        'matched_noop': matched_noop,
        'conflicts': conflicts,
        'links_updated': reconciled_links,
        'errors': errors,
    }


def list_calibration_conflicts(
    client: SporelyCloudClient,
    calibration_uuids: list[str] | None = None,
    remote_calibrations: list[dict] | None = None,
) -> list[dict]:
    """Return explicit calibration UUID conflicts between the local DB and cloud."""
    remote_source = remote_calibrations if remote_calibrations is not None else client.list_remote_calibrations()
    remote_rows = [dict(row or {}) for row in remote_source]
    remote_map = {
        _normalize_calibration_uuid(row.get('calibration_uuid')): row
        for row in remote_rows
        if _normalize_calibration_uuid(row.get('calibration_uuid'))
    }
    target_uuids = None
    if calibration_uuids is not None:
        target_uuids = {
            _normalize_calibration_uuid(value)
            for value in calibration_uuids
            if _normalize_calibration_uuid(value)
        }
    local_rows = _load_local_calibration_rows()
    if target_uuids is not None:
        local_rows = [
            row
            for row in local_rows
            if _normalize_calibration_uuid(row.get('calibration_uuid')) in target_uuids
        ]

    conflicts: list[dict] = []
    for local_row in local_rows:
        calibration_uuid = _normalize_calibration_uuid(local_row.get('calibration_uuid'))
        if not calibration_uuid:
            continue
        remote_row = remote_map.get(calibration_uuid)
        if remote_row is None:
            continue
        changes = _calibration_field_changes(local_row, remote_row)
        if not changes:
            continue
        conflict = {
            'calibration_uuid': calibration_uuid,
            'cloud_row_id': str(remote_row.get('id') or '').strip() or None,
            'label': _calibration_display_name(local_row),
            'fields': list(changes.keys()),
            'local_row': dict(local_row),
            'remote_row': dict(remote_row),
        }
        if 'measurements_json' in changes:
            conflict['normalized_local_measurements_json'] = _normalize_calibration_measurements_json(
                local_row.get('measurements_json')
            )
            conflict['normalized_remote_measurements_json'] = _normalize_calibration_measurements_json(
                remote_row.get('measurements_json')
            )
        conflicts.append(conflict)
    return conflicts


def repair_calibrations_local_wins(
    client: SporelyCloudClient,
    calibration_uuids: list[str] | None = None,
    progress_cb: ProgressCallback | None = None,
    progress_state: dict | None = None,
    remote_calibrations: list[dict] | None = None,
) -> dict:
    """Repair conflicting cloud calibration metadata using the local desktop rows as source of truth."""
    conflicts = list_calibration_conflicts(
        client,
        calibration_uuids=calibration_uuids,
        remote_calibrations=remote_calibrations,
    )
    total = len(conflicts)
    repaired = 0
    repairs: list[dict] = []
    errors: list[str] = []
    progress_state = progress_state if isinstance(progress_state, dict) else {}
    _extend_progress_total(progress_state, total)

    for index, conflict in enumerate(conflicts, start=1):
        calibration_uuid = _normalize_calibration_uuid(conflict.get('calibration_uuid'))
        local_row = dict(conflict.get('local_row') or {})
        remote_row = dict(conflict.get('remote_row') or {})
        label = str(conflict.get('label') or _calibration_display_name(local_row))
        _emit_progress(
            progress_cb,
            f"Repairing calibration {index}/{max(1, total)}: {label}…",
            progress_state,
        )
        try:
            if not calibration_uuid:
                errors.append('calibration ?: skipped repair because calibration_uuid is missing')
                continue

            fields = list(conflict.get('fields') or [])
            if not fields:
                continue

            cloud_row_id = str(conflict.get('cloud_row_id') or remote_row.get('id') or '').strip()
            if not cloud_row_id:
                current_remote = client.find_remote_calibration(calibration_uuid)
                remote_row = dict(current_remote or {})
                cloud_row_id = str(remote_row.get('id') or '').strip()
            if not cloud_row_id:
                errors.append(
                    f'calibration {calibration_uuid}: skipped repair because the cloud row id is unavailable'
                )
                continue

            patch_payload = _calibration_local_wins_patch_payload(local_row, remote_row)
            if not patch_payload:
                continue

            client._patch(
                f'calibrations?user_id=eq.{client.user_id}&id=eq.{cloud_row_id}',
                patch_payload,
            )
            repaired += 1
            fields = list(fields or _calibration_diff_fields(local_row, remote_row))
            repair_entry = {
                'calibration_uuid': calibration_uuid,
                'cloud_row_id': cloud_row_id,
                'fields': fields,
                'message': (
                    f'calibration {calibration_uuid}: repaired local-wins cloud row {cloud_row_id} '
                    f'overwrote fields ({", ".join(fields)})'
                ),
            }
            refreshed_remote = None
            if 'measurements_json' in fields:
                try:
                    refreshed_remote = client.find_remote_calibration(calibration_uuid)
                except Exception as exc:
                    if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
                        raise
                    errors.append(
                        f'calibration {calibration_uuid}: could not re-read cloud row after repair ({exc})'
                    )
                else:
                    remaining_changes = _calibration_field_changes(local_row, refreshed_remote or remote_row)
                    if 'measurements_json' in remaining_changes:
                        repair_entry['remaining_fields'] = list(remaining_changes.keys())
                        repair_entry['normalized_local_measurements_json'] = _normalize_calibration_measurements_json(
                            local_row.get('measurements_json')
                        )
                        repair_entry['normalized_remote_measurements_json'] = _normalize_calibration_measurements_json(
                            (refreshed_remote or remote_row).get('measurements_json')
                        )
                        print(
                            '[cloud_sync] '
                            f'calibration {calibration_uuid}: measurements_json still differs after local-wins repair '
                            f'(local={json.dumps(repair_entry["normalized_local_measurements_json"], ensure_ascii=False, sort_keys=True)}, '
                            f'remote={json.dumps(repair_entry["normalized_remote_measurements_json"], ensure_ascii=False, sort_keys=True)})'
                        )
            repairs.append(repair_entry)
        except CloudSyncError as exc:
            if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
                raise
            errors.append(f'calibration {calibration_uuid or "?"}: {exc}')
        except Exception as exc:
            if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
                raise
            errors.append(f'calibration {calibration_uuid or "?"}: {exc}')
        finally:
            _advance_progress(progress_state, 1)

    return {'repaired': repaired, 'total': total, 'repairs': repairs, 'errors': errors}


def unlink_local_observation_from_cloud(local_id: int) -> dict:
    local_obs = ObservationDB.get_observation(int(local_id))
    if not local_obs:
        raise CloudSyncError(f'Local observation {local_id} not found')

    cloud_id = str(local_obs.get('cloud_id') or '').strip()
    image_rows = list(ImageDB.get_images_for_observation(int(local_id)) or [])

    conn = get_connection()
    try:
        conn.execute(
            """
            UPDATE observations
            SET cloud_id = NULL,
                sync_status = NULL,
                synced_at = NULL
            WHERE id = ?
            """,
            (int(local_id),),
        )
        conn.execute(
            """
            UPDATE images
            SET cloud_id = NULL,
                synced_at = NULL
            WHERE observation_id = ?
            """,
            (int(local_id),),
        )
        conn.commit()
    finally:
        conn.close()

    if cloud_id:
        _clear_cloud_observation_snapshot(cloud_id)
    _clear_local_cloud_media_signature(int(local_id))
    for image_row in image_rows:
        image_id = _safe_int(image_row.get('id'))
        cloud_image_id = str(image_row.get('cloud_id') or '').strip()
        if image_id > 0:
            _clear_cloud_image_file_signature(int(local_id), image_id)
        if cloud_image_id:
            _clear_cloud_image_file_signature(int(local_id), cloud_image_id)
    return {'local_id': int(local_id), 'cloud_id': cloud_id}


def mark_observation_dirty(local_id: int) -> None:
    try:
        obs_id = int(local_id or 0)
    except (TypeError, ValueError):
        return
    if obs_id <= 0:
        return
    conn = get_connection()
    try:
        cursor = conn.cursor()
        mark_observation_sync_dirty(cursor, obs_id)
        conn.commit()
    finally:
        conn.close()


def mark_observation_media_dirty(local_id: int) -> None:
    """Schedule a user-selected media change for the next cloud sync.

    Checkbox changes are event-driven sync work, so they must not depend on
    the periodic pending-image repair scan. The image-specific cloud-id detach
    and explicit restore marker identify the pending upload; retaining the
    observation media signature lets the pre-encode pass prove that unrelated
    linked images are unchanged.
    """
    try:
        obs_id = int(local_id or 0)
    except (TypeError, ValueError):
        return
    if obs_id <= 0:
        return
    mark_observation_dirty(obs_id)


def set_image_cloud_selected(image_id: int, selected: bool) -> dict | None:
    """Apply one checkbox change to the image's canonical cloud lifecycle.

    Stage 1: also mirrors the checkbox into the cloud-storage-desired
    excluded set (``sporely_cloud_image_storage_excluded_ids_<obs>``) so the
    boundary byte gate sees a consistent view without depending on any UI
    layer. Tombstone / delete-pending / restore transitions continue to run
    as before.
    """
    image_id = _safe_int(image_id)
    if image_id <= 0:
        return None
    image = ImageDB.get_image(image_id)
    if not image:
        return None

    cloud_id = str(image.get("cloud_id") or "").strip()
    tombstone = (
        ImageDB.get_image_tombstone_by_deleted_cloud_id(cloud_id)
        if cloud_id
        else None
    )
    previous_state = derive_image_cloud_state(
        cloud_id,
        tombstone,
        metadata_only=(
            image_id in _cloud_metadata_only_image_ids(image.get("observation_id"))
        ),
    )
    next_state = previous_state
    next_cloud_id = cloud_id or None
    action = "none"
    observation_id = _safe_int(image.get("observation_id"))

    if not selected and previous_state == CLOUD_IMAGE_STATE_UPLOADED:
        queued_cloud_id = ImageDB.queue_image_tombstone_for_local_image(image_id)
        if queued_cloud_id:
            next_state = CLOUD_IMAGE_STATE_DELETE_PENDING
            next_cloud_id = str(queued_cloud_id)
            action = "delete_queued"
    elif selected and previous_state == CLOUD_IMAGE_STATE_DELETE_PENDING:
        if ImageDB.clear_image_tombstone_by_deleted_cloud_id(cloud_id):
            next_state = CLOUD_IMAGE_STATE_UPLOADED
            action = "delete_cancelled"
    elif selected and previous_state == CLOUD_IMAGE_STATE_DELETED:
        remember_explicit_image_restore_source(image_id, cloud_id)
        if ImageDB.clear_image_cloud_sync_state(image_id):
            next_state = CLOUD_IMAGE_STATE_NONE
            next_cloud_id = None
            action = "restore_queued"
            mark_observation_media_dirty(observation_id)
    elif selected and previous_state == CLOUD_IMAGE_STATE_NONE:
        mark_observation_media_dirty(observation_id)
        action = "upload_queued"
    elif selected and previous_state == CLOUD_IMAGE_STATE_METADATA_ONLY:
        mark_observation_media_dirty(observation_id)
        action = "upload_queued"

    # Stage 1: keep the cloud-storage-desired excluded set aligned with the
    # checkbox. Only mutate when the observation is known; a checkbox without
    # an observation cannot affect the byte gate anyway.
    if observation_id > 0:
        if selected:
            _remove_cloud_image_storage_excluded_image_id(observation_id, image_id)
        else:
            _add_cloud_image_storage_excluded_image_id(observation_id, image_id)
        # An explicit user decision IS storage intent — record it in the
        # per-image ledger so default seeding can never override it.
        _mark_cloud_image_storage_intent_initialized(observation_id, [image_id])

    return {
        "image_id": image_id,
        "observation_id": observation_id or None,
        "selected": bool(selected),
        "previous_state": previous_state,
        "cloud_state": next_state,
        "cloud_id": next_cloud_id,
        "action": action,
    }


def _explicit_image_restore_source_key(image_id: int | str) -> str:
    return f"sporely_cloud_explicit_image_restore_source_{int(image_id)}"


def remember_explicit_image_restore_source(image_id: int, deleted_cloud_id: str) -> None:
    """Remember the tombstoned cloud row that an explicit restore must not reuse."""
    image_id = _safe_int(image_id)
    cloud_id = str(deleted_cloud_id or "").strip()
    if image_id > 0 and cloud_id:
        SettingsDB.set_setting(_explicit_image_restore_source_key(image_id), cloud_id)


def _explicit_image_restore_source(image_id: int | str) -> str:
    image_id = _safe_int(image_id)
    if image_id <= 0:
        return ""
    return str(
        SettingsDB.get_setting(_explicit_image_restore_source_key(image_id), "") or ""
    ).strip()


def _clear_explicit_image_restore_source(image_id: int | str) -> None:
    image_id = _safe_int(image_id)
    if image_id > 0:
        SettingsDB.set_setting(_explicit_image_restore_source_key(image_id), "")


def _safe_int(value, default: int = 0) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _observation_sync_species_label(obs: dict | None) -> str:
    record = dict(obs or {})
    genus, species, species_guess = resolve_observation_taxon_fields(
        record.get('genus'),
        record.get('species'),
        record.get('species_guess'),
        record.get('ai_selected_scientific_name'),
    )
    label = " ".join(part for part in (genus, species) if part).strip()
    if label:
        return label
    common_name = str(record.get('common_name') or '').strip()
    if common_name:
        return common_name
    if species_guess:
        return species_guess
    return ''


def _format_cloud_sync_observation_status(obs: dict | None, message: str) -> str:
    record = dict(obs or {})
    obs_id = _safe_int(record.get('id'))
    label = _observation_sync_species_label(record)
    if obs_id > 0 and label:
        prefix = f'Observation {obs_id} ({label})'
    elif obs_id > 0:
        prefix = f'Observation {obs_id}'
    elif label:
        prefix = label
    else:
        prefix = 'Observation'
    text = str(message or '').strip()
    return f'{prefix}: {text}' if text else prefix


def _file_content_signature(path: str | Path) -> str:
    file_path = Path(path)
    if not file_path.exists() or not file_path.is_file():
        return ''
    digest = hashlib.sha1()
    with open(file_path, 'rb') as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b''):
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def _remote_ai_crop_box(image_row: dict | None) -> tuple[float, float, float, float] | None:
    row = dict(image_row or {})
    values = []
    for key in ('ai_crop_x1', 'ai_crop_y1', 'ai_crop_x2', 'ai_crop_y2'):
        value = row.get(key)
        if value is None:
            return None
        try:
            values.append(float(value))
        except (TypeError, ValueError):
            return None
    return tuple(values) if len(values) == 4 else None


def _remote_ai_crop_source_size(image_row: dict | None) -> tuple[int, int] | None:
    row = dict(image_row or {})
    width = row.get('ai_crop_source_w')
    height = row.get('ai_crop_source_h')
    if width is None or height is None:
        return None
    try:
        return int(width), int(height)
    except (TypeError, ValueError):
        return None


def _remote_ai_crop_is_custom(image_row: dict | None) -> bool | None:
    row = dict(image_row or {})
    value = row.get('ai_crop_is_custom')
    if value is None:
        return None
    return bool(value)


def _path_stat_signature(path_value: str | None) -> dict:
    path_text = str(path_value or '').strip()
    if not path_text:
        return {'path': '', 'exists': False}
    path = Path(path_text)
    try:
        stat = path.stat()
        return {
            'path': path_text,
            'exists': True,
            'size': int(stat.st_size),
            'mtime_ns': int(getattr(stat, 'st_mtime_ns', int(stat.st_mtime * 1_000_000_000))),
        }
    except Exception:
        return {'path': path_text, 'exists': path.exists()}


def _local_cloud_media_signature(
    observation_id: int | str,
    *,
    include_measurements: bool = True,
) -> str:
    obs_id = _safe_int(observation_id)
    if obs_id <= 0:
        return ''
    conn = get_connection()
    conn.row_factory = __import__('sqlite3').Row
    cursor = conn.cursor()
    try:
        try:
            image_columns = {
                str(info["name"])
                for info in cursor.execute("PRAGMA table_info(images)").fetchall()
            }
        except Exception:
            image_columns = set()
        try:
            calibration_table_exists = cursor.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name='calibrations'"
            ).fetchone() is not None
        except Exception:
            calibration_table_exists = False
        has_image_calibration_id = 'calibration_id' in image_columns
        calibration_id_column_sql = (
            "images.calibration_id" if has_image_calibration_id else "NULL AS calibration_id"
        )
        calibration_uuid_column_sql = (
            "calibrations.calibration_uuid AS calibration_uuid"
            if calibration_table_exists and has_image_calibration_id
            else "NULL AS calibration_uuid"
        )
        # `sample_source` is a Stage-2 addition; on databases that haven't
        # applied `database/schema.py` migration yet (test schemas, older
        # installs) the column may not exist. Fall back to NULL so the SELECT
        # doesn't blow up, matching the calibration_id treatment above.
        sample_source_column_sql = (
            "images.sample_source" if 'sample_source' in image_columns
            else "NULL AS sample_source"
        )
        captured_at_column_sql = (
            "images.captured_at" if 'captured_at' in image_columns
            else "NULL AS captured_at"
        )
        calibration_join_sql = (
            "LEFT JOIN calibrations ON calibrations.id = images.calibration_id"
            if calibration_table_exists and has_image_calibration_id
            else ""
        )
        cursor.execute(
            f'''
            SELECT
                images.id,
                images.filepath,
                images.original_filepath,
                images.sort_order,
                images.image_type,
                images.micro_category,
                {captured_at_column_sql},
                images.objective_name,
                images.scale_microns_per_pixel,
                images.resample_scale_factor,
                images.mount_medium,
                images.stain,
                images.sample_type,
                {sample_source_column_sql},
                images.contrast,
                images.measure_color,
                images.crop_mode,
                images.notes,
                images.gps_source,
                images.ai_crop_x1,
                images.ai_crop_y1,
                images.ai_crop_x2,
                images.ai_crop_y2,
                images.ai_crop_source_w,
                images.ai_crop_source_h,
                images.ai_crop_is_custom,
                {calibration_id_column_sql},
                {calibration_uuid_column_sql}
            FROM images
            {calibration_join_sql}
            WHERE images.observation_id = ?
            ORDER BY
                CASE WHEN images.sort_order IS NULL THEN 1 ELSE 0 END,
                images.sort_order,
                images.image_type,
                images.micro_category,
                images.created_at,
                images.id
            ''',
            (obs_id,),
        )
        image_rows = [dict(row) for row in cursor.fetchall()]
        tombstoned_cloud_ids = _local_tombstoned_cloud_image_ids(
            [str(row.get('cloud_id') or '').strip() for row in image_rows if str(row.get('cloud_id') or '').strip()]
        )
        if tombstoned_cloud_ids:
            image_rows = [
                row
                for row in image_rows
                if str(row.get('cloud_id') or '').strip() not in tombstoned_cloud_ids
            ]
        measurement_rows: list[dict] = []
        if include_measurements:
            cursor.execute(
                '''
                SELECT
                    m.id,
                    m.image_id,
                    m.length_um,
                    m.width_um,
                    m.measurement_type,
                    m.notes,
                    m.p1_x,
                    m.p1_y,
                    m.p2_x,
                    m.p2_y,
                    m.p3_x,
                    m.p3_y,
                    m.p4_x,
                    m.p4_y,
                    m.gallery_rotation
                FROM spore_measurements m
                JOIN images i ON i.id = m.image_id
                WHERE i.observation_id = ?
                ORDER BY m.id
                ''',
                (obs_id,),
            )
            measurement_rows = [dict(row) for row in cursor.fetchall()]
    finally:
        conn.close()

    payload = {
        'render_version': _CLOUD_LOCAL_MEDIA_RENDER_VERSION,
        'cloud_image_size_mode': 'full',
        'images': [
            {
                'id': _safe_int(row.get('id')),
                'filepath': _path_stat_signature(row.get('filepath')),
                'original_filepath': _path_stat_signature(row.get('original_filepath')),
                'sort_order': _normalize_snapshot_value(row.get('sort_order')),
                'image_type': _normalize_snapshot_value(row.get('image_type')),
                'micro_category': _normalize_snapshot_value(row.get('micro_category')),
                'captured_at': _normalize_image_captured_at_for_cloud(
                    row.get('captured_at'), local=True
                ),
                'objective_name': _normalize_snapshot_value(row.get('objective_name')),
                'scale_microns_per_pixel': _normalize_snapshot_value(row.get('scale_microns_per_pixel')),
                'resample_scale_factor': _normalize_snapshot_value(row.get('resample_scale_factor')),
                'mount_medium': _normalize_snapshot_value(row.get('mount_medium')),
                'stain': _normalize_snapshot_value(row.get('stain')),
                'sample_type': _normalize_snapshot_value(row.get('sample_type')),
                'sample_source': _normalize_snapshot_value(row.get('sample_source')),
                'contrast': _normalize_snapshot_value(row.get('contrast')),
                'measure_color': _normalize_snapshot_value(row.get('measure_color')),
                'crop_mode': _normalize_snapshot_value(row.get('crop_mode')),
                'notes': _normalize_snapshot_value(row.get('notes')),
                'gps_source': _normalize_snapshot_value(row.get('gps_source')),
                'ai_crop_x1': _normalize_snapshot_value(row.get('ai_crop_x1')),
                'ai_crop_y1': _normalize_snapshot_value(row.get('ai_crop_y1')),
                'ai_crop_x2': _normalize_snapshot_value(row.get('ai_crop_x2')),
                'ai_crop_y2': _normalize_snapshot_value(row.get('ai_crop_y2')),
                'ai_crop_source_w': _normalize_snapshot_value(row.get('ai_crop_source_w')),
                'ai_crop_source_h': _normalize_snapshot_value(row.get('ai_crop_source_h')),
                'calibration_uuid': _normalize_snapshot_value(row.get('calibration_uuid')),
            }
            for row in image_rows
        ],
    }
    if include_measurements:
        payload['measurements'] = [
            {
                **_measurement_compare_payload(row, local=False),
                'notes': _normalize_snapshot_value(row.get('notes')),
            }
            for row in measurement_rows
        ]
    return json.dumps(payload, ensure_ascii=True, sort_keys=True, separators=(',', ':'))


def _local_cloud_image_media_signature(observation_id: int | str) -> str:
    return _local_cloud_media_signature(observation_id, include_measurements=False)


def _local_media_signatures_match_ignoring_tombstoned_images(
    stored_signature: str | None,
    current_signature: str | None,
) -> bool:
    stored_text = str(stored_signature or '').strip()
    current_text = str(current_signature or '').strip()
    if not stored_text or not current_text:
        return stored_text == current_text
    if stored_text == current_text:
        return True

    tombstoned_local_ids = _local_tombstoned_local_image_ids()
    if not tombstoned_local_ids:
        return False

    stored_payload = _parsed_local_media_signature(stored_text)
    current_payload = _parsed_local_media_signature(current_text)
    if not stored_payload or not current_payload:
        return False

    def _filtered_payload(payload: dict) -> dict:
        filtered = dict(payload or {})
        images: list[dict] = []
        for row in list(filtered.get('images') or []):
            if not isinstance(row, dict):
                continue
            if _safe_int(row.get('id')) in tombstoned_local_ids:
                continue
            images.append(dict(row))
        filtered['images'] = images
        return filtered

    return _normalized_local_media_signature_payload(
        _filtered_payload(stored_payload),
        include_measurements=False,
    ) == _normalized_local_media_signature_payload(
        _filtered_payload(current_payload),
        include_measurements=False,
    )


def _local_media_prep_diagnostics(
    observation_id: int | str,
    stored_signature: str | None,
    current_signature: str | None,
) -> dict:
    stored_text = str(stored_signature or '').strip()
    current_text = str(current_signature or '').strip()
    stored_payload = _parsed_local_media_signature(stored_text)
    current_payload = _parsed_local_media_signature(current_text)
    image_render_signature_matched = bool(
        stored_text
        and current_text
        and _local_media_signatures_match(
            stored_text,
            current_text,
            include_measurements=False,
        )
    )
    tombstone_aware_signature_matched = bool(
        stored_text
        and current_text
        and _local_media_signatures_match_ignoring_tombstoned_images(
            stored_text,
            current_text,
        )
    )
    measurement_only_matched = bool(
        stored_text
        and current_text
        and image_render_signature_matched
        and not _local_media_signatures_match(stored_text, current_text)
    )

    local_image_rows: list[dict] = []
    obs_id = _safe_int(observation_id)
    if obs_id > 0:
        try:
            local_image_rows = [dict(row or {}) for row in ImageDB.get_images_for_observation(obs_id) or []]
        except Exception:
            local_image_rows = []
    has_local_image_cloud_id_null = any(not str(row.get('cloud_id') or '').strip() for row in local_image_rows)

    changed_keys: list[str] = []
    any_image_file_signature_changed = False
    any_render_affecting_field_changed = False
    only_metadata_fields_changed = False

    def _normalized_path_signature(path_value: object) -> dict:
        if not isinstance(path_value, dict):
            return {'path': '', 'exists': False}
        normalized = dict(path_value)
        normalized.pop('mtime_ns', None)
        return normalized

    if stored_payload and current_payload:
        stored_images = [dict(row or {}) for row in (stored_payload.get('images') or [])]
        current_images = [dict(row or {}) for row in (current_payload.get('images') or [])]
        image_changes = _analyze_image_changes(current_images, stored_images)
        changed_keys.extend(f'+{key}' for key in (image_changes.get('added_keys') or []))
        changed_keys.extend(f'-{key}' for key in (image_changes.get('removed_keys') or []))

        current_map = {_image_compare_key(row): row for row in current_images}
        stored_map = {_image_compare_key(row): row for row in stored_images}
        shared_keys = [key for key in current_map if key in stored_map]
        metadata_changed_field_count = 0

        for key in shared_keys:
            current_row = current_map[key]
            stored_row = stored_map[key]

            for path_key in ('filepath', 'original_filepath'):
                if _normalized_path_signature(current_row.get(path_key)) != _normalized_path_signature(stored_row.get(path_key)):
                    any_image_file_signature_changed = True
                    changed_keys.append(f'{key}:{path_key}')

            current_meta = _image_metadata_payload(current_row)
            stored_meta = _image_metadata_payload(stored_row)
            for field, current_value in current_meta.items():
                if current_value == stored_meta.get(field):
                    continue
                metadata_changed_field_count += 1
                changed_keys.append(f'{key}:{field}')
                if field in _LOCAL_MEDIA_PREP_RENDER_AFFECTING_IMAGE_FIELDS:
                    any_render_affecting_field_changed = True

        for field in _LOCAL_MEDIA_PREP_RENDER_AFFECTING_TOP_LEVEL_FIELDS:
            if current_payload.get(field) != stored_payload.get(field):
                any_render_affecting_field_changed = True
                changed_keys.append(field)

        if image_changes.get('added_keys') or image_changes.get('removed_keys'):
            any_image_file_signature_changed = True

        only_metadata_fields_changed = bool(
            metadata_changed_field_count
            and not any_image_file_signature_changed
            and not any_render_affecting_field_changed
            and not image_changes.get('added_keys')
            and not image_changes.get('removed_keys')
        )

    changed_keys = list(dict.fromkeys(str(key).strip() for key in changed_keys if str(key).strip()))

    return {
        'image_render_signature_matched': image_render_signature_matched,
        'tombstone_aware_signature_matched': tombstone_aware_signature_matched,
        'measurement_only_matched': measurement_only_matched,
        'has_local_image_cloud_id_null': has_local_image_cloud_id_null,
        'any_image_file_signature_changed': any_image_file_signature_changed,
        'any_render_affecting_field_changed': any_render_affecting_field_changed,
        'only_metadata_fields_changed': only_metadata_fields_changed,
        'changed_keys': changed_keys,
    }


def _format_local_media_prep_diagnostic_keys(keys: list[str], *, limit: int = 8) -> str:
    normalized_keys = [str(key).strip() for key in (keys or []) if str(key or '').strip()]
    if not normalized_keys:
        return '[]'
    display_keys = normalized_keys[: max(1, int(limit))]
    suffix = ''
    if len(normalized_keys) > len(display_keys):
        suffix = f', … (+{len(normalized_keys) - len(display_keys)} more)'
    return f"[{', '.join(display_keys)}{suffix}]"


def _prepared_item_remote_payload(
    image_row: dict,
    upload_path: str,
    storage_path: str,
    *,
    include_ai_crop: bool = True,
    include_upload_meta: bool = True,
) -> dict:
    normalized_key = _normalize_cloud_media_key(storage_path)
    payload = {
        'id': _normalize_snapshot_value(image_row.get('cloud_id')),
        'desktop_id': _safe_int(image_row.get('id')),
        'sort_order': _normalize_snapshot_value(image_row.get('sort_order')),
        'image_type': _normalize_snapshot_value(image_row.get('image_type')),
        'micro_category': _normalize_snapshot_value(image_row.get('micro_category')),
        'captured_at': _normalize_image_captured_at_for_cloud(
            image_row.get('captured_at'), local=True
        ),
        'calibration_uuid': _normalize_snapshot_value(_image_calibration_uuid(image_row)),
        'objective_name': _normalize_snapshot_value(image_row.get('objective_name')),
        'scale_microns_per_pixel': _normalize_snapshot_value(image_row.get('scale_microns_per_pixel')),
        'resample_scale_factor': _normalize_snapshot_value(image_row.get('resample_scale_factor')),
        'mount_medium': _normalize_snapshot_value(image_row.get('mount_medium')),
        'stain': _normalize_snapshot_value(image_row.get('stain')),
        'sample_type': _normalize_snapshot_value(image_row.get('sample_type')),
        # Compared against the same field on the remote payload — both sides
        # normalize to the desktop-canonical Title_Case form so lowercase
        # cloud values (`spore_print`) match Title_Case local values
        # (`Spore_print`) without triggering a false diff.
        'sample_source': _normalize_snapshot_value(
            _cloud_to_desktop_sample_source(image_row.get('sample_source'))
        ),
        'contrast': _normalize_snapshot_value(image_row.get('contrast')),
        'measure_color': _normalize_snapshot_value(image_row.get('measure_color')),
        'crop_mode': _normalize_snapshot_value(image_row.get('crop_mode')),
        'notes': _normalize_snapshot_value(image_row.get('notes')),
        'gps_source': _normalize_snapshot_value(
            None if image_row.get('gps_source') is None else bool(image_row.get('gps_source'))
        ),
        'storage_path': _normalize_snapshot_value(normalized_key or None),
        'original_filename': _normalize_snapshot_value(Path(str(upload_path or '').strip()).name or None),
    }
    if include_ai_crop:
        payload.update({
            'ai_crop_x1': _normalize_snapshot_value(image_row.get('ai_crop_x1')),
            'ai_crop_y1': _normalize_snapshot_value(image_row.get('ai_crop_y1')),
            'ai_crop_x2': _normalize_snapshot_value(image_row.get('ai_crop_x2')),
            'ai_crop_y2': _normalize_snapshot_value(image_row.get('ai_crop_y2')),
            'ai_crop_source_w': _normalize_snapshot_value(image_row.get('ai_crop_source_w')),
            'ai_crop_source_h': _normalize_snapshot_value(image_row.get('ai_crop_source_h')),
            'ai_crop_is_custom': _normalize_snapshot_value(image_row.get('ai_crop_is_custom')),
        })
    if include_upload_meta:
        payload.update({
            'upload_mode': _normalize_snapshot_value(image_row.get('upload_mode')),
            'source_width': _normalize_snapshot_value(image_row.get('source_width')),
            'source_height': _normalize_snapshot_value(image_row.get('source_height')),
            'stored_width': _normalize_snapshot_value(image_row.get('stored_width')),
            'stored_height': _normalize_snapshot_value(image_row.get('stored_height')),
            'stored_bytes': _normalize_snapshot_value(image_row.get('stored_bytes')),
        })
    return payload


