# Batch size for PostgREST `id=in.(...)` fetches (measurements + image metadata).
# IDs are UUIDs (~36 chars), so 100 IDs keep the `in.(...)` clause under ~3.7KB,
# well below any reasonable proxy URL limit (nginx default request line is 8KB),
# while halving the request count vs the previous size of 50 (e.g. 866 image IDs
# go from 18 requests to 9). Kept conservative on purpose; do not raise without
# re-checking the proxy URL limit for the longest realistic ID list.
_CLOUD_SYNC_IN_BATCH_SIZE = 100

# PostgREST silently truncates every response body to ``db-max-rows`` — Supabase's
# default is 1000. Callers of ``_get_paginated`` MUST include a deterministic
# ``order=`` clause; the helper pages with ``limit=1000&offset=N`` and stops when a
# page comes back shorter than this cap. Never treat a cap-sized response as
# complete without paging past it.
_CLOUD_SYNC_MAX_ROWS_PER_PAGE = 1000


def _normalize_measurement_type_value(value) -> str:
    text = str(value or 'manual').strip().lower()
    return text or 'manual'


def _normalize_measurement_timestamp_value(value) -> str | None:
    parsed = _parse_sync_timestamp(value)
    if parsed is not None:
        return parsed.isoformat()
    text = str(value or '').strip()
    return text or None


_MEASUREMENT_FLOAT_FIELDS = {
    'length_um',
    'width_um',
    'p1_x',
    'p1_y',
    'p2_x',
    'p2_y',
    'p3_x',
    'p3_y',
    'p4_x',
    'p4_y',
}
_MEASUREMENT_FLOAT_ABS_TOL = 1e-9
_MEASUREMENT_FLOAT_REL_TOL = 1e-9
_MEASUREMENT_SYNC_FIELDS = [
    'desktop_id',
    'image_id',
    'length_um',
    'width_um',
    'measurement_type',
    'p1_x',
    'p1_y',
    'p2_x',
    'p2_y',
    'p3_x',
    'p3_y',
    'p4_x',
    'p4_y',
    'measured_at',
]
_MEASUREMENT_PRESENTATION_FIELDS = ('gallery_rotation',)
_MEASUREMENT_SYNC_MEDIA_FIELDS = ['image_key', 'thumb_key']


def _normalize_measurement_identity_value(value) -> str | None:
    text = str(value or '').strip()
    return text or None


def _normalize_measurement_int_value(value, *, default: int | None = None) -> int | None:
    if value is None:
        return default
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, int):
        return int(value)
    if isinstance(value, float):
        try:
            return int(value)
        except Exception:
            return default
    text = str(value or '').strip()
    if not text:
        return default
    try:
        return int(float(text))
    except Exception:
        return default


def _normalize_measurement_float_value(value) -> float | None:
    if value is None:
        return None
    if isinstance(value, bool):
        return float(int(value))
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value or '').strip()
    if not text:
        return None
    try:
        return float(text)
    except Exception:
        return None


def _measurement_field_values_match(field: str, left, right) -> bool:
    if field in _MEASUREMENT_FLOAT_FIELDS:
        left_float = _normalize_measurement_float_value(left)
        right_float = _normalize_measurement_float_value(right)
        if left_float is None or right_float is None:
            return left_float is None and right_float is None
        return math.isclose(
            left_float,
            right_float,
            rel_tol=_MEASUREMENT_FLOAT_REL_TOL,
            abs_tol=_MEASUREMENT_FLOAT_ABS_TOL,
        )
    if field == 'measurement_type':
        return _normalize_measurement_type_value(left) == _normalize_measurement_type_value(right)
    if field == 'measured_at':
        return _normalize_measurement_timestamp_value(left) == _normalize_measurement_timestamp_value(right)
    if field == 'gallery_rotation':
        return _normalize_measurement_int_value(left, default=0) == _normalize_measurement_int_value(right, default=0)
    if field == 'desktop_id':
        return _normalize_measurement_int_value(left) == _normalize_measurement_int_value(right)
    if field in {'id', 'image_id', 'image_key', 'thumb_key'}:
        return _normalize_measurement_identity_value(left) == _normalize_measurement_identity_value(right)
    return _normalize_snapshot_value(left) == _normalize_snapshot_value(right)


def _measurement_compare_key(measurement_row: dict | None) -> str:
    row = dict(measurement_row or {})
    cloud_id = str(row.get('id') or '').strip()
    desktop_id = str(row.get('desktop_id') or '').strip()
    image_id = str(row.get('image_id') or '').strip()
    if cloud_id:
        return f'cloud:{cloud_id}'
    if desktop_id:
        return f'desktop:{desktop_id}'
    if image_id:
        return f'image:{image_id}'
    return json.dumps(row, ensure_ascii=True, sort_keys=True, separators=(',', ':'))


def _measurement_compare_payload(
    measurement_row: dict | None,
    *,
    local: bool,
    cloud_image_id: str | None = None,
    include_media_keys: bool = False,
    image_storage_key: str | None = None,
) -> dict:
    row = dict(measurement_row or {})
    payload: dict = {}
    if local:
        payload['id'] = _normalize_measurement_identity_value(
            str(row.get('cloud_id') or '').strip() or row.get('id')
        )
        payload['desktop_id'] = _normalize_measurement_int_value(row.get('id'))
        payload['image_id'] = _normalize_measurement_identity_value(
            cloud_image_id or str(row.get('image_cloud_id') or '').strip() or row.get('image_id')
        )
    else:
        payload['id'] = _normalize_measurement_identity_value(row.get('id'))
        payload['desktop_id'] = _normalize_measurement_int_value(row.get('desktop_id'))
        payload['image_id'] = _normalize_measurement_identity_value(row.get('image_id'))

    payload['length_um'] = _normalize_measurement_float_value(row.get('length_um'))
    payload['width_um'] = _normalize_measurement_float_value(row.get('width_um'))
    payload['measurement_type'] = _normalize_measurement_type_value(row.get('measurement_type'))
    payload['gallery_rotation'] = _normalize_measurement_int_value(row.get('gallery_rotation'), default=0)
    payload['p1_x'] = _normalize_measurement_float_value(row.get('p1_x'))
    payload['p1_y'] = _normalize_measurement_float_value(row.get('p1_y'))
    payload['p2_x'] = _normalize_measurement_float_value(row.get('p2_x'))
    payload['p2_y'] = _normalize_measurement_float_value(row.get('p2_y'))
    payload['p3_x'] = _normalize_measurement_float_value(row.get('p3_x'))
    payload['p3_y'] = _normalize_measurement_float_value(row.get('p3_y'))
    payload['p4_x'] = _normalize_measurement_float_value(row.get('p4_x'))
    payload['p4_y'] = _normalize_measurement_float_value(row.get('p4_y'))
    payload['measured_at'] = _normalize_measurement_timestamp_value(row.get('measured_at'))
    if include_media_keys:
        if local:
            storage_key = _normalize_cloud_media_key(image_storage_key)
            payload['image_key'] = storage_key or None
            payload['thumb_key'] = media_variant_key(storage_key, 'thumb') if storage_key else None
        else:
            payload['image_key'] = _normalize_cloud_media_key(row.get('image_key')) or None
            payload['thumb_key'] = _normalize_cloud_media_key(row.get('thumb_key')) or None
    return payload


def _local_measurement_snapshot_payload(measurement_row: dict | None) -> dict:
    return _measurement_compare_payload(measurement_row, local=True)


def _remote_measurement_snapshot_payload(measurement_row: dict | None) -> dict:
    return _measurement_compare_payload(measurement_row, local=False)


def _baseline_measurement_compare_payload(record: dict | None) -> dict:
    return _measurement_compare_payload(record, local=False)


def _measurement_sync_payload(
    measurement_row: dict | None,
    *,
    local: bool,
    cloud_image_id: str | None = None,
    image_storage_key: str | None = None,
    include_media_keys: bool = False,
) -> dict:
    payload = _measurement_compare_payload(
        measurement_row,
        local=local,
        cloud_image_id=cloud_image_id,
        include_media_keys=include_media_keys,
        image_storage_key=image_storage_key,
    )
    payload.pop('id', None)
    return payload


def _measurement_payloads_match(
    local_row: dict | None,
    remote_row: dict | None,
    *,
    cloud_image_id: str | None = None,
    image_storage_key: str | None = None,
    include_media_keys: bool = False,
) -> bool:
    local_payload = _measurement_sync_payload(
        local_row,
        local=True,
        cloud_image_id=cloud_image_id,
        image_storage_key=image_storage_key,
        include_media_keys=include_media_keys,
    )
    remote_payload = _measurement_sync_payload(
        remote_row,
        local=False,
        include_media_keys=include_media_keys,
    )
    compare_fields = list(_MEASUREMENT_SYNC_FIELDS)
    if include_media_keys:
        compare_fields.extend(_MEASUREMENT_SYNC_MEDIA_FIELDS)
    for field in compare_fields:
        if not _measurement_field_values_match(field, local_payload.get(field), remote_payload.get(field)):
            return False
    return True


def _measurement_push_diff_fields(
    local_row: dict | None,
    remote_row: dict | None,
    *,
    cloud_image_id: str | None = None,
    image_storage_key: str | None = None,
    include_media_keys: bool = False,
) -> list[str]:
    local_payload = _measurement_sync_payload(
        local_row,
        local=True,
        cloud_image_id=cloud_image_id,
        image_storage_key=image_storage_key,
        include_media_keys=include_media_keys,
    )
    remote_payload = _measurement_sync_payload(
        remote_row,
        local=False,
        include_media_keys=include_media_keys,
    )
    diff_fields: list[str] = []
    compare_fields = list(_MEASUREMENT_SYNC_FIELDS)
    if include_media_keys:
        compare_fields.extend(_MEASUREMENT_SYNC_MEDIA_FIELDS)
    for field in compare_fields:
        if not _measurement_field_values_match(field, local_payload.get(field), remote_payload.get(field)):
            diff_fields.append(field)
    return diff_fields


def _analyze_measurement_changes(current_measurements: list[dict], baseline_measurements: list[dict]) -> dict:
    current = [dict(row or {}) for row in (current_measurements or [])]
    baseline = [dict(row or {}) for row in (baseline_measurements or [])]
    current_keys = [_measurement_compare_key(row) for row in current]
    baseline_keys = [_measurement_compare_key(row) for row in baseline]
    current_map = {_measurement_compare_key(row): row for row in current}
    baseline_map = {_measurement_compare_key(row): row for row in baseline}

    added_keys = [key for key in current_keys if key not in baseline_map]
    removed_keys = [key for key in baseline_keys if key not in current_map]
    shared_keys = [key for key in current_keys if key in baseline_map]
    changed_keys: list[str] = []
    for key in shared_keys:
        current_payload = _measurement_compare_payload(current_map[key], local=False)
        baseline_payload = _measurement_compare_payload(baseline_map[key], local=False)
        if any(
            not _measurement_field_values_match(
                field,
                current_payload.get(field),
                baseline_payload.get(field),
            )
            for field in _SNAPSHOT_MEAS_FIELDS
        ):
            changed_keys.append(key)

    return {
        'added_keys': added_keys,
        'removed_keys': removed_keys,
        'changed_keys': changed_keys,
        'added': [current_map[key] for key in added_keys],
        'removed': [baseline_map[key] for key in removed_keys],
        'changed': bool(added_keys or removed_keys or changed_keys),
    }


def _mark_cloud_observations_dirty_for_media_changes() -> None:
    current_signature = _cloud_media_signature()
    previous_signature = str(SettingsDB.get_setting(_SETTING_CLOUD_MEDIA_SIGNATURE, '') or '').strip()
    if previous_signature == current_signature:
        return
    # Background cloud sync currently uploads source images/metadata, not the
    # optional rendered overlays/gallery/plate outputs tied to these settings.
    # Persist the new signature so future comparisons are stable, but don't mark
    # every linked observation dirty just because a global render preference changed.
    SettingsDB.set_setting(_SETTING_CLOUD_MEDIA_SIGNATURE, current_signature)


def _mark_cloud_observations_dirty_for_image_capture_time_changes() -> int:
    """Schedule linked images whose capture time is absent from the baseline.

    Older sync signatures predate ``images.captured_at``. Merely adding the
    field to the normal snapshot contract cannot revisit observations already
    stamped as synced, so explicit media sync performs this narrow comparison.
    Once a successful sync refreshes the local signature, the scan is a no-op.
    """
    conn = get_connection()
    try:
        image_columns = {
            str(row[1] or '').strip()
            for row in conn.execute("PRAGMA table_info(images)").fetchall()
        }
        if 'captured_at' not in image_columns:
            return 0
        rows = conn.execute(
            """
            SELECT DISTINCT o.id
            FROM observations o
            JOIN images i ON i.observation_id = o.id
            WHERE o.cloud_id IS NOT NULL
              AND COALESCE(o.sync_status, '') != 'dirty'
              AND i.cloud_id IS NOT NULL
              AND i.captured_at IS NOT NULL
              AND TRIM(CAST(i.captured_at AS TEXT)) != ''
            """
        ).fetchall()
    finally:
        conn.close()

    marked = 0
    for row in rows:
        observation_id = _safe_int(row[0])
        if observation_id <= 0:
            continue
        stored = _parsed_local_media_signature(
            _load_local_cloud_media_signature(observation_id)
        )
        current = _parsed_local_media_signature(
            _local_cloud_image_media_signature(observation_id)
        )
        stored_by_id = {
            _safe_int(image.get('id')): dict(image)
            for image in (stored.get('images') or [])
            if isinstance(image, dict) and _safe_int(image.get('id')) > 0
        }
        needs_sync = any(
            image.get('captured_at') is not None
            and image.get('captured_at')
            != stored_by_id.get(_safe_int(image.get('id')), {}).get('captured_at')
            for image in (current.get('images') or [])
            if isinstance(image, dict)
        )
        if not needs_sync:
            continue
        mark_observation_dirty(observation_id)
        marked += 1
    return marked


def microscope_image_requires_public_spore_anchor(image_id: int | None) -> bool:
    """Return whether one local image must retain a public metadata anchor.

    This is the shared local eligibility predicate used by checkbox/tombstone
    handling, normal sync, and the explicit mosaic backfill. It intentionally
    mirrors the established public mosaic measurement gate: the observation's
    spore data is public, the parent is a microscope image, both dimensions are
    present, and the measurement category is a spore category.
    """
    local_image_id = _safe_int(image_id)
    if local_image_id <= 0:
        return False
    conn = get_connection()
    try:
        cursor = conn.execute(
            """
            SELECT i.image_type, o.spore_data_visibility,
                   m.length_um, m.width_um, m.measurement_type
            FROM images i
            JOIN observations o ON o.id = i.observation_id
            LEFT JOIN spore_measurements m ON m.image_id = i.id
            WHERE i.id = ?
            """,
            (local_image_id,),
        )
        rows = cursor.fetchall()
        if not rows:
            return False
        if str(rows[0][0] or '') != 'microscope':
            return False
        if str(rows[0][1] or 'public').lower() != 'public':
            return False
        return any(
            measurement_qualifies_for_public_spore_anchor({
                'length_um': row[2],
                'width_um': row[3],
                'measurement_type': row[4],
            })
            for row in rows
        )
    finally:
        conn.close()


def measurement_qualifies_for_public_spore_anchor(measurement: dict | None) -> bool:
    """Pure eligibility predicate shared by sync and read-only incident audit."""
    row = dict(measurement or {})
    if row.get('length_um') is None or row.get('width_um') is None:
        return False
    measurement_type = str(row.get('measurement_type') or '').lower()
    return measurement_type in {'', 'manual', 'spore', 'spores'}


def _cloud_explicit_media_upload_selection(observation_id: int | None) -> set[int]:
    """Return image ids the user has kept in Sporely Cloud image storage.

    Stage 1: this is now the cloud-storage desired selection, read from the
    dedicated ``sporely_cloud_image_storage_excluded_ids_<obs>`` setting.
    Legacy ``artsobs_publish_excluded_image_ids_<obs>`` values are ignored
    here — that key is publication-only.
    """
    local_observation_id = _safe_int(observation_id)
    if local_observation_id <= 0:
        return set()
    conn = get_connection()
    try:
        all_ids = {
            _safe_int(row[0])
            for row in conn.execute(
                "SELECT id FROM images WHERE observation_id = ?",
                (local_observation_id,),
            ).fetchall()
            if _safe_int(row[0]) > 0
        }
        setting_key = _cloud_image_storage_excluded_ids_key(local_observation_id)
        try:
            setting_row = conn.execute(
                "SELECT value FROM settings WHERE key = ?",
                (setting_key,),
            ).fetchone()
        except sqlite3.OperationalError:
            setting_row = None
        excluded: set[int] = set()
        if setting_row:
            try:
                values = json.loads(setting_row[0] or "[]")
                if isinstance(values, list):
                    excluded = {_safe_int(value) for value in values}
            except (TypeError, ValueError, json.JSONDecodeError):
                excluded = set()
        return all_ids - excluded
    finally:
        conn.close()


def _cloud_publish_path_key(path: str | None) -> str:
    if not path:
        return ""
    try:
        return str(Path(path).resolve()).lower()
    except Exception:
        return str(Path(path)).lower()


PendingImageDecision = dict  # {"pending": bool, "reason": str}

# Reasons emitted by explain_pending_cloud_image_decision. Kept as string
# constants so callers can group-count them in diagnostic summaries.
PENDING_REASON_PENDING_UPLOAD = "pending_upload"
PENDING_REASON_ALREADY_SYNCED = "skipped_already_synced"
PENDING_REASON_WRONG_TYPE = "skipped_wrong_type"
PENDING_REASON_GENERATED = "skipped_generated_cloud_image"
PENDING_REASON_EXCLUDED = "skipped_excluded_by_user"
# Stage 1: split the "user has not requested a cloud copy" reason out of the
# generic exclusion bucket so diagnostic reports and callers can distinguish
# gallery-desired-state rejects from any other exclusion input.
PENDING_REASON_NOT_DESIRED_BY_USER = "skipped_not_desired_by_user"
# A row whose storage intent has never been assigned (not in the per-image
# ledger) must never be interpreted as pending cloud media: an unseeded
# excluded set makes everything look desired.
PENDING_REASON_INTENT_UNINITIALIZED = "skipped_storage_intent_uninitialized"
PENDING_REASON_DUPLICATE = "skipped_duplicate_path"
PENDING_REASON_MISSING_FILE = "skipped_missing_file"
PENDING_REASON_CACHE_ROW = "skipped_cloud_cache_row"
PENDING_REASON_MICROSCOPE_NO_MEASUREMENTS = "skipped_microscope_no_measurements"


def explain_pending_cloud_image_decision(
    row: dict,
    *,
    seen_paths: set[str],
    excluded_ids: set[int],
    image_measurement_counts: dict[int, int] | None = None,
    explicit_media_upload_selection: set[int] | None = None,
    initialized_intent_ids: set[int] | None = None,
) -> PendingImageDecision:
    """Shared predicate: should this image row upload its bytes to cloud right now?

    Used by both the dirty-scan (`_mark_cloud_observations_dirty_for_pending_local_images`
    → `_pending_cloud_pushable_image_ids`) and the upload-collection code path so
    both agree on which rows are pending. If they disagree the dirty-scan can
    perpetually re-dirty observations over rows that upload will skip anyway.

    Policy (matches the ``sync_images=True`` explicit media-upload semantics):

      * Field and microscope image bytes are eligible only when their thumbnail
        gallery checkbox is selected. Spore measurements never override an
        unchecked image; their metadata uses a metadata-only microscope anchor.
      * Cloud-cache rows (`source_role=cloud_recovery_cache` or
        `file_purpose=cache`): never re-upload bytes; they're stubs that only
        need metadata patches, which the sync handles separately.
      * Any image that already has ``cloud_id`` set: not pending — it already
        exists on cloud.

    The helper mutates ``seen_paths`` when it accepts the row so duplicate paths
    within the same observation collapse to a single upload.
    """
    reasons: dict[str, bool] = {}
    image_id = _safe_int(row.get("id"))
    if image_id <= 0:
        return {"pending": False, "reason": PENDING_REASON_WRONG_TYPE}

    image_type = str(row.get("image_type") or "").strip().lower()
    if image_type not in {"field", "microscope"}:
        return {"pending": False, "reason": PENDING_REASON_WRONG_TYPE}

    if _is_generated_cloud_image(row):
        return {"pending": False, "reason": PENDING_REASON_GENERATED}

    if image_id in excluded_ids:
        return {"pending": False, "reason": PENDING_REASON_EXCLUDED}

    if str(row.get("cloud_id") or "").strip():
        filepath = str(row.get("filepath") or row.get("original_filepath") or "").strip()
        path_key = _cloud_publish_path_key(filepath) if filepath else ""
        if path_key:
            # Synced canonical rows own their filepath too. Reserving it here
            # prevents a duplicate cloud_id-null row from being re-dirtied and
            # uploaded as a second copy of the same local file.
            seen_paths.add(path_key)
        return {"pending": False, "reason": PENDING_REASON_ALREADY_SYNCED}

    source_role = str(row.get("source_role") or "").strip().lower()
    file_purpose = str(row.get("file_purpose") or "").strip().lower()
    is_cloud_origin = source_role == "cloud_recovery_cache" or file_purpose == "cache"

    if (
        not is_cloud_origin
        and initialized_intent_ids is not None
        and image_id not in initialized_intent_ids
    ):
        # No storage-intent decision exists for this row yet. Refuse to treat
        # it as pending — the caller must seed intent first.
        return {"pending": False, "reason": PENDING_REASON_INTENT_UNINITIALIZED}

    explicit = explicit_media_upload_selection
    if not is_cloud_origin and explicit is not None and image_id not in explicit:
        return {"pending": False, "reason": PENDING_REASON_NOT_DESIRED_BY_USER}

    filepath = str(row.get("filepath") or row.get("original_filepath") or "").strip()
    if not is_cloud_origin and (not filepath or not Path(filepath).exists()):
        # Non cloud-origin rows need a local file to encode. Cache rows are
        # allowed through without a file — the sync will repair their cloud_id
        # via a metadata patch.
        return {"pending": False, "reason": PENDING_REASON_MISSING_FILE}

    path_key = _cloud_publish_path_key(filepath) if filepath else ""
    if path_key and path_key in seen_paths:
        return {"pending": False, "reason": PENDING_REASON_DUPLICATE}

    if image_type == "microscope" and not is_cloud_origin and explicit is None:
        # Callers that do not provide the persisted gallery selection must not
        # infer byte-upload consent from the presence of measurements.
        return {
            "pending": False,
            "reason": PENDING_REASON_MICROSCOPE_NO_MEASUREMENTS,
        }

    if path_key:
        seen_paths.add(path_key)
    return {"pending": True, "reason": PENDING_REASON_PENDING_UPLOAD}


def _measurement_counts_for_observation_images(observation_id: int) -> dict[int, int]:
    """Return image_id → count of spore_measurements. Empty on any DB error."""
    counts: dict[int, int] = {}
    try:
        conn = get_connection()
        try:
            for row in conn.execute(
                "SELECT image_id, COUNT(*) AS n FROM spore_measurements "
                "WHERE image_id IN (SELECT id FROM images WHERE observation_id = ?) "
                "GROUP BY image_id",
                (int(observation_id),),
            ).fetchall():
                counts[_safe_int(row[0])] = int(row[1] or 0)
        finally:
            conn.close()
    except Exception as exc:
        print(f"[cloud_sync] Could not fetch measurement counts for obs {observation_id}: {exc}")
    return counts


def _pending_cloud_pushable_image_ids(
    observation_id: int,
    *,
    explicit_media_upload_selection: set[int] | None = None,
    diagnostic_log: bool = False,
) -> list[int]:
    """Image ids still missing a cloud_id that cloud sync would actually push.

    Uses :func:`explain_pending_cloud_image_decision` so this stays in lock-step
    with the upload-collection predicate. External-publish exclusions are
    intentionally ignored. Any row the upload path would otherwise skip
    (duplicate, missing file, cache row, microscope-no-measurements) is dropped
    here too, so the dirty-scan cannot perpetually re-dirty observations over
    rows the sync intentionally leaves local.
    """
    excluded_ids: set[int] = set()

    conn = get_connection()
    try:
        conn.row_factory = sqlite3.Row
        existing_cols = {
            str(info["name"])
            for info in conn.execute("PRAGMA table_info(images)").fetchall()
        }
        if "id" not in existing_cols or "image_type" not in existing_cols:
            return []
        wanted = [
            col
            for col in (
                "id", "image_type", "cloud_id", "filepath", "original_filepath",
                "source_role", "file_purpose", "notes", "sort_order",
            )
            if col in existing_cols
        ]
        order_bits: list[str] = []
        if "sort_order" in existing_cols:
            order_bits.append("CASE WHEN sort_order IS NULL THEN 1 ELSE 0 END")
            order_bits.append("sort_order")
        order_bits.append("id")
        rows = conn.execute(
            f"SELECT {', '.join(wanted)} FROM images WHERE observation_id = ? "
            f"ORDER BY {', '.join(order_bits)}",
            (int(observation_id),),
        ).fetchall()
    finally:
        conn.close()

    measurement_counts = _measurement_counts_for_observation_images(observation_id)
    # Only rows with recorded storage intent may be evaluated as pending. A
    # caller-provided explicit selection IS storage intent for those ids
    # (e.g. an explicit "upload media" request), so it counts as initialized;
    # the derived default selection computed below does not.
    initialized_intent_ids = _cloud_image_storage_intent_initialized_ids(observation_id)
    if explicit_media_upload_selection is None:
        explicit_media_upload_selection = _cloud_explicit_media_upload_selection(observation_id)
    else:
        initialized_intent_ids = initialized_intent_ids | {
            _safe_int(value)
            for value in explicit_media_upload_selection
            if _safe_int(value) > 0
        }

    pending: list[int] = []
    seen_paths: set[str] = set()
    reason_counts: dict[str, int] = {}
    for image in rows or []:
        row = dict(image)
        decision = explain_pending_cloud_image_decision(
            row,
            seen_paths=seen_paths,
            excluded_ids=excluded_ids,
            image_measurement_counts=measurement_counts,
            explicit_media_upload_selection=explicit_media_upload_selection,
            initialized_intent_ids=initialized_intent_ids,
        )
        reason = decision.get("reason") or ""
        reason_counts[reason] = reason_counts.get(reason, 0) + 1
        if decision.get("pending"):
            pending.append(_safe_int(row.get("id")))

    if diagnostic_log and rows:
        summary = ", ".join(f"{k}={v}" for k, v in sorted(reason_counts.items()))
        print(
            f"[cloud_sync] pending scan obs {observation_id}: rows={len(rows)} "
            f"pending={len(pending)} {summary}"
        )

    return pending


def _mark_cloud_observations_dirty_for_pending_local_images(
    *,
    include_pending_local_media_uploads: bool = False,
    explicit_media_upload_selection: set[int] | None = None,
    diagnostic_log: bool = False,
) -> bool:
    """Mark synced observations dirty when they still have cloud-eligible local images.

    Only runs when the caller explicitly requests a media-upload pass. Metadata-only
    background sync must NOT re-dirty observations over local rows that have no
    cloud_id — those rows are treated as local-only until the user explicitly runs
    "Upload media". Otherwise a fresh install with hundreds of pre-existing local
    microscope photos would surface as "everything dirty" and start pushing bytes.

    Callers pass ``include_pending_local_media_uploads=True`` from the explicit
    media-upload code path. All other callers (Refresh, auto-sync) must leave the
    default False so the scan is a no-op.
    """
    if not include_pending_local_media_uploads:
        return True
    dirty_ids: list[int] = []
    scan_completed = True
    conn = get_connection()
    try:
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        rows = cursor.execute(
            """
            SELECT DISTINCT o.id AS observation_id
            FROM observations o
            JOIN images i ON i.observation_id = o.id
            WHERE o.cloud_id IS NOT NULL
              AND i.cloud_id IS NULL
              AND i.image_type IN ('field', 'microscope')
            ORDER BY o.id
            """
        ).fetchall()
        candidate_ids = [
            _safe_int(dict(row or {}).get("observation_id"))
            for row in rows or []
        ]
    except Exception as exc:
        print(f"[cloud_sync] Could not mark observations dirty for pending local images: {exc}")
        candidate_ids = []
        scan_completed = False
    finally:
        conn.close()

    for obs_id in candidate_ids:
        if obs_id <= 0:
            continue
        # Incremental storage-intent initialization MUST run before any
        # cloud-null row here can be interpreted as pending cloud media. A
        # newly-imported microscope image must never appear desired merely
        # because the excluded set has not been seeded yet. Fail closed: if
        # seeding fails, skip this observation instead of evaluating it.
        try:
            _ensure_cloud_image_storage_intent_initialized(obs_id)
        except Exception as exc:
            print(
                f"[cloud_sync] Could not initialize storage intent for observation {obs_id}: {exc}"
            )
            scan_completed = False
            continue
        try:
            pending_ids = _pending_cloud_pushable_image_ids(
                obs_id,
                explicit_media_upload_selection=explicit_media_upload_selection,
                diagnostic_log=diagnostic_log,
            )
        except Exception as exc:
            print(
                f"[cloud_sync] Could not evaluate pending local images for observation {obs_id}: {exc}"
            )
            scan_completed = False
            continue
        pending_count = len(pending_ids)
        if pending_count > 0:
            print(
                f"[cloud_sync] Observation {obs_id}: re-dirtied because "
                f"{pending_count} cloud-eligible local image row(s) still have cloud_id IS NULL"
            )
            dirty_ids.append(obs_id)
    if not dirty_ids:
        return scan_completed

    _increment_sync_summary(
        _cloud_sync_current_summary(),
        'observations_redirtied_pending_local_images',
        len(dirty_ids),
    )

    for obs_id in dirty_ids:
        try:
            _clear_local_cloud_media_signature(obs_id)
        except Exception as exc:
            print(
                f"[cloud_sync] Could not clear local media signature for observation {obs_id}: {exc}"
            )

    conn = get_connection()
    try:
        cursor = conn.cursor()
        for obs_id in dirty_ids:
            mark_observation_sync_dirty(cursor, obs_id)
        conn.commit()
    except Exception as exc:
        conn.rollback()
        print(f"[cloud_sync] Could not update dirty state for pending local images: {exc}")
        scan_completed = False
    finally:
        conn.close()
    return scan_completed


def _load_local_observation_lookup() -> tuple[dict[str, dict], dict[int, dict]]:
    conn = get_connection()
    conn.row_factory = __import__('sqlite3').Row
    cursor = conn.cursor()
    try:
        cursor.execute('SELECT * FROM observations')
        rows = [dict(row) for row in cursor.fetchall()]
    finally:
        conn.close()
    by_cloud_id: dict[str, dict] = {}
    by_local_id: dict[int, dict] = {}
    for row in rows:
        local_id = _safe_int(row.get('id'))
        cloud_id = str(row.get('cloud_id') or '').strip()
        if local_id > 0:
            by_local_id[local_id] = row
        if cloud_id:
            by_cloud_id[cloud_id] = row
    return by_cloud_id, by_local_id


def _load_local_measurement_lookup(observation_id: int) -> tuple[dict[str, dict], dict[int, dict]]:
    conn = get_connection()
    conn.row_factory = __import__('sqlite3').Row
    cursor = conn.cursor()
    try:
        cursor.execute(
            '''
            SELECT
                m.*,
                i.cloud_id AS image_cloud_id
            FROM spore_measurements m
            JOIN images i ON i.id = m.image_id
            WHERE i.observation_id = ?
            ORDER BY m.id
            ''',
            (int(observation_id),),
        )
        rows = [dict(row) for row in cursor.fetchall()]
    finally:
        conn.close()
    by_cloud_id: dict[str, dict] = {}
    by_local_id: dict[int, dict] = {}
    for row in rows:
        local_id = _safe_int(row.get('id'))
        cloud_id = str(row.get('cloud_id') or '').strip()
        if local_id > 0:
            by_local_id[local_id] = row
        if cloud_id:
            by_cloud_id[cloud_id] = row
    return by_cloud_id, by_local_id


def _build_remote_measurement_identity_cache(remote_measurements: list[dict] | None) -> dict[str, dict]:
    cache: dict[str, dict] = {}
    for row in remote_measurements or []:
        remote_row = dict(row or {})
        cloud_id = str(remote_row.get('id') or '').strip()
        if cloud_id:
            cache[f'cloud:{cloud_id}'] = remote_row
        desktop_id = _safe_int(remote_row.get('desktop_id'))
        if desktop_id > 0:
            cache[f'desktop:{desktop_id}'] = remote_row
    return cache


def _measurement_push_lookup_keys(measurement_row: dict | None) -> list[str]:
    row = dict(measurement_row or {})
    keys: list[str] = []
    cloud_id = str(row.get('cloud_id') or '').strip()
    if cloud_id:
        keys.append(f'cloud:{cloud_id}')
    desktop_id = _safe_int(row.get('id'))
    if desktop_id > 0:
        keys.append(f'desktop:{desktop_id}')
    return keys


def fetch_remote_measurement_identity_cache(
    client,
    image_cloud_ids: list[str],
) -> dict[str, dict]:
    fetcher = getattr(client, 'pull_measurements_for_images', None)
    if not callable(fetcher):
        return {}
    remote_measurements = fetcher(image_cloud_ids)
    return _build_remote_measurement_identity_cache(remote_measurements)


def _load_local_image_lookup(observation_id: int) -> tuple[dict[str, dict], dict[int, dict]]:
    local_images = ImageDB.get_images_for_observation(int(observation_id))
    by_cloud_id: dict[str, dict] = {}
    by_local_id: dict[int, dict] = {}
    for image_row in local_images or []:
        local_image_id = _safe_int(image_row.get('id'))
        if local_image_id > 0:
            by_local_id[local_image_id] = dict(image_row or {})
        cloud_image_id = str(image_row.get('cloud_id') or '').strip()
        if cloud_image_id:
            by_cloud_id[cloud_image_id] = dict(image_row or {})
    return by_cloud_id, by_local_id


def _find_local_observation_for_remote_cached(
    remote: dict,
    by_cloud_id: dict[str, dict],
    by_local_id: dict[int, dict],
) -> dict | None:
    cloud_id = str((remote or {}).get('id') or '').strip()
    if cloud_id and cloud_id in by_cloud_id:
        return dict(by_cloud_id[cloud_id])
    local_id = _safe_int((remote or {}).get('desktop_id'))
    if local_id > 0 and local_id in by_local_id:
        candidate = dict(by_local_id[local_id])
        if bool(candidate.get('portable_cloud_identity_pending')):
            return None
        return candidate
    return None


def _portable_cloud_identity_pending_for_observation(observation_id: int) -> bool:
    """Return the persistent portable identity guard without assuming migration state."""
    conn = get_connection()
    try:
        try:
            table_info = list(conn.execute('PRAGMA table_info(observations)'))
        except (TypeError, sqlite3.Error):
            return False
        if 'portable_cloud_identity_pending' not in {str(info[1]) for info in table_info}:
            return False
        row = conn.execute(
            'SELECT portable_cloud_identity_pending FROM observations WHERE id=?',
            (int(observation_id),),
        ).fetchone()
        return bool(row and row[0])
    finally:
        conn.close()


def _remote_snapshot_has_meaningful_changes(
    remote: dict | None,
    remote_images: list[dict] | None,
    remote_measurements: list[dict] | None,
    stored_snapshot: str | None,
) -> bool:
    snapshot = _parse_cloud_observation_snapshot(stored_snapshot)
    if not snapshot:
        return True
    baseline_obs = _baseline_observation_compare_payload(snapshot.get('observation') or {})
    if not baseline_obs:
        return True
    remote_payload = _observation_compare_payload(remote, local=False)
    for field in _SNAPSHOT_OBS_FIELDS:
        if field in {'id', 'desktop_id'}:
            continue
        if not _observation_field_values_match(field, remote_payload.get(field), baseline_obs.get(field)):
            return True
    baseline_images = [dict(row or {}) for row in (snapshot.get('images') or [])]
    remote_image_payloads = [_remote_image_payload(img) for img in (remote_images or [])]
    remote_image_changes = _analyze_image_changes(remote_image_payloads, baseline_images)
    baseline_measurements = [dict(row or {}) for row in (snapshot.get('measurements') or [])]
    remote_measurement_payloads = [_remote_measurement_snapshot_payload(row) for row in (remote_measurements or [])]
    remote_measurement_changes = _analyze_measurement_changes(remote_measurement_payloads, baseline_measurements)
    return bool(
        remote_image_changes.get('added_keys')
        or remote_image_changes.get('removed_keys')
        or remote_image_changes.get('metadata_changed_keys')
        or remote_measurement_changes.get('changed')
    )


def _stamp_observation_synced(local_id: int, cloud_id: str) -> None:
    _set_observation_sync_state(int(local_id), str(cloud_id or '').strip(), dirty=False)


def _set_observation_sync_state(
    local_id: int,
    cloud_id: str,
    *,
    dirty: bool,
    synced_at: str | None | object = _UNSET,
) -> None:
    conn = get_connection()
    try:
        cursor = conn.cursor()
        if synced_at is _UNSET:
            synced_at_value: str | None = datetime.now(timezone.utc).isoformat()
        else:
            synced_at_value = synced_at if synced_at is None else str(synced_at)
        update_observation_sync_state(
            cursor,
            int(local_id),
            cloud_id=str(cloud_id or '').strip() or None,
            sync_status='dirty' if dirty else 'synced',
            synced_at=synced_at_value,
            clear_sync_error_state=True,
        )
        conn.commit()
    finally:
        conn.close()


def _set_observation_sync_blocked(local_id: int, raw_error: str, blocked_reason: str, *, error_code: str | None = None) -> str:
    code, _ = _collect_sync_error_details(raw_error)
    conn = get_connection()
    try:
        cursor = conn.cursor()
        update_observation_sync_state(
            cursor,
            int(local_id),
            sync_status='blocked',
            sync_error_code=error_code or code or None,
            sync_error_message=str(raw_error or '').strip() or None,
            sync_blocked_reason=blocked_reason,
            sync_blocked_at=datetime.now(timezone.utc).isoformat(),
        )
        conn.commit()
    finally:
        conn.close()
    return blocked_reason


def _set_observation_privacy_blocked(local_id: int, raw_error: str) -> str:
    return _set_observation_sync_blocked(
        local_id,
        raw_error,
        privacy_slot_limit_user_message(),
        error_code='privacy_slot_limit',
    )


def _set_observation_plan_image_retryable(local_id: int, raw_error: str) -> str:
    conn = get_connection()
    try:
        cursor = conn.cursor()
        update_observation_sync_state(
            cursor,
            int(local_id),
            sync_status='dirty',
            sync_error_code='image_too_large_for_plan',
            sync_error_message=str(raw_error or '').strip() or None,
            sync_blocked_reason=None,
            sync_blocked_at=None,
        )
        conn.commit()
    finally:
        conn.close()
    return summarize_image_too_large_for_plan_error(raw_error)


def _remote_observation_update_kwargs(remote: dict) -> dict:
    raw_location_public = remote.get('location_public')
    location_public = _normalize_observation_bool_value(raw_location_public, default=None)
    raw_publish_target = str(remote.get('publish_target') or '').strip()
    genus, species, species_guess = resolve_observation_taxon_fields(
        remote.get('genus'),
        remote.get('species'),
        remote.get('species_guess'),
        remote.get('ai_selected_scientific_name'),
    )
    return {
        'date': remote.get('date'),
        'genus': genus,
        'species': species,
        'common_name': remote.get('common_name'),
        'species_guess': species_guess,
        'location': remote.get('location'),
        'habitat': remote.get('habitat'),
        'notes': remote.get('notes'),
        'open_comment': remote.get('open_comment'),
        'interesting_comment': _normalize_observation_bool_value(remote.get('interesting_comment'), default=False),
        'sharing_scope': _cloud_visibility_to_sharing_scope(
            remote.get('visibility') or remote.get('sharing_scope'),
            fallback='friends' if location_public else 'private',
        ),
        'location_public': location_public,
        'is_draft': _normalize_observation_bool_value(remote.get('is_draft'), default=True),
        'location_precision': ObservationDB._normalize_location_precision(
            remote.get('location_precision')
        ),
        'ai_selected_service': remote.get('ai_selected_service'),
        'ai_selected_taxon_id': remote.get('ai_selected_taxon_id'),
        'ai_selected_scientific_name': remote.get('ai_selected_scientific_name'),
        'ai_selected_probability': _normalize_observation_float_value(remote.get('ai_selected_probability')),
        'ai_selected_at': remote.get('ai_selected_at'),
        'spore_data_visibility': (lambda v: v if v in {'private', 'friends', 'public'} else 'public')(
            str(remote.get('spore_data_visibility') or 'public').strip().lower()
        ),
        'uncertain': _normalize_observation_bool_value(remote.get('uncertain'), default=False),
        'unspontaneous': _normalize_observation_bool_value(remote.get('unspontaneous'), default=False),
        'gps_latitude': _normalize_observation_float_value(remote.get('gps_latitude')),
        'gps_longitude': _normalize_observation_float_value(remote.get('gps_longitude')),
        'artsdata_id': _normalize_observation_int_value(remote.get('artsdata_id')),
        'artportalen_id': _normalize_observation_int_value(remote.get('artportalen_id')),
        'publish_target': normalize_publish_target(raw_publish_target) if raw_publish_target else None,
        'determination_method': _normalize_observation_int_value(remote.get('determination_method')),
        'habitat_nin2_path': remote.get('habitat_nin2_path'),
        'habitat_substrate_path': remote.get('habitat_substrate_path'),
        'habitat_host_genus': remote.get('habitat_host_genus'),
        'habitat_host_species': remote.get('habitat_host_species'),
        'habitat_host_common_name': remote.get('habitat_host_common_name'),
        'habitat_nin2_note': remote.get('habitat_nin2_note'),
        'habitat_substrate_note': remote.get('habitat_substrate_note'),
        'habitat_grows_on_note': remote.get('habitat_grows_on_note'),
        'country_code': normalize_country_code(remote.get('country_code')),
        'region_id': _normalize_observation_field_value('region_id', remote.get('region_id')),
        'allow_nulls': True,
    }


def _remote_observation_extra_values(remote: dict) -> dict:
    raw_spore_stats = remote.get('spore_statistics')
    serialized_spore_stats = _normalize_observation_json_value(raw_spore_stats)
    if serialized_spore_stats is not None and not isinstance(serialized_spore_stats, str):
        serialized_spore_stats = json.dumps(serialized_spore_stats, ensure_ascii=False, sort_keys=True)
    raw_auto_threshold = _normalize_observation_float_value(remote.get('auto_threshold'))
    # The cloud stores red_list_categories_json as JSONB; the local column is
    # TEXT. Serialize back to a JSON string so the local writer stores the
    # exact same payload sporely-web shows in Taxonomy → Red list.
    raw_red_categories = remote.get('red_list_categories_json')
    serialized_red_categories = _normalize_observation_json_value(raw_red_categories)
    if serialized_red_categories is not None and not isinstance(serialized_red_categories, str):
        serialized_red_categories = json.dumps(
            serialized_red_categories, ensure_ascii=False, sort_keys=True
        )
    return {
        'inaturalist_id': _normalize_observation_int_value(remote.get('inaturalist_id')),
        'mushroomobserver_id': _normalize_observation_int_value(remote.get('mushroomobserver_id')),
        'source_type': remote.get('source_type'),
        'citation': remote.get('citation'),
        'data_provider': remote.get('data_provider'),
        'author': remote.get('author'),
        'spore_statistics': serialized_spore_stats,
        'auto_threshold': raw_auto_threshold,
        'red_list_category': remote.get('red_list_category'),
        'red_list_categories_json': serialized_red_categories,
    }


_MERGE_PROTECTED_AI_FIELDS = (
    'ai_selected_service',
    'ai_selected_taxon_id',
    'ai_selected_scientific_name',
    'ai_selected_probability',
    'ai_selected_at',
    'red_list_category',
    'red_list_categories_json',
)


def _merge_cloud_selected_ai_fields(local_obs: dict | None, remote_obs: dict | None) -> dict:
    """Preserve cloud-side selected AI values for an existing identification.

    Existing desktop observations may have `NULL` in the newly added fields until
    they are re-pulled from cloud. When we push an unrelated desktop edit, we
    don't want those missing local values to wipe the cloud selection. A fully
    empty local identification is different: its nulls are an explicit clear
    and must reach the cloud.
    """
    merged = dict(local_obs or {})
    remote = dict(remote_obs or {})
    identification_fields = (
        'genus',
        'species',
        'common_name',
        'species_guess',
    )
    # Missing keys mean this may be a partial update payload. Only treat the
    # identification as explicitly cleared when all identity fields are
    # present and every one is blank/null.
    identification_is_empty = (
        all(field in merged for field in identification_fields)
        and not any(
            str(merged.get(field) or '').strip()
            for field in identification_fields
        )
    )
    for field in _MERGE_PROTECTED_AI_FIELDS:
        # An empty local identification is an explicit tombstone when the row
        # is pushed. Preserve raw observation_identifications separately, but
        # do not resurrect the previously selected AI taxon or red-list data.
        if identification_is_empty:
            continue
        local_value = merged.get(field)
        if local_value not in (None, ''):
            continue
        remote_value = remote.get(field)
        if remote_value not in (None, ''):
            merged[field] = remote_value
    return merged


def _adopt_merge_filled_ai_fields_locally(local_id, local_obs: dict | None, merged: dict | None) -> None:
    """Persist merge-protected fields that the push payload filled from cloud.

    ``_merge_cloud_selected_ai_fields`` fills local NULL/'' AI-selection and
    red-list fields from the remote row so an unrelated push cannot wipe
    them. Without also adopting those values into the LOCAL row, the cloud
    row and the stored snapshot carry the value while the local column stays
    NULL — a manufactured local-only diff that re-marks the observation
    dirty on every subsequent pull (perpetual push/pull loop, live obs
    673/742 red_list_category). Writes only the filled columns; never
    touches sync status or dirty flags.
    """
    try:
        obs_id = int(local_id)
    except (TypeError, ValueError):
        return
    if obs_id <= 0:
        return
    updates: dict[str, object] = {}
    local_row = dict(local_obs or {})
    merged_row = dict(merged or {})
    for field in _MERGE_PROTECTED_AI_FIELDS:
        if local_row.get(field) not in (None, ''):
            continue
        merged_value = merged_row.get(field)
        if merged_value in (None, ''):
            continue
        if isinstance(merged_value, (dict, list)):
            merged_value = json.dumps(merged_value)
        updates[field] = merged_value
    if not updates:
        return
    conn = get_connection()
    try:
        assignments = ', '.join(f'{column} = ?' for column in updates)
        conn.execute(
            f'UPDATE observations SET {assignments} WHERE id = ?',
            (*updates.values(), obs_id),
        )
        conn.commit()
    finally:
        conn.close()


def _normalize_cloud_identification_service(value: object) -> str | None:
    raw = str(value or '').strip().lower()
    if raw in {'artsorakel', 'arts'}:
        return 'artsorakel'
    if raw in {'inat', 'inaturalist'}:
        return 'inat'
    return None


def _cloud_identification_prediction_taxon(prediction: dict, service: str | None = None) -> dict | None:
    pred = dict(prediction or {})
    taxon = dict(pred.get('taxon') or {})
    scientific_name = str(
        pred.get('scientificName')
        or pred.get('scientific_name')
        or pred.get('name')
        or ''
    ).strip()
    vernacular_name = str(
        pred.get('vernacularName')
        or pred.get('vernacular_name')
        or pred.get('commonName')
        or pred.get('common_name')
        or ''
    ).strip()
    taxon_id = pred.get('taxonId') or pred.get('taxon_id')

    if scientific_name:
        taxon.setdefault('scientificName', scientific_name)
        taxon.setdefault('scientific_name', scientific_name)
        taxon.setdefault('name', scientific_name)
    if vernacular_name:
        taxon.setdefault('vernacularName', vernacular_name)
        taxon.setdefault('vernacular_name', vernacular_name)
        taxon.setdefault('preferred_common_name', vernacular_name)
        taxon.setdefault('common_name', vernacular_name)
    if taxon_id not in (None, ''):
        taxon.setdefault('id', taxon_id)
        taxon.setdefault('taxonId', taxon_id)
        taxon.setdefault('taxon_id', taxon_id)
    if service == 'inat' and vernacular_name and not taxon.get('preferred_common_name'):
        taxon['preferred_common_name'] = vernacular_name

    # Preserve Artsorakel redlist metadata so the desktop's Species AI panel
    # can render the badge for predictions produced remotely. sporely-web
    # emits `redlistCategory` / `redlist_category` (lowercase l) plus the
    # rich `redlist_categories` payload; the raw Artsorakel API uses
    # `redListCategory` (capital L). Copy whichever form we find and mirror
    # it under all three aliases so the reader in observations_tab.py can
    # pick it up regardless of casing.
    for key in ('redListCategory', 'redlistCategory', 'redlist_category'):
        value = pred.get(key) or taxon.get(key)
        if value:
            for alias in ('redListCategory', 'redlistCategory', 'redlist_category'):
                taxon.setdefault(alias, value)
            break
    for key in ('redListCategories', 'redlistCategories', 'redlist_categories'):
        value = pred.get(key)
        if value is None:
            value = taxon.get(key)
        if isinstance(value, dict) and value:
            for alias in ('redListCategories', 'redlistCategories', 'redlist_categories'):
                taxon.setdefault(alias, value)
            break

    return taxon or None


def _cloud_identification_prediction_display_name(prediction: dict) -> str:
    scientific_name = str(
        prediction.get('scientificName')
        or prediction.get('scientific_name')
        or prediction.get('name')
        or ''
    ).strip()
    vernacular_name = str(
        prediction.get('vernacularName')
        or prediction.get('vernacular_name')
        or prediction.get('commonName')
        or prediction.get('common_name')
        or ''
    ).strip()
    display_name = str(prediction.get('displayName') or prediction.get('display_name') or '').strip()

    if display_name:
        return display_name
    if vernacular_name and scientific_name and vernacular_name.casefold() != scientific_name.casefold():
        return f'{vernacular_name} ({scientific_name})'
    return vernacular_name or scientific_name


def _cloud_identification_prediction_species_url(prediction: dict, service: str | None = None) -> str | None:
    pred = dict(prediction or {})
    taxon = dict(pred.get('taxon') or {})
    if service == 'inat':
        taxon_id = str(
            pred.get('taxonId')
            or pred.get('taxon_id')
            or taxon.get('id')
            or taxon.get('taxonId')
            or taxon.get('taxon_id')
            or ''
        ).strip()
        if taxon_id:
            return f'https://www.inaturalist.org/taxa/{taxon_id}'
        return None

    for source in (pred, taxon):
        for key in (
            'species_url',
            'speciesUrl',
            'adbUrl',
            'url',
            'link',
            'href',
            'uri',
            'infoUrl',
            'infoURL',
            'info_url',
        ):
            value = source.get(key)
            if isinstance(value, str) and value.strip().startswith('http'):
                return value.strip()

    taxon_id = str(
        pred.get('taxonId')
        or pred.get('taxon_id')
        or taxon.get('taxonId')
        or taxon.get('taxon_id')
        or taxon.get('id')
        or ''
    ).strip()
    if taxon_id and taxon_id.isdigit():
        # Stage 3B.5: this helper runs on the GUI thread inside a
        # per-prediction loop when the observation-detail dialog opens.
        # A 5 s network resolve × ~10 predictions would freeze the
        # editor for tens of seconds on a bad link. Use cache-only mode:
        # cache hits return the true concept URL, misses fall to the
        # NorTaxa fallback with no network I/O.
        return concept_link_from_name_id(taxon_id, network=False)
    return None


def _cloud_identification_prediction_matches_observation(prediction: dict, observation: dict | None) -> bool:
    obs = dict(observation or {})
    obs_scientific_name = str(
        obs.get('genus')
        or ''
    ).strip()
    obs_species = str(obs.get('species') or '').strip()
    if obs_scientific_name and obs_species:
        obs_scientific_name = f'{obs_scientific_name} {obs_species}'.strip()
    else:
        obs_scientific_name = str(obs.get('species_guess') or obs_scientific_name or '').strip()
    obs_common_name = str(obs.get('common_name') or '').strip()

    prediction_scientific_name = str(
        prediction.get('scientificName')
        or prediction.get('scientific_name')
        or prediction.get('name')
        or ''
    ).strip()
    taxon = dict(prediction.get('taxon') or {})
    if not prediction_scientific_name:
        prediction_scientific_name = str(
            taxon.get('scientificName')
            or taxon.get('scientific_name')
            or taxon.get('name')
            or ''
        ).strip()
    prediction_common_name = str(
        prediction.get('vernacularName')
        or prediction.get('vernacular_name')
        or prediction.get('commonName')
        or prediction.get('common_name')
        or ''
    ).strip()
    if not prediction_common_name:
        prediction_common_name = str(
            taxon.get('vernacularName')
            or taxon.get('vernacular_name')
            or taxon.get('preferred_common_name')
            or taxon.get('common_name')
            or ''
        ).strip()
    prediction_taxon_id = str(
        prediction.get('taxonId')
        or prediction.get('taxon_id')
        or ''
    ).strip()
    if not prediction_taxon_id:
        prediction_taxon_id = str(
            taxon.get('id')
            or taxon.get('taxonId')
            or taxon.get('taxon_id')
            or ''
        ).strip()
    selected_taxon_id = str(obs.get('ai_selected_taxon_id') or '').strip()
    selected_scientific_name = str(obs.get('ai_selected_scientific_name') or '').strip()

    if selected_taxon_id and prediction_taxon_id and selected_taxon_id == prediction_taxon_id:
        return True
    if selected_scientific_name and prediction_scientific_name and selected_scientific_name == prediction_scientific_name:
        return True
    if obs_scientific_name and prediction_scientific_name and obs_scientific_name == prediction_scientific_name:
        return True
    if obs_common_name and prediction_common_name and obs_common_name == prediction_common_name:
        return True
    return False


def build_cloud_ai_state_from_observation_identifications(
    observation: dict | None,
    identification_rows: list[dict] | None,
    local_images: list[dict] | None = None,
) -> dict | None:
    """Build the desktop AI-state cache from cloud observation_identifications rows.

    The cloud table stays authoritative; the desktop only keeps a derived cache
    so the observation detail dialog can render the same suggestions without a
    separate local AI run.
    """
    obs = dict(observation or {})
    rows = [dict(row or {}) for row in (identification_rows or []) if row]
    if not rows:
        return None

    local_image_rows = [dict(row or {}) for row in (local_images or []) if row]
    index_count = len(local_image_rows) or 1
    indices = list(range(index_count))
    paths = [str(row.get('filepath') or '').strip() for row in local_image_rows]
    image_ids = [_safe_int(row.get('id')) or None for row in local_image_rows]
    selected_service = _normalize_cloud_identification_service(obs.get('ai_selected_service'))

    service_rows: dict[str, dict] = {}
    for row in sorted(
        rows,
        key=lambda item: (
            _parse_sync_timestamp(item.get('created_at')) or datetime.min.replace(tzinfo=timezone.utc),
            _safe_int(item.get('id')) or 0,
        ),
        reverse=True,
    ):
        service = _normalize_cloud_identification_service(row.get('service'))
        if not service or service in service_rows:
            continue
        service_rows[service] = row

    predictions_by_service: dict[str, list[dict]] = {'artsorakel': [], 'inat': []}
    selected_by_service: dict[str, dict] = {}
    for service, row in service_rows.items():
        raw_predictions = [dict(pred or {}) for pred in (row.get('results') or []) if isinstance(pred, dict)]
        normalized_predictions: list[dict] = []
        for prediction in raw_predictions:
            taxon = _cloud_identification_prediction_taxon(prediction, service=service)
            if taxon:
                prediction['taxon'] = taxon
            if not str(prediction.get('scientificName') or '').strip():
                scientific_name = str(
                    prediction.get('scientific_name')
                    or taxon.get('scientificName')
                    or taxon.get('scientific_name')
                    or taxon.get('name')
                    or ''
                ).strip()
                if scientific_name:
                    prediction['scientificName'] = scientific_name
                    prediction['scientific_name'] = scientific_name
            if not str(prediction.get('vernacularName') or '').strip():
                vernacular_name = str(
                    prediction.get('vernacular_name')
                    or taxon.get('vernacularName')
                    or taxon.get('vernacular_name')
                    or taxon.get('preferred_common_name')
                    or taxon.get('common_name')
                    or ''
                ).strip()
                if vernacular_name:
                    prediction['vernacularName'] = vernacular_name
                    prediction['vernacular_name'] = vernacular_name
            if not str(prediction.get('displayName') or '').strip():
                display_name = _cloud_identification_prediction_display_name(prediction)
                if display_name:
                    prediction['displayName'] = display_name
                    prediction['display_name'] = display_name
            species_url = _cloud_identification_prediction_species_url(prediction, service=service)
            if species_url:
                prediction['species_url'] = species_url
                prediction['speciesUrl'] = species_url
                prediction['adbUrl'] = species_url
            normalized_predictions.append(prediction)

        if not normalized_predictions:
            top_scientific_name = str(row.get('top_scientific_name') or '').strip()
            top_vernacular_name = str(row.get('top_vernacular_name') or '').strip()
            top_taxon_id = str(row.get('top_taxon_id') or '').strip()
            top_species_url = str(
                row.get('top_species_url')
                or row.get('top_speciesUrl')
                or row.get('top_adbUrl')
                or ''
            ).strip()
            if top_scientific_name or top_vernacular_name or top_taxon_id:
                synth_prediction = {
                    'service': service,
                    'rank': 1,
                    'scientificName': top_scientific_name or None,
                    'scientific_name': top_scientific_name or None,
                    'vernacularName': top_vernacular_name or None,
                    'vernacular_name': top_vernacular_name or None,
                    'displayName': top_vernacular_name or top_scientific_name or top_taxon_id or 'Unknown',
                    'taxonId': top_taxon_id or None,
                    'taxon_id': top_taxon_id or None,
                    'probability': row.get('top_probability'),
                }
                if top_species_url:
                    synth_prediction['species_url'] = top_species_url
                    synth_prediction['speciesUrl'] = top_species_url
                    synth_prediction['adbUrl'] = top_species_url
                taxon = _cloud_identification_prediction_taxon(synth_prediction, service=service)
                if taxon:
                    synth_prediction['taxon'] = taxon
                normalized_predictions = [synth_prediction]

        if not normalized_predictions:
            continue

        selected_prediction = None
        if selected_service == service:
            selected_prediction = next(
                (
                    prediction
                    for prediction in normalized_predictions
                    if _cloud_identification_prediction_matches_observation(prediction, obs)
                ),
                None,
            )

        predictions_by_service[service] = normalized_predictions
        if selected_prediction:
            selected_by_service[service] = selected_prediction

    if not any(predictions_by_service.values()) and not selected_by_service:
        selected_service = _normalize_cloud_identification_service(obs.get('ai_selected_service'))
        selected_scientific_name = str(obs.get('ai_selected_scientific_name') or '').strip()
        selected_taxon_id = str(obs.get('ai_selected_taxon_id') or '').strip()
        if selected_service and (selected_scientific_name or selected_taxon_id):
            synth_prediction = {
                'service': selected_service,
                'rank': 1,
                'scientificName': selected_scientific_name or None,
                'scientific_name': selected_scientific_name or None,
                'vernacularName': str(obs.get('common_name') or '').strip() or None,
                'vernacular_name': str(obs.get('common_name') or '').strip() or None,
                'displayName': selected_scientific_name or str(obs.get('common_name') or '').strip() or selected_taxon_id or 'Unknown',
                'taxonId': selected_taxon_id or None,
                'taxon_id': selected_taxon_id or None,
                'probability': obs.get('ai_selected_probability'),
            }
            taxon = _cloud_identification_prediction_taxon(synth_prediction, service=selected_service)
            if taxon:
                synth_prediction['taxon'] = taxon
            predictions_by_service[selected_service] = [synth_prediction]
            selected_by_service[selected_service] = synth_prediction

    if not any(predictions_by_service.values()) and not selected_by_service:
        return None

    state: dict = {
        'predictions': {},
        'selected': {},
        'inat_predictions': {},
        'inat_selected': {},
        'selected_index': indices[0] if indices else None,
        'paths': paths,
        'image_ids': image_ids,
    }

    for index in indices:
        if predictions_by_service.get('artsorakel'):
            state['predictions'][index] = [dict(pred or {}) for pred in predictions_by_service['artsorakel']]
            if selected_by_service.get('artsorakel'):
                state['selected'][index] = dict(selected_by_service['artsorakel'])
        if predictions_by_service.get('inat'):
            state['inat_predictions'][index] = [dict(pred or {}) for pred in predictions_by_service['inat']]
            if selected_by_service.get('inat'):
                state['inat_selected'][index] = dict(selected_by_service['inat'])

    return state


def _apply_remote_observation_fields(
    local_id: int,
    remote: dict,
    *,
    fields: set[str] | None = None,
) -> None:
    requested_fields = {
        str(field or '').strip()
        for field in (fields or set(_SNAPSHOT_OBS_FIELDS))
        if str(field or '').strip()
    }
    if not requested_fields:
        return

    normalized_fields = {
        'sharing_scope' if field in {'visibility', 'sharing_scope'} else field
        for field in requested_fields
    }
    update_kwargs = _remote_observation_update_kwargs(remote)
    partial_kwargs = {
        key: value
        for key, value in update_kwargs.items()
        if key == 'allow_nulls' or key in normalized_fields
    }
    if len(partial_kwargs) > 1:
        ObservationDB.update_observation(int(local_id), **partial_kwargs)

    extra_values = _remote_observation_extra_values(remote)
    extra_updates = {
        key: value
        for key, value in extra_values.items()
        if key in normalized_fields
    }
    if not extra_updates:
        return

    conn = get_connection()
    try:
        assignments = [f'{column} = ?' for column in extra_updates]
        values = list(extra_updates.values())
        values.append(int(local_id))
        conn.execute(
            f"UPDATE observations SET {', '.join(assignments)} WHERE id = ?",
            tuple(values),
        )
        conn.commit()
    finally:
        conn.close()


def _inject_obs_exif_into_field_image(
    image_path: Path,
    obs_lat: float | None,
    obs_lon: float | None,
    obs_altitude: float | None,
    obs_datetime_str: str | None,
    camera_model: str | None = None,
    iso: int | None = None,
    exposure_time: float | None = None,
    f_number: float | None = None,
    gps_accuracy: float | None = None,
) -> None:
    """Write observation GPS/datetime and camera metadata into an image that has no EXIF.

    Called on cloud-synced field images whose EXIF was stripped by the web
    app's conversion.  Only modifies the file when the image has no
    existing DateTimeOriginal AND the observation has GPS or datetime data.
    Does nothing for unsupported files or on any error.
    """
    if not image_path.exists():
        return
    suffix = image_path.suffix.lower()
    if suffix not in {'.jpg', '.jpeg', '.webp'}:
        return
    has_coords = obs_lat is not None and obs_lon is not None
    has_datetime = bool(obs_datetime_str)
    has_camera_data = any(x is not None for x in (camera_model, iso, exposure_time, f_number))
    if not has_coords and not has_datetime and not has_camera_data:
        return
    try:
        from PIL import Image as _PilImage, ExifTags as _ExifTags
        with _PilImage.open(image_path) as img:
            existing_exif = img.getexif()
            existing_tags = {
                _ExifTags.TAGS.get(k, k): v for k, v in existing_exif.items()
            } if existing_exif else {}
            already_has_dt = any(
                t in existing_tags
                for t in ('DateTimeOriginal', 'DateTimeDigitized', 'DateTime')
            )
            try:
                already_has_gps = bool(existing_exif.get_ifd(0x8825))
            except Exception:
                already_has_gps = False
                
            already_has_camera = any(
                t in existing_tags
                for t in ('Model', 'Make', 'ISOSpeedRatings', 'ExposureTime', 'FNumber')
            )
            
            if already_has_dt and already_has_gps and already_has_camera:
                return  # nothing to do

            exif = existing_exif if existing_exif is not None else img.getexif()

            if not already_has_dt and has_datetime:
                try:
                    dt_exif = _exif_datetime_from_text(obs_datetime_str)
                    # Tag 306 = DateTime, 36867 = DateTimeOriginal, 36868 = DateTimeDigitized
                    if dt_exif:
                        exif[306] = dt_exif
                        exif[36867] = dt_exif
                        exif[36868] = dt_exif
                except Exception:
                    pass

            if not already_has_gps and has_coords:
                try:
                    def _deg_to_rational(deg_float):
                        d = int(abs(deg_float))
                        m_float = (abs(deg_float) - d) * 60
                        m = int(m_float)
                        s_float = (m_float - m) * 60
                        s_num = int(round(s_float * 1000))
                        return ((d, 1), (m, 1), (s_num, 1000))

                    gps_ifd = {
                        1: 'N' if obs_lat >= 0 else 'S',    # GPSLatitudeRef
                        2: _deg_to_rational(obs_lat),        # GPSLatitude
                        3: 'E' if obs_lon >= 0 else 'W',    # GPSLongitudeRef
                        4: _deg_to_rational(obs_lon),        # GPSLongitude
                    }
                    if obs_altitude is not None:
                        altitude = float(obs_altitude)
                        gps_ifd[5] = 1 if altitude < 0 else 0  # GPSAltitudeRef
                        gps_ifd[6] = (int(round(abs(altitude) * 100)), 100)
                    if gps_accuracy is not None:
                        acc = float(gps_accuracy)
                        if acc >= 0:
                            gps_ifd[31] = (int(round(acc * 100)), 100)  # GPSHPositioningError
                    exif[34853] = gps_ifd  # GPSInfo
                except Exception:
                    pass
                    
            if not already_has_camera:
                try:
                    if camera_model:
                        exif[272] = camera_model  # Model
                    if iso is not None:
                        exif[34855] = int(iso)  # ISOSpeedRatings
                    if exposure_time is not None:
                        try:
                            ex_time = float(exposure_time)
                            if ex_time > 0:
                                if ex_time >= 1:
                                    exif[33434] = (int(round(ex_time * 1000)), 1000)  # ExposureTime
                                else:
                                    exif[33434] = (1, int(round(1 / ex_time)))
                        except Exception:
                            pass
                    if f_number is not None:
                        try:
                            fn = float(f_number)
                            if fn > 0:
                                exif[33437] = (int(round(fn * 10)), 10)  # FNumber
                        except Exception:
                            pass
                except Exception:
                    pass

            mode = img.mode
            if suffix in {'.jpg', '.jpeg'} and mode not in {'RGB', 'L'}:
                img = img.convert('RGB')
            try:
                exif_bytes = exif.tobytes()
                if suffix == '.webp':
                    save_kwargs = {'format': 'WEBP', 'exif': exif_bytes}
                    if mode == 'RGBA':
                        save_kwargs['lossless'] = True
                    else:
                        save_kwargs['quality'] = 96
                else:
                    save_kwargs = {'format': 'JPEG', 'exif': exif_bytes, 'quality': 92}
                img.save(image_path, **save_kwargs)
            except Exception:
                pass
    except Exception as exc:
        print(f'[cloud_sync] Could not inject EXIF into {image_path.name}: {exc}')


def _exif_datetime_from_text(value: str | None) -> str | None:
    """Return EXIF datetime text (YYYY:MM:DD HH:MM:SS) from ISO/date text."""
    text = str(value or '').strip()
    if not text:
        return None
    try:
        normalized = text.replace('Z', '+00:00')
        parsed = datetime.fromisoformat(normalized)
        return parsed.strftime('%Y:%m:%d %H:%M:%S')
    except Exception:
        pass
    try:
        if 'T' in text:
            date_part, time_part = text.split('T', 1)
        elif ' ' in text:
            date_part, time_part = text.split(' ', 1)
        else:
            date_part, time_part = text, '00:00:00'
        time_part = time_part.split('+', 1)[0].split('-', 1)[0].split('.', 1)[0]
        bits = [part for part in time_part.split(':') if part]
        while len(bits) < 3:
            bits.append('00')
        return f"{date_part.replace('-', ':')} {':'.join(bits[:3])}"
    except Exception:
        return None


def _load_obs_exif_fallback(observation_id: int, fallback_datetime: str | None = None) -> tuple[float | None, float | None, float | None, float | None, str | None]:
    """Return (lat, lon, altitude, gps_accuracy, datetime_str) from local observation data."""
    try:
        obs = ObservationDB.get_observation(observation_id)
        if not obs:
            return None, None, None, None, fallback_datetime
        lat = obs.get('gps_latitude')
        lon = obs.get('gps_longitude')
        altitude = obs.get('gps_altitude')
        accuracy = obs.get('gps_accuracy')
        datetime_str = str(
            obs.get('captured_at')
            or obs.get('date')
            or fallback_datetime
            or ''
        ).strip() or None
        return (float(lat) if lat is not None else None,
                float(lon) if lon is not None else None,
                float(altitude) if altitude is not None else None,
                float(accuracy) if accuracy is not None else None,
                datetime_str)
    except Exception:
        return None, None, None, None, fallback_datetime


def _is_missing_cloud_image_error(exc: Exception | str | None) -> bool:
    text = str(exc or '').strip().lower()
    if not text:
        return False
    return (
        'cloud image file is missing from storage' in text
        or 'nosuchkey' in text
    )


def _cloud_missing_image_warning(local_id: int, remote_image: dict) -> str:
    cloud_image_id = str(remote_image.get('id') or '').strip() or '?'
    filename = Path(str(remote_image.get('original_filename') or '')).name or f'cloud image {cloud_image_id}'
    return (
        f'obs {int(local_id)}: skipped missing cloud image {cloud_image_id}'
        f' ({filename})'
    )


def _cloud_thumb_save_format(path: Path) -> tuple[str, str, dict]:
    if features.check('webp'):
        return 'WEBP', 'image/webp', {'quality': 65, 'method': 4}
    return 'JPEG', 'image/jpeg', {'quality': 72}


def _cloud_upload_policy_from_meta(upload_meta: dict | None) -> dict[str, object]:
    meta = dict(upload_meta or {})
    upload_mode = str(meta.get('upload_mode') or meta.get('uploadMode') or 'full').strip().lower() or 'full'
    cloud_plan = str(meta.get('cloud_plan') or meta.get('cloudPlan') or '').strip().lower()
    quality_profile = str(meta.get('quality_profile') or meta.get('qualityProfile') or '').strip().lower()
    profile = {}
    if cloud_plan:
        profile['cloud_plan'] = cloud_plan
    elif quality_profile == 'high':
        profile['is_pro'] = True
    return build_cloud_upload_policy(normalize_cloud_plan_profile(profile), upload_mode=upload_mode)


def _prepare_cloud_image_upload_file(
    source_path: str,
    temp_dir: Path,
    image_id: int,
    upload_meta: dict | None,
) -> tuple[Path, int, int, int, int, str, int | float | None]:
    source = Path(str(source_path or '').strip())
    if not source.exists():
        raise FileNotFoundError(source)

    policy = _cloud_upload_policy_from_meta(upload_meta)
    resize_max_pixels = max(
        1,
        int(
            policy.get('resizeMaxPixels')
            or policy.get('resize_max_pixels')
            or policy.get('maxPixels')
            or 0
        ) or 20_000_000,
    )
    resize_max_edge = policy.get('resizeMaxEdge') or policy.get('resize_max_edge')
    quality_profile = str(policy.get('qualityProfile') or 'standard').strip().lower() or 'standard'
    byte_cap = int(policy.get('fullImageByteCap') or 0)
    webp_qualities = list(build_full_image_webp_quality_attempts(quality_profile))

    if not features.check('webp'):
        raise CloudSyncError(WEBP_REQUIRED_FOR_CLOUD_MEDIA_UPLOAD_MESSAGE)

    with Image.open(source) as img:
        img = ImageOps.exif_transpose(img)
        source_width = int(img.width or 0)
        source_height = int(img.height or 0)
        if not source_width or not source_height:
            raise RuntimeError('Could not determine image dimensions')

        if img.mode in ('RGBA', 'LA') or 'transparency' in img.info:
            rgba = img.convert('RGBA')
            background = Image.new('RGB', rgba.size, (255, 255, 255))
            background.paste(rgba, mask=rgba.getchannel('A'))
            img = background
        elif img.mode != 'RGB':
            img = img.convert('RGB')

        target = scale_dimensions_to_max_pixels(source_width, source_height, resize_max_pixels, resize_max_edge)
        if target['resized']:
            img = img.resize((int(target['width']), int(target['height'])), Image.Resampling.LANCZOS)

        for attempt_quality in webp_qualities:
            buffer = io.BytesIO()
            img.save(buffer, 'WEBP', quality=attempt_quality, method=4)
            data = buffer.getvalue()
            if byte_cap and len(data) > byte_cap:
                continue

            out_path = temp_dir / f'cloud_{int(image_id):04d}.webp'
            out_path.write_bytes(data)
            try:
                source_stat = source.stat()
                os.utime(out_path, (source_stat.st_atime, source_stat.st_mtime))
            except Exception:
                pass

            return (
                out_path,
                source_width,
                source_height,
                int(img.width or 0),
                int(img.height or 0),
                'image/webp',
                attempt_quality,
            )

    raise CloudSyncError(IMAGE_TOO_LARGE_FOR_PLAN_MESSAGE)


def _profile_generate_all_sizes(image_path: str, image_id: int):
    profiler = _cloud_sync_current_profiler()
    start = _cloud_sync_perf_counter()
    try:
        return generate_all_sizes(image_path, image_id)
    finally:
        if profiler is not None:
            try:
                profiler.record_generate_all_sizes(max(0.0, (_cloud_sync_perf_counter() - start) * 1000.0))
            except Exception:
                pass


def _content_type_for_path(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix == '.webp':
        return 'image/webp'
    return mimetypes.guess_type(path.name)[0] or 'image/jpeg'


def _detected_image_extension(path: str | Path) -> str:
    try:
        with Image.open(path) as img:
            fmt = str(img.format or '').strip().upper()
    except Exception:
        return Path(path).suffix.lower() or '.jpg'
    if fmt == 'WEBP':
        return '.webp'
    if fmt == 'AVIF':
        return '.avif'
    if fmt in {'JPEG', 'JPG'}:
        return '.jpg'
    if fmt == 'PNG':
        return '.png'
    if fmt == 'TIFF':
        return '.tif'
    return Path(path).suffix.lower() or '.jpg'


def _rename_to_detected_image_extension(path: Path) -> Path:
    detected_ext = _detected_image_extension(path)
    if not detected_ext or path.suffix.lower() == detected_ext:
        return path
    target = path.with_suffix(detected_ext)
    counter = 1
    while target.exists() and target != path:
        target = path.with_name(f"{path.stem}_{counter}{detected_ext}")
        counter += 1
    path.rename(target)
    return target


def _apply_remote_image_metadata_only_to_local(
    local_image: dict,
    remote_image: dict,
) -> None:
    """Patch the local image row from remote metadata without touching bytes.

    Used when the remote row differs only in descriptive fields (AI crop,
    calibration reference, notes, sort order, etc.). Skips the download,
    thumbnail regeneration and file signature bookkeeping that
    ``_sync_existing_remote_image_to_local`` performs.
    """
    image_id = int(local_image.get('id'))
    calibration_id = _local_calibration_id_for_image(remote_image)
    update_kwargs = {
        'image_type': str(remote_image.get('image_type') or 'field'),
        'scale': remote_image.get('scale_microns_per_pixel'),
        'notes': remote_image.get('notes'),
        'micro_category': remote_image.get('micro_category'),
        'objective_name': remote_image.get('objective_name'),
        'measure_color': remote_image.get('measure_color'),
        'mount_medium': remote_image.get('mount_medium'),
        'stain': remote_image.get('stain'),
        'sample_type': remote_image.get('sample_type'),
        'sample_source': _cloud_to_desktop_sample_source(remote_image.get('sample_source')),
        'contrast': remote_image.get('contrast'),
        'crop_mode': remote_image.get('crop_mode'),
        'gps_source': remote_image.get('gps_source'),
        'resample_scale_factor': remote_image.get('resample_scale_factor'),
        'ai_crop_box': _remote_ai_crop_box(remote_image),
        'ai_crop_source_size': _remote_ai_crop_source_size(remote_image),
        'ai_crop_is_custom': _remote_ai_crop_is_custom(remote_image),
        'sort_order': remote_image.get('sort_order'),
    }
    if calibration_id is not None:
        update_kwargs['calibration_id'] = calibration_id
    ImageDB.update_image(image_id, **update_kwargs)
    remote_captured_at = _cloud_image_captured_at_to_local(remote_image.get('captured_at'))
    if remote_captured_at is not None:
        _update_image_columns_without_touching_observation(
            image_id,
            {'captured_at': remote_captured_at},
        )
    conn = get_connection()
    try:
        conn.execute(
            'UPDATE images SET cloud_id = ?, synced_at = ? WHERE id = ?',
            (str(remote_image.get('id') or '').strip() or None, datetime.now(timezone.utc).isoformat(), image_id),
        )
        conn.commit()
    finally:
        conn.close()


def _promote_temp_imported_image_if_needed(
    local_image_id: int,
    observation_id: int,
    temp_dir: Path,
) -> Path | None:
    """Copy a temp-backed imported image into a durable images path.

    Some sync tests and older rows do not have an observation folder_path yet,
    which means ``ImageDB.add_image(..., copy_to_folder=True)`` can leave the
    image pointing at the temp download path. That path is cleaned up at the
    end of the import, so the row would look missing on the next reconciliation
    pass. If the stored filepath still lives under the temp dir, copy it to a
    stable observation-owned location and update the row.
    """
    if local_image_id <= 0:
        return None
    try:
        temp_root = Path(temp_dir).resolve()
        image_row = ImageDB.get_image(int(local_image_id)) or {}
    except Exception:
        return None
    current_path_text = str(image_row.get('filepath') or '').strip()
    if not current_path_text:
        return None
    try:
        current_path = Path(current_path_text).resolve()
    except Exception:
        return None
    try:
        if not current_path.is_relative_to(temp_root):
            return current_path
    except Exception:
        if str(current_path).startswith(str(temp_root)):
            pass
        else:
            return current_path

    fallback_dir = Path(get_images_dir()) / f'observation_{int(observation_id)}'
    fallback_dir.mkdir(parents=True, exist_ok=True)
    target_path = fallback_dir / current_path.name
    counter = 1
    while target_path.exists():
        target_path = fallback_dir / f"{current_path.stem}_{counter}{current_path.suffix}"
        counter += 1
    shutil.copy2(current_path, target_path)
    try:
        ImageDB.update_image(int(local_image_id), filepath=str(target_path))
    except Exception:
        return None
    return target_path


def _ensure_local_metadata_only_microscope_anchor(
    client: "SporelyCloudClient" | None,
    local_observation_id: int,
    remote_image: dict,
    local_image: dict | None = None,
) -> int | None:
    """Create or update a file-less microscope anchor for a remote row.

    These rows are valid measurement anchors even though the raw microscope
    bytes were never uploaded. The local row must keep its cloud id mapping and
    metadata, but it must not trigger the download/materialization branch.
    """
    remote_row = dict(remote_image or {})
    if not _is_metadata_only_microscope_cloud_image(remote_row):
        return None

    cloud_image_id = str(remote_row.get('id') or '').strip()
    if not cloud_image_id:
        return None

    existing_local = dict(local_image or {})
    local_image_id = _safe_int(existing_local.get('id'))
    existing_path = str(existing_local.get('filepath') or '').strip()
    has_local_file = bool(existing_path)
    if has_local_file:
        try:
            has_local_file = Path(existing_path).exists()
        except Exception:
            has_local_file = False

    calibration_id = _local_calibration_id_for_image(remote_row)
    ai_crop_box = _remote_ai_crop_box(remote_row)
    ai_crop_source_size = _remote_ai_crop_source_size(remote_row)
    metadata_columns = {
        'image_type': 'microscope',
        'scale_microns_per_pixel': remote_row.get('scale_microns_per_pixel'),
        'notes': remote_row.get('notes'),
        'micro_category': remote_row.get('micro_category'),
        'objective_name': remote_row.get('objective_name'),
        'measure_color': remote_row.get('measure_color'),
        'mount_medium': remote_row.get('mount_medium'),
        'stain': remote_row.get('stain'),
        'sample_type': remote_row.get('sample_type'),
        'sample_source': _cloud_to_desktop_sample_source(remote_row.get('sample_source')),
        'contrast': remote_row.get('contrast'),
        'sort_order': remote_row.get('sort_order'),
        'crop_mode': remote_row.get('crop_mode'),
        'gps_source': remote_row.get('gps_source'),
        'resample_scale_factor': remote_row.get('resample_scale_factor'),
        'ai_crop_x1': ai_crop_box[0] if ai_crop_box and len(ai_crop_box) == 4 else None,
        'ai_crop_y1': ai_crop_box[1] if ai_crop_box and len(ai_crop_box) == 4 else None,
        'ai_crop_x2': ai_crop_box[2] if ai_crop_box and len(ai_crop_box) == 4 else None,
        'ai_crop_y2': ai_crop_box[3] if ai_crop_box and len(ai_crop_box) == 4 else None,
        'ai_crop_source_w': ai_crop_source_size[0] if ai_crop_source_size and len(ai_crop_source_size) == 2 else None,
        'ai_crop_source_h': ai_crop_source_size[1] if ai_crop_source_size and len(ai_crop_source_size) == 2 else None,
        'ai_crop_is_custom': _remote_ai_crop_is_custom(remote_row),
    }
    remote_captured_at = _cloud_image_captured_at_to_local(remote_row.get('captured_at'))
    if remote_captured_at is not None:
        metadata_columns['captured_at'] = remote_captured_at
    if calibration_id is not None:
        metadata_columns['calibration_id'] = calibration_id

    if local_image_id > 0:
        update_columns = dict(metadata_columns)
        if not has_local_file:
            update_columns['filepath'] = ''
        _update_image_columns_without_touching_observation(local_image_id, update_columns)
    else:
        created_local_image_id = ImageDB.add_image(
            observation_id=int(local_observation_id),
            filepath='',
            image_type='microscope',
            scale=remote_row.get('scale_microns_per_pixel'),
            notes=remote_row.get('notes'),
            micro_category=remote_row.get('micro_category'),
            objective_name=remote_row.get('objective_name'),
            measure_color=remote_row.get('measure_color'),
            mount_medium=remote_row.get('mount_medium'),
            stain=remote_row.get('stain'),
            sample_type=remote_row.get('sample_type'),
            sample_source=_cloud_to_desktop_sample_source(remote_row.get('sample_source')),
            contrast=remote_row.get('contrast'),
            sort_order=remote_row.get('sort_order'),
            crop_mode=remote_row.get('crop_mode'),
            gps_source=remote_row.get('gps_source'),
            resample_scale_factor=remote_row.get('resample_scale_factor'),
            calibration_id=calibration_id,
            ai_crop_box=ai_crop_box,
            ai_crop_source_size=ai_crop_source_size,
            ai_crop_is_custom=_remote_ai_crop_is_custom(remote_row),
            captured_at=remote_captured_at,
            copy_to_folder=False,
            mark_observation_dirty=False,
            source_role='cloud_recovery_cache',
            file_purpose='cache',
            original_mime_type=None,
            working_mime_type=None,
        )
        local_image_id = _safe_int(created_local_image_id)
        if local_image_id <= 0:
            return None
        has_local_file = False

    _update_image_columns_without_touching_observation(
        local_image_id,
        {
            'cloud_id': cloud_image_id,
            'synced_at': datetime.now(timezone.utc).isoformat(),
        },
    )
    if not has_local_file:
        _update_image_columns_without_touching_observation(
            local_image_id,
            {
                'filepath': '',
                'source_role': 'cloud_recovery_cache',
                'file_purpose': 'cache',
                'original_mime_type': None,
                'working_mime_type': None,
            },
        )

    if (
        client is not None
        and not getattr(client, 'is_pull_only', False)
        and not _portable_cloud_identity_pending_for_observation(
            int(local_observation_id)
        )
        and not _remote_image_desktop_id_current(remote_row, local_image_id)
    ):
        set_image_desktop_id = getattr(client, 'set_image_desktop_id', None)
        if callable(set_image_desktop_id):
            try:
                set_image_desktop_id(cloud_image_id, int(local_image_id))
                remote_row['desktop_id'] = int(local_image_id)
            except Exception as exc:
                if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
                    raise

    if local_image is not None:
        local_image['id'] = local_image_id
        local_image['cloud_id'] = cloud_image_id
        if not has_local_file:
            local_image['filepath'] = ''
    return local_image_id


def _remote_image_bytes_match_local(local_image: dict, remote_image: dict) -> bool:
    """True when the remote row points at bytes the local copy already has.

    Guards the metadata-only pull path: we only skip the download when the
    local file exists and its file-content signature matches the signature we
    recorded the last time we synced from the same cloud row. That signature
    is stamped both after upload and after previous downloads, so a cloud-side
    metadata-only edit (AI crop, calibration reference, notes …) keeps the
    signature stable and lets us patch the DB row without re-downloading.
    """
    local_cloud_id = str(local_image.get('cloud_id') or '').strip()
    remote_cloud_id = str(remote_image.get('id') or '').strip()
    if not local_cloud_id or not remote_cloud_id or local_cloud_id != remote_cloud_id:
        return False
    existing_path = str(local_image.get('filepath') or '').strip()
    if not existing_path:
        return False
    try:
        if not Path(existing_path).exists():
            return False
    except Exception:
        return False
    try:
        current_sig = _file_content_signature(existing_path)
    except Exception:
        return False
    if not current_sig:
        return False
    stored_sig = _load_cloud_image_file_signature(
        local_image.get('observation_id'), local_image.get('id')
    )
    return bool(stored_sig) and stored_sig == current_sig


def _sync_existing_remote_image_to_local(
    client: "SporelyCloudClient",
    local_image: dict,
    remote_image: dict,
    materialize_remote_images: bool = True,
) -> None:
    if not materialize_remote_images:
        return
    if _remote_image_bytes_match_local(local_image, remote_image):
        # Metadata-only remote change (e.g. AI crop or calibration reference).
        # Skip the download and thumbnail regeneration — patch the row only.
        _apply_remote_image_metadata_only_to_local(local_image, remote_image)
        return
    image_id = int(local_image.get('id'))
    existing_path = str(local_image.get('filepath') or '').strip()
    temp_dir = Path(tempfile.mkdtemp(prefix=f'sporely_cloud_image_{image_id}_'))
    try:
        filename = Path(str(remote_image.get('original_filename') or '')).name or f'cloud_{image_id}.jpg'
        temp_path = temp_dir / filename
        client.download_image_file(str(remote_image.get('storage_path') or ''), temp_path)
        temp_path = _rename_to_detected_image_extension(temp_path)
        image_type = str(remote_image.get('image_type') or 'field').strip().lower()
        target_path = Path(existing_path) if existing_path else temp_path

        # Preserve any existing local field image. Cloud field copies are the
        # reduced sync artifact, so metadata can update without replacing the
        # desktop original bytes.
        local_file_exists = bool(existing_path and Path(existing_path).exists())
        local_is_larger = bool(local_file_exists and image_type == 'field')

        if image_type == 'field' and not local_is_larger:
            obs_id = int(local_image.get('observation_id') or 0)
            if obs_id > 0:
                lat, lon, altitude, gps_acc, datetime_str = _load_obs_exif_fallback(
                    obs_id,
                    fallback_datetime=remote_image.get('captured_at'),
                )
                img_lat = remote_image.get('gps_latitude') if remote_image.get('gps_latitude') is not None else lat
                img_lon = remote_image.get('gps_longitude') if remote_image.get('gps_longitude') is not None else lon
                img_alt = remote_image.get('gps_altitude') if remote_image.get('gps_altitude') is not None else altitude
                img_acc = remote_image.get('gps_accuracy') if remote_image.get('gps_accuracy') is not None else gps_acc
                _inject_obs_exif_into_field_image(
                    temp_path, img_lat, img_lon, img_alt, datetime_str,
                    camera_model=remote_image.get('camera_model'),
                    iso=remote_image.get('iso'),
                    exposure_time=remote_image.get('exposure_time'),
                    f_number=remote_image.get('f_number'),
                    gps_accuracy=img_acc,
                )

        if existing_path and not local_is_larger:
            detected_ext = _detected_image_extension(temp_path)
            if detected_ext and target_path.suffix.lower() != detected_ext:
                target_path = target_path.with_suffix(detected_ext)
            target_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(temp_path, target_path)
        # If local is larger it is the full-res desktop-imported original — keep it as-is.

        calibration_id = _local_calibration_id_for_image(remote_image)
        update_kwargs = {
            'filepath': str(target_path),
            'image_type': str(remote_image.get('image_type') or 'field'),
            'scale': remote_image.get('scale_microns_per_pixel'),
            'notes': remote_image.get('notes'),
            'micro_category': remote_image.get('micro_category'),
            'objective_name': remote_image.get('objective_name'),
            'measure_color': remote_image.get('measure_color'),
            'mount_medium': remote_image.get('mount_medium'),
            'stain': remote_image.get('stain'),
            'sample_type': remote_image.get('sample_type'),
            'sample_source': _cloud_to_desktop_sample_source(remote_image.get('sample_source')),
            'contrast': remote_image.get('contrast'),
            'crop_mode': remote_image.get('crop_mode'),
            'gps_source': remote_image.get('gps_source'),
            'resample_scale_factor': remote_image.get('resample_scale_factor'),
            'ai_crop_box': _remote_ai_crop_box(remote_image),
            'ai_crop_source_size': _remote_ai_crop_source_size(remote_image),
            'ai_crop_is_custom': _remote_ai_crop_is_custom(remote_image),
        }
        if calibration_id is not None:
            update_kwargs['calibration_id'] = calibration_id
        ImageDB.update_image(image_id, **update_kwargs)
        remote_captured_at = _cloud_image_captured_at_to_local(remote_image.get('captured_at'))
        if remote_captured_at is not None:
            _update_image_columns_without_touching_observation(
                image_id,
                {'captured_at': remote_captured_at},
            )
        conn = get_connection()
        try:
            conn.execute(
                'UPDATE images SET cloud_id = ?, synced_at = ? WHERE id = ?',
                (str(remote_image.get('id') or '').strip() or None, datetime.now(timezone.utc).isoformat(), image_id),
            )
            conn.commit()
        finally:
            conn.close()
        try:
            _profile_generate_all_sizes(str(target_path), image_id)
        except Exception:
            pass
        try:
            file_sig = _file_content_signature(str(target_path))
            if file_sig:
                _store_cloud_image_file_signature(int(local_image.get('observation_id') or 0), image_id, file_sig)
        except Exception:
            pass
        _increment_sync_summary(_cloud_sync_current_summary(), 'remote_media_materializations')
    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)


def _remote_image_desktop_id_current(remote_image, local_image_id) -> bool:
    """True when the cloud row's desktop_id already equals the local image id.

    Guards every ``set_image_desktop_id`` call in the pull path. The PATCH used
    to be a tolerated no-op when the link was already correct, but the cloud
    ``updated_at`` trigger now advances on EVERY update — so an unconditional
    relink PATCH per pulled image makes each sync's own writes look like child
    changes to the next sync's probe (self-sustaining full-pull echo loop).
    """
    try:
        lid = int(local_image_id)
    except (TypeError, ValueError):
        return False
    if lid <= 0:
        return False
    try:
        return int((remote_image or {}).get('desktop_id')) == lid
    except (TypeError, ValueError):
        return False


def _apply_remote_images_to_local(
    client: "SporelyCloudClient",
    local_id: int,
    remote_images: list[dict],
    *,
    allow_delete: bool = True,
    materialize_remote_images: bool = True,
) -> list[str]:
    warnings: list[str] = []
    # ``set_image_desktop_id`` PATCHes the cloud row's desktop_id link — a
    # cloud write. Skip it when running under Download-from-Cloud so we
    # can honour the zero-cloud-writes contract. The pull_only flag comes
    # from the wrapping ``PullOnlyCloudClient`` proxy.
    pull_only = bool(getattr(client, 'is_pull_only', False))
    suppress_reverse_identity = (
        pull_only or _portable_cloud_identity_pending_for_observation(int(local_id))
    )
    local_images = ImageDB.get_images_for_observation(int(local_id))
    local_cloud_map = {
        str(img.get('cloud_id') or '').strip(): img
        for img in local_images
        if should_pull_cloud_image_to_desktop(img)
        if str(img.get('cloud_id') or '').strip()
    }
    remote_map = {
        str(img.get('id') or '').strip(): img
        for img in (remote_images or [])
        if should_pull_cloud_image_to_desktop(img)
        if str(img.get('id') or '').strip()
    }
    tombstoned_cloud_ids = _local_tombstoned_cloud_image_ids(remote_map.keys())

    for cloud_image_id, remote_image in remote_map.items():
        if cloud_image_id in tombstoned_cloud_ids:
            warning = _tombstoned_cloud_image_warning(local_id, cloud_image_id)
            warnings.append(warning)
            print(f'[cloud_sync] Warning: {warning}')
            continue
        local_image = local_cloud_map.get(cloud_image_id)
        if local_image:
            if _is_metadata_only_microscope_cloud_image(remote_image):
                _ensure_local_metadata_only_microscope_anchor(
                    client,
                    int(local_id),
                    remote_image,
                    local_image=local_image,
                )
                continue
            if not materialize_remote_images:
                _apply_remote_image_metadata_only_to_local(local_image, remote_image)
                if not suppress_reverse_identity and not _remote_image_desktop_id_current(
                    remote_image, local_image.get('id')
                ):
                    try:
                        client.set_image_desktop_id(cloud_image_id, int(local_image.get('id')))
                        remote_image['desktop_id'] = int(local_image.get('id'))
                    except Exception:
                        pass
                continue
            try:
                _sync_existing_remote_image_to_local(
                    client,
                    local_image,
                    remote_image,
                    materialize_remote_images=materialize_remote_images,
                )
            except CloudSyncError as exc:
                if _is_missing_cloud_image_error(exc):
                    print(f'[cloud_sync] Warning: {_cloud_missing_image_warning(local_id, remote_image)}')
                    continue
                raise
            if not suppress_reverse_identity and not _remote_image_desktop_id_current(
                remote_image, local_image.get('id')
            ):
                try:
                    client.set_image_desktop_id(cloud_image_id, int(local_image.get('id')))
                    remote_image['desktop_id'] = int(local_image.get('id'))
                except Exception:
                    pass
            continue

        if _is_metadata_only_microscope_cloud_image(remote_image):
            _ensure_local_metadata_only_microscope_anchor(
                client,
                int(local_id),
                remote_image,
            )
            continue
        if not materialize_remote_images:
            continue

        storage_path = _normalize_cloud_media_key(remote_image.get('storage_path'))
        if not storage_path:
            warning = (
                f"obs {local_id}: skipped cloud image {cloud_image_id} "
                f"because it is missing storage path"
            )
            warnings.append(warning)
            print(f'[cloud_sync] Warning: {warning}')
            continue
        temp_dir = Path(tempfile.mkdtemp(prefix=f'sporely_cloud_pull_{local_id}_'))
        try:
            filename = Path(str(remote_image.get('original_filename') or '')).name or f'{cloud_image_id}.jpg'
            download_path = temp_dir / filename
            try:
                client.download_image_file(storage_path, download_path)
                download_path = _rename_to_detected_image_extension(download_path)
            except CloudSyncError as exc:
                if _is_missing_cloud_image_error(exc):
                    print(f'[cloud_sync] Warning: {_cloud_missing_image_warning(local_id, remote_image)}')
                    continue
                raise
            new_image_type = str(remote_image.get('image_type') or 'field').strip().lower()
            if new_image_type == 'field':
                lat, lon, altitude, gps_acc, datetime_str = _load_obs_exif_fallback(
                    int(local_id),
                    fallback_datetime=remote_image.get('captured_at'),
                )
                img_lat = remote_image.get('gps_latitude') if remote_image.get('gps_latitude') is not None else lat
                img_lon = remote_image.get('gps_longitude') if remote_image.get('gps_longitude') is not None else lon
                img_alt = remote_image.get('gps_altitude') if remote_image.get('gps_altitude') is not None else altitude
                img_acc = remote_image.get('gps_accuracy') if remote_image.get('gps_accuracy') is not None else gps_acc
                _inject_obs_exif_into_field_image(
                    download_path, img_lat, img_lon, img_alt, datetime_str,
                    camera_model=remote_image.get('camera_model'),
                    iso=remote_image.get('iso'),
                    exposure_time=remote_image.get('exposure_time'),
                    f_number=remote_image.get('f_number'),
                    gps_accuracy=img_acc,
                )
            local_image_id = ImageDB.add_image(
                observation_id=int(local_id),
                filepath=str(download_path),
                image_type=str(remote_image.get('image_type') or 'field'),
                scale=remote_image.get('scale_microns_per_pixel'),
                notes=remote_image.get('notes'),
                micro_category=remote_image.get('micro_category'),
                objective_name=remote_image.get('objective_name'),
                measure_color=remote_image.get('measure_color'),
                mount_medium=remote_image.get('mount_medium'),
                stain=remote_image.get('stain'),
                sample_type=remote_image.get('sample_type'),
                sample_source=_cloud_to_desktop_sample_source(remote_image.get('sample_source')),
                contrast=remote_image.get('contrast'),
                crop_mode=remote_image.get('crop_mode'),
                sort_order=remote_image.get('sort_order'),
                gps_source=remote_image.get('gps_source'),
                resample_scale_factor=remote_image.get('resample_scale_factor'),
                calibration_id=_local_calibration_id_for_image(remote_image),
                ai_crop_box=_remote_ai_crop_box(remote_image),
                ai_crop_source_size=_remote_ai_crop_source_size(remote_image),
                ai_crop_is_custom=_remote_ai_crop_is_custom(remote_image),
                captured_at=_cloud_image_captured_at_to_local(
                    remote_image.get('captured_at')
                ),
                copy_to_folder=True,
                mark_observation_dirty=False,
                source_role='cloud_recovery_cache',
                file_purpose='cache',
                original_mime_type=None,
                working_mime_type=guess_local_image_mime_type(download_path),
            )
            download_path = _promote_temp_imported_image_if_needed(
                int(local_image_id),
                int(local_id),
                temp_dir,
            ) or download_path
            conn = get_connection()
            try:
                conn.execute(
                    'UPDATE images SET cloud_id = ?, synced_at = ? WHERE id = ?',
                    (cloud_image_id, datetime.now(timezone.utc).isoformat(), int(local_image_id)),
                )
                conn.commit()
            finally:
                conn.close()
            if not suppress_reverse_identity and not _remote_image_desktop_id_current(
                remote_image, local_image_id
            ):
                try:
                    client.set_image_desktop_id(cloud_image_id, int(local_image_id))
                    remote_image['desktop_id'] = int(local_image_id)
                except Exception:
                    pass
            try:
                _profile_generate_all_sizes(str(download_path), int(local_image_id))
            except Exception:
                pass
            _increment_sync_summary(_cloud_sync_current_summary(), 'remote_media_materializations')
        finally:
            shutil.rmtree(temp_dir, ignore_errors=True)

    if allow_delete:
        for cloud_image_id, local_image in local_cloud_map.items():
            if cloud_image_id in remote_map:
                continue
            image_id = int(local_image.get('id') or 0)
            if image_id <= 0:
                continue
            if MeasurementDB.get_measurements_for_image(image_id):
                warnings.append(
                    f"obs {local_id}: kept local image {image_id} because it has measurements, even though the cloud copy was removed"
                )
                continue
            try:
                ImageDB.delete_image(image_id)
            except Exception as exc:
                warnings.append(f"obs {local_id}: could not remove local image {image_id}: {exc}")

    _normalize_cloud_pulled_image_order(int(local_id))
    return warnings


def _build_plan_from_automatic_decisions(detail: dict) -> dict:
    """Translate ``detail['automatic_decisions']`` into a resolve_conflict_plan.

    The produced plan uses the exact same primitives ordinary sync would
    otherwise reach for; we route through the plan executor so drift
    protection, identity validation, presentation policy, statistics
    recomputation, and finalization all run consistently.
    """
    detail = detail or {}
    auto = detail.get('automatic_decisions') or {}
    items: list[dict] = []
    for entry in auto.get('fields') or []:
        action = entry.get('action')
        field = entry.get('field')
        if not field:
            continue
        if action == 'push_local':
            items.append({'kind': 'field', 'field': field, 'choice': 'local'})
        elif action == 'pull_cloud':
            items.append({'kind': 'field', 'field': field, 'choice': 'cloud'})
        elif action == 'auto_draft_wins':
            side = entry.get('chosen_side') or 'local'
            items.append({'kind': 'field', 'field': field, 'choice': side})
    for entry in auto.get('media') or []:
        kind = entry.get('kind')
        side = entry.get('side')
        action = entry.get('action') or ''
        local_id = _safe_int(entry.get('local_id')) or None
        cloud_id = str(entry.get('cloud_id') or '').strip() or None
        if kind == 'image' and side == 'local_only':
            items.append({'kind': 'image', 'side': 'local_only',
                          'local_id': local_id, 'choice': 'upload'})
        elif kind == 'image' and side == 'cloud_only':
            items.append({'kind': 'image', 'side': 'cloud_only',
                          'cloud_id': cloud_id, 'choice': 'download'})
        elif kind == 'image_metadata':
            choice = 'local' if action == 'auto_apply_local' else 'cloud'
            items.append({'kind': 'image_metadata',
                          'local_id': local_id, 'cloud_id': cloud_id,
                          'choice': choice})
        elif kind == 'measurement' and side == 'local_only':
            items.append({'kind': 'measurement', 'side': 'local_only',
                          'local_id': local_id, 'choice': 'upload'})
        elif kind == 'measurement' and side == 'cloud_only':
            items.append({'kind': 'measurement', 'side': 'cloud_only',
                          'cloud_id': cloud_id, 'choice': 'download'})
        elif kind == 'measurement' and side == 'matched':
            choice = 'local' if action == 'auto_apply_local' else 'cloud'
            items.append({'kind': 'measurement', 'side': 'matched',
                          'local_id': local_id, 'cloud_id': cloud_id,
                          'choice': choice})
    return {
        'items': items,
        'baseline': detail.get('plan_baseline'),
        'allow_media_deletion': False,
        'derived_statistics': (
            'recompute_from_measurements'
            if detail.get('derived_statistics') else 'unchanged'
        ),
    }


def finalize_sync_candidates(
    client: "SporelyCloudClient",
    candidates: list[dict],
    *,
    prepare_images_cb=None,
) -> tuple[list[dict], list[dict]]:
    """The shared final gate used by both caller sites before the dialog opens.

    For each preflight-flagged candidate:

    1. Load read-only conflict detail.
    2. If ``automatic_decisions`` contains any operations, execute them
       through :func:`resolve_conflict_plan` (same executor used for manual
       plans — same drift/identity/finalization guarantees).
    3. Reread and reclassify.
    4. Keep only candidates whose FINAL detail has ``has_manual_conflicts=True``.

    Automatic-execution failures are returned separately as sync errors —
    they are never silently hidden.  A candidate that fails an automatic
    step and still has manual work is passed through so the dialog can
    receive it; a candidate that fails an automatic step with no remaining
    manual work becomes a plain sync error.
    """
    manual_candidates: list[dict] = []
    automatic_errors: list[dict] = []
    for candidate in candidates or []:
        try:
            local_id = int(candidate.get('local_id') or 0)
        except (TypeError, ValueError):
            local_id = 0
        cloud_id = str(candidate.get('cloud_id') or '').strip()
        if not local_id:
            # Malformed candidate — do not silently drop; treat as error.
            automatic_errors.append({
                'local_id': 0, 'cloud_id': cloud_id,
                'phase': 'read', 'error': 'candidate missing local_id',
            })
            continue
        try:
            detail = get_conflict_detail(client, local_id, cloud_id or None)
        except Exception as exc:
            automatic_errors.append({
                'local_id': local_id, 'cloud_id': cloud_id,
                'phase': 'read', 'error': str(exc),
            })
            continue
        auto_ops = detail.get('automatic_decisions') or {}
        has_automatic = bool(auto_ops.get('fields') or auto_ops.get('media'))
        has_manual = bool(detail.get('has_manual_conflicts'))
        if has_automatic:
            plan = _build_plan_from_automatic_decisions(detail)
            try:
                resolve_conflict_plan(
                    client, local_id,
                    cloud_id=cloud_id or None,
                    plan=plan,
                    prepare_images_cb=prepare_images_cb,
                )
            except Exception as exc:
                automatic_errors.append({
                    'local_id': local_id, 'cloud_id': cloud_id,
                    'phase': 'execute', 'error': str(exc),
                })
                if has_manual:
                    manual_candidates.append({**candidate, 'detail': detail})
                continue
        # Reread and reclassify.
        try:
            final_detail = get_conflict_detail(client, local_id, cloud_id or None)
        except Exception as exc:
            automatic_errors.append({
                'local_id': local_id, 'cloud_id': cloud_id,
                'phase': 'verify', 'error': str(exc),
            })
            continue
        if final_detail.get('has_manual_conflicts'):
            manual_candidates.append({**candidate, 'detail': final_detail})
        elif has_automatic:
            _clear_observation_conflict_review_pending(local_id)
    return manual_candidates, automatic_errors


def _local_observation_id_by_cloud_id(cloud_id: str) -> int:
    """Resolve local observation id from cloud id via SQL, best-effort."""
    text = str(cloud_id or '').strip()
    if not text:
        return 0
    try:
        conn = get_connection()
        cursor = conn.cursor()
        cursor.execute(
            "SELECT id FROM observations WHERE cloud_id = ? LIMIT 1",
            (text,),
        )
        row = cursor.fetchone()
        if row:
            return int(row[0])
    except Exception:
        return 0
    return 0


def _store_remote_snapshot(
    client: "SporelyCloudClient",
    cloud_id: str,
    remote: dict | None = None,
    remote_images: list[dict] | None = None,
    remote_measurements: list[dict] | None = None,
    *,
    include_images: bool = True,
    include_measurements: bool = True,
    accepted_asymmetry: dict | None = None,
) -> None:
    cloud_value = str(cloud_id or '').strip()
    if not cloud_value:
        return
    remote_obs = remote or client.get_observation(cloud_value)
    if not remote_obs:
        return
    profiler = _cloud_sync_current_profiler()
    if profiler is not None:
        try:
            profiler.record_store_remote_snapshot_fetch(images=include_images and remote_images is None)
            profiler.record_store_remote_snapshot_fetch(
                measurements=include_measurements and remote_measurements is None
            )
        except Exception:
            pass
    if include_images:
        images = (
            [dict(row or {}) for row in (remote_images or [])]
            if remote_images is not None
            else [dict(row or {}) for row in (client.pull_image_metadata(cloud_value) or [])]
        )
    else:
        images = []
    if include_measurements:
        if remote_measurements is not None:
            measurements = [dict(row or {}) for row in remote_measurements]
        else:
            measurements = list(_pull_remote_measurements_for_images(
                client,
                [str(row.get('id') or '').strip() for row in images if str(row.get('id') or '').strip()],
            ))
    else:
        measurements = []
    # ── B3 + final Fix 2: reconcile accepted-asymmetry on every schema-2
    # snapshot write.  Ordinary sync callers do NOT supply
    # ``accepted_asymmetry`` — they invoke this helper to persist a fresh
    # baseline.  We must never create new acceptance in that path, but we
    # MUST prune existing entries whose stable identity is no longer one-sided
    # or no longer exists.  Only the plan resolver passes a non-None
    # ``accepted_asymmetry`` (containing new / replacement entries) — those
    # additions come from ``_reconcile_accepted_asymmetry`` upstream and are
    # respected verbatim here.
    previous = _parse_cloud_observation_snapshot(
        _load_cloud_observation_snapshot(cloud_value)
    )
    prev_asym = previous.get('accepted_asymmetry')
    additions_from_caller = accepted_asymmetry if isinstance(accepted_asymmetry, dict) else None
    if additions_from_caller is not None or isinstance(prev_asym, dict):
        # Best-effort resolve local observation id from cloud id so we can
        # apply local-side pruning rules (row deleted / relinked).  If we
        # cannot resolve it, we degrade gracefully to remote-only pruning.
        local_observation_id = _local_observation_id_by_cloud_id(cloud_value)
        current_local_images: list[dict] = []
        current_local_measurements: list[dict] = []
        if local_observation_id:
            try:
                current_local_images = ImageDB.get_images_for_observation(int(local_observation_id))
            except Exception:
                current_local_images = []
            try:
                current_local_measurements = MeasurementDB.get_measurements_for_observation(
                    int(local_observation_id)
                )
            except Exception:
                current_local_measurements = []
        # Determine matched IDs (counterpart appearance) from remote state.
        matched_local_image_ids = {
            _safe_int(row.get('desktop_id'))
            for row in images if _safe_int(row.get('desktop_id'))
        } | {
            _safe_int(row.get('id')) for row in current_local_images
            if str(row.get('cloud_id') or '').strip()
        }
        matched_cloud_image_ids = {
            str(row.get('cloud_id') or '').strip()
            for row in current_local_images
            if str(row.get('cloud_id') or '').strip()
        }
        matched_local_measurement_ids = {
            _safe_int(row.get('desktop_id'))
            for row in measurements if _safe_int(row.get('desktop_id'))
        } | {
            _safe_int(row.get('id')) for row in current_local_measurements
            if str(row.get('cloud_id') or '').strip()
        }
        matched_cloud_measurement_ids = {
            str(row.get('cloud_id') or '').strip()
            for row in current_local_measurements
            if str(row.get('cloud_id') or '').strip()
        }
        # Ordinary sync path: additions_from_caller is None → we only prune.
        # Plan-resolver path: additions_from_caller carries new entries → they
        # are added on top of the pruned survivors.
        new_entries_source = additions_from_caller if additions_from_caller is not None else {
            'local_only_images': [],
            'cloud_only_images': [],
            'local_only_measurements': [],
            'cloud_only_measurements': [],
        }
        reconciled = _reconcile_accepted_asymmetry(
            prev_asym, new_entries_source,
            plan_items=[],  # ordinary sync has no plan; overrides come from additions_from_caller only
            current_local_images=current_local_images,
            current_remote_images=images,
            current_local_measurements=current_local_measurements,
            current_remote_measurements=measurements,
            matched_local_image_ids=matched_local_image_ids,
            matched_cloud_image_ids=matched_cloud_image_ids,
            matched_local_measurement_ids=matched_local_measurement_ids,
            matched_cloud_measurement_ids=matched_cloud_measurement_ids,
        )
        # If reconciliation produced nothing meaningful, drop the section
        # entirely (empty dict) so the snapshot stays lean.
        if any(reconciled.get(key) for key in (
            'local_only_images', 'cloud_only_images',
            'local_only_measurements', 'cloud_only_measurements',
        )):
            accepted_asymmetry = reconciled
        else:
            accepted_asymmetry = None
    _store_cloud_observation_snapshot(
        cloud_value,
        _cloud_observation_snapshot(
            remote_obs,
            images if include_images else None,
            measurements if include_measurements else None,
            include_images=include_images,
            include_measurements=include_measurements,
            accepted_asymmetry=accepted_asymmetry,
        ),
    )


def resolve_conflict_keep_local(
    client: "SporelyCloudClient",
    local_id: int,
    prepare_images_cb: PreparedImagesCallback | None = None,
    progress_cb: ProgressCallback | None = None,
) -> dict:
    local_obs = ObservationDB.get_observation(int(local_id))
    if not local_obs:
        raise CloudSyncError(f'Local observation {local_id} not found')

    remote_obs = None
    cloud_value = str(local_obs.get('cloud_id') or '').strip()
    if cloud_value:
        try:
            remote_obs = client.get_observation(cloud_value)
        except Exception:
            remote_obs = None

    merged_obs = _merge_cloud_selected_ai_fields(local_obs, remote_obs)
    try:
        cloud_id = client.push_observation(
            merged_obs,
            remote_obs=remote_obs,
        )
    except Exception as exc:
        if not is_privacy_slot_limit_error(exc):
            raise
        blocked_reason = _set_observation_privacy_blocked(int(local_id), str(exc))
        return {
            'local_id': int(local_id),
            'cloud_id': None,
            'blocked': True,
            'blocked_reason': blocked_reason,
            'raw_error': str(exc),
        }
    _adopt_merge_filled_ai_fields_locally(local_id, local_obs, merged_obs)
    conn = get_connection()
    try:
        cursor = conn.cursor()
        update_observation_sync_state(
            cursor,
            int(local_id),
            cloud_id=cloud_id,
            sync_status='synced',
            synced_at=datetime.now(timezone.utc).isoformat(),
            clear_sync_error_state=True,
        )
        conn.commit()
    finally:
        conn.close()

    should_push_images = prepare_images_cb is not None
    stored_local_media_signature = _load_local_cloud_media_signature(int(local_id))
    current_local_media_signature = _local_cloud_media_signature(int(local_id))
    local_media_changed = bool(
        stored_local_media_signature
        and current_local_media_signature
        and not _local_media_signatures_match(
            stored_local_media_signature,
            current_local_media_signature,
        )
    )
    if not local_media_changed:
        _store_local_media_signature_if_equivalent(
            int(local_id),
            stored_local_media_signature,
            current_local_media_signature,
        )

    remote_images_raw = _pull_remote_images_for_sync(client, cloud_id) if cloud_id else []
    if remote_images_raw:
        _record_remote_image_tombstones(
            remote_images_raw,
            local_observation_id=int(local_id),
            cloud_observation_id=cloud_id,
        )
        tombstoned_remote_image_keys = _deleted_remote_image_identity_keys(remote_images_raw)

    if should_push_images and cloud_id:
        stored_snapshot = _load_cloud_observation_snapshot(cloud_id)
        if stored_snapshot:
            baseline_images = [dict(row or {}) for row in (_parse_cloud_observation_snapshot(stored_snapshot).get('images') or [])]
            remote_images = [
                dict(row or {})
                for row in remote_images_raw
                if should_pull_cloud_image_to_desktop(row)
                and not str(row.get('deleted_at') or '').strip()
            ]
            remote_image_payloads = [_remote_image_payload(img) for img in remote_images]
            remote_image_changes = _analyze_image_changes(
                remote_image_payloads,
                baseline_images,
                ignored_keys=tombstoned_remote_image_keys,
            )
            should_push_images = bool(
                local_media_changed
                or remote_image_changes.get('added_keys')
                or remote_image_changes.get('removed_keys')
                or remote_image_changes.get('metadata_changed_keys')
            )

    if should_push_images:
        images_ok = _push_images_for_observation(
            client,
            local_obs,
            cloud_id,
            prepare_images_cb=prepare_images_cb,
            progress_cb=progress_cb,
            progress_state={'done': 0, 'total': 0},
            observation_index=1,
            observation_total=1,
        )
        if not images_ok:
            mark_observation_dirty(int(local_id))
            raise CloudSyncError(f'Could not fully upload images for observation {local_id}')

    _push_measurements_for_observation(client, int(local_id))
    try:
        _push_spore_mosaic_for_observation(client, int(local_id), cloud_id)
    except Exception as exc:
        if is_cloud_auth_error(exc) or is_cloud_temporary_unavailable_error(exc):
            raise
        print(
            f'[cloud_sync] Mosaic push errored while keeping local observation '
            f'{int(local_id)}: {exc}',
            flush=True,
        )

    _store_remote_snapshot(client, cloud_id)
    _refresh_local_cloud_media_signature(int(local_id))
    return {'local_id': int(local_id), 'cloud_id': cloud_id}


def resolve_conflict_keep_cloud(
    client: "SporelyCloudClient",
    local_id: int,
    cloud_id: str | None = None,
    allow_delete: bool = False,
) -> dict:
    local_obs = ObservationDB.get_observation(int(local_id))
    if not local_obs:
        raise CloudSyncError(f'Local observation {local_id} not found')
    resolved_cloud_id = str(cloud_id or local_obs.get('cloud_id') or '').strip()
    if not resolved_cloud_id:
        raise CloudSyncError(f'Observation {local_id} is not linked to Sporely Cloud')

    remote_obs = client.get_observation(resolved_cloud_id)
    if not remote_obs:
        raise CloudSyncError(f'Cloud observation {resolved_cloud_id} not found')
    remote_images_raw = _pull_remote_images_for_sync(client, resolved_cloud_id)
    _record_remote_image_tombstones(
        remote_images_raw,
        local_observation_id=int(local_id),
        cloud_observation_id=resolved_cloud_id,
    )
    remote_images = [
        dict(row or {})
        for row in remote_images_raw
        if should_pull_cloud_image_to_desktop(row)
        and not str(row.get('deleted_at') or '').strip()
    ]

    _apply_remote_observation_fields(int(local_id), remote_obs)
    warnings = _apply_remote_images_to_local(client, int(local_id), remote_images, allow_delete=allow_delete)
    remote_measurements = _pull_remote_measurements_for_images(
        client,
        [str(row.get('id') or '').strip() for row in remote_images if str(row.get('id') or '').strip()],
    )
    measurement_result = _import_remote_measurements_for_observation(
        client,
        int(local_id),
        resolved_cloud_id,
        remote_images=remote_images,
        remote_measurements=remote_measurements,
        materialize_remote_images=True,
        overwrite_conflicts=True,
    )
    warnings.extend(str(item) for item in (measurement_result.get('warnings') or []))
    if measurement_result.get('failed'):
        raise CloudSyncError(
            f'Could not apply all Sporely Cloud measurements for observation {local_id}'
        )
    _stamp_observation_synced(int(local_id), resolved_cloud_id)
    _refresh_local_cloud_media_signature(int(local_id))
    _store_remote_snapshot(
        client,
        resolved_cloud_id,
        remote_obs,
        remote_images,
        remote_measurements=remote_measurements,
    )
    return {'local_id': int(local_id), 'cloud_id': resolved_cloud_id, 'warnings': warnings}


def resolve_conflict_merge(
    client: "SporelyCloudClient",
    local_id: int,
    cloud_id: str | None = None,
    prepare_images_cb: PreparedImagesCallback | None = None,
    progress_cb: ProgressCallback | None = None,
) -> dict:
    # For merge, keep local observation but add any new images from cloud
    local_obs = ObservationDB.get_observation(int(local_id))
    if not local_obs:
        raise CloudSyncError(f'Local observation {local_id} not found')
    resolved_cloud_id = str(cloud_id or local_obs.get('cloud_id') or '').strip()
    if not resolved_cloud_id:
        raise CloudSyncError(f'Observation {local_id} is not linked to Sporely Cloud')

    # First, pull any new images from cloud and add to local
    remote_obs = client.get_observation(resolved_cloud_id)
    if remote_obs:
        remote_images_raw = _pull_remote_images_for_sync(client, resolved_cloud_id)
        _record_remote_image_tombstones(
            remote_images_raw,
            local_observation_id=int(local_id),
            cloud_observation_id=resolved_cloud_id,
        )
        remote_images = [
            dict(row or {})
            for row in remote_images_raw
            if should_pull_cloud_image_to_desktop(row)
            and not str(row.get('deleted_at') or '').strip()
        ]
        warnings = _apply_remote_images_to_local(client, int(local_id), remote_images, allow_delete=False)
    else:
        warnings = []

    # Then push the local observation (which now includes merged images)
    merged_obs = _merge_cloud_selected_ai_fields(local_obs, remote_obs)
    try:
        cloud_id = client.push_observation(
            merged_obs,
            remote_obs=remote_obs,
        )
    except Exception as exc:
        if not is_privacy_slot_limit_error(exc):
            raise
        blocked_reason = _set_observation_privacy_blocked(int(local_id), str(exc))
        return {
            'local_id': int(local_id),
            'cloud_id': None,
            'blocked': True,
            'blocked_reason': blocked_reason,
            'raw_error': str(exc),
            'warnings': warnings,
        }
    _adopt_merge_filled_ai_fields_locally(local_id, local_obs, merged_obs)
    conn = get_connection()
    try:
        cursor = conn.cursor()
        update_observation_sync_state(
            cursor,
            int(local_id),
            cloud_id=cloud_id,
            sync_status='synced',
            synced_at=datetime.now(timezone.utc).isoformat(),
            clear_sync_error_state=True,
        )
        conn.commit()
    finally:
        conn.close()

    # Push images if needed
    should_push_images = prepare_images_cb is not None
    if should_push_images:
        images_ok = _push_images_for_observation(
            client,
            local_obs,
            cloud_id,
            prepare_images_cb=prepare_images_cb,
            progress_cb=progress_cb,
            progress_state={'done': 0, 'total': 0},
            observation_index=1,
            observation_total=1,
        )
        if not images_ok:
            mark_observation_dirty(int(local_id))
            raise CloudSyncError(f'Could not fully upload images for observation {local_id}')

    _store_remote_snapshot(client, cloud_id)
    _refresh_local_cloud_media_signature(int(local_id))
    return {'local_id': int(local_id), 'cloud_id': cloud_id, 'warnings': warnings}


def _format_recomputed_spore_statistics(observation_id: int) -> str | None:
    stats = MeasurementDB.get_statistics_for_observation(
        int(observation_id), measurement_category='spores'
    )
    if not stats:
        return None
    text = (
        f"Spores: ({stats['length_min']:.1f}-){stats['length_p5']:.1f}-"
        f"{stats['length_p95']:.1f}(-{stats['length_max']:.1f}) um"
    )
    if stats.get('width_mean', 0) > 0:
        text += (
            f" x ({stats['width_min']:.1f}-){stats['width_p5']:.1f}-"
            f"{stats['width_p95']:.1f}(-{stats['width_max']:.1f}) um"
            f", Q = ({stats['ratio_min']:.1f}-){stats['ratio_p5']:.1f}-"
            f"{stats['ratio_p95']:.1f}(-{stats['ratio_max']:.1f})"
            f", Qm = {stats['ratio_mean']:.1f}"
        )
    return text + f", n = {stats['count']}"


# ── Per-item conflict plan — helpers ──────────────────────────────────────────

def _conflict_plan_local_observation_fingerprint(record: dict | None) -> dict:
    """Normalized local observation fingerprint used for drift detection."""
    return _observation_compare_payload(record or {}, local=True)


def _conflict_plan_remote_observation_fingerprint(record: dict | None) -> dict:
    return _observation_compare_payload(record or {}, local=False)


def _conflict_plan_local_image_fingerprint(row: dict | None) -> dict:
    payload = _local_image_snapshot_payload(row or {})
    payload['__local_id'] = _safe_int((row or {}).get('id'))
    payload['__cloud_id'] = str((row or {}).get('cloud_id') or '').strip() or None
    return payload


def _conflict_plan_remote_image_fingerprint(row: dict | None) -> dict:
    payload = _remote_image_payload(row or {})
    payload['__cloud_id'] = str((row or {}).get('id') or '').strip() or None
    payload['__desktop_id'] = _safe_int((row or {}).get('desktop_id'))
    return payload


def _conflict_plan_local_measurement_fingerprint(row: dict | None) -> dict:
    payload = _local_measurement_snapshot_payload(row or {})
    payload['__local_id'] = _safe_int((row or {}).get('id'))
    payload['__cloud_id'] = str((row or {}).get('cloud_id') or '').strip() or None
    return payload


def _conflict_plan_remote_measurement_fingerprint(row: dict | None) -> dict:
    payload = _remote_measurement_snapshot_payload(row or {})
    payload['__cloud_id'] = str((row or {}).get('id') or '').strip() or None
    payload['__desktop_id'] = _safe_int((row or {}).get('desktop_id'))
    return payload


def build_conflict_plan_baseline(
    *,
    local_obs: dict | None,
    remote_obs: dict | None,
    local_images: list[dict],
    remote_images: list[dict],
    local_measurements: list[dict],
    remote_measurements: list[dict],
) -> dict:
    """Deterministic baseline fingerprint returned inside get_conflict_detail.

    The dialog echoes this back inside the plan under ``baseline`` so that
    ``resolve_conflict_plan`` can prove the reviewed state still matches the
    live state before any write occurs.
    """
    return {
        'schema_version': _CONFLICT_PLAN_BASELINE_SCHEMA_VERSION,
        'local_observation': _conflict_plan_local_observation_fingerprint(local_obs),
        'remote_observation': _conflict_plan_remote_observation_fingerprint(remote_obs),
        'local_images': [
            _conflict_plan_local_image_fingerprint(row) for row in (local_images or [])
        ],
        'remote_images': [
            _conflict_plan_remote_image_fingerprint(row) for row in (remote_images or [])
        ],
        'local_measurements': [
            _conflict_plan_local_measurement_fingerprint(row)
            for row in (local_measurements or [])
        ],
        'remote_measurements': [
            _conflict_plan_remote_measurement_fingerprint(row)
            for row in (remote_measurements or [])
        ],
    }


def _plan_drift_message() -> str:
    return (
        'The observation changed after this comparison was loaded. '
        'Refresh the comparison before applying.'
    )


def _find_local_image_fingerprint(baseline_images: list[dict], *, local_id: int | None,
                                  cloud_id: str | None) -> dict | None:
    if local_id:
        for row in baseline_images:
            if _safe_int(row.get('__local_id')) == int(local_id):
                return row
    if cloud_id:
        for row in baseline_images:
            if str(row.get('__cloud_id') or '') == str(cloud_id):
                return row
    return None


def _find_remote_image_fingerprint(baseline_images: list[dict], *, cloud_id: str | None,
                                   local_id: int | None) -> dict | None:
    if cloud_id:
        for row in baseline_images:
            if str(row.get('__cloud_id') or '') == str(cloud_id):
                return row
    if local_id:
        for row in baseline_images:
            if _safe_int(row.get('__desktop_id')) == int(local_id):
                return row
    return None


def _find_local_measurement_fingerprint(rows: list[dict], *, local_id: int | None,
                                        cloud_id: str | None) -> dict | None:
    if local_id:
        for row in rows:
            if _safe_int(row.get('__local_id')) == int(local_id):
                return row
    if cloud_id:
        for row in rows:
            if str(row.get('__cloud_id') or '') == str(cloud_id):
                return row
    return None


def _find_remote_measurement_fingerprint(rows: list[dict], *, cloud_id: str | None,
                                         local_id: int | None) -> dict | None:
    if cloud_id:
        for row in rows:
            if str(row.get('__cloud_id') or '') == str(cloud_id):
                return row
    if local_id:
        for row in rows:
            if _safe_int(row.get('__desktop_id')) == int(local_id):
                return row
    return None


_CONFLICT_PLAN_BASELINE_SCHEMA_VERSION = 1
_CONFLICT_PLAN_BASELINE_REQUIRED_KEYS = (
    'local_observation',
    'remote_observation',
    'local_images',
    'remote_images',
    'local_measurements',
    'remote_measurements',
)


def _validate_plan_baseline_shape(baseline: dict | None) -> None:
    """Fail closed when the per-item plan lacks a well-formed baseline.

    Turn-A A1: the item-level plan is not backward-compatible with callers
    that omit a baseline.  The old whole-observation resolvers
    (``resolve_conflict_keep_local`` / ``keep_cloud`` / ``merge``) are
    separate APIs that never took a baseline; those remain compatible.
    """
    if not isinstance(baseline, dict) or not baseline:
        raise CloudSyncError(
            'Conflict plan is missing the reviewed baseline. '
            'Refresh the comparison and try again.'
        )
    schema = baseline.get('schema_version')
    if schema != _CONFLICT_PLAN_BASELINE_SCHEMA_VERSION:
        raise CloudSyncError(
            f'Unsupported conflict plan baseline schema {schema!r}. '
            'Refresh the comparison and try again.'
        )
    for key in _CONFLICT_PLAN_BASELINE_REQUIRED_KEYS:
        if key not in baseline:
            raise CloudSyncError(
                f'Malformed conflict plan baseline (missing "{key}"). '
                'Refresh the comparison and try again.'
            )
    # Collection keys must be list-shaped.
    for key in _CONFLICT_PLAN_BASELINE_REQUIRED_KEYS[2:]:
        if not isinstance(baseline.get(key), list):
            raise CloudSyncError(
                f'Malformed conflict plan baseline ("{key}" not a list). '
                'Refresh the comparison and try again.'
            )
    if not isinstance(baseline.get('local_observation'), dict):
        raise CloudSyncError(
            'Malformed conflict plan baseline (local_observation not an object). '
            'Refresh the comparison and try again.'
        )
    if not isinstance(baseline.get('remote_observation'), dict):
        raise CloudSyncError(
            'Malformed conflict plan baseline (remote_observation not an object). '
            'Refresh the comparison and try again.'
        )


def _verify_plan_baseline(
    baseline: dict,
    items: list[dict],
    *,
    local_obs: dict | None,
    remote_obs: dict | None,
    local_images: list[dict],
    remote_images: list[dict],
    local_measurements: list[dict],
    remote_measurements: list[dict],
) -> None:
    """Abort before any write if reviewed values or identities changed."""
    has_field_item = any(item.get('kind') == 'field' for item in items)
    if has_field_item:
        current_local = _conflict_plan_local_observation_fingerprint(local_obs)
        if baseline.get('local_observation') != current_local:
            raise CloudSyncError(_plan_drift_message())
        current_remote = _conflict_plan_remote_observation_fingerprint(remote_obs)
        if baseline.get('remote_observation') != current_remote:
            raise CloudSyncError(_plan_drift_message())

    baseline_local_images = list(baseline.get('local_images') or [])
    baseline_remote_images = list(baseline.get('remote_images') or [])
    baseline_local_measurements = list(baseline.get('local_measurements') or [])
    baseline_remote_measurements = list(baseline.get('remote_measurements') or [])

    current_local_image_by_local = {
        _safe_int(row.get('id')): _conflict_plan_local_image_fingerprint(row)
        for row in local_images or []
        if _safe_int(row.get('id'))
    }
    current_local_image_by_cloud = {
        str(row.get('cloud_id') or '').strip(): _conflict_plan_local_image_fingerprint(row)
        for row in local_images or []
        if str(row.get('cloud_id') or '').strip()
    }
    current_remote_image_by_cloud = {
        str(row.get('id') or '').strip(): _conflict_plan_remote_image_fingerprint(row)
        for row in remote_images or []
        if str(row.get('id') or '').strip()
    }
    current_remote_image_by_desktop = {
        _safe_int(row.get('desktop_id')): _conflict_plan_remote_image_fingerprint(row)
        for row in remote_images or []
        if _safe_int(row.get('desktop_id'))
    }
    current_local_measurement_by_local = {
        _safe_int(row.get('id')): _conflict_plan_local_measurement_fingerprint(row)
        for row in local_measurements or []
        if _safe_int(row.get('id'))
    }
    current_local_measurement_by_cloud = {
        str(row.get('cloud_id') or '').strip(): _conflict_plan_local_measurement_fingerprint(row)
        for row in local_measurements or []
        if str(row.get('cloud_id') or '').strip()
    }
    current_remote_measurement_by_cloud = {
        str(row.get('id') or '').strip(): _conflict_plan_remote_measurement_fingerprint(row)
        for row in remote_measurements or []
        if str(row.get('id') or '').strip()
    }
    current_remote_measurement_by_desktop = {
        _safe_int(row.get('desktop_id')): _conflict_plan_remote_measurement_fingerprint(row)
        for row in remote_measurements or []
        if _safe_int(row.get('desktop_id'))
    }

    for item in items:
        kind = item.get('kind')
        local_id = _safe_int(item.get('local_id')) or None
        cloud_id = str(item.get('cloud_id') or '').strip() or None
        if kind in {'image', 'image_metadata'}:
            expected_local = _find_local_image_fingerprint(
                baseline_local_images, local_id=local_id, cloud_id=cloud_id,
            )
            if expected_local is not None:
                current = (
                    current_local_image_by_local.get(local_id) if local_id
                    else current_local_image_by_cloud.get(cloud_id or '')
                )
                if current != expected_local:
                    raise CloudSyncError(_plan_drift_message())
            expected_remote = _find_remote_image_fingerprint(
                baseline_remote_images, cloud_id=cloud_id, local_id=local_id,
            )
            if expected_remote is not None:
                current = (
                    current_remote_image_by_cloud.get(cloud_id or '') if cloud_id
                    else current_remote_image_by_desktop.get(local_id)
                )
                if current != expected_remote:
                    raise CloudSyncError(_plan_drift_message())
        elif kind == 'measurement':
            expected_local = _find_local_measurement_fingerprint(
                baseline_local_measurements, local_id=local_id, cloud_id=cloud_id,
            )
            if expected_local is not None:
                current = (
                    current_local_measurement_by_local.get(local_id) if local_id
                    else current_local_measurement_by_cloud.get(cloud_id or '')
                )
                if current != expected_local:
                    raise CloudSyncError(_plan_drift_message())
            expected_remote = _find_remote_measurement_fingerprint(
                baseline_remote_measurements, cloud_id=cloud_id, local_id=local_id,
            )
            if expected_remote is not None:
                current = (
                    current_remote_measurement_by_cloud.get(cloud_id or '') if cloud_id
                    else current_remote_measurement_by_desktop.get(local_id)
                )
                if current != expected_remote:
                    raise CloudSyncError(_plan_drift_message())


def _validate_plan_identity_state(
    *,
    local_images: list[dict],
    remote_images: list[dict],
    local_measurements: list[dict],
    remote_measurements: list[dict],
    items: list[dict],
) -> None:
    """Refuse ambiguous or contradictory identity — resolver-side belt-and-braces."""
    # duplicate local cloud_ids
    local_cloud_id_counts: dict[str, int] = {}
    for row in local_images or []:
        cid = str(row.get('cloud_id') or '').strip()
        if cid:
            local_cloud_id_counts[cid] = local_cloud_id_counts.get(cid, 0) + 1
    for cid, count in local_cloud_id_counts.items():
        if count > 1:
            raise CloudSyncError(
                f'Image identity conflict: multiple local images share cloud ID {cid}'
            )
    # duplicate cloud desktop_ids
    remote_desktop_counts: dict[int, int] = {}
    for row in remote_images or []:
        did = _safe_int(row.get('desktop_id'))
        if did:
            remote_desktop_counts[did] = remote_desktop_counts.get(did, 0) + 1
    for did, count in remote_desktop_counts.items():
        if count > 1:
            raise CloudSyncError(
                f'Image identity conflict: multiple cloud images reference local image {did}'
            )
    # contradictory cross-references for every affected image
    local_by_cloud = {
        str(row.get('cloud_id') or '').strip(): row
        for row in local_images or []
        if str(row.get('cloud_id') or '').strip()
    }
    remote_by_cloud = {
        str(row.get('id') or '').strip(): row
        for row in remote_images or []
        if str(row.get('id') or '').strip()
    }
    remote_by_desktop = {
        _safe_int(row.get('desktop_id')): row
        for row in remote_images or []
        if _safe_int(row.get('desktop_id'))
    }
    for item in items:
        if item.get('kind') not in {'image', 'image_metadata', 'measurement'}:
            continue
        local_id = _safe_int(item.get('local_id')) or None
        cloud_id = str(item.get('cloud_id') or '').strip() or None
        if item.get('kind') in {'image', 'image_metadata'}:
            if cloud_id and cloud_id in remote_by_cloud and local_id:
                remote_row = remote_by_cloud[cloud_id]
                remote_desktop = _safe_int(remote_row.get('desktop_id'))
                if remote_desktop and remote_desktop != local_id:
                    raise CloudSyncError(
                        f'Image identity conflict: cloud image {cloud_id} references '
                        f'local image {remote_desktop}, not {local_id}'
                    )
            if local_id and local_id in remote_by_desktop and cloud_id:
                candidate_cloud = str(remote_by_desktop[local_id].get('id') or '').strip()
                if candidate_cloud and candidate_cloud != cloud_id:
                    raise CloudSyncError(
                        f'Image identity conflict: local image {local_id} is referenced '
                        f'by cloud image {candidate_cloud}, not {cloud_id}'
                    )
    # ── Measurement identity guards (A2) ──────────────────────────────────
    # 1. duplicate local measurement cloud_ids
    local_meas_cloud_counts: dict[str, int] = {}
    for row in local_measurements or []:
        cid = str(row.get('cloud_id') or '').strip()
        if cid:
            local_meas_cloud_counts[cid] = local_meas_cloud_counts.get(cid, 0) + 1
    for cid, count in local_meas_cloud_counts.items():
        if count > 1:
            raise CloudSyncError(
                f'Measurement identity conflict: multiple local measurements share cloud ID {cid}. '
                'Refresh the comparison and repair the link before applying.'
            )
    # 2. duplicate cloud measurement desktop_ids
    remote_meas_desktop_counts: dict[int, int] = {}
    for row in remote_measurements or []:
        did = _safe_int(row.get('desktop_id'))
        if did:
            remote_meas_desktop_counts[did] = remote_meas_desktop_counts.get(did, 0) + 1
    for did, count in remote_meas_desktop_counts.items():
        if count > 1:
            raise CloudSyncError(
                f'Measurement identity conflict: multiple cloud measurements reference local '
                f'measurement {did}. Refresh the comparison and repair the link before applying.'
            )
    # 3. cross-referenced measurement contradiction
    local_meas_by_cloud = {
        str(row.get('cloud_id') or '').strip(): row
        for row in local_measurements or []
        if str(row.get('cloud_id') or '').strip()
    }
    remote_meas_by_cloud = {
        str(row.get('id') or '').strip(): row
        for row in remote_measurements or []
        if str(row.get('id') or '').strip()
    }
    remote_meas_by_desktop = {
        _safe_int(row.get('desktop_id')): row
        for row in remote_measurements or []
        if _safe_int(row.get('desktop_id'))
    }
    local_meas_by_local = {
        _safe_int(row.get('id')): row
        for row in local_measurements or []
        if _safe_int(row.get('id'))
    }
    for item in items:
        if item.get('kind') != 'measurement':
            continue
        local_id = _safe_int(item.get('local_id')) or None
        cloud_id = str(item.get('cloud_id') or '').strip() or None
        side = item.get('side')
        # 4. missing local target
        if side in {'matched', 'local_only'} and local_id and local_id not in local_meas_by_local:
            raise CloudSyncError(
                f'Measurement identity conflict: local measurement {local_id} no longer exists. '
                'Refresh the comparison before applying.'
            )
        # 5. missing cloud target
        if side in {'matched', 'cloud_only'} and cloud_id and cloud_id not in remote_meas_by_cloud:
            raise CloudSyncError(
                f'Measurement identity conflict: cloud measurement {cloud_id} no longer exists. '
                'Refresh the comparison before applying.'
            )
        # 6. cross-referenced contradiction for matched measurements
        if side == 'matched' and local_id and cloud_id:
            remote = remote_meas_by_cloud.get(cloud_id)
            if remote is not None:
                remote_desktop = _safe_int(remote.get('desktop_id'))
                if remote_desktop and remote_desktop != local_id:
                    raise CloudSyncError(
                        f'Measurement identity conflict: cloud measurement {cloud_id} '
                        f'references local measurement {remote_desktop}, not {local_id}. '
                        'Refresh the comparison before applying.'
                    )
            reverse = remote_meas_by_desktop.get(local_id)
            if reverse is not None:
                reverse_cloud = str(reverse.get('id') or '').strip()
                if reverse_cloud and reverse_cloud != cloud_id:
                    raise CloudSyncError(
                        f'Measurement identity conflict: local measurement {local_id} is '
                        f'referenced by cloud measurement {reverse_cloud}, not {cloud_id}. '
                        'Refresh the comparison before applying.'
                    )
        # 7. measurement moved to a different image after review
        if side == 'matched' and local_id:
            local_row = local_meas_by_local.get(local_id)
            reviewed_local_image = _safe_int(item.get('local_image_id')) or None
            if local_row is not None and reviewed_local_image:
                current_image = _safe_int(local_row.get('image_id'))
                if current_image and current_image != reviewed_local_image:
                    raise CloudSyncError(
                        f'Measurement identity conflict: local measurement {local_id} '
                        f'now belongs to image {current_image}, not {reviewed_local_image}. '
                        'Refresh the comparison before applying.'
                    )
        if side == 'matched' and cloud_id:
            remote_row = remote_meas_by_cloud.get(cloud_id)
            reviewed_cloud_image = str(item.get('cloud_image_id') or '').strip() or None
            if remote_row is not None and reviewed_cloud_image:
                current_image = str(remote_row.get('image_id') or '').strip()
                if current_image and current_image != reviewed_cloud_image:
                    raise CloudSyncError(
                        f'Measurement identity conflict: cloud measurement {cloud_id} '
                        f'now belongs to image {current_image}, not {reviewed_cloud_image}. '
                        'Refresh the comparison before applying.'
                    )
        # 8. owning image not among the authoritative paired images
        image_local = _safe_int(item.get('local_image_id')) or None
        image_cloud = str(item.get('cloud_image_id') or '').strip() or None
        if image_local:
            if image_local not in {_safe_int(row.get('id'))
                                   for row in local_images or [] if _safe_int(row.get('id'))}:
                raise CloudSyncError(
                    f'Measurement identity conflict: local image {image_local} no longer exists. '
                    'Refresh the comparison before applying.'
                )
        if image_cloud:
            if image_cloud not in {str(row.get('id') or '').strip()
                                    for row in remote_images or [] if str(row.get('id') or '').strip()}:
                raise CloudSyncError(
                    f'Measurement identity conflict: cloud image {image_cloud} no longer exists. '
                    'Refresh the comparison before applying.'
                )
        # 9. matched measurement whose reviewed owning-image pair is not itself authoritative
        if side == 'matched' and image_local and image_cloud:
            authoritative_pairs = {
                (_safe_int(lrow.get('id')), str(rrow.get('id') or '').strip())
                for lrow in local_images or []
                for rrow in remote_images or []
                if _safe_int(lrow.get('id'))
                and str(rrow.get('id') or '').strip()
                and str(lrow.get('cloud_id') or '').strip() == str(rrow.get('id') or '').strip()
            }
            if (image_local, image_cloud) not in authoritative_pairs:
                raise CloudSyncError(
                    f'Measurement identity conflict: reviewed owning images '
                    f'(local {image_local}, cloud {image_cloud}) are not the authoritative '
                    'paired images. Refresh the comparison and repair the link before applying.'
                )
        # 10. ambiguous plan identity
        if side == 'matched' and not (local_id and cloud_id):
            raise CloudSyncError(
                'Measurement identity conflict: matched-measurement plan item is missing '
                'one of local_id or cloud_id. Refresh the comparison before applying.'
            )


def _capture_local_presentation(rows: list[dict]) -> dict[int, dict]:
    """Snapshot ``gallery_rotation`` and ``sort_order`` per local image id."""
    capture: dict[int, dict] = {}
    for row in rows or []:
        rid = _safe_int(row.get('id'))
        if rid <= 0:
            continue
        capture[rid] = {
            'gallery_rotation': row.get('gallery_rotation'),
            'sort_order': row.get('sort_order'),
        }
    return capture


def _restore_local_presentation(
    captured: dict[int, dict],
    *,
    matched_local_ids: set[int],
) -> list[dict]:
    """Restore captured rotation/sort_order for matched images and verify.

    A3: presentation is no longer silently swallowed.  Each attempted write
    is followed by a read-back that verifies the row now has the intended
    ``gallery_rotation`` and ``sort_order``.  Per-row status is returned so
    the resolver can surface it in the operation log.
    """
    statuses: list[dict] = []
    for local_id in matched_local_ids:
        snapshot = captured.get(int(local_id))
        if not snapshot:
            continue
        expected_rotation = snapshot.get('gallery_rotation')
        expected_order = snapshot.get('sort_order')
        error_message: str | None = None
        try:
            ImageDB.update_image(
                int(local_id),
                gallery_rotation=expected_rotation,
                sort_order=expected_order,
            )
        except Exception as exc:
            error_message = f'update_image failed: {exc}'
        try:
            current_rows = ImageDB.get_images_for_observation(int(local_id))
        except Exception as exc:
            current_rows = []
            error_message = error_message or f'read-back failed: {exc}'
        current = next(
            (row for row in current_rows if _safe_int(row.get('id')) == int(local_id)),
            None,
        )
        status = 'failed'
        if error_message is None and current is not None:
            actual_rotation = current.get('gallery_rotation')
            actual_order = current.get('sort_order')
            already = (
                actual_rotation == expected_rotation and actual_order == expected_order
            )
            status = 'completed' if already else 'failed'
            if status == 'failed':
                error_message = (
                    f'presentation drift after restore: expected rotation={expected_rotation!r} '
                    f'order={expected_order!r}, got rotation={actual_rotation!r} '
                    f'order={actual_order!r}'
                )
        statuses.append({
            'op': 'restore_presentation',
            'local_id': int(local_id),
            'status': status,
            'expected': {'gallery_rotation': expected_rotation, 'sort_order': expected_order},
            'error': error_message,
        })
    return statuses


def _assign_downloaded_image_order(
    *,
    local_id: int,
    downloaded_cloud_ids: set[str],
    captured_before: dict[int, dict],
) -> list[dict]:
    """Give newly-downloaded cloud-only images deterministic non-colliding order.

    Returns per-row status entries so the resolver can surface completed vs
    failed presentation policy in the plan operation log.
    """
    statuses: list[dict] = []
    if not downloaded_cloud_ids:
        return statuses
    try:
        current_rows = ImageDB.get_images_for_observation(int(local_id))
    except Exception as exc:
        return [{
            'op': 'assign_downloaded_order',
            'status': 'failed',
            'cloud_ids': sorted(downloaded_cloud_ids),
            'error': f'read images failed: {exc}',
        }]
    new_rows = [
        row for row in current_rows
        if str(row.get('cloud_id') or '').strip() in downloaded_cloud_ids
        and _safe_int(row.get('id')) not in captured_before
    ]
    if not new_rows:
        return statuses
    existing_orders = [_safe_int(v.get('sort_order')) for v in captured_before.values()]
    base = (max(existing_orders) + 1) if existing_orders else 1
    for offset, row in enumerate(
        sorted(new_rows, key=lambda r: str(r.get('cloud_id') or ''))
    ):
        expected_order = base + offset
        row_local_id = _safe_int(row.get('id'))
        error_message: str | None = None
        try:
            ImageDB.update_image(int(row_local_id), sort_order=expected_order)
        except Exception as exc:
            error_message = f'update_image failed: {exc}'
        try:
            after_rows = ImageDB.get_images_for_observation(int(local_id))
        except Exception as exc:
            after_rows = []
            error_message = error_message or f'read-back failed: {exc}'
        current = next(
            (r for r in after_rows if _safe_int(r.get('id')) == row_local_id),
            None,
        )
        status = 'failed'
        if error_message is None and current is not None:
            status = 'completed' if _safe_int(current.get('sort_order')) == expected_order else 'failed'
            if status == 'failed':
                error_message = (
                    f'assigned order drift: expected {expected_order}, '
                    f'got {current.get("sort_order")!r}'
                )
        statuses.append({
            'op': 'assign_downloaded_order',
            'local_id': row_local_id,
            'cloud_id': str(row.get('cloud_id') or '').strip(),
            'expected_sort_order': expected_order,
            'status': status,
            'error': error_message,
        })
    return statuses


# Material-content fields for the accepted-asymmetry image fingerprint.  Turn-B
# fix 3: presentation-only fields (``gallery_rotation``, ``sort_order``) and
# transport/storage/cache metadata are excluded so that a thumbnail rotation
# or gallery/image-order tweak governed by the automatic desktop presentation
# policy does NOT resurface an accepted one-sided media conflict.  Only fields
# that represent genuine user or scientific media content participate.
_ASYMMETRY_MATERIAL_IMAGE_FIELDS = (
    'image_type',
    'micro_category',
    'notes',
    'objective_name',
    'scale_microns_per_pixel',
    'mount_medium',
    'stain',
    'sample_type',
    'sample_source',
    'contrast',
    'crop_mode',
    'microscope_notes',
)


def _asymmetry_fingerprint_local_image(row: dict | None) -> dict:
    """Material content fingerprint for a local-only accepted image.

    Excludes presentation-only fields (``gallery_rotation``, ``sort_order``)
    and every transport/storage/cache/derivative field (``filepath``,
    ``storage_path``, thumbnail keys, ...).
    """
    row = dict(row or {})
    return {
        field: _normalize_snapshot_value(row.get(field))
        for field in _ASYMMETRY_MATERIAL_IMAGE_FIELDS
    }


def _asymmetry_fingerprint_remote_image(row: dict | None) -> dict:
    row = dict(row or {})
    return {
        field: _normalize_snapshot_value(row.get(field))
        for field in _ASYMMETRY_MATERIAL_IMAGE_FIELDS
    }


def _asymmetry_fingerprint_local_measurement(row: dict | None) -> dict:
    """Content fingerprint for a local-only accepted measurement."""
    row = dict(row or {})
    return {
        'length_um': _normalize_measurement_float_value(row.get('length_um')),
        'width_um': _normalize_measurement_float_value(row.get('width_um')),
        'measurement_type': _normalize_measurement_type_value(row.get('measurement_type')),
        'p1_x': _normalize_measurement_float_value(row.get('p1_x')),
        'p1_y': _normalize_measurement_float_value(row.get('p1_y')),
        'p2_x': _normalize_measurement_float_value(row.get('p2_x')),
        'p2_y': _normalize_measurement_float_value(row.get('p2_y')),
        'image_id': _safe_int(row.get('image_id')) or None,
    }


def _asymmetry_fingerprint_remote_measurement(row: dict | None) -> dict:
    row = dict(row or {})
    return {
        'length_um': _normalize_measurement_float_value(row.get('length_um')),
        'width_um': _normalize_measurement_float_value(row.get('width_um')),
        'measurement_type': _normalize_measurement_type_value(row.get('measurement_type')),
        'p1_x': _normalize_measurement_float_value(row.get('p1_x')),
        'p1_y': _normalize_measurement_float_value(row.get('p1_y')),
        'p2_x': _normalize_measurement_float_value(row.get('p2_x')),
        'p2_y': _normalize_measurement_float_value(row.get('p2_y')),
        'image_id': str(row.get('image_id') or '').strip() or None,
    }


def _accepted_asymmetry_key(entry: dict) -> tuple:
    return (
        str(entry.get('side') or ''),
        str(entry.get('kind') or ''),
        _safe_int(entry.get('local_id')) or 0,
        str(entry.get('cloud_id') or '').strip(),
    )


def _build_plan_operations(items: list[dict]) -> list[dict]:
    """Turn the item plan into a spy-friendly, unambiguous operation list.

    Every op is dispatched later by ``resolve_conflict_plan`` from this list;
    no set-comprehension is used to derive execution behavior after this point.
    """
    ops: list[dict] = []
    for item in items:
        kind = item.get('kind')
        choice = item.get('choice')
        local_id = _safe_int(item.get('local_id')) or None
        cloud_id = str(item.get('cloud_id') or '').strip() or None
        side = item.get('side')
        if kind == 'field':
            if choice == 'cloud':
                ops.append({'op': 'pull_field', 'field': item.get('field')})
            elif choice == 'local':
                ops.append({'op': 'push_field', 'field': item.get('field')})
        elif kind == 'image':
            if choice == 'upload':
                ops.append({'op': 'push_image', 'local_id': local_id})
            elif choice == 'download':
                ops.append({'op': 'import_image', 'cloud_id': cloud_id})
            elif choice in {'keep_local', 'keep_cloud'}:
                ops.append({
                    'op': 'keep_asymmetric_image',
                    'side': 'local' if choice == 'keep_local' else 'cloud',
                    'local_id': local_id,
                    'cloud_id': cloud_id,
                })
        elif kind == 'image_metadata':
            if choice == 'local':
                ops.append({
                    'op': 'push_image_metadata',
                    'local_id': local_id,
                    'cloud_id': cloud_id,
                })
            elif choice == 'cloud':
                ops.append({
                    'op': 'apply_image_metadata',
                    'local_id': local_id,
                    'cloud_id': cloud_id,
                })
        elif kind == 'measurement':
            if side == 'matched':
                if choice == 'local':
                    ops.append({
                        'op': 'push_measurement',
                        'local_id': local_id,
                        'cloud_id': cloud_id,
                    })
                elif choice == 'cloud':
                    ops.append({
                        'op': 'import_measurement',
                        'cloud_id': cloud_id,
                        'local_id': local_id,
                    })
            elif side == 'local_only':
                if choice == 'upload':
                    ops.append({
                        'op': 'push_measurement',
                        'local_id': local_id,
                    })
                elif choice == 'keep_local':
                    ops.append({
                        'op': 'keep_asymmetric_measurement',
                        'side': 'local',
                        'local_id': local_id,
                    })
            elif side == 'cloud_only':
                if choice == 'download':
                    ops.append({
                        'op': 'import_measurement',
                        'cloud_id': cloud_id,
                    })
                elif choice == 'keep_cloud':
                    ops.append({
                        'op': 'keep_asymmetric_measurement',
                        'side': 'cloud',
                        'cloud_id': cloud_id,
                    })
    return ops


def _malformed_retry_state(reason: str) -> CloudSyncError:
    """Fail-closed error used when a retry ``prior_result`` op is unusable."""
    return CloudSyncError(
        f'Malformed retry state ({reason}). Refresh the comparison and try again.'
    )


def _reconcile_verification_pending_op(
    op: dict,
    *,
    local_images: list[dict],
    remote_images: list[dict],
    local_measurements: list[dict],
    remote_measurements: list[dict],
) -> tuple:
    """Recover from a write-succeeded / read-back-failed op on retry.

    Returns one of:

    * ``('completed', {'local_image_ids': ..., 'cloud_image_ids': ..., ...})``
      when the intended row is present in current state and material matches;
    * ``('drift', <reason>)`` when a candidate row is present but its material
      diverges (unrelated edit) — retry aborts;
    * ``('missing', None)`` when no candidate row exists — treat the write as
      not having gone through, let the plan's normal dispatch rerun it.
    """
    opname = op.get('op')
    stable = op.get('stable_identity') or {}
    intended = op.get('intended_after') or {}
    kind = intended.get('kind')
    explained = {'local_image_ids': set(), 'cloud_image_ids': set(),
                 'local_meas_ids': set(), 'cloud_meas_ids': set()}
    if kind == 'image':
        material_local_intended = (intended.get('material_local') or {}).get('material') or {}
        material_remote_intended = (intended.get('material_remote') or {}).get('material') or {}
        lid = _safe_int(stable.get('local_id')) or None
        cid = str(stable.get('cloud_id') or '').strip() or None
        local_row = None
        remote_row = None
        if lid:
            local_row = next((r for r in local_images if _safe_int(r.get('id')) == lid), None)
        if not local_row and cid:
            local_row = next(
                (r for r in local_images
                 if str(r.get('cloud_id') or '').strip() == cid),
                None,
            )
        if cid:
            remote_row = next(
                (r for r in remote_images
                 if str(r.get('id') or '').strip() == cid),
                None,
            )
        if not remote_row and lid:
            remote_row = next(
                (r for r in remote_images if _safe_int(r.get('desktop_id')) == lid),
                None,
            )
        if not local_row and not remote_row:
            return ('missing', None)
        if material_local_intended and local_row is not None:
            current_local_material = _material_image_expected_state(
                local_row, side='local',
            ).get('material')
            if current_local_material != material_local_intended:
                return ('drift',
                        f'{opname} verification recovered a local image whose material differs')
            explained['local_image_ids'].add(_safe_int(local_row.get('id')))
        if material_remote_intended and remote_row is not None:
            current_remote_material = _material_image_expected_state(
                remote_row, side='remote',
            ).get('material')
            if current_remote_material != material_remote_intended:
                return ('drift',
                        f'{opname} verification recovered a cloud image whose material differs')
            explained['cloud_image_ids'].add(str(remote_row.get('id') or '').strip())
        return ('completed', explained)
    if kind == 'measurement':
        material_local_intended = (intended.get('material_local') or {}).get('material') or {}
        material_remote_intended = (intended.get('material_remote') or {}).get('material') or {}
        lid = _safe_int(stable.get('local_id')) or None
        cid = str(stable.get('cloud_id') or '').strip() or None
        local_row = None
        remote_row = None
        if lid:
            local_row = next(
                (r for r in local_measurements if _safe_int(r.get('id')) == lid),
                None,
            )
        if not local_row and cid:
            local_row = next(
                (r for r in local_measurements
                 if str(r.get('cloud_id') or '').strip() == cid),
                None,
            )
        if cid:
            remote_row = next(
                (r for r in remote_measurements
                 if str(r.get('id') or '').strip() == cid),
                None,
            )
        if not remote_row and lid:
            remote_row = next(
                (r for r in remote_measurements if _safe_int(r.get('desktop_id')) == lid),
                None,
            )
        if not local_row and not remote_row:
            return ('missing', None)
        if material_local_intended and local_row is not None:
            current_local_material = _material_measurement_expected_state(
                local_row, side='local',
            ).get('material')
            if current_local_material != material_local_intended:
                return ('drift',
                        f'{opname} verification recovered a local measurement whose material differs')
            explained['local_meas_ids'].add(_safe_int(local_row.get('id')))
        if material_remote_intended and remote_row is not None:
            current_remote_material = _material_measurement_expected_state(
                remote_row, side='remote',
            ).get('material')
            if current_remote_material != material_remote_intended:
                return ('drift',
                        f'{opname} verification recovered a cloud measurement whose material differs')
            explained['cloud_meas_ids'].add(str(remote_row.get('id') or '').strip())
        return ('completed', explained)
    return ('missing', None)


def _validate_prior_op_expected_after(op: dict) -> None:
    """Reject a prior completed/verification-pending op with missing structure.

    Fails closed rather than accepting identity-only proof.  This runs BEFORE
    any explained-set inclusion, so a malformed op cannot make its records
    silently exclude themselves from drift validation.
    """
    opname = str(op.get('op') or '')
    status = str(op.get('status') or '')
    expected = op.get('expected_after')
    intended = op.get('intended_after')
    if status == 'verification_pending':
        # Own set of requirements — validated in the verification_pending
        # branch below; but we still require write_attempted + stable_identity
        # + intended_after with a kind.
        if not op.get('write_attempted'):
            raise _malformed_retry_state(
                f'{opname} verification_pending without write_attempted flag'
            )
        if not isinstance(op.get('stable_identity'), dict):
            raise _malformed_retry_state(
                f'{opname} verification_pending missing stable_identity'
            )
        if not isinstance(intended, dict):
            raise _malformed_retry_state(
                f'{opname} verification_pending missing intended_after'
            )
        kind = intended.get('kind')
        if kind not in {'image', 'measurement'}:
            raise _malformed_retry_state(
                f'{opname} verification_pending has invalid intended_after.kind'
            )
        return
    if status != 'completed':
        return  # failed / pending / already_complete — validated elsewhere
    if opname in {'push_field', 'pull_field'}:
        if not isinstance(expected, dict):
            raise _malformed_retry_state(f'{opname} missing expected_after')
        if 'value' not in expected:
            raise _malformed_retry_state(f'{opname} missing expected_after.value')
        if not op.get('field'):
            raise _malformed_retry_state(f'{opname} missing field name')
        return
    if opname == 'recompute_spore_statistics':
        if not isinstance(expected, dict) or 'value' not in expected:
            raise _malformed_retry_state(
                'recompute_spore_statistics missing expected_after.value'
            )
        return
    if opname in {'keep_asymmetric_image', 'keep_asymmetric_measurement',
                  'preserve_spore_statistics_no_measurements',
                  'restore_presentation', 'assign_downloaded_order',
                  'store_snapshot'}:
        return  # no material verification needed
    if opname in {'push_image', 'import_image',
                  'push_image_metadata', 'apply_image_metadata'}:
        _require_full_material_expected(op, expected, kind='image')
        return
    if opname in {'push_measurement', 'import_measurement'}:
        _require_full_material_expected(op, expected, kind='measurement')
        return
    raise _malformed_retry_state(f'unknown completed op {opname!r}')


def _require_full_material_expected(op: dict, expected, *, kind: str) -> None:
    opname = op.get('op')

    def _bad(reason: str):
        raise _malformed_retry_state(f'{opname}: {reason}')

    if not isinstance(expected, dict):
        _bad('missing expected_after')
    if expected.get('kind') != kind:
        _bad(f'expected_after.kind should be {kind!r}')
    for side in ('material_local', 'material_remote'):
        side_data = expected.get(side)
        if not isinstance(side_data, dict):
            _bad(f'missing {side}')
        stable = side_data.get('stable')
        material = side_data.get('material')
        if not isinstance(stable, dict):
            _bad(f'{side} missing stable identity')
        if not isinstance(material, dict):
            _bad(f'{side} missing material fingerprint')
        if kind == 'image':
            required_material = set(_ASYMMETRY_MATERIAL_IMAGE_FIELDS)
        else:
            required_material = set(_EXPECTED_AFTER_MEASUREMENT_MATERIAL_FIELDS)
        missing = required_material - set(material.keys())
        if missing:
            _bad(f'{side}.material missing fields: {sorted(missing)}')
    # Op-specific stable-identity requirements.
    local_stable = expected['material_local']['stable']
    remote_stable = expected['material_remote']['stable']
    if opname == 'push_image':
        if not remote_stable.get('cloud_id'):
            _bad('material_remote.stable.cloud_id is required after upload')
        if not local_stable.get('local_id'):
            _bad('material_local.stable.local_id is required (upload source)')
    elif opname == 'import_image':
        if not local_stable.get('local_id'):
            _bad('material_local.stable.local_id is required after import')
        if not remote_stable.get('cloud_id'):
            _bad('material_remote.stable.cloud_id is required (import source)')
    elif opname in {'push_image_metadata', 'apply_image_metadata'}:
        if not local_stable.get('local_id'):
            _bad('material_local.stable.local_id is required')
        if not remote_stable.get('cloud_id'):
            _bad('material_remote.stable.cloud_id is required')
    elif opname in {'push_measurement', 'import_measurement'}:
        if not local_stable.get('local_id'):
            _bad('material_local.stable.local_id is required')
        if not remote_stable.get('cloud_id'):
            _bad('material_remote.stable.cloud_id is required')
        # Owning-image identity must be present (may be null, but the key
        # must exist so we KNOW it was captured, not just omitted).
        if 'owning_local_image_id' not in local_stable:
            _bad('material_local.stable.owning_local_image_id is required')
        if 'owning_cloud_image_id' not in remote_stable:
            _bad('material_remote.stable.owning_cloud_image_id is required')


# ── Full material expected-after fingerprints (Turn-B final Fix 1) ───────────
# Presentation-only fields (``gallery_rotation``, ``sort_order``) and every
# transport/storage/cache field are intentionally excluded so that a purely
# nonmaterial change between attempts does NOT abort a legitimate retry.

_EXPECTED_AFTER_MEASUREMENT_MATERIAL_FIELDS = (
    'length_um', 'width_um', 'measurement_type',
    'p1_x', 'p1_y', 'p2_x', 'p2_y', 'p3_x', 'p3_y', 'p4_x', 'p4_y',
)


def _material_image_expected_state(row: dict | None, *, side: str) -> dict:
    """Full material post-state fingerprint of one image row.

    Includes stable identity + owning-observation link + every material
    content field.  Used both to record the post-write state on each completed
    op and to verify it on retry.
    """
    row = dict(row or {})
    if side == 'local':
        stable = {
            'local_id': _safe_int(row.get('id')) or None,
            'cloud_id': str(row.get('cloud_id') or '').strip() or None,
            'observation_id': _safe_int(row.get('observation_id')) or None,
        }
    else:
        stable = {
            'cloud_id': str(row.get('id') or '').strip() or None,
            'local_id': _safe_int(row.get('desktop_id')) or None,
            'observation_id': str(row.get('observation_id') or '').strip() or None,
        }
    payload = {
        field: _normalize_snapshot_value(row.get(field))
        for field in _ASYMMETRY_MATERIAL_IMAGE_FIELDS
    }
    return {'side': side, 'stable': stable, 'material': payload}


def _material_measurement_expected_state(row: dict | None, *, side: str) -> dict:
    """Full material post-state fingerprint of one measurement row.

    Includes stable identity, owning-image identity, and every scientific
    value.  Non-scientific / transport / presentation fields are excluded.
    """
    row = dict(row or {})
    if side == 'local':
        stable = {
            'local_id': _safe_int(row.get('id')) or None,
            'cloud_id': str(row.get('cloud_id') or '').strip() or None,
            'owning_local_image_id': _safe_int(row.get('image_id')) or None,
            'owning_cloud_image_id': None,
        }
    else:
        stable = {
            'cloud_id': str(row.get('id') or '').strip() or None,
            'local_id': _safe_int(row.get('desktop_id')) or None,
            'owning_local_image_id': None,
            'owning_cloud_image_id': str(row.get('image_id') or '').strip() or None,
        }
    payload: dict = {}
    for field in _EXPECTED_AFTER_MEASUREMENT_MATERIAL_FIELDS:
        if field == 'measurement_type':
            payload[field] = _normalize_measurement_type_value(row.get(field))
        else:
            payload[field] = _normalize_measurement_float_value(row.get(field))
    return {'side': side, 'stable': stable, 'material': payload}


def _intended_after_image_from_local(row: dict | None) -> dict:
    """Build ``intended_after`` for a push whose readback failed.

    Uses the local (source) row's material fields as the intended cloud
    material — since a push copies material fields, the cloud row is expected
    to match once it materializes.
    """
    row = dict(row or {})
    local_state = _material_image_expected_state(row, side='local')
    remote_material = dict(local_state.get('material') or {})
    return {
        'kind': 'image',
        'material_local': local_state,
        'material_remote': {
            'side': 'remote',
            'stable': {
                'cloud_id': str(row.get('cloud_id') or '').strip() or None,
                'local_id': _safe_int(row.get('id')) or None,
                'observation_id': None,
            },
            'material': remote_material,
        },
    }


def _intended_after_image_from_remote(row: dict | None) -> dict:
    row = dict(row or {})
    remote_state = _material_image_expected_state(row, side='remote')
    local_material = dict(remote_state.get('material') or {})
    return {
        'kind': 'image',
        'material_local': {
            'side': 'local',
            'stable': {
                'local_id': _safe_int(row.get('desktop_id')) or None,
                'cloud_id': str(row.get('id') or '').strip() or None,
                'observation_id': None,
            },
            'material': local_material,
        },
        'material_remote': remote_state,
    }


def _intended_after_measurement_from_local(row: dict | None) -> dict:
    row = dict(row or {})
    local_state = _material_measurement_expected_state(row, side='local')
    material = dict(local_state.get('material') or {})
    return {
        'kind': 'measurement',
        'material_local': local_state,
        'material_remote': {
            'side': 'remote',
            'stable': {
                'cloud_id': str(row.get('cloud_id') or '').strip() or None,
                'local_id': _safe_int(row.get('id')) or None,
                'owning_local_image_id': None,
                'owning_cloud_image_id': None,
            },
            'material': material,
        },
    }


def _intended_after_measurement_from_remote(row: dict | None) -> dict:
    row = dict(row or {})
    remote_state = _material_measurement_expected_state(row, side='remote')
    material = dict(remote_state.get('material') or {})
    return {
        'kind': 'measurement',
        'material_local': {
            'side': 'local',
            'stable': {
                'local_id': _safe_int(row.get('desktop_id')) or None,
                'cloud_id': str(row.get('id') or '').strip() or None,
                'owning_local_image_id': None,
                'owning_cloud_image_id': str(row.get('image_id') or '').strip() or None,
            },
            'material': material,
        },
        'material_remote': remote_state,
    }


def _material_image_current_state(current_row: dict | None, *, side: str) -> dict:
    """Alias — the current-side fingerprint uses the same shape."""
    return _material_image_expected_state(current_row, side=side)


def _material_measurement_current_state(current_row: dict | None, *, side: str) -> dict:
    return _material_measurement_expected_state(current_row, side=side)


def _normalize_observation_field_for_baseline(
    obs: dict | None, field: str, *, local: bool
) -> object:
    """Return the same normalized value the baseline fingerprint would carry."""
    payload = _observation_compare_payload(obs or {}, local=local)
    return payload.get(field)


def _verify_completed_ops_and_rebase(
    prior_result: dict,
    original_baseline: dict,
    *,
    local_obs: dict | None,
    remote_obs: dict | None,
    local_images: list[dict],
    remote_images: list[dict],
    local_measurements: list[dict],
    remote_measurements: list[dict],
) -> tuple[dict, set[tuple], list[dict]]:
    """Verify each completed op's expected effect, then rebase the baseline.

    Returns ``(rebased_baseline, completed_op_keys, verified_ops)``.  Raises
    :class:`CloudSyncError` if any completed op's expected effect is missing
    from the current state or if any UNRELATED record has drifted.

    The caller treats ``completed_op_keys`` as "do not re-dispatch" and uses
    the rebased baseline for drift-checking the remaining (pending/failed)
    operations.  This is the expected-effect-aware retry algorithm.
    """
    completed_ops = [
        op for op in (prior_result.get('operations') or [])
        if isinstance(op, dict) and op.get('status') in {'completed', 'verification_pending'}
    ]

    explained_field_names: set[str] = set()
    explained_local_image_ids: set[int] = set()
    explained_cloud_image_ids: set[str] = set()
    explained_local_meas_ids: set[int] = set()
    explained_cloud_meas_ids: set[str] = set()

    def _drift_error(reason: str) -> CloudSyncError:
        return CloudSyncError(
            f'{_plan_drift_message()} ({reason})'
        )

    # Ops that couldn't be resolved on retry (row missing) fall out of the
    # explained set so the plan re-dispatches them; they are removed from
    # ``completed_ops`` here so downstream code doesn't add them.
    resolved_verification_pending: list[dict] = []

    for op in list(completed_ops):
        # Fail-closed structure check.  A malformed prior op cannot bypass
        # drift validation via the explained-set — the exception aborts the
        # retry before any explained-set entry is added.
        _validate_prior_op_expected_after(op)
        if op.get('status') == 'verification_pending':
            resolution = _reconcile_verification_pending_op(
                op,
                local_images=local_images, remote_images=remote_images,
                local_measurements=local_measurements,
                remote_measurements=remote_measurements,
            )
            # resolution is one of:
            #   ('completed', explained_ids...) — row discovered and material matches
            #   ('drift', reason)               — row discovered but material differs
            #   ('missing', None)               — row not found; re-dispatch normally
            kind = resolution[0]
            if kind == 'drift':
                raise _drift_error(resolution[1])
            if kind == 'missing':
                # Do NOT add to explained_* — the plan's normal dispatch reruns
                # the op (safe: underlying helpers upsert by stable id).
                completed_ops.remove(op)
                continue
            # kind == 'completed'
            explained = resolution[1]
            explained_local_image_ids.update(explained.get('local_image_ids', set()))
            explained_cloud_image_ids.update(explained.get('cloud_image_ids', set()))
            explained_local_meas_ids.update(explained.get('local_meas_ids', set()))
            explained_cloud_meas_ids.update(explained.get('cloud_meas_ids', set()))
            resolved_verification_pending.append(op)
            continue
        opname = op.get('op')
        expected = op.get('expected_after') or {}
        if opname == 'pull_field':
            field = op.get('field') or ''
            if not field:
                continue
            current = _normalize_observation_field_for_baseline(
                local_obs, field, local=True
            )
            if not _observation_field_values_match(field, current, expected.get('value')):
                raise _drift_error(
                    f'local observation field "{field}" no longer matches the '
                    'expected effect of a completed pull_field'
                )
            explained_field_names.add(field)
        elif opname == 'push_field':
            field = op.get('field') or ''
            if not field:
                continue
            current = _normalize_observation_field_for_baseline(
                remote_obs, field, local=False
            )
            if not _observation_field_values_match(field, current, expected.get('value')):
                raise _drift_error(
                    f'cloud observation field "{field}" no longer matches the '
                    'expected effect of a completed push_field'
                )
            explained_field_names.add(field)
        elif opname in {'push_image', 'import_image',
                        'push_image_metadata', 'apply_image_metadata'}:
            # Full material verification for every image op.  Identity alone is
            # not proof of intactness; the material post-state must match.
            lid = _safe_int(op.get('local_id')) or None
            cid = str(op.get('cloud_id') or '').strip() or None
            expected_local = (expected or {}).get('material_local')
            expected_remote = (expected or {}).get('material_remote')
            if lid and expected_local is not None:
                current_local = next(
                    (r for r in local_images if _safe_int(r.get('id')) == lid),
                    None,
                )
                if current_local is None:
                    raise _drift_error(
                        f'{opname}: local image {lid} no longer exists'
                    )
                current_fp = _material_image_current_state(current_local, side='local')
                if current_fp != expected_local:
                    raise _drift_error(
                        f'{opname}: local image {lid} material content changed since '
                        'the completed operation wrote it'
                    )
                explained_local_image_ids.add(lid)
            if cid and expected_remote is not None:
                current_remote_row = next(
                    (r for r in remote_images if str(r.get('id') or '').strip() == cid),
                    None,
                )
                if current_remote_row is None:
                    raise _drift_error(
                        f'{opname}: cloud image {cid} no longer exists'
                    )
                current_fp_r = _material_image_current_state(current_remote_row, side='remote')
                if current_fp_r != expected_remote:
                    raise _drift_error(
                        f'{opname}: cloud image {cid} material content changed since '
                        'the completed operation wrote it'
                    )
                explained_cloud_image_ids.add(cid)
        elif opname in {'push_measurement', 'import_measurement'}:
            lid = _safe_int(op.get('local_id')) or None
            cid = str(op.get('cloud_id') or '').strip() or None
            expected_local = (expected or {}).get('material_local')
            expected_remote = (expected or {}).get('material_remote')
            if lid and expected_local is not None:
                current_local = next(
                    (r for r in local_measurements if _safe_int(r.get('id')) == lid),
                    None,
                )
                if current_local is None:
                    raise _drift_error(
                        f'{opname}: local measurement {lid} no longer exists'
                    )
                # Owning-image change is caught here: material_local includes
                # ``stable.owning_local_image_id``.
                current_fp = _material_measurement_current_state(current_local, side='local')
                if current_fp != expected_local:
                    raise _drift_error(
                        f'{opname}: local measurement {lid} scientific values or '
                        'owning image changed since the completed operation'
                    )
                explained_local_meas_ids.add(lid)
            if cid and expected_remote is not None:
                current_remote_row = next(
                    (r for r in remote_measurements if str(r.get('id') or '').strip() == cid),
                    None,
                )
                if current_remote_row is None:
                    raise _drift_error(
                        f'{opname}: cloud measurement {cid} no longer exists'
                    )
                current_fp_r = _material_measurement_current_state(current_remote_row, side='remote')
                if current_fp_r != expected_remote:
                    raise _drift_error(
                        f'{opname}: cloud measurement {cid} scientific values or '
                        'owning image changed since the completed operation'
                    )
                explained_cloud_meas_ids.add(cid)
        elif opname == 'recompute_spore_statistics':
            explained_field_names.add('spore_statistics')
            value = expected.get('value') if isinstance(expected, dict) else None
            if value is not None:
                current_local = _normalize_observation_field_for_baseline(
                    local_obs, 'spore_statistics', local=True
                )
                current_remote = _normalize_observation_field_for_baseline(
                    remote_obs, 'spore_statistics', local=False
                )
                if not (
                    _observation_field_values_match('spore_statistics', current_local, value)
                    and _observation_field_values_match(
                        'spore_statistics', current_remote, value
                    )
                ):
                    raise _drift_error(
                        'spore_statistics no longer matches the recomputed value'
                    )
        # keep_asymmetric_*, preserve_spore_statistics_no_measurements,
        # restore_presentation, assign_downloaded_order: no verification needed
        # here (no cloud/local material write happened).

    # ── Now check that every UNRELATED record still matches original baseline ─
    original_local_obs = original_baseline.get('local_observation') or {}
    original_remote_obs = original_baseline.get('remote_observation') or {}
    current_local_obs_fp = _conflict_plan_local_observation_fingerprint(local_obs)
    current_remote_obs_fp = _conflict_plan_remote_observation_fingerprint(remote_obs)
    for field, expected_value in original_local_obs.items():
        if field in explained_field_names:
            continue
        if not _observation_field_values_match(
            field, current_local_obs_fp.get(field), expected_value
        ):
            raise _drift_error(
                f'unrelated local field "{field}" changed since the baseline'
            )
    for field, expected_value in original_remote_obs.items():
        if field in explained_field_names:
            continue
        if not _observation_field_values_match(
            field, current_remote_obs_fp.get(field), expected_value
        ):
            raise _drift_error(
                f'unrelated cloud field "{field}" changed since the baseline'
            )

    def _local_id(row): return _safe_int(row.get('__local_id')) or _safe_int(row.get('local_id'))
    def _cloud_id(row): return str(row.get('__cloud_id') or row.get('cloud_id') or '').strip()

    current_local_images_fp = {
        _safe_int(row.get('id')): _conflict_plan_local_image_fingerprint(row)
        for row in local_images or [] if _safe_int(row.get('id'))
    }
    current_remote_images_fp = {
        str(row.get('id') or '').strip(): _conflict_plan_remote_image_fingerprint(row)
        for row in remote_images or [] if str(row.get('id') or '').strip()
    }
    for row in original_baseline.get('local_images') or []:
        lid = _local_id(row)
        if not lid or lid in explained_local_image_ids:
            continue
        current = current_local_images_fp.get(lid)
        if current != row:
            raise _drift_error(
                f'unrelated local image {lid} changed since the baseline'
            )
    for row in original_baseline.get('remote_images') or []:
        cid = _cloud_id(row)
        if not cid or cid in explained_cloud_image_ids:
            continue
        current = current_remote_images_fp.get(cid)
        if current != row:
            raise _drift_error(
                f'unrelated cloud image {cid} changed since the baseline'
            )

    current_local_meas_fp = {
        _safe_int(row.get('id')): _conflict_plan_local_measurement_fingerprint(row)
        for row in local_measurements or [] if _safe_int(row.get('id'))
    }
    current_remote_meas_fp = {
        str(row.get('id') or '').strip(): _conflict_plan_remote_measurement_fingerprint(row)
        for row in remote_measurements or [] if str(row.get('id') or '').strip()
    }
    for row in original_baseline.get('local_measurements') or []:
        lid = _local_id(row)
        if not lid or lid in explained_local_meas_ids:
            continue
        current = current_local_meas_fp.get(lid)
        if current != row:
            raise _drift_error(
                f'unrelated local measurement {lid} changed since the baseline'
            )
    for row in original_baseline.get('remote_measurements') or []:
        cid = _cloud_id(row)
        if not cid or cid in explained_cloud_meas_ids:
            continue
        current = current_remote_meas_fp.get(cid)
        if current != row:
            raise _drift_error(
                f'unrelated cloud measurement {cid} changed since the baseline'
            )

    # Rebase — build a fresh baseline from the verified current state.
    rebased = build_conflict_plan_baseline(
        local_obs=local_obs,
        remote_obs=remote_obs,
        local_images=list(local_images or []),
        remote_images=list(remote_images or []),
        local_measurements=list(local_measurements or []),
        remote_measurements=list(remote_measurements or []),
    )
    completed_keys = {_stable_op_key(op) for op in completed_ops}
    # Attach the observed ``already_complete`` status to the ops we hand back.
    verified_ops = []
    for op in completed_ops:
        entry = dict(op)
        entry['status'] = 'already_complete'
        verified_ops.append(entry)
    return rebased, completed_keys, verified_ops


def _stable_op_key(op: dict) -> tuple:
    """Identity of an operation across retries.  Used to dedupe completed work."""
    return (
        str(op.get('op') or ''),
        str(op.get('field') or ''),
        _safe_int(op.get('local_id')) or 0,
        str(op.get('cloud_id') or '').strip(),
    )


def _plan_dispatch_keys(op: dict) -> set:
    """Every plan-op key an item with the same identity could produce.

    A completed op may carry the newly-formed cloud id (or the newly-linked
    local id), but the plan-op derived from the user's item won't yet know it.
    Return both variants so the filter matches either.
    """
    opname = str(op.get('op') or '')
    field = str(op.get('field') or '')
    local_id = _safe_int(op.get('local_id')) or 0
    cloud_id = str(op.get('cloud_id') or '').strip()
    keys: set = {(opname, field, local_id, cloud_id)}
    if opname in {'push_image', 'push_measurement'}:
        # Plan-op form: cloud_id not yet known.
        keys.add((opname, field, local_id, ''))
    elif opname in {'import_image', 'import_measurement'}:
        # Plan-op form: local_id not yet known.
        keys.add((opname, field, 0, cloud_id))
    return keys


def _plan_item_matches_completed_op(item: dict, completed_key: tuple) -> bool:
    """Return True when a plan item's dispatch matches an already-completed op key."""
    kind = item.get('kind')
    choice = item.get('choice')
    side = item.get('side')
    local_id = _safe_int(item.get('local_id')) or 0
    cloud_id = str(item.get('cloud_id') or '').strip()
    field = str(item.get('field') or '')
    if kind == 'field':
        if choice == 'cloud':
            return completed_key == ('pull_field', field, 0, '')
        if choice == 'local':
            return completed_key == ('push_field', field, 0, '')
    elif kind == 'image':
        if choice == 'upload':
            return completed_key == ('push_image', '', local_id, '')
        if choice == 'download':
            return completed_key == ('import_image', '', 0, cloud_id)
        if choice in {'keep_local', 'keep_cloud'}:
            return completed_key == (
                'keep_asymmetric_image', '', local_id, cloud_id,
            )
    elif kind == 'image_metadata':
        if choice == 'local':
            return completed_key == ('push_image_metadata', '', local_id, cloud_id)
        if choice == 'cloud':
            return completed_key == ('apply_image_metadata', '', local_id, cloud_id)
    elif kind == 'measurement':
        if side == 'matched':
            if choice == 'local':
                return completed_key == ('push_measurement', '', local_id, cloud_id)
            if choice == 'cloud':
                return completed_key == ('import_measurement', '', local_id, cloud_id)
        elif side == 'local_only':
            if choice == 'upload':
                return completed_key == ('push_measurement', '', local_id, '')
            if choice == 'keep_local':
                return completed_key == ('keep_asymmetric_measurement', '', local_id, '')
        elif side == 'cloud_only':
            if choice == 'download':
                return completed_key == ('import_measurement', '', 0, cloud_id)
            if choice == 'keep_cloud':
                return completed_key == ('keep_asymmetric_measurement', '', 0, cloud_id)
    return False


def _build_accepted_asymmetry_from_plan(
    items: list[dict],
    *,
    local_images: list[dict],
    remote_images: list[dict],
    local_measurements: list[dict],
    remote_measurements: list[dict],
) -> dict:
    """Turn each ``keep_*`` item into a durable accepted-asymmetry entry.

    Only items whose stable identity still resolves to a live row on the
    named side are recorded; a keep-only choice against a phantom row is
    ignored so we never invent acceptance.
    """
    accepted = {
        'local_only_images': [],
        'cloud_only_images': [],
        'local_only_measurements': [],
        'cloud_only_measurements': [],
    }
    local_image_by_id = {_safe_int(r.get('id')): r for r in local_images
                         if _safe_int(r.get('id'))}
    remote_image_by_id = {str(r.get('id') or '').strip(): r for r in remote_images
                          if str(r.get('id') or '').strip()}
    local_meas_by_id = {_safe_int(r.get('id')): r for r in local_measurements
                        if _safe_int(r.get('id'))}
    remote_meas_by_id = {str(r.get('id') or '').strip(): r for r in remote_measurements
                         if str(r.get('id') or '').strip()}
    for item in items:
        kind = item.get('kind')
        choice = item.get('choice')
        if kind == 'image' and choice == 'keep_local':
            local_id = _safe_int(item.get('local_id'))
            row = local_image_by_id.get(local_id)
            if row is None:
                continue
            accepted['local_only_images'].append({
                'side': 'local_only', 'kind': 'image',
                'local_id': local_id, 'cloud_id': None,
                'owning_local_image_id': None, 'owning_cloud_image_id': None,
                'fingerprint': _asymmetry_fingerprint_local_image(row),
                'accepted_at': _iso_timestamp_now(),
                'choice': 'keep_local',
            })
        elif kind == 'image' and choice == 'keep_cloud':
            cloud_id = str(item.get('cloud_id') or '').strip()
            row = remote_image_by_id.get(cloud_id)
            if row is None:
                continue
            accepted['cloud_only_images'].append({
                'side': 'cloud_only', 'kind': 'image',
                'local_id': None, 'cloud_id': cloud_id,
                'owning_local_image_id': None, 'owning_cloud_image_id': None,
                'fingerprint': _asymmetry_fingerprint_remote_image(row),
                'accepted_at': _iso_timestamp_now(),
                'choice': 'keep_cloud',
            })
        elif kind == 'measurement' and choice == 'keep_local':
            local_id = _safe_int(item.get('local_id'))
            row = local_meas_by_id.get(local_id)
            if row is None:
                continue
            accepted['local_only_measurements'].append({
                'side': 'local_only', 'kind': 'measurement',
                'local_id': local_id, 'cloud_id': None,
                'owning_local_image_id': _safe_int(row.get('image_id')) or None,
                'owning_cloud_image_id': None,
                'fingerprint': _asymmetry_fingerprint_local_measurement(row),
                'accepted_at': _iso_timestamp_now(),
                'choice': 'keep_local',
            })
        elif kind == 'measurement' and choice == 'keep_cloud':
            cloud_id = str(item.get('cloud_id') or '').strip()
            row = remote_meas_by_id.get(cloud_id)
            if row is None:
                continue
            accepted['cloud_only_measurements'].append({
                'side': 'cloud_only', 'kind': 'measurement',
                'local_id': None, 'cloud_id': cloud_id,
                'owning_local_image_id': None,
                'owning_cloud_image_id': str(row.get('image_id') or '').strip() or None,
                'fingerprint': _asymmetry_fingerprint_remote_measurement(row),
                'accepted_at': _iso_timestamp_now(),
                'choice': 'keep_cloud',
            })
    return accepted


def _identities_referenced_by_plan(items: list[dict]) -> dict:
    """Every stable identity that this plan explicitly touches with a non-keep choice.

    Used to remove prior accepted-asymmetry entries the user is overriding.
    """
    image_identities: set[tuple[int, str]] = set()
    measurement_identities: set[tuple[int, str]] = set()
    for item in items or []:
        kind = item.get('kind')
        choice = item.get('choice')
        # ``keep_*`` choices are handled by _build_accepted_asymmetry_from_plan.
        # Everything else counts as an override that removes any prior keep-only
        # entry for the same stable identity.
        if choice in {'keep_local', 'keep_cloud'}:
            continue
        local_id = _safe_int(item.get('local_id')) or 0
        cloud_id = str(item.get('cloud_id') or '').strip()
        if kind in {'image', 'image_metadata'}:
            image_identities.add((local_id, cloud_id))
        elif kind == 'measurement':
            measurement_identities.add((local_id, cloud_id))
    return {'images': image_identities, 'measurements': measurement_identities}


def _reconcile_accepted_asymmetry(
    previous: dict | None,
    new: dict,
    *,
    plan_items: list[dict],
    current_local_images: list[dict],
    current_remote_images: list[dict],
    current_local_measurements: list[dict],
    current_remote_measurements: list[dict],
    matched_local_image_ids: set[int] | None = None,
    matched_cloud_image_ids: set[str] | None = None,
    matched_local_measurement_ids: set[int] | None = None,
    matched_cloud_measurement_ids: set[str] | None = None,
) -> dict:
    """Merge, prune, and supersede accepted-asymmetry entries.

    Removes an accepted entry when any of the following is now true:

    * its stable identity is referenced by a non-keep plan choice (user
      explicitly changed their mind to upload/download);
    * the counterpart now exists (row is no longer one-sided);
    * the accepted row no longer exists on its side (deletion / relink);
    * for measurements: the row's owning image identity changed;
    * ownership or side changed.

    Newer keep-only entries for the same identity replace older ones so the
    fingerprint stays fresh.  The result contains only entries that are still
    valid.
    """
    result = {
        'local_only_images': [],
        'cloud_only_images': [],
        'local_only_measurements': [],
        'cloud_only_measurements': [],
    }
    prev = previous if isinstance(previous, dict) else {}
    override = _identities_referenced_by_plan(plan_items or [])
    override_images = override['images']
    override_measurements = override['measurements']
    matched_local_image_ids = matched_local_image_ids or set()
    matched_cloud_image_ids = matched_cloud_image_ids or set()
    matched_local_measurement_ids = matched_local_measurement_ids or set()
    matched_cloud_measurement_ids = matched_cloud_measurement_ids or set()

    local_image_by_id = {_safe_int(r.get('id')): r for r in current_local_images or []
                         if _safe_int(r.get('id'))}
    remote_image_by_id = {str(r.get('id') or '').strip(): r for r in current_remote_images or []
                          if str(r.get('id') or '').strip()}
    local_meas_by_id = {_safe_int(r.get('id')): r for r in current_local_measurements or []
                        if _safe_int(r.get('id'))}
    remote_meas_by_id = {str(r.get('id') or '').strip(): r for r in current_remote_measurements or []
                         if str(r.get('id') or '').strip()}

    def _still_local_only_image(entry: dict) -> bool:
        local_id = _safe_int(entry.get('local_id'))
        if not local_id or local_id not in local_image_by_id:
            return False  # row is gone
        row = local_image_by_id[local_id]
        # Row now linked to a cloud row → no longer one-sided.
        if str(row.get('cloud_id') or '').strip():
            return False
        # A cloud row now claims this local id → no longer one-sided.
        if local_id in matched_local_image_ids:
            return False
        # User overrode (upload etc.) → drop.
        if (local_id, '') in override_images or any(lid == local_id for lid, _ in override_images):
            return False
        return True

    def _still_cloud_only_image(entry: dict) -> bool:
        cloud_id = str(entry.get('cloud_id') or '').strip()
        if not cloud_id or cloud_id not in remote_image_by_id:
            return False
        row = remote_image_by_id[cloud_id]
        if _safe_int(row.get('desktop_id')):
            return False  # cloud row now points at a local row
        if cloud_id in matched_cloud_image_ids:
            return False
        if any(cid == cloud_id for _, cid in override_images):
            return False
        return True

    def _still_local_only_measurement(entry: dict) -> bool:
        local_id = _safe_int(entry.get('local_id'))
        if not local_id or local_id not in local_meas_by_id:
            return False
        row = local_meas_by_id[local_id]
        if str(row.get('cloud_id') or '').strip():
            return False  # relinked
        # Owning-image identity changed → drop; fresh conflict.
        expected_owner = _safe_int(entry.get('owning_local_image_id')) or None
        current_owner = _safe_int(row.get('image_id')) or None
        if expected_owner is not None and current_owner is not None and expected_owner != current_owner:
            return False
        if local_id in matched_local_measurement_ids:
            return False
        if any(lid == local_id for lid, _ in override_measurements):
            return False
        return True

    def _still_cloud_only_measurement(entry: dict) -> bool:
        cloud_id = str(entry.get('cloud_id') or '').strip()
        if not cloud_id or cloud_id not in remote_meas_by_id:
            return False
        row = remote_meas_by_id[cloud_id]
        if _safe_int(row.get('desktop_id')):
            return False
        expected_owner = str(entry.get('owning_cloud_image_id') or '').strip() or None
        current_owner = str(row.get('image_id') or '').strip() or None
        if expected_owner and current_owner and expected_owner != current_owner:
            return False
        if cloud_id in matched_cloud_measurement_ids:
            return False
        if any(cid == cloud_id for _, cid in override_measurements):
            return False
        return True

    predicates = {
        'local_only_images': _still_local_only_image,
        'cloud_only_images': _still_cloud_only_image,
        'local_only_measurements': _still_local_only_measurement,
        'cloud_only_measurements': _still_cloud_only_measurement,
    }

    for key, predicate in predicates.items():
        seen: dict[tuple, dict] = {}
        # Prior entries first (survivors of pruning).
        for entry in prev.get(key) or []:
            if isinstance(entry, dict) and predicate(entry):
                seen[_accepted_asymmetry_key(entry)] = dict(entry)
        # New entries override / add — they were computed against fresh state
        # so they are always valid.
        for entry in new.get(key) or []:
            if isinstance(entry, dict):
                seen[_accepted_asymmetry_key(entry)] = dict(entry)
        result[key] = list(seen.values())
    return result


def _merge_accepted_asymmetry(previous: dict | None, new: dict) -> dict:
    """Preserved for ordinary sync callers that don't do full reconciliation.

    Kept as a thin wrapper for backward compatibility with helpers that store
    a snapshot without a plan context (e.g. push_all).  A plan resolution
    should call ``_reconcile_accepted_asymmetry`` directly.
    """
    result = {
        'local_only_images': [],
        'cloud_only_images': [],
        'local_only_measurements': [],
        'cloud_only_measurements': [],
    }
    prev = previous if isinstance(previous, dict) else {}
    for key in result.keys():
        seen: dict[tuple, dict] = {}
        for entry in prev.get(key) or []:
            if isinstance(entry, dict):
                seen[_accepted_asymmetry_key(entry)] = dict(entry)
        for entry in new.get(key) or []:
            if isinstance(entry, dict):
                seen[_accepted_asymmetry_key(entry)] = dict(entry)
        result[key] = list(seen.values())
    return result


def _iso_timestamp_now() -> str:
    """UTC timestamp for accepted_at diagnostics.  Never used as identity."""
    try:
        from datetime import datetime, timezone
        return datetime.now(tz=timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    except Exception:
        return ''


def resolve_conflict_plan(
    client: "SporelyCloudClient",
    local_id: int,
    *,
    cloud_id: str | None = None,
    plan: dict | None = None,
    prepare_images_cb: PreparedImagesCallback | None = None,
    prior_result: dict | None = None,
) -> dict:
    """Apply one explicit, non-destructive per-item conflict plan.

    Turn-A execution order:

    1. Refetch local and cloud state.
    2. Validate identity (belt-and-braces of UI-side detection).
    3. Verify the reviewed plan against the fresh state (drift check).
    4. Build an explicit per-(kind, side, choice) operation list.
    5. Capture local presentation state so cloud metadata cannot silently
       overwrite ``gallery_rotation`` / ``sort_order`` on matched images.
    6. Execute every operation exactly once.
    7. Restore presentation for matched images; assign deterministic order to
       downloaded cloud-only images.
    8. Recompute spore statistics from the *final* measurement set, preserving
       cloud value when recomputation legitimately yields nothing.
    9. Finalize: store snapshot → refresh media signature → stamp synced.
    """
    selected_plan = dict(plan or {})
    if selected_plan.get('allow_media_deletion'):
        raise CloudSyncError('Conflict plans cannot authorize media deletion')

    local_obs = ObservationDB.get_observation(int(local_id))
    if not local_obs:
        raise CloudSyncError(f'Local observation {local_id} not found')
    resolved_cloud_id = str(cloud_id or local_obs.get('cloud_id') or '').strip()
    if not resolved_cloud_id:
        raise CloudSyncError(f'Observation {local_id} is not linked to Sporely Cloud')

    items = [dict(item or {}) for item in (selected_plan.get('items') or [])]
    baseline = selected_plan.get('baseline')
    # A1: item-level plans MUST carry a reviewed baseline.  Old whole-observation
    # resolvers (resolve_conflict_keep_local / _keep_cloud / _merge) are separate
    # APIs and are unaffected.
    _validate_plan_baseline_shape(baseline)
    baseline = dict(baseline)

    # ── B2: partial-retry — carry forward completed operations ─────────────
    completed_prior_ops: list[dict] = []
    completed_prior_keys: set = set()
    if isinstance(prior_result, dict):
        for op in prior_result.get('operations') or []:
            if isinstance(op, dict) and op.get('status') in {
                'completed', 'verification_pending'
            }:
                completed_prior_ops.append(dict(op))
                completed_prior_keys |= _plan_dispatch_keys(op)

    # ── Step 1: refetch current state ─────────────────────────────────────────
    remote_obs = client.get_observation(resolved_cloud_id)
    remote_images = [
        dict(row or {})
        for row in (_pull_remote_images_for_sync(client, resolved_cloud_id) or [])
        if not str((row or {}).get('deleted_at') or '').strip()
        and should_pull_cloud_image_to_desktop(row)
    ]
    remote_measurements = _pull_remote_measurements_for_images(
        client,
        [
            str(row.get('id') or '').strip()
            for row in remote_images
            if str(row.get('id') or '').strip()
        ],
    )
    current_local_images = ImageDB.get_images_for_observation(int(local_id))
    current_local_measurements = MeasurementDB.get_measurements_for_observation(int(local_id))

    # ── Step 2: identity validation ───────────────────────────────────────────
    _validate_plan_identity_state(
        local_images=current_local_images,
        remote_images=remote_images,
        local_measurements=current_local_measurements,
        remote_measurements=remote_measurements,
        items=items,
    )

    # ── Step 2b: retry rebasing ──────────────────────────────────────────────
    # Turn-B fix 1: expected-effect-aware rebasing.  If we were handed a
    # ``prior_result`` from an earlier PartialConflictPlanError, verify each
    # completed op's ``expected_after`` against the current state, ensure that
    # every UNRELATED record still matches the original baseline, then replace
    # the baseline with a fresh one so the drift check for the remaining
    # (pending/failed) ops runs against the rebased state.
    verified_completed_ops: list[dict] = []
    if isinstance(prior_result, dict) and prior_result.get('operations'):
        baseline, rebased_keys, verified_completed_ops = _verify_completed_ops_and_rebase(
            prior_result, baseline,
            local_obs=local_obs, remote_obs=remote_obs,
            local_images=current_local_images, remote_images=remote_images,
            local_measurements=current_local_measurements,
            remote_measurements=remote_measurements,
        )
        # Expand the completed keys to include plan-dispatch variants.
        for op in prior_result.get('operations') or []:
            if isinstance(op, dict) and op.get('status') in {
                'completed', 'verification_pending'
            }:
                completed_prior_keys |= _plan_dispatch_keys(op)
        completed_prior_keys |= rebased_keys

    # ── Step 3: drift validation against (possibly rebased) baseline ─────────
    _verify_plan_baseline(
        baseline,
        items,
        local_obs=local_obs,
        remote_obs=remote_obs,
        local_images=current_local_images,
        remote_images=remote_images,
        local_measurements=current_local_measurements,
        remote_measurements=remote_measurements,
    )

    # ── Step 4: build the explicit operation list ─────────────────────────────
    ops = [
        op for op in _build_plan_operations(items)
        if _stable_op_key(op) not in completed_prior_keys
    ]

    # ── Step 5: capture local presentation state ──────────────────────────────
    presentation_before = _capture_local_presentation(current_local_images)

    # ── Step 6: execute operations, in a stable order ─────────────────────────
    # Retry carries verified completed prior ops forward as ``already_complete``
    # entries so the return value reports the full history.
    executed: list[dict] = list(verified_completed_ops) if verified_completed_ops else list(completed_prior_ops)
    matched_image_local_ids: set[int] = set()

    def _partial_error(message: str, failing: dict | None = None,
                       cause: Exception | None = None) -> PartialConflictPlanError:
        pending = list(executed)
        if failing is not None:
            pending.append({
                **failing,
                'status': 'failed',
                'error': str(cause) if cause else message,
            })
        err = PartialConflictPlanError(
            message,
            partial_result={
                'local_id': int(local_id),
                'cloud_id': resolved_cloud_id,
                'plan_applied': False,
                'operations': pending,
            },
        )
        if cause is not None:
            err.__cause__ = cause
        return err

    # Field: pull from cloud
    cloud_field_names = {
        str(op.get('field') or '')
        for op in ops
        if op.get('op') == 'pull_field' and op.get('field')
    }
    if cloud_field_names:
        try:
            _apply_remote_observation_fields(int(local_id), remote_obs, fields=cloud_field_names)
        except Exception as exc:
            raise _partial_error(
                f'Could not apply cloud fields to local: {exc}',
                failing={'op': 'pull_field', 'fields': sorted(cloud_field_names)},
                cause=exc,
            )
        # Record the expected local value that pull_field wrote — retry
        # verifies the current local field still matches.
        refreshed_after_pull = ObservationDB.get_observation(int(local_id)) or local_obs
        for f in sorted(cloud_field_names):
            executed.append({
                'op': 'pull_field', 'field': f, 'status': 'completed',
                'stable_identity': {'field': f, 'side': 'local'},
                'expected_after': {
                    'side': 'local',
                    'field': f,
                    'value': _normalize_observation_field_for_baseline(
                        refreshed_after_pull, f, local=True,
                    ),
                },
            })

    # Field: push to cloud
    local_field_names = {
        str(op.get('field') or '')
        for op in ops
        if op.get('op') == 'push_field' and op.get('field')
    }
    if local_field_names:
        try:
            refreshed_local = ObservationDB.get_observation(int(local_id)) or local_obs
            local_payload = _observation_push_payload(refreshed_local, local=True)
            patch_payload = {
                ('visibility' if field == 'sharing_scope' else field): local_payload.get(
                    'visibility' if field in {'visibility', 'sharing_scope'} else field
                )
                for field in local_field_names
            }
            if patch_payload:
                client._patch(f'observations?id=eq.{resolved_cloud_id}', patch_payload)
        except Exception as exc:
            raise _partial_error(
                f'Could not push local fields to cloud: {exc}',
                failing={'op': 'push_field', 'fields': sorted(local_field_names)},
                cause=exc,
            )
        for f in sorted(local_field_names):
            executed.append({
                'op': 'push_field', 'field': f, 'status': 'completed',
                'stable_identity': {'field': f, 'side': 'cloud'},
                'expected_after': {
                    'side': 'cloud',
                    'field': f,
                    'value': _normalize_observation_field_for_baseline(
                        refreshed_local, f, local=True,
                    ),
                },
            })

    # Image: import from cloud (materialize) + apply metadata from cloud
    remote_ids_to_import = {
        str(op.get('cloud_id') or '')
        for op in ops
        if op.get('op') == 'import_image' and str(op.get('cloud_id') or '')
    }
    remote_ids_metadata_only = {
        str(op.get('cloud_id') or '')
        for op in ops
        if op.get('op') == 'apply_image_metadata' and str(op.get('cloud_id') or '')
    }
    combined_remote_ids = remote_ids_to_import | remote_ids_metadata_only
    if combined_remote_ids:
        try:
            _apply_remote_images_to_local(
                client,
                int(local_id),
                [row for row in remote_images if str(row.get('id') or '') in combined_remote_ids],
                allow_delete=False,
                materialize_remote_images=True,
            )
        except Exception as exc:
            raise _partial_error(
                f'Could not apply cloud images to local: {exc}',
                failing={'op': 'apply_or_import_image',
                         'cloud_ids': sorted(combined_remote_ids)},
                cause=exc,
            )
        try:
            local_after = ImageDB.get_images_for_observation(int(local_id))
            local_by_cloud = {
                str(r.get('cloud_id') or '').strip(): r for r in local_after
                if str(r.get('cloud_id') or '').strip()
            }
            remote_by_cloud_after = {
                str(row.get('id') or '').strip(): row for row in remote_images
                if str(row.get('id') or '').strip()
            }
            for cid in sorted(combined_remote_ids):
                local_link = local_by_cloud.get(cid) or {}
                remote_row = remote_by_cloud_after.get(cid) or {}
                op_kind = ('import_image' if cid in remote_ids_to_import
                           else 'apply_image_metadata')
                executed.append({
                    'op': op_kind,
                    'cloud_id': cid,
                    'local_id': _safe_int(local_link.get('id')) or None,
                    'status': 'completed',
                    'stable_identity': {'cloud_id': cid,
                                        'local_id': _safe_int(local_link.get('id')) or None},
                    'expected_after': {
                        'kind': 'image',
                        'material_local': _material_image_expected_state(
                            local_link, side='local'
                        ),
                        'material_remote': _material_image_expected_state(
                            remote_row, side='remote'
                        ),
                    },
                })
        except Exception as exc:
            remote_by_cloud_after = {
                str(row.get('id') or '').strip(): row for row in remote_images
                if str(row.get('id') or '').strip()
            }
            for cid in sorted(combined_remote_ids):
                remote_row = remote_by_cloud_after.get(cid) or {}
                op_kind = ('import_image' if cid in remote_ids_to_import
                           else 'apply_image_metadata')
                executed.append({
                    'op': op_kind,
                    'cloud_id': cid,
                    'status': 'verification_pending',
                    'write_attempted': True,
                    'stable_identity': {'cloud_id': cid},
                    'intended_after': _intended_after_image_from_remote(remote_row),
                })
            raise _partial_error(
                f'Cloud→local image apply succeeded but verification read failed: {exc}',
                failing=None, cause=exc,
            )

    # Track matched image local ids for later presentation restore.
    # Matched = the local id appears in an image_metadata op (this attempt) OR
    # was touched by an already-verified image op from a prior attempt.  Even
    # if the underlying apply is not re-run this attempt, presentation restore
    # is a nonblocking write that MUST still be re-attempted so a failed
    # presentation from the prior attempt is retried.
    for op in ops:
        if op.get('op') in {'apply_image_metadata', 'push_image_metadata'}:
            lid = _safe_int(op.get('local_id'))
            if lid:
                matched_image_local_ids.add(lid)
    for op in verified_completed_ops or []:
        if op.get('op') in {'apply_image_metadata', 'push_image_metadata'}:
            lid = _safe_int(op.get('local_id'))
            if lid:
                matched_image_local_ids.add(lid)

    # Image: upload
    local_image_ids_to_push = {
        _safe_int(op.get('local_id'))
        for op in ops
        if op.get('op') == 'push_image' and _safe_int(op.get('local_id')) > 0
    }
    if local_image_ids_to_push and prepare_images_cb is None:
        raise CloudSyncError('Selected local images require the desktop image preparer')
    if local_image_ids_to_push:
        try:
            refreshed_local = ObservationDB.get_observation(int(local_id)) or local_obs
            pushed_ok = _push_images_for_observation(
                client,
                refreshed_local,
                resolved_cloud_id,
                prepare_images_cb=prepare_images_cb,
                include_image_ids=local_image_ids_to_push,
            )
        except Exception as exc:
            raise _partial_error(
                f'Could not upload all selected local images: {exc}',
                failing={'op': 'push_image', 'local_ids': sorted(local_image_ids_to_push)},
                cause=exc,
            )
        if not pushed_ok:
            raise _partial_error(
                'Could not upload all selected local images',
                failing={'op': 'push_image', 'local_ids': sorted(local_image_ids_to_push)},
            )
        # Reread both sides.  If the verification read-back fails after the
        # write succeeded, emit ``verification_pending`` ops so retry can
        # discover the created rows via stable identity without re-dispatch.
        try:
            local_after_push = ImageDB.get_images_for_observation(int(local_id))
            by_local_id = {_safe_int(r.get('id')): r for r in local_after_push
                           if _safe_int(r.get('id'))}
            remote_after_push = [
                dict(row or {})
                for row in (_pull_remote_images_for_sync(client, resolved_cloud_id) or [])
                if not str((row or {}).get('deleted_at') or '').strip()
                and should_pull_cloud_image_to_desktop(row)
            ]
            remote_by_desktop = {_safe_int(r.get('desktop_id')): r for r in remote_after_push
                                 if _safe_int(r.get('desktop_id'))}
            for lid in sorted(local_image_ids_to_push):
                local_row = by_local_id.get(int(lid)) or {}
                cid_after = str(local_row.get('cloud_id') or '').strip() or None
                remote_row = remote_by_desktop.get(int(lid)) or {}
                executed.append({
                    'op': 'push_image', 'local_id': lid,
                    'cloud_id': cid_after,
                    'status': 'completed',
                    'stable_identity': {'local_id': lid, 'cloud_id': cid_after},
                    'expected_after': {
                        'kind': 'image',
                        'material_local': _material_image_expected_state(
                            local_row, side='local'
                        ),
                        'material_remote': _material_image_expected_state(
                            remote_row, side='remote'
                        ),
                    },
                })
        except Exception as exc:
            # Cloud write succeeded but verification fetch failed.  Capture
            # intended_after from the local rows we tried to push, then raise
            # a partial error so the caller can retry safely.
            best_local_rows = {_safe_int(r.get('id')): r
                               for r in current_local_images
                               if _safe_int(r.get('id'))}
            for lid in sorted(local_image_ids_to_push):
                source = best_local_rows.get(int(lid)) or {}
                cid = str(source.get('cloud_id') or '').strip() or None
                executed.append({
                    'op': 'push_image', 'local_id': lid,
                    'cloud_id': cid,
                    'status': 'verification_pending',
                    'write_attempted': True,
                    'stable_identity': {'local_id': lid, 'cloud_id': cid},
                    'intended_after': _intended_after_image_from_local(source),
                })
            raise _partial_error(
                f'Push succeeded but verification fetch failed: {exc}',
                failing=None, cause=exc,
            )

    # Image metadata: local → cloud.  Only when the user chose 'local'.
    local_metadata_image_ids_to_push = {
        _safe_int(op.get('local_id'))
        for op in ops
        if op.get('op') == 'push_image_metadata' and _safe_int(op.get('local_id')) > 0
    }
    if local_metadata_image_ids_to_push and prepare_images_cb is None:
        raise CloudSyncError('Selected local images require the desktop image preparer')
    if local_metadata_image_ids_to_push:
        try:
            refreshed_local = ObservationDB.get_observation(int(local_id)) or local_obs
            pushed_ok = _push_images_for_observation(
                client,
                refreshed_local,
                resolved_cloud_id,
                prepare_images_cb=prepare_images_cb,
                include_image_ids=local_metadata_image_ids_to_push,
            )
        except Exception as exc:
            raise _partial_error(
                f'Could not push local image metadata: {exc}',
                failing={'op': 'push_image_metadata',
                         'local_ids': sorted(local_metadata_image_ids_to_push)},
                cause=exc,
            )
        if not pushed_ok:
            raise _partial_error(
                'Could not push local image metadata',
                failing={'op': 'push_image_metadata',
                         'local_ids': sorted(local_metadata_image_ids_to_push)},
            )
        try:
            local_after_meta = ImageDB.get_images_for_observation(int(local_id))
            by_local_id_meta = {_safe_int(r.get('id')): r for r in local_after_meta
                                if _safe_int(r.get('id'))}
            remote_after_meta = [
                dict(row or {})
                for row in (_pull_remote_images_for_sync(client, resolved_cloud_id) or [])
                if not str((row or {}).get('deleted_at') or '').strip()
                and should_pull_cloud_image_to_desktop(row)
            ]
            remote_meta_by_desktop = {_safe_int(r.get('desktop_id')): r
                                      for r in remote_after_meta
                                      if _safe_int(r.get('desktop_id'))}
            for lid in sorted(local_metadata_image_ids_to_push):
                local_row = by_local_id_meta.get(int(lid)) or {}
                remote_row = remote_meta_by_desktop.get(int(lid)) or {}
                cid_after = str(local_row.get('cloud_id') or '').strip() or None
                executed.append({
                    'op': 'push_image_metadata', 'local_id': lid,
                    'cloud_id': cid_after,
                    'status': 'completed',
                    'stable_identity': {'local_id': lid, 'cloud_id': cid_after},
                    'expected_after': {
                        'kind': 'image',
                        'material_local': _material_image_expected_state(
                            local_row, side='local'
                        ),
                        'material_remote': _material_image_expected_state(
                            remote_row, side='remote'
                        ),
                    },
                })
        except Exception as exc:
            best_local_rows = {_safe_int(r.get('id')): r for r in current_local_images
                               if _safe_int(r.get('id'))}
            for lid in sorted(local_metadata_image_ids_to_push):
                source = best_local_rows.get(int(lid)) or {}
                cid = str(source.get('cloud_id') or '').strip() or None
                executed.append({
                    'op': 'push_image_metadata', 'local_id': lid,
                    'cloud_id': cid,
                    'status': 'verification_pending',
                    'write_attempted': True,
                    'stable_identity': {'local_id': lid, 'cloud_id': cid},
                    'intended_after': _intended_after_image_from_local(source),
                })
            raise _partial_error(
                f'Metadata push succeeded but verification fetch failed: {exc}',
                failing=None, cause=exc,
            )

    # Measurement: cloud → local (matched with choice=cloud, or cloud_only+download)
    remote_measurement_ids_to_apply = {
        str(op.get('cloud_id') or '')
        for op in ops
        if op.get('op') == 'import_measurement' and str(op.get('cloud_id') or '')
    }
    if remote_measurement_ids_to_apply:
        try:
            result = _import_remote_measurements_for_observation(
                client,
                int(local_id),
                resolved_cloud_id,
                remote_images=remote_images,
                remote_measurements=[
                    row for row in remote_measurements
                    if str(row.get('id') or '') in remote_measurement_ids_to_apply
                ],
                materialize_remote_images=True,
                overwrite_conflicts=True,
            )
        except Exception as exc:
            raise _partial_error(
                f'Could not apply selected cloud measurements: {exc}',
                failing={'op': 'import_measurement',
                         'cloud_ids': sorted(remote_measurement_ids_to_apply)},
                cause=exc,
            )
        if result.get('failed'):
            raise _partial_error(
                'Could not apply selected cloud measurements',
                failing={'op': 'import_measurement',
                         'cloud_ids': sorted(remote_measurement_ids_to_apply)},
            )
        try:
            local_after_import = MeasurementDB.get_measurements_for_observation(int(local_id))
            by_cloud_id_import = {
                str(r.get('cloud_id') or '').strip(): r for r in local_after_import
                if str(r.get('cloud_id') or '').strip()
            }
            remote_by_cloud_import = {
                str(r.get('id') or '').strip(): r for r in remote_measurements
                if str(r.get('id') or '').strip()
            }
            for cid in sorted(remote_measurement_ids_to_apply):
                local_row = by_cloud_id_import.get(cid) or {}
                remote_row = remote_by_cloud_import.get(cid) or {}
                executed.append({
                    'op': 'import_measurement', 'cloud_id': cid,
                    'local_id': _safe_int(local_row.get('id')) or None,
                    'status': 'completed',
                    'stable_identity': {'cloud_id': cid,
                                        'local_id': _safe_int(local_row.get('id')) or None},
                    'expected_after': {
                        'kind': 'measurement',
                        'material_local': _material_measurement_expected_state(
                            local_row, side='local'
                        ),
                        'material_remote': _material_measurement_expected_state(
                            remote_row, side='remote'
                        ),
                    },
                })
        except Exception as exc:
            remote_by_cloud_import = {
                str(r.get('id') or '').strip(): r for r in remote_measurements
                if str(r.get('id') or '').strip()
            }
            for cid in sorted(remote_measurement_ids_to_apply):
                remote_row = remote_by_cloud_import.get(cid) or {}
                executed.append({
                    'op': 'import_measurement', 'cloud_id': cid,
                    'status': 'verification_pending',
                    'write_attempted': True,
                    'stable_identity': {'cloud_id': cid},
                    'intended_after': _intended_after_measurement_from_remote(remote_row),
                })
            raise _partial_error(
                f'Measurement import succeeded but verification read failed: {exc}',
                failing=None, cause=exc,
            )

    # Measurement: local → cloud.  Only ids explicitly marked as push_measurement.
    local_measurement_ids_to_push = {
        _safe_int(op.get('local_id'))
        for op in ops
        if op.get('op') == 'push_measurement' and _safe_int(op.get('local_id')) > 0
    }
    if local_measurement_ids_to_push:
        try:
            _push_measurements_for_observation(
                client,
                int(local_id),
                measurement_ids=local_measurement_ids_to_push,
            )
        except Exception as exc:
            raise _partial_error(
                f'Could not push local measurements: {exc}',
                failing={'op': 'push_measurement',
                         'local_ids': sorted(local_measurement_ids_to_push)},
                cause=exc,
            )
        try:
            local_after_meas_push = MeasurementDB.get_measurements_for_observation(int(local_id))
            by_local_id_mp = {_safe_int(r.get('id')): r for r in local_after_meas_push
                              if _safe_int(r.get('id'))}
            remote_after_meas_push = _pull_remote_measurements_for_images(
                client,
                [str(row.get('id') or '').strip() for row in remote_images
                 if str(row.get('id') or '').strip()],
            )
            remote_by_desktop_mp = {_safe_int(r.get('desktop_id')): r
                                    for r in remote_after_meas_push
                                    if _safe_int(r.get('desktop_id'))}
            for lid in sorted(local_measurement_ids_to_push):
                local_row = by_local_id_mp.get(int(lid)) or {}
                remote_row = remote_by_desktop_mp.get(int(lid)) or {}
                cid_after = str(local_row.get('cloud_id') or '').strip() or None
                executed.append({
                    'op': 'push_measurement', 'local_id': lid,
                    'cloud_id': cid_after,
                    'status': 'completed',
                    'stable_identity': {'local_id': lid, 'cloud_id': cid_after},
                    'expected_after': {
                        'kind': 'measurement',
                        'material_local': _material_measurement_expected_state(
                            local_row, side='local'
                        ),
                        'material_remote': _material_measurement_expected_state(
                            remote_row, side='remote'
                        ),
                    },
                })
        except Exception as exc:
            best_local_rows = {_safe_int(r.get('id')): r
                               for r in current_local_measurements
                               if _safe_int(r.get('id'))}
            for lid in sorted(local_measurement_ids_to_push):
                source = best_local_rows.get(int(lid)) or {}
                cid = str(source.get('cloud_id') or '').strip() or None
                executed.append({
                    'op': 'push_measurement', 'local_id': lid,
                    'cloud_id': cid,
                    'status': 'verification_pending',
                    'write_attempted': True,
                    'stable_identity': {'local_id': lid, 'cloud_id': cid},
                    'intended_after': _intended_after_measurement_from_local(source),
                })
            raise _partial_error(
                f'Measurement push succeeded but verification fetch failed: {exc}',
                failing=None, cause=exc,
            )

    # keep-asymmetric ops are recorded here; B4 turns them into a durable
    # accepted-asymmetry baseline that _store_remote_snapshot preserves.
    for op in ops:
        if op.get('op') in {'keep_asymmetric_image', 'keep_asymmetric_measurement'}:
            recorded = dict(op)
            recorded['status'] = 'completed'
            executed.append(recorded)

    # ── Step 7: restore presentation on matched images ────────────────────────
    presentation_statuses = _restore_local_presentation(
        presentation_before, matched_local_ids=matched_image_local_ids
    )
    presentation_statuses.extend(_assign_downloaded_image_order(
        local_id=int(local_id),
        downloaded_cloud_ids=remote_ids_to_import,
        captured_before=presentation_before,
    ))
    executed.extend(presentation_statuses)
    presentation_warnings = [
        status for status in presentation_statuses if status.get('status') != 'completed'
    ]

    # ── Step 8: derived statistics ────────────────────────────────────────────
    split_measurement_sets = any(
        op.get('op') in {'keep_asymmetric_measurement'} for op in ops
    )
    statistics_expected = bool(
        MeasurementDB.get_measurements_for_observation(int(local_id))
    )
    if (
        selected_plan.get('derived_statistics') == 'recompute_from_measurements'
        and not split_measurement_sets
    ):
        try:
            recomputed = _format_recomputed_spore_statistics(int(local_id))
        except Exception as exc:
            raise _partial_error(
                f'Could not recompute spore statistics: {exc}',
                failing={'op': 'recompute_spore_statistics'}, cause=exc,
            )
        if recomputed is None or not str(recomputed).strip():
            if statistics_expected:
                raise _partial_error(
                    'Could not recompute spore statistics from the selected measurements',
                    failing={'op': 'recompute_spore_statistics'},
                )
            # No measurements: preserve the current cloud value.
            executed.append({'op': 'preserve_spore_statistics_no_measurements',
                             'status': 'completed'})
        else:
            try:
                ObservationDB.update_spore_statistics(int(local_id), recomputed)
                client._patch(
                    f'observations?id=eq.{resolved_cloud_id}',
                    {'spore_statistics': recomputed},
                )
            except Exception as exc:
                raise _partial_error(
                    f'Could not persist recomputed spore statistics: {exc}',
                    failing={'op': 'recompute_spore_statistics'}, cause=exc,
                )
            executed.append({
                'op': 'recompute_spore_statistics', 'status': 'completed',
                'stable_identity': {'field': 'spore_statistics'},
                'expected_after': {
                    'side': 'both',
                    'field': 'spore_statistics',
                    'value': _normalize_observation_json_value(recomputed),
                },
            })

    # ── Step 9: build accepted-asymmetry entries from the plan ────────────────
    # Reread current local rows so freshly-created cloud IDs (from upload) or
    # freshly-linked local rows (from download) are visible for reconciliation.
    reconciled_local_images = ImageDB.get_images_for_observation(int(local_id))
    reconciled_local_measurements = MeasurementDB.get_measurements_for_observation(int(local_id))
    reconciled_remote_images = [
        dict(row or {})
        for row in (_pull_remote_images_for_sync(client, resolved_cloud_id) or [])
        if not str((row or {}).get('deleted_at') or '').strip()
        and should_pull_cloud_image_to_desktop(row)
    ]
    reconciled_remote_measurements = _pull_remote_measurements_for_images(
        client,
        [str(row.get('id') or '').strip()
         for row in reconciled_remote_images if str(row.get('id') or '').strip()],
    )
    matched_cloud_image_ids: set[str] = set(
        str(row.get('cloud_id') or '').strip()
        for row in reconciled_local_images
        if str(row.get('cloud_id') or '').strip()
    )
    matched_local_image_ids_now = matched_image_local_ids | {
        _safe_int(row.get('desktop_id'))
        for row in reconciled_remote_images
        if _safe_int(row.get('desktop_id'))
    }
    matched_cloud_measurement_ids: set[str] = set(
        str(row.get('cloud_id') or '').strip()
        for row in reconciled_local_measurements
        if str(row.get('cloud_id') or '').strip()
    )
    matched_local_measurement_ids_now = {
        _safe_int(row.get('desktop_id'))
        for row in reconciled_remote_measurements
        if _safe_int(row.get('desktop_id'))
    }
    new_asymmetry = _build_accepted_asymmetry_from_plan(
        items,
        local_images=reconciled_local_images,
        remote_images=reconciled_remote_images,
        local_measurements=reconciled_local_measurements,
        remote_measurements=reconciled_remote_measurements,
    )
    previous_snapshot = _parse_cloud_observation_snapshot(
        _load_cloud_observation_snapshot(resolved_cloud_id)
    )
    prev_asymmetry = previous_snapshot.get('accepted_asymmetry')
    merged_asymmetry = _reconcile_accepted_asymmetry(
        prev_asymmetry, new_asymmetry,
        plan_items=items,
        current_local_images=reconciled_local_images,
        current_remote_images=reconciled_remote_images,
        current_local_measurements=reconciled_local_measurements,
        current_remote_measurements=reconciled_remote_measurements,
        matched_local_image_ids=matched_local_image_ids_now,
        matched_cloud_image_ids=matched_cloud_image_ids,
        matched_local_measurement_ids=matched_local_measurement_ids_now,
        matched_cloud_measurement_ids=matched_cloud_measurement_ids,
    )

    # ── Step 10: finalize in order — snapshot → signature → stamp ─────────────
    try:
        _store_remote_snapshot(
            client, resolved_cloud_id,
            accepted_asymmetry=merged_asymmetry,
        )
    except Exception as exc:
        raise _partial_error(
            f'Could not store fresh cloud snapshot after applying plan: {exc}',
            failing={'op': 'store_snapshot'}, cause=exc,
        )
    _refresh_local_cloud_media_signature(int(local_id))
    _stamp_observation_synced(int(local_id), resolved_cloud_id)

    return {
        'local_id': int(local_id),
        'cloud_id': resolved_cloud_id,
        'plan_applied': True,
        'media_deleted': False,
        'operations': executed,
        'presentation_warnings': presentation_warnings,
        'accepted_asymmetry': merged_asymmetry,
    }


def _get_keyring_module():
    try:
        import keyring  # type: ignore

        return keyring
    except Exception:
        return None


def load_saved_cloud_password() -> tuple[str, str | None, bool]:
    settings = get_app_settings()
    email = str(settings.get('cloud_user_email') or '').strip()
    keyring = _get_keyring_module()
    if keyring is None:
        return email, None, False
    try:
        password = keyring.get_password(_CLOUD_KEYRING_SERVICE, _CLOUD_KEYRING_ACCOUNT)
        if password is None and not using_isolated_profile():
            password = keyring.get_password(_CLOUD_LEGACY_KEYRING_SERVICE, _CLOUD_KEYRING_ACCOUNT)
    except Exception:
        return email, None, False
    return email, password, True


def save_cloud_password(email: str, password: str) -> None:
    keyring = _get_keyring_module()
    if keyring is None:
        raise RuntimeError("Secure password storage is unavailable on this system.")
    try:
        keyring.set_password(_CLOUD_KEYRING_SERVICE, _CLOUD_KEYRING_ACCOUNT, password)
    except Exception as exc:
        raise RuntimeError(f"Could not securely save password: {exc}") from exc
    update_app_settings({'cloud_user_email': str(email or '').strip()})


def clear_saved_cloud_password() -> list[str]:
    keyring = _get_keyring_module()
    if keyring is None:
        return []
    from utils.keyring_cleanup import delete_password_entries

    return delete_password_entries(
        keyring,
        (
            (_CLOUD_KEYRING_SERVICE, _CLOUD_KEYRING_ACCOUNT),
            (_CLOUD_LEGACY_KEYRING_SERVICE, _CLOUD_KEYRING_ACCOUNT),
        ),
    )


def has_saved_cloud_password() -> bool:
    email, password, _ = load_saved_cloud_password()
    return bool(email and password)


class SporelyCloudClient:
    """Thin wrapper around Supabase REST API."""

    def __init__(self, access_token: str, user_id: str, refresh_token: str | None = None):
        self.access_token = access_token
        self.user_id = user_id
        self.refresh_token = str(refresh_token or '').strip() or None
        self._s = requests.Session()
        self._r2: CloudflareR2Client | None = None
        self._media_worker: CloudflareMediaWorkerClient | None = None
        self._column_support_cache: dict[tuple[str, str], bool] = {}
        self._cloud_image_storage_key_cache: dict[str, str] = {}
        self._s.headers.update({
            'apikey': SUPABASE_KEY,
            'Authorization': f'Bearer {access_token}',
            'Content-Type': 'application/json',
        })

    def _get_r2(self) -> CloudflareR2Client:
        if self._r2 is None:
            self._r2 = CloudflareR2Client.from_env()
        return self._r2

    def _get_media_worker(self) -> CloudflareMediaWorkerClient:
        if self._media_worker is None:
            self._media_worker = CloudflareMediaWorkerClient.from_access_token(self.access_token)
        return self._media_worker

    def _using_default_r2_loader(self) -> bool:
        if "_get_r2" in self.__dict__:
            return False
        return type(self)._get_r2 is SporelyCloudClient._get_r2

    def _response_indicates_auth_error(self, response: requests.Response) -> bool:
        return _response_indicates_auth_error(response)

    def _adopt_session_from_values(
        self,
        access_token: str,
        user_id: str | None,
        refresh_token: str | None,
    ) -> None:
        """Copy a freshly-observed session onto this client in-memory.

        Kept small so both the "adopt from settings" and "adopt from
        refresh response" branches of :meth:`_refresh_session_if_possible`
        stay symmetric.
        """
        self.access_token = access_token
        self.user_id = (
            _decode_jwt_subject(access_token)
            or _normalize_cloud_user_id(user_id)
            or self.user_id
        )
        if refresh_token:
            self.refresh_token = refresh_token
        self._s.headers.update({'Authorization': f'Bearer {self.access_token}'})
        self._media_worker = None

    def _refresh_session_if_possible(self) -> bool:
        # Serialize every refresh attempt so concurrent clients cannot
        # race Supabase into rotating the same refresh token twice.
        with _CLOUD_REFRESH_LOCK:
            settings_access, settings_user_id, settings_refresh = (
                _read_current_cloud_session_settings()
            )
            self_access = str(self.access_token or '').strip() or None

            # Account-safety guard: if the on-disk session belongs to a
            # *different* Sporely Cloud user than this client is bound
            # to, refuse to adopt or refresh with any of it.  A stale
            # worker must not authenticate as another account just
            # because settings rotated under it.
            if not _settings_session_is_compatible(
                self.user_id, settings_user_id, settings_access
            ):
                raise CloudSessionAccountMismatchError(
                    "Stored cloud session belongs to a different account "
                    "than this client instance; refusing to adopt or refresh."
                )

            # Fast path: another thread already rotated tokens while we
            # were waiting for the lock.  Adopt the newer access token
            # and skip the network round-trip entirely.
            if (
                settings_access
                and settings_access != self_access
                and not _jwt_expires_soon(settings_access)
            ):
                self._adopt_session_from_values(
                    settings_access, settings_user_id, settings_refresh
                )
                return True

            # Refresh path: prefer whichever refresh token settings has
            # right now over our in-memory copy.  The account-safety
            # guard above has already confirmed settings belongs to the
            # same user, so preferring the settings refresh token is
            # safe.
            candidate_refresh = settings_refresh or (
                str(self.refresh_token or '').strip() or None
            )
            if not candidate_refresh:
                return False

            try:
                refreshed = type(self).refresh_login(candidate_refresh)
            except CloudTemporarilyUnavailableError:
                raise
            except CloudReauthRequiredError:
                # Before treating the session as dead, re-read settings
                # one more time — another thread may have just rotated
                # the refresh token so ``candidate_refresh`` looks dead
                # to Supabase (reuse detection) even though the session
                # is fine.
                after_access, after_user_id, after_refresh = (
                    _read_current_cloud_session_settings()
                )
                # Re-apply the account guard to the fresh snapshot.  If
                # the user switched accounts while we were mid-refresh
                # we must not adopt or retry with the new account's
                # tokens.  Propagate the original reauth-required
                # signal so the caller can prompt sign-in.
                if not _settings_session_is_compatible(
                    self.user_id, after_user_id, after_access
                ):
                    raise
                if (
                    after_access
                    and after_access != settings_access
                    and not _jwt_expires_soon(after_access)
                ):
                    self._adopt_session_from_values(
                        after_access, after_user_id, after_refresh
                    )
                    return True
                if after_refresh and after_refresh != candidate_refresh:
                    # A newer refresh token appeared on disk after we
                    # snapshotted.  Retry once with it before giving up.
                    try:
                        refreshed = type(self).refresh_login(after_refresh)
                    except CloudTemporarilyUnavailableError:
                        raise
                    except CloudReauthRequiredError:
                        # The newer token is also dead — this session
                        # really does need sign-in.  Do NOT clear tokens
                        # here; the UI decides how to prompt the user.
                        raise
                    except CloudSyncError:
                        return False
                else:
                    raise
            except CloudSyncError:
                return False

            self._adopt_session_from_values(
                refreshed.access_token, refreshed.user_id, refreshed.refresh_token
            )
            try:
                self.save_credentials()
            except Exception:
                pass
            return True

    def _request_with_refresh(self, method: str, url: str, *, refresh_on_auth_error: bool = True, **kwargs):
        return _request_with_transient_retry(
            self._s.request,
            method,
            url,
            refresh_on_auth_error=refresh_on_auth_error,
            refresh_callback=self._refresh_session_if_possible if refresh_on_auth_error else None,
            **kwargs,
        )

    def _has_column(self, table_name: str, column_name: str) -> bool:
        cache_key = (str(table_name or '').strip(), str(column_name or '').strip())
        if not all(cache_key):
            return False
        if cache_key in self._column_support_cache:
            return self._column_support_cache[cache_key]
        try:
            self._get(f'{cache_key[0]}?select={cache_key[1]}&limit=1')
            supported = True
        except CloudSyncError as exc:
            text = str(exc or '').lower()
            if (
                ('column' in text and cache_key[1].lower() in text and 'does not exist' in text)
                or 'could not find the' in text
            ):
                supported = False
            else:
                raise
        self._column_support_cache[cache_key] = supported
        return supported

    def _observation_supports_media_keys(self) -> bool:
        return self._has_column('observations', 'image_key') or self._has_column('observations', 'thumb_key')

    def _observation_images_support_ai_crop(self) -> bool:
        return self._has_column('observation_images', 'ai_crop_x1') or self._has_column('observation_images', 'ai_crop_source_w')

    def _observation_images_support_ai_crop_custom(self) -> bool:
        return self._has_column('observation_images', 'ai_crop_is_custom')

    def _observation_images_support_upload_metadata(self) -> bool:
        return self._has_column('observation_images', 'upload_mode') or self._has_column('observation_images', 'stored_bytes')

    def _observation_images_support_storage_exif_safe(self) -> bool:
        return self._has_column('observation_images', 'storage_exif_safe')

    def _observation_images_support_original_storage_path(self) -> bool:
        return self._has_column('observation_images', 'original_storage_path')

    def _observation_images_support_sample_source(self) -> bool:
        """`sample_source` is added by the sporely-web Stage 2A migration.

        Older cloud deployments only have `sample_type`. When missing here,
        push drops `sample_source` from the payload so PostgREST doesn't
        return a schema-cache error, and legacy `sample_type='Spore_print'`
        stays on the payload so the value doesn't get silently dropped
        during the transition.
        """
        return self._has_column('observation_images', 'sample_source')

    def _measurement_supports_media_keys(self) -> bool:
        return self._has_column('spore_measurements', 'image_key') or self._has_column('spore_measurements', 'thumb_key')

    def _set_observation_media_keys(self, obs_cloud_id: str, storage_key: str, sort_order) -> None:
        if not obs_cloud_id:
            return
        if sort_order not in (None, 0, '0'):
            return
        if not self._observation_supports_media_keys():
            return
        normalized_key = _normalize_cloud_media_key(storage_key)
        if not normalized_key:
            return
        payload: dict[str, str] = {}
        if self._has_column('observations', 'image_key'):
            payload['image_key'] = normalized_key
        if self._has_column('observations', 'thumb_key'):
            payload['thumb_key'] = media_variant_key(normalized_key, 'thumb')
        if payload:
            self._patch(f'observations?id=eq.{obs_cloud_id}', payload)

    def _cloud_image_storage_key(self, cloud_image_id: str) -> str:
        normalized_id = str(cloud_image_id or '').strip()
        if not normalized_id:
            return ''
        if normalized_id in self._cloud_image_storage_key_cache:
            return self._cloud_image_storage_key_cache[normalized_id]
        rows = self._get(f'observation_images?id=eq.{normalized_id}&select=storage_path&limit=1')
        storage_key = _normalize_cloud_media_key((rows[0] or {}).get('storage_path') if rows else '')
        self._cloud_image_storage_key_cache[normalized_id] = storage_key
        return storage_key

    # ── Auth ────────────────────────────────────────────────────────────

    @classmethod
    def login(cls, email: str, password: str) -> 'SporelyCloudClient':
        resp = _request_with_transient_retry(
            requests.request,
            'POST',
            f'{SUPABASE_URL}/auth/v1/token?grant_type=password',
            json={'email': email, 'password': password},
            headers={'apikey': SUPABASE_KEY, 'Content-Type': 'application/json'},
            timeout=_SUPABASE_AUTH_TIMEOUT,
        )
        if not resp.ok:
            raise CloudSyncError(f'Login failed (status={resp.status_code}): {resp.text}')
        d = resp.json()
        return cls(
            access_token=d['access_token'],
            user_id=d['user']['id'],
            refresh_token=d.get('refresh_token'),
        )

    @classmethod
    def refresh_login(cls, refresh_token: str) -> 'SporelyCloudClient':
        token = str(refresh_token or '').strip()
        if not token:
            raise CloudSyncError('Missing refresh token')
        resp = _request_with_transient_retry(
            requests.request,
            'POST',
            f'{SUPABASE_URL}/auth/v1/token?grant_type=refresh_token',
            json={'refresh_token': token},
            headers={'apikey': SUPABASE_KEY, 'Content-Type': 'application/json'},
            timeout=_SUPABASE_AUTH_TIMEOUT,
        )
        if not resp.ok:
            body_text = str(getattr(resp, 'text', '') or '')
            body_lower = body_text.lower()
            status_code = int(getattr(resp, 'status_code', 0) or 0)
            # Supabase returns 400 with an ``invalid_grant`` (or similar)
            # body only when it can prove the refresh token itself is dead:
            # revoked, rotated, expired, or reused past the detection
            # window.  Any *other* non-ok status is treated as a generic
            # CloudSyncError so a rotation race or transient blip does not
            # look terminal to callers.
            if status_code == 400 and any(
                hint in body_lower for hint in _CLOUD_REAUTH_REQUIRED_HINTS
            ):
                raise CloudReauthRequiredError(
                    f'Refresh failed (status={status_code}): {body_text}'
                )
            raise CloudSyncError(f'Refresh failed (status={status_code}): {body_text}')
        d = resp.json()
        return cls(
            access_token=d['access_token'],
            user_id=d['user']['id'],
            refresh_token=d.get('refresh_token') or token,
        )

    @classmethod
    def from_stored_credentials(cls) -> 'SporelyCloudClient | None':
        settings = get_app_settings()
        token = settings.get('cloud_access_token')
        user_id = settings.get('cloud_user_id')
        refresh_token = settings.get('cloud_refresh_token')
        token_text = str(token or '').strip()
        user_id_text = _normalize_cloud_user_id(user_id)
        refresh_text = str(refresh_token or '').strip() or None
        if token_text and user_id_text:
            token_user_id = _decode_jwt_subject(token_text)
            client = cls(
                access_token=token_text,
                user_id=token_user_id or user_id_text,
                refresh_token=refresh_text,
            )
            expiry_seconds = _decode_jwt_expiry(token_text)
            # Only refresh proactively when we can *prove* the token is
            # near expiry AND we have a refresh token to spend.  If the
            # JWT is undecodable, keep the historical fast path and rely
            # on a first-request 401 to trigger the locked refresh.
            if (
                expiry_seconds is not None
                and _jwt_expires_soon(token_text)
                and refresh_text
            ):
                try:
                    client._refresh_session_if_possible()
                    return client
                except CloudTemporarilyUnavailableError:
                    # Transient — return the client anyway.  A first API
                    # call will retry the refresh through the same lock.
                    return client
                except CloudReauthRequiredError:
                    # Session is genuinely dead — fall through to the
                    # saved-password path below without wiping tokens.
                    pass
            else:
                return client
        if refresh_text:
            try:
                client = cls.refresh_login(str(refresh_text))
                client.save_credentials()
                return client
            except CloudTemporarilyUnavailableError:
                raise
            except CloudSyncError:
                pass
        email, password, _ = load_saved_cloud_password()
        if email and password:
            try:
                client = cls.login(email, password)
                client.save_credentials(email=email)
                return client
            except CloudTemporarilyUnavailableError:
                raise
            except CloudSyncError:
                return None
        return None

    def fetch_current_user_id(self) -> str:
        """Return the authenticated Supabase user id for the current session."""
        user_info = self.fetch_current_user_info()
        user_id = _normalize_cloud_user_id(user_info.get('id') if isinstance(user_info, dict) else None)
        if user_id:
            if user_id != self.user_id:
                self.user_id = user_id
            return user_id
        raise CloudSyncError('Could not fetch current cloud user.')

    def fetch_current_user_info(self) -> dict:
        """Return the authenticated Supabase user record."""
        resp = self._request_with_refresh('GET', f'{SUPABASE_URL}/auth/v1/user', timeout=_SUPABASE_AUTH_TIMEOUT)
        if resp.ok:
            try:
                data = resp.json()
            except Exception:
                data = {}
            user_id = _normalize_cloud_user_id(data.get('id') if isinstance(data, dict) else None)
            if user_id:
                if user_id != self.user_id:
                    self.user_id = user_id
                return data if isinstance(data, dict) else {'id': user_id}
        if not self._response_indicates_auth_error(resp):
            token_user_id = _decode_jwt_subject(self.access_token)
            if token_user_id:
                if token_user_id != self.user_id:
                    self.user_id = token_user_id
                return {'id': token_user_id}
        raise CloudSyncError(f'Could not fetch current cloud user: {resp.text if resp is not None else ""}')

    def fetch_profile(self) -> dict:
        rows = self._get(
            f'profiles?id=eq.{self.user_id}&select=id,username,display_name,bio,avatar_url&limit=1'
        )
        return dict(rows[0] or {}) if rows else {}

    def fetch_cloud_plan_profile(self) -> dict:
        rows = self._get(
            f'profiles?id=eq.{self.user_id}&select='
            'id,cloud_plan,is_pro,full_res_storage_enabled,storage_quota_bytes,'
            'total_storage_bytes,storage_used_bytes,image_count,is_banned&limit=1'
        )
        return normalize_cloud_plan_profile(rows[0] if rows else {})

    def update_profile(
        self,
        *,
        username: str | None = None,
        display_name: str | None = None,
        bio: str | None = None,
        avatar_url: str | None = None,
    ) -> None:
        payload: dict[str, object] = {}
        if username is not None:
            normalized = str(username or '').strip().lstrip('@')
            payload['username'] = normalized or None
        if display_name is not None:
            normalized = str(display_name or '').strip()
            payload['display_name'] = normalized or None
        if bio is not None:
            normalized = str(bio or '').strip()
            payload['bio'] = normalized or None
        if avatar_url is not None:
            normalized = str(avatar_url or '').strip()
            payload['avatar_url'] = normalized or None
        if not payload:
            return
        self._patch(f'profiles?id=eq.{self.user_id}', payload)

    def upload_profile_avatar(self, jpeg_bytes: bytes) -> str:
        content = bytes(jpeg_bytes or b'')
        if not content:
            raise CloudSyncError('Missing avatar image data.')
        path = f'{self.user_id}/avatar.jpg'
        url = f'{SUPABASE_URL}/storage/v1/object/avatars/{path}'
        headers = {
            'Content-Type': 'image/jpeg',
            'x-upsert': 'true',
        }
        resp = self._request_with_refresh('POST', url, data=content, headers=headers, timeout=_SUPABASE_PROFILE_UPLOAD_TIMEOUT)
        if not resp.ok:
            resp = self._request_with_refresh('PUT', url, data=content, headers=headers, timeout=_SUPABASE_PROFILE_UPLOAD_TIMEOUT)
        if not resp.ok:
            raise CloudSyncError(f'Avatar upload failed: {resp.text}')
        public_url = f'{SUPABASE_URL}/storage/v1/object/public/avatars/{path}'
        self.update_profile(avatar_url=public_url)
        return public_url

    def save_credentials(
        self,
        email: str | None = None,
        password: str | None = None,
        remember_password: bool | None = None,
    ) -> None:
        updates = {
            'cloud_access_token': self.access_token,
            'cloud_user_id': self.user_id,
            'cloud_refresh_token': self.refresh_token,
        }
        if email is not None:
            updates['cloud_user_email'] = str(email or '').strip()
        update_app_settings(updates)
        # Only change the saved password when the caller explicitly asked us to.
        # Auto-login/refresh paths should preserve whatever the user chose earlier.
        if remember_password is True and email and password:
            save_cloud_password(str(email or '').strip(), password)
        elif remember_password is False:
            clear_saved_cloud_password()

    @staticmethod
    def clear_session() -> None:
        """Forget only the cloud tokens so the saved password can survive re-login."""
        update_app_settings({
            'cloud_access_token': None,
            'cloud_user_id': None,
            'cloud_refresh_token': None,
        })

    @staticmethod
    def clear_credentials() -> None:
        clear_saved_cloud_password()
        update_app_settings({
            'cloud_access_token': None,
            'cloud_user_id': None,
            'cloud_refresh_token': None,
            'cloud_user_email': None,
        })

    # ── REST helpers ─────────────────────────────────────────────────────

    def _get(self, path: str) -> list:
        resp = self._request_with_refresh('GET', f'{SUPABASE_URL}/rest/v1/{path}', timeout=_SUPABASE_REST_TIMEOUT)
        if not resp.ok:
            raise CloudSyncError(f'GET {path}: {resp.text}')
        return resp.json()

    def _get_paginated(self, path: str, *, page_size: int = _CLOUD_SYNC_MAX_ROWS_PER_PAGE) -> list:
        """Fully page a PostgREST GET past the server ``db-max-rows`` cap.

        Callers MUST include a deterministic ``order=`` clause (with ``id.asc``
        as tie-breaker) in ``path``; otherwise offset-based paging can skip or
        duplicate rows across pages. On any page failure the exception from
        ``_get`` propagates — partial results are never returned, so callers
        must not treat truncation as an authoritative empty result.
        """
        if page_size <= 0:
            raise CloudSyncError(f'GET {path}: invalid page_size {page_size}')
        all_rows: list = []
        offset = 0
        sep = '&' if '?' in path else '?'
        while True:
            page_path = f'{path}{sep}limit={page_size}&offset={offset}'
            rows = self._get(page_path)
            if not isinstance(rows, list):
                raise CloudSyncError(
                    f'GET {path}: expected list response for paginated fetch, '
                    f'got {type(rows).__name__}'
                )
            all_rows.extend(rows)
            if len(rows) < page_size:
                return all_rows
            offset += len(rows)

    def get_read_only(self, path: str) -> list:
        """Perform one REST GET without token refresh or credential writes."""
        resp = self._request_with_refresh(
            'GET',
            f'{SUPABASE_URL}/rest/v1/{path}',
            timeout=_SUPABASE_REST_TIMEOUT,
            refresh_on_auth_error=False,
        )
        if not resp.ok:
            status = int(getattr(resp, 'status_code', 0) or 0)
            if status in {401, 403} or self._response_indicates_auth_error(resp):
                raise CloudReauthRequiredError(
                    'Read-only cloud audit authentication expired; sign in again before retrying.'
                )
            raise CloudSyncError(f'GET {path}: {resp.text}')
        return resp.json()

    def _post(self, path: str, payload: dict) -> list:
        resp = self._request_with_refresh(
            'POST',
            f'{SUPABASE_URL}/rest/v1/{path}',
            json=payload,
            headers={'Prefer': 'return=representation'},
            timeout=_SUPABASE_REST_TIMEOUT,
        )
        if not resp.ok:
            raise CloudSyncError(f'POST {path}: {resp.text}')
        return resp.json()

    def _rpc(self, function_name: str, payload: dict | None = None):
        rpc_name = str(function_name or '').strip()
        if not rpc_name:
            raise CloudSyncError('Missing RPC function name')
        resp = self._request_with_refresh(
            'POST',
            f'{SUPABASE_URL}/rest/v1/rpc/{rpc_name}',
            json=dict(payload or {}),
            timeout=_SUPABASE_REST_TIMEOUT,
        )
        if not resp.ok:
            raise CloudSyncError(f'RPC {rpc_name}: {resp.text}')
        if not resp.content:
            return None
        return resp.json()

